def _oracle_queue_directed(priority: float, label: str, fn: Callable) -> None:
    with _ORACLE_DIRECTED_LOCK:
        if label in _ORACLE_DIRECTED_SEEN:
            return
        _ORACLE_DIRECTED_SEEN.add(label)
        _heapq.heappush(_ORACLE_DIRECTED_QUEUE, (priority, label, fn))

def _oracle_drain_directed(n: int = 8) -> List[Tuple[str, Callable]]:
    tasks: List[Tuple[str, Callable]] = []
    with _ORACLE_DIRECTED_LOCK:
        while _ORACLE_DIRECTED_QUEUE and len(tasks) < n:
            _, label, fn = _heapq.heappop(_ORACLE_DIRECTED_QUEUE)
            tasks.append((label, fn))
    return tasks


