_REQ_COUNT_10S_QUEUE: collections.deque = collections.deque()

def _req_count_decay_worker() -> None:
    global _REQ_COUNT_10S
    while True:
        time.sleep(0.5)
        now = time.monotonic()
        with _REQ_TS_LOCK:
            while _REQ_COUNT_10S_QUEUE and _REQ_COUNT_10S_QUEUE[0] <= now - 10.0:
                _REQ_COUNT_10S_QUEUE.popleft()
            _REQ_COUNT_10S = len(_REQ_COUNT_10S_QUEUE)

_REQ_DECAY_THREAD = threading.Thread(target=_req_count_decay_worker, daemon=True)
_REQ_DECAY_THREAD.start()

def _auto_workers(kind: str = "module", requested: int = 0) -> int:
    if requested and requested > 0:
        cap = 250 if kind == "path" else 128
        return max(1, min(cap, int(requested)))
    cpus = os.cpu_count() or 4
    if kind == "path":
        return max(24, min(160, cpus * 10))
    if kind == "fast":
        return max(48, min(128, cpus * 12))
    return max(32, min(96, cpus * 8))

