try:
    from playwright.sync_api import sync_playwright as _sync_playwright
    _HAS_PLAYWRIGHT = True
except ImportError:
    _sync_playwright = None
    _HAS_PLAYWRIGHT = False

_PW_PLAYWRIGHT: Optional[object] = None
_PW_BROWSER: Optional[object] = None
_PW_LOCK = threading.Lock()

def _global_cookie_pairs() -> Dict[str, str]:
    raw = _GLOBAL_HEADERS.get("Cookie", "") or _GLOBAL_HEADERS.get("cookie", "") or ""
    pairs: Dict[str, str] = {}
    for part in raw.split(";"):
        if "=" not in part:
            continue
        name, value = part.split("=", 1)
        name = name.strip()
        if name:
            pairs[name] = value.strip()
    return pairs

def _get_pw_browser() -> Optional[object]:
    global _PW_PLAYWRIGHT, _PW_BROWSER
    if not _HAS_PLAYWRIGHT or _sync_playwright is None:
        return None
    with _PW_LOCK:
        if _PW_BROWSER is not None:
            return _PW_BROWSER
        try:
            _PW_PLAYWRIGHT = _sync_playwright().__enter__()
            _PW_BROWSER = _PW_PLAYWRIGHT.chromium.launch(
                headless=True,
                args=["--no-sandbox", "--disable-dev-shm-usage"],
            )
        except Exception as exc:
            _quality_event("failed", "playwright", "browser launch failed: %s" % exc)
            _PW_BROWSER = None
            return None
        return _PW_BROWSER

def _new_pw_context(base: Optional[str] = None) -> Optional[object]:
    browser = _get_pw_browser()
    if browser is None:
        return None
    ctx = browser.new_context(
        ignore_https_errors=not _TLS_VERIFY,
        user_agent=_SCAN_CONFIG.user_agent,
        viewport={"width": 1365, "height": 900},
    )
    if _SCAN_CONFIG.headers:
        try:
            ctx.set_extra_http_headers({k: v for k, v in _SCAN_CONFIG.headers.items() if k.lower() != "cookie"})
        except Exception as exc:
            _quality_event("failed", "playwright", "setting browser headers failed: %s" % exc)
    if base:
        origin = ""
        try:
            p = urllib.parse.urlparse(base)
            if p.scheme and p.netloc:
                origin = p.scheme + "://" + p.netloc
        except Exception as exc:
            _quality_event("failed", "playwright", "invalid browser context base URL: %s" % exc)
            origin = ""
        cookies = []
        for name, value in _global_cookie_pairs().items():
            if origin:
                cookies.append({"name": name, "value": value, "url": origin})
        if cookies:
            try:
                ctx.add_cookies(cookies)
            except Exception as exc:
                _quality_event("failed", "playwright", "setting browser cookies failed: %s" % exc)
    return ctx

def _close_pw_browser() -> None:
    global _PW_PLAYWRIGHT, _PW_BROWSER
    with _PW_LOCK:
        try:
            if _PW_BROWSER is not None:
                _PW_BROWSER.close()
        except Exception as exc:
            if _VERBOSE:
                sys.stderr.write("[scanner] playwright browser close failed: %s\n" % exc)
        try:
            if _PW_PLAYWRIGHT is not None:
                _PW_PLAYWRIGHT.__exit__(None, None, None)
        except Exception as exc:
            if _VERBOSE:
                sys.stderr.write("[scanner] playwright shutdown failed: %s\n" % exc)
        _PW_BROWSER = None
        _PW_PLAYWRIGHT = None

atexit.register(_close_pw_browser)

