def _write_har_export(filepath: str) -> None:
    entries: List[Dict[str, Any]] = []
    with _HTTP_EVIDENCE_LOCK:
        records = list(_HTTP_EVIDENCE_LOG)
    for item in records:
        req = item.get("request", {})
        resp = item.get("response", {})
        entries.append({
            "startedDateTime": item.get("ts") or datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "time": 0,
            "request": {
                "method": req.get("method", "GET"),
                "url": req.get("url", ""),
                "httpVersion": "HTTP/1.1",
                "headers": [{"name": k, "value": str(v)} for k, v in dict(req.get("headers", {})).items()],
                "queryString": [],
                "cookies": [],
                "headersSize": -1,
                "bodySize": len(str(req.get("body_sample", ""))),
                "postData": {"mimeType": "text/plain", "text": req.get("body_sample", "")} if req.get("body_sample") else None,
            },
            "response": {
                "status": int(resp.get("status", 0) or 0),
                "statusText": "",
                "httpVersion": "HTTP/1.1",
                "headers": [{"name": k, "value": str(v)} for k, v in dict(resp.get("headers", {})).items()],
                "cookies": [],
                "content": {"size": int(resp.get("body_len", 0) or 0), "mimeType": resp.get("headers", {}).get("content-type", ""), "text": resp.get("body_sample", "")},
                "redirectURL": resp.get("final_url", ""),
                "headersSize": -1,
                "bodySize": int(resp.get("body_len", 0) or 0),
            },
            "cache": {},
            "timings": {"send": 0, "wait": 0, "receive": 0},
        })
    har = {"log": {"version": "1.2", "creator": {"name": _TOOL_NAME, "version": "1"}, "entries": entries}}
    try:
        _write_json_atomic(filepath, _redact_obj(har), label="har writer")
    except Exception as exc:
        _quality_event("failed", "har writer", str(exc))

def _load_resume_state(path: str) -> None:
    global _RESUME_COMPLETED
    if not path:
        return
    raw = _load_json_file(path, {})
    completed: Set[str] = set()
    if isinstance(raw, dict):
        rows = raw.get("completed_modules", [])
        if isinstance(rows, list):
            completed = {str(x).strip().lower() for x in rows if str(x).strip()}
    elif isinstance(raw, list):
        completed = {str(x).strip().lower() for x in raw if str(x).strip()}
    with _RESUME_LOCK:
        _RESUME_COMPLETED = completed
    if completed:
        _out(_paint("  [resume] loaded %d completed module(s) from %s" % (len(completed), path), A.C))

def _write_resume_state(path: str) -> None:
    if not path:
        return
    with _RESUME_LOCK:
        completed = sorted(_RESUME_COMPLETED)
    data = {
        "schema_version": "1.0",
        "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "target": _SCAN_BASE_URL,
        "completed_modules": completed,
    }
    try:
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(data, fh, indent=2, ensure_ascii=False)
        os.replace(tmp, path)
    except Exception as exc:
        _quality_event("failed", "resume writer", str(exc))

def _resume_has_completed(label: str) -> bool:
    if not _RESUME_FILE:
        return False
    with _RESUME_LOCK:
        return label.strip().lower() in _RESUME_COMPLETED

def _resume_mark_completed(label: str) -> None:
    if not _RESUME_FILE:
        return
    lab = label.strip().lower()
    if not lab:
        return
    changed = False
    with _RESUME_LOCK:
        if lab not in _RESUME_COMPLETED:
            _RESUME_COMPLETED.add(lab)
            changed = True
    if changed:
        _write_resume_state(_RESUME_FILE)

def _load_module_timing_cache() -> None:
    global _MODULE_TIMING_CACHE
    if not _MODULE_TIMING_FILE:
        return
    raw = _load_json_file(_MODULE_TIMING_FILE, {})
    rows = raw.get("modules", raw) if isinstance(raw, dict) else {}
    clean: Dict[str, Dict[str, float]] = {}
    if isinstance(rows, dict):
        for label, data in rows.items():
            if not isinstance(data, dict):
                continue
            try:
                clean[str(label).strip().lower()] = {
                    "avg": float(data.get("avg", 0) or 0),
                    "runs": float(data.get("runs", 0) or 0),
                    "last": float(data.get("last", 0) or 0),
                }
            except Exception:
                pass
    with _MODULE_TIMING_LOCK:
        _MODULE_TIMING_CACHE = clean

def _write_module_timing_cache() -> None:
    if not _MODULE_TIMING_FILE:
        return
    with _MODULE_TIMING_LOCK:
        data = {"schema_version": "1.0", "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(), "modules": _MODULE_TIMING_CACHE}
    try:
        parent = os.path.dirname(_MODULE_TIMING_FILE)
        if parent:
            os.makedirs(parent, exist_ok=True)
        tmp = _MODULE_TIMING_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(data, fh, indent=2, ensure_ascii=False)
        os.replace(tmp, _MODULE_TIMING_FILE)
    except Exception:
        pass

def _record_module_timing(label: str, elapsed: float) -> None:
    lab = label.strip().lower()
    if not lab or elapsed <= 0:
        return
    with _MODULE_TIMING_LOCK:
        row = _MODULE_TIMING_CACHE.setdefault(lab, {"avg": 0.0, "runs": 0.0, "last": 0.0})
        runs = float(row.get("runs", 0) or 0)
        avg = float(row.get("avg", 0) or 0)
        row["avg"] = round(((avg * runs) + elapsed) / (runs + 1.0), 3)
        row["runs"] = runs + 1.0
        row["last"] = round(elapsed, 3)
    _write_module_timing_cache()

def _module_timing_avg(label: str) -> float:
    with _MODULE_TIMING_LOCK:
        return float((_MODULE_TIMING_CACHE.get(label.strip().lower()) or {}).get("avg", 0) or 0)

def _module_throttle_before_request(label: str) -> None:
    if not label:
        return
    with _MODULE_THROTTLE_LOCK:
        until = _MODULE_NOISY_UNTIL.get(label, 0.0)
    now = time.monotonic()
    if until > now:
        time.sleep(min(2.0, until - now))

def _module_throttle_event(label: str, code: int) -> None:
    if not label:
        return
    with _MODULE_THROTTLE_LOCK:
        count = int(_MODULE_THROTTLE_COUNTS.get(label, 0)) + 1
        _MODULE_THROTTLE_COUNTS[label] = count
        if count >= 3:
            wait = min(12.0, 1.5 * count)
            _MODULE_NOISY_UNTIL[label] = time.monotonic() + wait
            _quality_event("throttle", label, "HTTP %d noisy module slowdown %.1fs" % (code, wait))



def _run_doctor(args: object) -> int:
    code, rows = _doctor_run(
        output_dir=_OUTPUT_DIR,
        proxy_files=_default_proxy_files(),
        normalize_proxy_url=_normalize_proxy_url,
        proxy_kind=_proxy_kind,
        scan_registry=_SCAN_REGISTRY,
        scan_severity=_SCAN_SEVERITY,
        load_json_file=_load_json_file,
        config_path=getattr(args, "config", None),
        doctor_json_file=_DOCTOR_JSON_FILE,
        has_urllib3=_HAS_URLLIB3,
        has_socks=_HAS_URLLIB3_SOCKS,
    )
    _emit_maintenance_rows(rows)
    return code

