def _write_evidence_attachment(fid: str, evidence: Any) -> Optional[str]:
    if not _EVIDENCE_ATTACH_DIR or not evidence:
        return None
    try:
        os.makedirs(_EVIDENCE_ATTACH_DIR, exist_ok=True)
        safe = re.sub(r"[^A-Za-z0-9_.-]+", "_", fid or secrets.token_hex(4))
        path = os.path.join(_EVIDENCE_ATTACH_DIR, safe + ".json")
        _write_json_atomic(path, _redact_obj(evidence), label="evidence attachment")
        return path
    except Exception:
        return None

