def _new_ssl_context() -> ssl.SSLContext:
    ctx = ssl.create_default_context()
    if not _TLS_VERIFY:
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
    return ctx

_CTX = _new_ssl_context()

_POOL_MANAGER: Optional[object] = None
_PROXY_MANAGER: Optional[object] = None
_PROXY_MANAGERS: Dict[str, object] = {}
_POOL_LOCK = threading.Lock()
_LAST_PROXY_FOR_MGR: Optional[str] = None

_DNS_CACHE: Dict[str, Tuple[str, float]] = {}
_DNS_CACHE_LOCK = threading.Lock()
_DNS_TTL = 300.0
_DNS_INFLIGHT: Dict[str, threading.Event] = {}
_DNS_INFLIGHT_LOCK = threading.Lock()

def _configure_tls_verify(enabled: bool) -> None:
    global _TLS_VERIFY, _CTX, _POOL_MANAGER, _PROXY_MANAGER, _LAST_PROXY_FOR_MGR
    _TLS_VERIFY = bool(enabled)
    _CTX = _new_ssl_context()
    _sync_scan_config_from_globals()
    with _POOL_LOCK:
        _POOL_MANAGER = None
        _PROXY_MANAGER = None
        _PROXY_MANAGERS.clear()
        _LAST_PROXY_FOR_MGR = None

def _get_pool_manager():
    global _POOL_MANAGER
    if _POOL_MANAGER is not None:
        return _POOL_MANAGER
    with _POOL_LOCK:
        if _POOL_MANAGER is None:
            _POOL_MANAGER = urllib3.PoolManager(
                num_pools=128,
                maxsize=256,
                block=False,
                ssl_context=_CTX,
                cert_reqs="CERT_REQUIRED" if _TLS_VERIFY else "CERT_NONE",
                assert_hostname=None if _TLS_VERIFY else False,
                retries=False,
                timeout=urllib3.Timeout(connect=6.0, read=15.0),
            )
    return _POOL_MANAGER

def _get_proxy_manager(proxy_url: str):
    global _PROXY_MANAGER, _LAST_PROXY_FOR_MGR
    if proxy_url in _PROXY_MANAGERS:
        return _PROXY_MANAGERS[proxy_url]
    with _POOL_LOCK:
        if proxy_url not in _PROXY_MANAGERS:
            scheme = urllib.parse.urlparse(proxy_url).scheme.lower()
            manager_cls = urllib3.ProxyManager
            if scheme.startswith("socks"):
                if not _HAS_URLLIB3_SOCKS or _SOCKSProxyManager is None:
                    raise RuntimeError("SOCKS proxy support requires PySocks")
                manager_cls = _SOCKSProxyManager
            _PROXY_MANAGER = manager_cls(
                    proxy_url,
                    num_pools=128,
                    maxsize=256,
                    block=False,
                    ssl_context=_CTX,
                    cert_reqs="CERT_REQUIRED" if _TLS_VERIFY else "CERT_NONE",
                    assert_hostname=None if _TLS_VERIFY else False,
                    retries=False,
                    timeout=urllib3.Timeout(connect=6.0, read=15.0),
                )
            _PROXY_MANAGERS[proxy_url] = _PROXY_MANAGER
            _LAST_PROXY_FOR_MGR = proxy_url
    return _PROXY_MANAGERS[proxy_url]

def _proxy_kind(proxy_url: Optional[str]) -> str:
    if not proxy_url:
        return "DIRECT"
    scheme = urllib.parse.urlparse(proxy_url).scheme.lower()
    if scheme in ("socks4", "socks4h"):
        return "SOCKS4"
    if scheme in ("socks5", "socks5h"):
        return "SOCKS5"
    return scheme.upper() if scheme else "HTTP"

def _proxy_display(proxy_url: Optional[str]) -> str:
    if not proxy_url:
        return "DIRECT"
    return "--%s-- %s" % (_proxy_kind(proxy_url), proxy_url)

def _normalize_proxy_url(raw: str, default_scheme: str = "http") -> Optional[str]:
    return _normalize_proxy_url_basic(raw, default_scheme=default_scheme)

def _load_proxy_file(path: str, default_scheme: str = "http") -> List[str]:
    global _PROXY_FILE_INVALID_COUNT, _PROXY_FILE_INVALID_EXAMPLES
    proxies: List[str] = []
    _PROXY_FILE_INVALID_COUNT = 0
    _PROXY_FILE_INVALID_EXAMPLES = []
    try:
        with open(path, "r", encoding="utf-8") as f:
            for lineno, line in enumerate(f, 1):
                proxy = _normalize_proxy_url(line, default_scheme=default_scheme)
                if proxy:
                    proxies.append(proxy)
                elif line.strip() and not line.lstrip().startswith("#"):
                    _PROXY_FILE_INVALID_COUNT += 1
                    if len(_PROXY_FILE_INVALID_EXAMPLES) < 5:
                        _PROXY_FILE_INVALID_EXAMPLES.append("%d:%s" % (lineno, line.strip()[:80]))
    except Exception as e:
        _out(_paint("  [proxy] unable to read proxy file %s: %s" % (path, e), A.Y))
    return proxies

def _print_proxy_diagnostics(source: str, loaded: int) -> None:
    if not source:
        return
    msg = "  [proxy] parsed %d valid proxy/proxies from %s" % (loaded, source)
    if _PROXY_FILE_INVALID_COUNT:
        msg += "  invalid=%d" % _PROXY_FILE_INVALID_COUNT
    _out(_paint(msg, A.C if loaded else A.Y))
    for example in _PROXY_FILE_INVALID_EXAMPLES:
        _out(_paint("  [proxy] invalid line " + example, A.Y))
    if any(urllib.parse.urlparse(p).scheme.lower().startswith("socks") for p in _GLOBAL_PROXIES):
        if _HAS_URLLIB3_SOCKS:
            _out(_paint("  [proxy] SOCKS4/SOCKS5 support enabled", A.C))
        else:
            _out(_paint("  [proxy] SOCKS proxies configured, but PySocks is missing; install PySocks or use HTTP/HTTPS proxies", A.Y))


def _default_proxy_files() -> List[Tuple[str, str, str]]:
    root = os.path.dirname(os.path.abspath(__file__))
    folder = os.path.join(root, "proxies")
    typed = [
        (os.path.join(folder, "http.txt"), "HTTP", "http"),
        (os.path.join(folder, "socks4.txt"), "SOCKS4", "socks4"),
        (os.path.join(folder, "socks5.txt"), "SOCKS5", "socks5"),
    ]
    known = {os.path.abspath(path).lower() for path, _, _ in typed}
    if os.path.isdir(folder):
        for name in sorted(os.listdir(folder)):
            path = os.path.join(folder, name)
            if not name.lower().endswith(".txt") or not os.path.isfile(path):
                continue
            if os.path.abspath(path).lower() in known:
                continue
            lname = name.lower()
            if "socks5" in lname:
                typed.append((path, "SOCKS5 user", "socks5"))
            elif "socks4" in lname:
                typed.append((path, "SOCKS4 user", "socks4"))
            else:
                typed.append((path, "HTTP user", "http"))
    legacy = _default_proxy_file_basic(__file__)
    if os.path.exists(legacy):
        typed.append((legacy, "legacy", "http"))
    return typed

def _resolve_output_path(path: Optional[str], subdir: str = "reports") -> Optional[str]:
    return _paths_resolve_output_path(path, _OUTPUT_DIR, subdir)


def _default_template_path() -> str:
    return _paths_default_template_path(__file__)

def _default_fuzz_wordlist_path() -> str:
    return _paths_default_fuzz_wordlist_path(__file__)

def _configure_proxies(values: List[str], strategy: str = "round-robin") -> None:
    global _GLOBAL_PROXY, _GLOBAL_PROXIES, _PROXY_STRATEGY, _PROXY_INDEX, _PROXIES_ENABLED
    global _PROXY_FAILURES, _PROXY_SUCCESSES, _PROXY_CIRCUIT_WARNED
    cleaned: List[str] = []
    seen: Set[str] = set()
    for value in values:
        for part in str(value).split(","):
            proxy = _normalize_proxy_url(part)
            if proxy and proxy not in seen:
                seen.add(proxy)
                cleaned.append(proxy)
    with _PROXY_LOCK:
        _GLOBAL_PROXIES = cleaned
        _GLOBAL_PROXY = cleaned[0] if cleaned else None
        _PROXY_STRATEGY = strategy if strategy in ("round-robin", "random", "sticky") else "round-robin"
        _PROXY_INDEX = 0
        _PROXIES_ENABLED = bool(cleaned)
        _PROXY_BAD_UNTIL.clear()
        _PROXY_FAILURES = 0
        _PROXY_SUCCESSES = 0
        _PROXY_CIRCUIT_WARNED = False
        _PROXY_FAILURE_DETAILS.clear()

def _split_csv(value: Optional[str]) -> Set[str]:
    return _paths_split_csv(value)

def _set_proxies_enabled(enabled: bool) -> None:
    global _PROXIES_ENABLED
    with _PROXY_LOCK:
        _PROXIES_ENABLED = bool(enabled)

def _proxy_mark_failure(proxy: Optional[str], cooldown: float = 300.0, reason: str = "") -> None:
    global _PROXIES_ENABLED, _PROXY_FAILURES, _PROXY_CIRCUIT_WARNED
    if not proxy:
        return
    warn = False
    with _PROXY_LOCK:
        _PROXY_BAD_UNTIL[proxy] = time.monotonic() + cooldown
        _PROXY_FAILURES += 1
        detail = _PROXY_FAILURE_DETAILS.setdefault(proxy, {"failures": 0, "successes": 0, "last_reason": "", "last_failure": 0.0})
        detail["failures"] = int(detail.get("failures", 0)) + 1
        detail["last_reason"] = (reason or "connection failure")[:160]
        detail["last_failure"] = round(time.time(), 3)
        if _PROXY_FAILURE_DISABLE_THRESHOLD > 0 and _PROXY_FAILURES >= _PROXY_FAILURE_DISABLE_THRESHOLD and _PROXY_SUCCESSES == 0:
            _PROXIES_ENABLED = False
            warn = not _PROXY_CIRCUIT_WARNED
            _PROXY_CIRCUIT_WARNED = True
    if warn and not _QUIET_MODE:
        mode = "failed proxied requests will fail closed" if not _PROXY_DIRECT_FALLBACK else "continuing direct"
        _out(_paint(
            "  [proxy] disabling proxies after %d failed attempt(s); %s. "
            "Use --proxy-failure-threshold 0 to never auto-disable."
            % (_PROXY_FAILURES, mode),
            A.Y,
        ))

def _proxy_mark_success(proxy: Optional[str]) -> None:
    global _PROXY_SUCCESSES
    if not proxy:
        return
    with _PROXY_LOCK:
        _PROXY_SUCCESSES += 1
        detail = _PROXY_FAILURE_DETAILS.setdefault(proxy, {"failures": 0, "successes": 0, "last_reason": "", "last_failure": 0.0})
        detail["successes"] = int(detail.get("successes", 0)) + 1
        _PROXY_BAD_UNTIL.pop(proxy, None)

def _proxy_runtime_report() -> Dict[str, Any]:
    with _PROXY_LOCK:
        proxies = list(_GLOBAL_PROXIES)
        details = json.loads(json.dumps(_PROXY_FAILURE_DETAILS))
        disabled = not _PROXIES_ENABLED and bool(_GLOBAL_PROXIES)
    rows: List[Dict[str, Any]] = []
    for proxy in sorted(set(proxies) | set(details.keys())):
        item = details.get(proxy, {})
        rows.append({
            "proxy": proxy,
            "type": _proxy_kind(proxy),
            "failures": int(item.get("failures", 0) or 0),
            "successes": int(item.get("successes", 0) or 0),
            "last_reason": item.get("last_reason", ""),
            "quarantined": _PROXY_BAD_UNTIL.get(proxy, 0.0) > time.monotonic(),
        })
    return {
        "configured": len(proxies),
        "enabled": not disabled,
        "direct_fallback": _PROXY_DIRECT_FALLBACK,
        "required": _PROXY_REQUIRED,
        "strategy": _PROXY_STRATEGY,
        "total_failures": _PROXY_FAILURES,
        "total_successes": _PROXY_SUCCESSES,
        "unsupported": list(_PROXY_UNSUPPORTED_EXAMPLES),
        "proxies": rows,
    }

def _print_proxy_runtime_report() -> None:
    report = _proxy_runtime_report()
    if not report["configured"] and not report["unsupported"]:
        return
    _out("  " + _u3("PROXY".ljust(9), _UI3["dim"]) + ":: "
         + _u3("configured=%d ok=%d failed=%d fallback=%s" % (
             report["configured"], report["total_successes"], report["total_failures"],
             "off" if not report["direct_fallback"] else "on",
         ), _UI3["dim"]))
    failed = [p for p in report["proxies"] if p.get("failures")]
    for item in sorted(failed, key=lambda x: (-int(x.get("failures", 0)), x.get("proxy", "")))[:8]:
        _out("  " + _u3("PROXY".ljust(9), _UI3["dim"]) + ":: "
             + _u3("--%s-- %s failures=%s successes=%s reason=%s" % (
                 item.get("type", "HTTP"),
                 item.get("proxy", ""),
                 item.get("failures", 0),
                 item.get("successes", 0),
                 item.get("last_reason", "") or "unknown",
             ), _UI3["dim"]))

def _network_failure(reason: str = "") -> None:
    global _NETWORK_FAILURES
    _NETWORK_FAILURES += 1
    if _NETWORK_FAIL_FAST_THRESHOLD > 0 and _NETWORK_FAILURES >= _NETWORK_FAIL_FAST_THRESHOLD:
        _NETWORK_FAIL_FAST_EVENT.set()
        if not _QUIET_MODE and _NETWORK_FAILURES == _NETWORK_FAIL_FAST_THRESHOLD:
            _out(_paint("  [net] fail-fast triggered after %d network failures%s" % (
                _NETWORK_FAILURES,
                (": " + reason) if reason else "",
            ), A.Y))

def _network_result_failure(key: Optional[str], url: str, reason: str = "") -> Tuple[int, Dict[str, str], bytes, str]:
    _network_failure(reason)
    return _inflight_notify(key, (0, {}, b"", url))

def _proxy_healthcheck(base: str, proxies: List[str], timeout: float = 5.0) -> Tuple[List[str], List[Tuple[str, str]]]:
    good: List[str] = []
    bad: List[Tuple[str, str]] = []
    headers = {"User-Agent": _GLOBAL_UA, "Accept": "*/*"}
    for proxy in proxies:
        try:
            if _HAS_URLLIB3:
                try:
                    mgr = _get_proxy_manager(proxy)
                    resp = mgr.request(
                        "HEAD",
                        base,
                        headers=headers,
                        timeout=urllib3.Timeout(connect=min(timeout, 5.0), read=timeout),
                        redirect=True,
                        retries=False,
                        preload_content=False,
                    )
                    try:
                        if resp.status:
                            good.append(proxy)
                            continue
                    finally:
                        resp.release_conn()
                except Exception:
                    pass
            if urllib.parse.urlparse(proxy).scheme.lower().startswith("socks"):
                bad.append((proxy, "SOCKS healthcheck requires urllib3/PySocks"))
                continue
            req = urllib.request.Request(base, headers=headers, method="HEAD")
            opener = urllib.request.build_opener(
                urllib.request.ProxyHandler({"http": proxy, "https": proxy}),
                urllib.request.HTTPSHandler(context=_CTX),
            )
            try:
                with opener.open(req, timeout=timeout) as resp:
                    if resp.getcode():
                        good.append(proxy)
                        continue
            except urllib.error.HTTPError:
                good.append(proxy)
                continue
            except Exception:
                req = urllib.request.Request(base, headers=headers, method="GET")
                with opener.open(req, timeout=timeout) as resp:
                    if resp.getcode():
                        good.append(proxy)
                        continue
            bad.append((proxy, "no response"))
        except Exception as exc:
            bad.append((proxy, str(exc).splitlines()[0][:120]))
    return good, bad

def _run_proxy_healthcheck(base: str) -> bool:
    if not _GLOBAL_PROXIES:
        _out(_paint("  [proxy] healthcheck skipped: no proxies configured", A.Y))
        return not _PROXY_REQUIRED
    _out(_paint("  [proxy] healthchecking %d proxy/proxies against %s" % (len(_GLOBAL_PROXIES), base), A.C))
    good, bad = _proxy_healthcheck(base, list(_GLOBAL_PROXIES))
    _out(_paint("  [proxy] healthcheck result: good=%d bad=%d" % (len(good), len(bad)), A.G if good else A.Y))
    for proxy, reason in bad[:5]:
        _out(_paint("  [proxy] bad " + _proxy_display(proxy) + " :: " + reason, A.Y))
    for proxy, reason in bad:
        with _PROXY_LOCK:
            detail = _PROXY_FAILURE_DETAILS.setdefault(proxy, {"failures": 0, "successes": 0, "last_reason": "", "last_failure": 0.0})
            detail["failures"] = int(detail.get("failures", 0)) + 1
            detail["last_reason"] = reason[:160]
            detail["last_failure"] = round(time.time(), 3)
    for proxy in good:
        with _PROXY_LOCK:
            detail = _PROXY_FAILURE_DETAILS.setdefault(proxy, {"failures": 0, "successes": 0, "last_reason": "", "last_failure": 0.0})
            detail["successes"] = int(detail.get("successes", 0)) + 1
    if good:
        if len(good) != len(_GLOBAL_PROXIES):
            _configure_proxies(good, _PROXY_STRATEGY)
        return True
    if _PROXY_REQUIRED:
        _out(_paint("  [proxy] required proxy mode is enabled and no proxy passed healthcheck", A.R))
        return False
    _set_proxies_enabled(False)
    _out(_paint("  [proxy] no healthy proxies; continuing direct. Use --proxy-required to fail closed.", A.Y))
    return True

def _select_proxy() -> Optional[str]:
    global _PROXY_INDEX
    with _PROXY_LOCK:
        if not _PROXIES_ENABLED:
            return None
        if _GLOBAL_PROXIES:
            now = time.monotonic()
            if _PROXY_STRATEGY == "random":
                candidates = [p for p in _GLOBAL_PROXIES if _PROXY_BAD_UNTIL.get(p, 0.0) <= now]
                return random.choice(candidates or _GLOBAL_PROXIES)
            if _PROXY_STRATEGY == "sticky":
                return _GLOBAL_PROXIES[0]
            for _ in range(len(_GLOBAL_PROXIES)):
                proxy = _GLOBAL_PROXIES[_PROXY_INDEX % len(_GLOBAL_PROXIES)]
                _PROXY_INDEX += 1
                if _PROXY_BAD_UNTIL.get(proxy, 0.0) <= now:
                    return proxy
            return None
        return _GLOBAL_PROXY

_orig_getaddrinfo = socket.getaddrinfo

def _cached_getaddrinfo(host, port, *args, **kwargs):
    if not isinstance(host, str) or not host:
        return _orig_getaddrinfo(host, port, *args, **kwargs)
    key = "%s:%s" % (host, port)
    now = time.time()
    with _DNS_CACHE_LOCK:
        cached = _DNS_CACHE.get(key)
        if cached and cached[1] > now:
            return cached[0]
    leader = False
    waiter_ev: threading.Event
    with _DNS_INFLIGHT_LOCK:
        if key in _DNS_INFLIGHT:
            waiter_ev = _DNS_INFLIGHT[key]
        else:
            waiter_ev = threading.Event()
            _DNS_INFLIGHT[key] = waiter_ev
            leader = True
    if not leader:
        waiter_ev.wait(timeout=30.0)
        with _DNS_CACHE_LOCK:
            cached = _DNS_CACHE.get(key)
            if cached and cached[1] > time.time():
                return cached[0]
        return _orig_getaddrinfo(host, port, *args, **kwargs)
    try:
        result = _orig_getaddrinfo(host, port, *args, **kwargs)
        with _DNS_CACHE_LOCK:
            _DNS_CACHE[key] = (result, time.time() + _DNS_TTL)
        return result
    finally:
        with _DNS_INFLIGHT_LOCK:
            _DNS_INFLIGHT.pop(key, None)
        waiter_ev.set()

if _HAS_URLLIB3:
    socket.getaddrinfo = _cached_getaddrinfo

def _dns_prefetch(urls: List[str]) -> None:
    hosts: set = set()
    for u in urls:
        h = _host_of(u)
        if h:
            hosts.add(h)
    if not hosts:
        return
    def _resolve(h: str) -> None:
        try:
            _cached_getaddrinfo(h, 443)
        except Exception:
            try:
                _cached_getaddrinfo(h, 80)
            except Exception:
                pass
    with ThreadPoolExecutor(max_workers=min(32, len(hosts))) as ex:
        list(ex.map(_resolve, hosts))

