_RATE_LIMIT: float = 0.0
_RATE_TOKENS: float = 0.0
_RATE_LAST_REFILL: float = 0.0
_RATE_LOCK = threading.Lock()
_RATE_COND = threading.Condition(_RATE_LOCK)

_HOST_BACKOFF_UNTIL: Dict[str, float] = {}
_HOST_BACKOFF_LOCK = threading.Lock()
_BACKOFF_BASE = 1.0
_BACKOFF_MAX = 60.0
_HOST_429_STREAK: Dict[str, int] = {}

def _rate_limit_acquire() -> None:
    global _RATE_TOKENS, _RATE_LAST_REFILL
    if _RATE_LIMIT <= 0:
        return
    with _RATE_COND:
        while True:
            now = time.monotonic()
            elapsed = now - _RATE_LAST_REFILL
            if elapsed > 0:
                old_int = int(_RATE_TOKENS)
                _RATE_TOKENS = min(_RATE_LIMIT, _RATE_TOKENS + elapsed * _RATE_LIMIT)
                _RATE_LAST_REFILL = now
                added = int(_RATE_TOKENS) - old_int
                if added > 0:
                    _RATE_COND.notify(added)
            if _RATE_TOKENS >= 1.0:
                _RATE_TOKENS -= 1.0
                return
            wait = (1.0 - _RATE_TOKENS) / _RATE_LIMIT
            _RATE_COND.wait(timeout=wait)

def _backoff_check(host: str) -> None:
    if not host or not _HOST_BACKOFF_UNTIL:
        return
    with _HOST_BACKOFF_LOCK:
        until = _HOST_BACKOFF_UNTIL.get(host, 0.0)
    if until > 0:
        now = time.monotonic()
        if until > now:
            time.sleep(min(until - now, _BACKOFF_MAX))

def _backoff_register(host: str, retry_after: Optional[str]) -> None:
    if not host:
        return
    with _HOST_BACKOFF_LOCK:
        streak = _HOST_429_STREAK.get(host, 0) + 1
        _HOST_429_STREAK[host] = streak
        wait = _BACKOFF_BASE * (2 ** min(streak - 1, 6))
        wait = min(wait, _BACKOFF_MAX)
        if retry_after:
            try:
                ra = float(retry_after.strip())
                wait = max(wait, min(ra, _BACKOFF_MAX))
            except (ValueError, AttributeError):
                pass
        _HOST_BACKOFF_UNTIL[host] = time.monotonic() + wait
        if _VERBOSE:
            _out(_paint("  [backoff] %s cooling down %.1fs (streak=%d)" % (host, wait, streak), A.Y))

def _backoff_reset(host: str) -> None:
    if not host:
        return
    with _HOST_BACKOFF_LOCK:
        if host in _HOST_429_STREAK:
            del _HOST_429_STREAK[host]
        if host in _HOST_BACKOFF_UNTIL:
            del _HOST_BACKOFF_UNTIL[host]

def _parallel_map(fn: Callable, items: list, workers: int = 8) -> list:
    if workers <= 1 or len(items) <= 1:
        return [fn(it) for it in items]
    out = []
    with ThreadPoolExecutor(max_workers=min(workers, len(items))) as ex:
        futs = [ex.submit(fn, it) for it in items]
        for f in as_completed(futs):
            try:
                r = f.result()
                if r is not None:
                    out.append(r)
            except Exception as e:
                if _VERBOSE:
                    _out(_paint("  [parallel_map] worker error: %s" % e, A.Y))
    return out

def _par_scan(fn: Callable, items: list, workers: int = 12) -> "ScanFindings":
    out: list = []
    for chunk in _parallel_map(fn, items, workers=min(workers, len(items)) if items else 1):
        if chunk:
            out.extend(chunk)
    return out

def _inflight_notify(key: Optional[str], result: Tuple) -> Tuple:
    if key is not None:
        with _INFLIGHT_RES_LOCK:
            _INFLIGHT_RESULTS[key] = result
        with _INFLIGHT_LOCK:
            ev = _INFLIGHT.pop(key, None)
        if ev:
            ev.set()
    return result

def _build_request_headers(
    extra_headers: Optional[Dict[str, str]],
    content_type: Optional[str],
) -> Dict[str, str]:
    global _HEADERS_BASE_CACHE, _HEADERS_BASE_STAMP
    cfg = _SCAN_CONFIG
    stamp = (cfg.user_agent, _GLOBAL_HEADERS_VER)
    if _HEADERS_BASE_CACHE is None or stamp != _HEADERS_BASE_STAMP:
        base: Dict[str, str] = {"User-Agent": cfg.user_agent, "Accept": "*/*", "Connection": "keep-alive"}
        base.update(cfg.headers)
        _HEADERS_BASE_CACHE = base
        _HEADERS_BASE_STAMP = stamp
    if not extra_headers and not content_type:
        return _HEADERS_BASE_CACHE
    h = dict(_HEADERS_BASE_CACHE)
    if extra_headers:
        h.update(extra_headers)
    if content_type:
        h["Content-Type"] = content_type
    return h

def _check_all_caches(
    url: str,
    method: str,
    data: Optional[bytes],
    headers: Optional[Dict[str, str]],
    use_cache: bool = False,
) -> Optional[Tuple]:
    if not _REQUEST_CACHE_ENABLED:
        _REQUEST_CACHE_STATS["misses"] = _REQUEST_CACHE_STATS.get("misses", 0) + 1
        return None
    if method == "GET" and data is None and not headers:
        with _FAST_CACHE_LOCK:
            cached = _FAST_RESPONSE_CACHE.get(url)
        if cached is not None:
            _REQUEST_CACHE_STATS["hits"] = _REQUEST_CACHE_STATS.get("hits", 0) + 1
            return cached
        if not use_cache:
            with _INFLIGHT_RES_LOCK:
                ir = _INFLIGHT_RESULTS.get(url)
            if ir is not None:
                _REQUEST_CACHE_STATS["inflight_hits"] = _REQUEST_CACHE_STATS.get("inflight_hits", 0) + 1
                return ir
    if use_cache and method == "GET" and data is None:
        with _BASE_CACHE_LOCK:
            if url in _BASE_CACHE:
                _REQUEST_CACHE_STATS["hits"] = _REQUEST_CACHE_STATS.get("hits", 0) + 1
                return _BASE_CACHE[url]
    _REQUEST_CACHE_STATS["misses"] = _REQUEST_CACHE_STATS.get("misses", 0) + 1
    return None

def _capture_http_evidence(
    method: str,
    url: str,
    req_headers: Optional[Dict[str, str]],
    req_body: Optional[bytes],
    code: int,
    resp_headers: Dict[str, str],
    resp_body: bytes,
    final_url: str,
) -> None:
    if not _HTTP_EVIDENCE_ENABLED:
        return
    with _HTTP_EVIDENCE_LOCK:
        if len(_HTTP_EVIDENCE_LOG) >= _HTTP_EVIDENCE_LIMIT:
            return
        body_sample = resp_body[:2048].decode("utf-8", "replace") if resp_body else ""
        req_sample = req_body[:1024].decode("utf-8", "replace") if req_body else ""
        _HTTP_EVIDENCE_LOG.append(_redact_obj({
            "ts": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "module": _CURRENT_SCAN_MODULE or getattr(_SCAN_THREAD, "module", ""),
            "request": {
                "method": method,
                "url": url,
                "headers": req_headers or {},
                "body_sample": req_sample,
            },
            "response": {
                "status": code,
                "final_url": final_url,
                "headers": resp_headers,
                "body_len": len(resp_body or b""),
                "body_sample": body_sample,
            },
        }))

def _maybe_refresh_session() -> None:
    global _SESSION_REFRESH_LAST
    if not _SESSION_REFRESH_URL or _SESSION_REFRESH_EVERY <= 0:
        return
    now = time.monotonic()
    if _SESSION_REFRESH_LAST and now - _SESSION_REFRESH_LAST < _SESSION_REFRESH_EVERY:
        return
    with _SESSION_REFRESH_LOCK:
        now = time.monotonic()
        if _SESSION_REFRESH_LAST and now - _SESSION_REFRESH_LAST < _SESSION_REFRESH_EVERY:
            return
        _SESSION_REFRESH_LAST = now
    try:
        _req(_SESSION_REFRESH_URL, timeout=min(_GLOBAL_TIMEOUT, 6.0), use_cache=False)
        if _VERBOSE:
            _out(_paint("  [auth] refreshed session via " + _SESSION_REFRESH_URL, A.D))
    except Exception:
        pass

def _merge_response_cookies(set_cookie: str) -> None:
    global _GLOBAL_HEADERS_VER
    if not _SESSION_JAR_ENABLED or not set_cookie:
        return
    existing: Dict[str, str] = {}
    for part in re.split(r";\s*|,\s*(?=[A-Za-z0-9_.-]+=)", _GLOBAL_HEADERS.get("Cookie", "")):
        if "=" in part:
            k, v = part.split("=", 1)
            if k.strip():
                existing[k.strip()] = v.strip()
    changed = False
    for line in re.split(r"\r-\n", set_cookie):
        m = re.match(r"\s*([A-Za-z0-9_.-]+)=([^;]*)", line)
        if not m:
            continue
        name, value = m.group(1), m.group(2)
        if existing.get(name) != value:
            existing[name] = value
            changed = True
    if changed:
        _GLOBAL_HEADERS["Cookie"] = "; ".join("%s=%s" % (k, v) for k, v in sorted(existing.items()))
        _GLOBAL_HEADERS_VER += 1

def _check_logged_out_detector(body: bytes, final_url: str) -> None:
    if not _LOGGED_OUT_PATTERNS:
        return
    text = body[:12000].decode("utf-8", "ignore")
    sample = final_url + "\n" + text
    for pattern in _LOGGED_OUT_PATTERNS:
        try:
            matched = re.search(pattern, sample, re.I) is not None
        except re.error:
            matched = pattern.lower() in sample.lower()
        if matched:
            _quality_event("auth", _CURRENT_SCAN_MODULE or "http", "logged-out detector matched: " + pattern[:80])
            if _VERBOSE:
                _out(_paint("  [auth] logged-out detector matched " + pattern[:80], A.Y))
            return

def _refresh_csrf_from_response(body: bytes) -> None:
    global _GLOBAL_HEADERS_VER
    if not _CSRF_REFRESH_ENABLED:
        return
    text = body[:60000].decode("utf-8", "ignore")
    names = [_CSRF_FIELD_NAME] if _CSRF_FIELD_NAME else ["csrf", "csrf_token", "_csrf", "xsrf", "_token"]
    for name in names:
        if not name:
            continue
        pat = r'name=["\']%s["\'][^>]{0,300}value=["\']([^"\']{8,})["\']' % re.escape(name)
        m = re.search(pat, text, re.I)
        if not m:
            pat = r'value=["\']([^"\']{8,})["\'][^>]{0,300}name=["\']%s["\']' % re.escape(name)
            m = re.search(pat, text, re.I)
        if m:
            token = m.group(1)
            if _GLOBAL_HEADERS.get("X-CSRF-Token") != token:
                _GLOBAL_HEADERS["X-CSRF-Token"] = token
                _GLOBAL_HEADERS_VER += 1
            return

def _finalize_response(
    code: int,
    hdrs: Dict[str, str],
    body: bytes,
    final_url: str,
    url: str,
    host: str,
    use_cache: bool,
    method: str,
    data: Optional[bytes],
    req_headers: Optional[Dict[str, str]],
    inflight_key: Optional[str],
) -> Tuple[int, Dict[str, str], bytes, str]:
    result = (code, hdrs, body, final_url)
    if _VERBOSE and len(body) == _GLOBAL_MAX_BODY:
        _out(_paint("  [warn] response body capped at %d bytes for %s -- analysis may be incomplete"
                    % (_GLOBAL_MAX_BODY, url), A.Y))
    _merge_response_cookies(hdrs.get("set-cookie", ""))
    if method == "GET" and 200 <= code < 400:
        _refresh_csrf_from_response(body)
    _check_logged_out_detector(body, final_url)
    if code in (429, 503):
        _backoff_register(host, hdrs.get("retry-after"))
        _module_throttle_event(_CURRENT_SCAN_MODULE or getattr(_SCAN_THREAD, "module", ""), code)
        if _ADAPTIVE_RATE_ENABLED:
            _quality_event("throttle", _CURRENT_SCAN_MODULE or "http", "adaptive slowdown after HTTP %d" % code)
            time.sleep(min(3.0, 0.25 + len(_HOST_429_STREAK) * 0.1))
    elif 200 <= code < 400:
        _backoff_reset(host)
    if use_cache and method == "GET" and data is None:
        with _BASE_CACHE_LOCK:
            _BASE_CACHE[url] = result
    if method == "GET" and data is None and not req_headers and 200 <= code < 500:
        with _FAST_CACHE_LOCK:
            if url not in _FAST_RESPONSE_CACHE and len(_FAST_RESPONSE_CACHE) >= _FAST_RESPONSE_MAX:
                _FAST_RESPONSE_CACHE.popitem(last=False)
            _FAST_RESPONSE_CACHE[url] = result
            _REQUEST_CACHE_STATS["stored"] = _REQUEST_CACHE_STATS.get("stored", 0) + 1
    _capture_http_evidence(method, url, req_headers, data, code, hdrs, body, final_url)
    return _inflight_notify(inflight_key, result)

def _req(
    url: str,
    method: str = "GET",
    data: Optional[bytes] = None,
    headers: Optional[Dict[str, str]] = None,
    timeout: Optional[float] = None,
    content_type: Optional[str] = None,
    use_cache: bool = False,
) -> Tuple[int, Dict[str, str], bytes, str]:
    cached = _check_all_caches(url, method, data, headers, use_cache)
    if cached is not None:
        return cached
    if _NETWORK_FAIL_FAST_EVENT.is_set():
        return (0, {}, b"", url)
    if not (_SESSION_REFRESH_URL and url == _SESSION_REFRESH_URL):
        _maybe_refresh_session()
    _inflight_key: Optional[str] = None
    _inflight_leader: bool = False
    _inflight_evt: Optional[threading.Event] = None
    if method == "GET" and data is None and not headers:
        with _INFLIGHT_LOCK:
            if url in _INFLIGHT:
                _inflight_evt = _INFLIGHT[url]
            else:
                _inflight_evt = threading.Event()
                _INFLIGHT[url] = _inflight_evt
                _inflight_leader = True
                _inflight_key = url
        if not _inflight_leader:
            _t_eff = _ADAPTIVE_TIMEOUT if _ADAPTIVE_TIMEOUT > 0 else _GLOBAL_TIMEOUT
            _inflight_evt.wait(timeout=_t_eff + 2.0)
            with _INFLIGHT_RES_LOCK:
                _r = _INFLIGHT_RESULTS.get(url)
            return _r if _r is not None else (0, {}, b"", url)
    _budget_label = _CURRENT_SCAN_MODULE
    if _budget_label and not _REQUEST_BUDGETS.allow_request(_budget_label):
        _quality_event("timeout", _budget_label, "request budget exhausted")
        if _VERBOSE:
            _out(_paint("  [budget] " + _budget_label + " request budget exhausted", A.Y))
        return _inflight_notify(_inflight_key, (0, {}, b"", url))
    if _GLOBAL_DELAY > 0:
        time.sleep(_GLOBAL_DELAY)
    _host = _host_of(url)
    _backoff_check(_host)
    _module_throttle_before_request(_CURRENT_SCAN_MODULE or getattr(_SCAN_THREAD, "module", ""))
    _rate_limit_acquire()
    _now_ts = time.monotonic()
    with _REQ_TS_LOCK:
        _REQ_TIMESTAMPS.append(_now_ts)
        _REQ_COUNT_10S_QUEUE.append(_now_ts)
    h = _build_request_headers(headers, content_type)
    _coverage_record_request(url, method, data, content_type)
    eff_timeout = _ADAPTIVE_TIMEOUT if _ADAPTIVE_TIMEOUT > 0 else _GLOBAL_TIMEOUT
    t = timeout if timeout is not None else eff_timeout
    proxy_url = _select_proxy()
    proxy_timeout = min(t, 1.5) if proxy_url and _PROXY_DIRECT_FALLBACK else t
    if _VERBOSE:
        via = (" via " + _proxy_display(proxy_url)) if proxy_url else ""
        _out(_paint("  --> " + method + " " + url + via, A.D))

    proxy_is_socks = bool(proxy_url and urllib.parse.urlparse(proxy_url).scheme.lower().startswith("socks"))
    if _HAS_URLLIB3:
        try:
            mgr = _get_proxy_manager(proxy_url) if proxy_url else _get_pool_manager()
            resp = mgr.request(
                method,
                url,
                body=data,
                headers=h,
                timeout=urllib3.Timeout(connect=min(proxy_timeout, 10.0), read=proxy_timeout),
                redirect=True,
                retries=False,
                preload_content=False,
                decode_content=True,
            )
            try:
                hdrs = {k.lower(): v for k, v in resp.headers.items()}
                try:
                    all_sc = resp.headers.getlist("Set-Cookie")
                except AttributeError:
                    all_sc = []
                if all_sc:
                    hdrs["set-cookie"] = "\n".join(all_sc)
                body = resp.read(_GLOBAL_MAX_BODY)
                code = resp.status or 200
                try:
                    raw_final = resp.geturl() if hasattr(resp, "geturl") else None
                except Exception:
                    raw_final = None
                if raw_final and raw_final != url:
                    final_url = urllib.parse.urljoin(url, raw_final)
                else:
                    final_url = url
                _proxy_mark_success(proxy_url)
                return _finalize_response(code, hdrs, body, final_url, url, _host, use_cache, method, data, headers, _inflight_key)
            finally:
                resp.release_conn()
        except urllib3.exceptions.MaxRetryError as e:
            if _VERBOSE:
                _out(_paint("  [net] " + method + " " + url + "  -- MaxRetryError: " + str(e.reason), A.D))
            if proxy_url:
                _proxy_mark_failure(proxy_url, reason=str(e.reason)[:160])
            if proxy_url and _PROXY_DIRECT_FALLBACK:
                if _VERBOSE:
                    _out(_paint("  [proxy] " + _proxy_display(proxy_url) + " failed; retrying direct", A.D))
                proxy_url = None
            else:
                return _network_result_failure(_inflight_key, url, "urllib3 max retry")
        except urllib3.exceptions.HTTPError as e:
            if _VERBOSE:
                _out(_paint("  [net] " + method + " " + url + "  -- " + type(e).__name__ + ": " + str(e), A.D))
            if proxy_url:
                _proxy_mark_failure(proxy_url, reason=type(e).__name__ + ": " + str(e)[:140])
            if proxy_url and _PROXY_DIRECT_FALLBACK:
                if _VERBOSE:
                    _out(_paint("  [proxy] " + _proxy_display(proxy_url) + " failed; retrying direct", A.D))
                proxy_url = None
            else:
                return _network_result_failure(_inflight_key, url, type(e).__name__)
        except Exception as e:
            if _VERBOSE:
                _out(_paint("  [net] urllib3 path failed (" + type(e).__name__ + "), falling back: " + str(e), A.D))
            if proxy_url:
                _proxy_mark_failure(proxy_url, reason=type(e).__name__ + ": " + str(e)[:140])
            if proxy_url and _PROXY_DIRECT_FALLBACK:
                proxy_url = None
            elif proxy_is_socks:
                return _network_result_failure(_inflight_key, url, "socks proxy failure")

    req = urllib.request.Request(url, data=data, headers=h, method=method)
    try:
        if proxy_url:
            if urllib.parse.urlparse(proxy_url).scheme.lower().startswith("socks"):
                return _network_result_failure(_inflight_key, url, "SOCKS proxy requires urllib3/PySocks transport")
            proxy_handler = urllib.request.ProxyHandler({
                "http":  proxy_url,
                "https": proxy_url,
            })
            opener = urllib.request.build_opener(proxy_handler)
            ctx_handler = urllib.request.HTTPSHandler(context=_CTX)
            opener.add_handler(ctx_handler)
            resp_cm = opener.open(req, timeout=proxy_timeout)
        else:
            resp_cm = urllib.request.urlopen(req, context=_CTX, timeout=t)
        with resp_cm as resp:
            hdrs = {k.lower(): v for k, v in resp.headers.items()}
            all_sc = resp.headers.get_all("set-cookie")
            if all_sc:
                hdrs["set-cookie"] = "\n".join(all_sc)
            body = resp.read(_GLOBAL_MAX_BODY)
            code = resp.getcode() or 200
            _proxy_mark_success(proxy_url)
            return _finalize_response(code, hdrs, body, url, url, _host, use_cache, method, data, headers, _inflight_key)
    except urllib.error.HTTPError as e:
        hdrs = {k.lower(): v for k, v in e.headers.items()} if e.headers else {}
        if e.headers:
            all_sc = e.headers.get_all("set-cookie")
            if all_sc:
                hdrs["set-cookie"] = "\n".join(all_sc)
        try:
            body = e.read(_GLOBAL_MAX_BODY)
        except Exception:
            body = b""
        if e.code in (429, 503):
            _backoff_register(_host, hdrs.get("retry-after"))
        return _inflight_notify(_inflight_key, (e.code, hdrs, body, url))
    except Exception as e:
        if proxy_url and _PROXY_DIRECT_FALLBACK:
            _proxy_mark_failure(proxy_url, reason=type(e).__name__ + ": " + str(e)[:140])
            if _VERBOSE:
                _out(_paint("  [proxy] " + _proxy_display(proxy_url) + " failed in urllib fallback; retrying direct", A.D))
            try:
                with urllib.request.urlopen(req, context=_CTX, timeout=t) as resp:
                    hdrs = {k.lower(): v for k, v in resp.headers.items()}
                    all_sc = resp.headers.get_all("set-cookie")
                    if all_sc:
                        hdrs["set-cookie"] = "\n".join(all_sc)
                    body = resp.read(_GLOBAL_MAX_BODY)
                    code = resp.getcode() or 200
                    return _finalize_response(code, hdrs, body, url, url, _host, use_cache, method, data, headers, _inflight_key)
            except urllib.error.HTTPError as he:
                hdrs = {k.lower(): v for k, v in he.headers.items()} if he.headers else {}
                try:
                    body = he.read(_GLOBAL_MAX_BODY)
                except Exception:
                    body = b""
                return _inflight_notify(_inflight_key, (he.code, hdrs, body, url))
            except Exception:
                pass
        if _VERBOSE:
            _out(_paint("  [net] " + method + " " + url + "  -- " + type(e).__name__ + ": " + str(e), A.D))
        return _network_result_failure(_inflight_key, url, type(e).__name__)

def _req_with_time(
    url: str,
    method: str = "GET",
    data: Optional[bytes] = None,
    headers: Optional[Dict[str, str]] = None,
    timeout: Optional[float] = None,
    content_type: Optional[str] = None,
) -> Tuple[int, Dict[str, str], bytes, str, float]:
    t0 = time.perf_counter()
    code, hdrs, body, u = _req(url, method=method, data=data, headers=headers, timeout=timeout, content_type=content_type)
    elapsed = time.perf_counter() - t0
    if _ORACLE_ACTIVE and _ORACLE is not None and code > 0:
        timing_us = elapsed * 1_000_000
        parsed_u = urllib.parse.urlparse(url)
        param_names = [k for k, _ in urllib.parse.parse_qsl(parsed_u.query)]
        param = param_names[0] if param_names else None
        anomaly = _ORACLE.score_probe(url, method, code, hdrs, body, timing_us, param)
        if anomaly >= _ORACLE_THRESHOLD:
            with _ORACLE_MODULE_LOCK:
                cur = _ORACLE_MODULE_MAX_ANOMALY.get(_CURRENT_SCAN_MODULE, 0.0)
                _ORACLE_MODULE_MAX_ANOMALY[_CURRENT_SCAN_MODULE] = max(cur, anomaly)
    return code, hdrs, body, u, elapsed

_HTTP_CLIENT = HttpClient(_req)

def _scan_context() -> ScanContext:
    return ScanContext(
        config=_SCAN_CONFIG,
        client=_HTTP_CLIENT,
        budgets=_REQUEST_BUDGETS,
        join_url=_join_url,
        category_for_option=category_for_option,
    )


@dataclasses.dataclass
class _OracleWeights:
    timing: float = 0.20
    size:   float = 0.20
    status: float = 0.20
    header: float = 0.15
    schema: float = 0.10
    body:   float = 0.10

_ORACLE_W = _OracleWeights()

class _BehavioralOracle:
    def __init__(self) -> None:
        self._baseline: Dict[str, Dict] = {}
        self._param_heat: Dict[Tuple[str, str], Dict] = {}
        self._param_heat_lock = threading.Lock()
        self._seen_hashes: Dict[str, Set[str]] = {}
        self._probe_records: List[Dict] = []
        self._probe_records_lock = threading.Lock()
        self._fused_findings: List[Dict] = []
        self._endpoint_module_findings: Dict[str, List[str]] = {}
        self._finding_anomalies: Dict[str, float] = {}
        self._finding_anomalies_lock = threading.Lock()
        self._probes_analyzed: int = 0
        self._anomaly_count: int = 0
        self._load_window: collections.deque = collections.deque(maxlen=500)
        self._load_window_lock = threading.Lock()
        self._estimator_type: Dict[str, str] = {}
        self._confirmed_endpoints: Dict[str, float] = {}
        self._post_probe_snapshots: Dict[str, Tuple[int, int, str]] = {}
        self._cross_ep_changes: List[Tuple] = []
        self._alerted_fusions: Set[str] = set()
        self._steered_fusions: Set[str] = set()
        self._steered_pairs: Set[Tuple[str, str]] = set()

    def _benign_value(self) -> str:
        kind = random.randint(0, 3)
        if kind == 0:
            return "".join(random.choices(string.ascii_lowercase, k=random.randint(3, 8)))
        elif kind == 1:
            return str(random.randint(1, 1000))
        elif kind == 2:
            d = datetime.date(2020, 1, 1) + datetime.timedelta(days=random.randint(0, 1000))
            return d.isoformat()
        else:
            return "".join(random.choices(string.ascii_lowercase, k=5))

    def _body_sha1(self, body: bytes) -> str:
        return hashlib.sha1(body).hexdigest()

    def _json_schema(self, body: bytes) -> Optional[str]:
        try:
            obj = json.loads(body)
            return self._type_tree(obj)
        except Exception:
            return None

    def _type_tree(self, obj, depth: int = 0) -> str:
        if depth > 4:
            return type(obj).__name__
        if isinstance(obj, dict):
            sorted_keys = sorted(obj.keys())
            parts = [k + ":" + self._type_tree(obj[k], depth + 1) for k in sorted_keys[:8]]
            tail = ",..." if len(sorted_keys) > 8 else ""
            return "{" + ",".join(parts) + tail + ";n=" + str(len(sorted_keys)) + "}"
        elif isinstance(obj, list):
            if obj:
                return "[" + self._type_tree(obj[0], depth + 1) + "]"
            return "[]"
        return type(obj).__name__

    def _html_tag_vector(self, body: bytes) -> Optional[Dict[str, float]]:
        try:
            text = body.decode("utf-8", "replace")
            tags = re.findall(r"<([a-zA-Z][a-zA-Z0-9]*)", text)
            if not tags:
                return None
            total = len(tags)
            freq: Dict[str, int] = {}
            for t in tags:
                tl = t.lower()
                freq[tl] = freq.get(tl, 0) + 1
            return {k: v / total for k, v in freq.items()}
        except Exception:
            return None

    def _schema_diff(self, body: bytes, fingerprint: Optional[str]) -> float:
        if fingerprint is None:
            return 0.0
        new_schema = self._json_schema(body)
        if new_schema is None:
            return 0.0
        if new_schema != fingerprint:
            tokens_fp = frozenset(re.split(r'[,{}\[\]():]+', fingerprint))
            tokens_new = frozenset(re.split(r'[,{}\[\]():]+', new_schema))
            inter = len(tokens_new & tokens_fp)
            union = len(tokens_new | tokens_fp)
            return 1.0 - (inter / max(union, 1))
        return 0.0

    def _body_entropy_delta(self, body: bytes, ep_key: str) -> float:
        if len(body) < 8:
            return 0.0
        chunk = body[:4096]
        new_cr = len(zlib.compress(chunk)) / max(len(chunk), 1)
        bl = self._baseline.get(ep_key, {})
        baseline_cr = bl.get("compress_ratio_median", new_cr)
        bh = self._body_sha1(body)
        seen = self._seen_hashes.get(ep_key, set())
        if bh in seen:
            return 0.0
        self._seen_hashes.setdefault(ep_key, set()).add(bh)
        cr_delta = abs(new_cr - baseline_cr)
        return min(1.0, cr_delta * 4.0 + 0.3)

    def _sigmoid(self, x: float) -> float:
        x = max(-500.0, min(500.0, x))
        return 1.0 / (1.0 + math.exp(-x))

    def _mad(self, values: List[float]) -> float:
        if not values:
            return 1.0
        med = statistics.median(values)
        devs = [abs(v - med) for v in values]
        m = statistics.median(devs)
        return max(m, 1e-9)

    def _median(self, values: List[float]) -> float:
        return statistics.median(values) if values else 0.0

    def _trimmed_mean(self, values: List[float], trim: float = 0.10) -> float:
        if not values:
            return 0.0
        s = sorted(values)
        n = len(s)
        k = max(1, int(n * trim))
        trimmed = s[k : n - k] if n > 2 * k else s
        return sum(trimmed) / max(len(trimmed), 1)

    def _biweight_midvariance(self, values: List[float]) -> float:
        if len(values) < 3:
            return max(self._mad(values), 1e-9)
        med = self._median(values)
        mad = self._mad(values)
        if mad < 1e-12:
            return 1e-9
        us = [(v - med) / (9.0 * mad) for v in values]
        mask = [1.0 if abs(u) < 1.0 else 0.0 for u in us]
        n_eff = sum(mask)
        if n_eff < 1:
            return max(self._mad(values), 1e-9)
        num = sum(((v - med) ** 2) * ((1 - u ** 2) ** 4) * m
                  for v, u, m in zip(values, us, mask))
        den_inner = sum((1 - u ** 2) * (1 - 5 * u ** 2) * m
                        for u, m in zip(us, mask))
        den = den_inner ** 2
        if den < 1e-12:
            return max(self._mad(values), 1e-9)
        return math.sqrt(max(0.0, n_eff * num / den))

    def _skewness(self, values: List[float]) -> float:
        n = len(values)
        if n < 3:
            return 0.0
        mean = sum(values) / n
        var = sum((v - mean) ** 2 for v in values) / n
        std = math.sqrt(var) if var > 0 else 1e-12
        return (sum((v - mean) ** 3 for v in values) / n) / (std ** 3)

    def _build_probe(self, parsed: Any, params: list, i: int) -> str:
        new_params = []
        for idx2, (k, v) in enumerate(params):
            if i % max(1, len(params)) == idx2 % max(1, len(params)):
                new_params.append((k, self._benign_value()))
            else:
                new_params.append((k, v))
        return urllib.parse.urlunparse((
            parsed.scheme, parsed.netloc, parsed.path,
            parsed.params, urllib.parse.urlencode(new_params, doseq=True), ""
        ))

    def _fetch_sample(self, parsed: Any, params: list, i: int) -> Optional[tuple]:
        try:
            pu = self._build_probe(parsed, params, i)
            t0 = time.perf_counter()
            code, hdrs, body, _ = _req(pu)
            elapsed_us = (time.perf_counter() - t0) * 1_000_000
            if code == 0:
                return None
            return (code, hdrs, body, elapsed_us)
        except Exception:
            return None

    def learn_baseline(self, base: str, endpoints: List[str], max_eps: int, samples: int) -> None:
        capped = endpoints[:max_eps]
        _out(_paint("  [oracle] learning baseline: %d endpoints x %d samples" % (len(capped), samples), _ORACLE_COLOR + (A.X if _COLOR else "")))
        if not capped:
            _out(_paint("  [oracle] baseline complete: 0 endpoints profiled", _ORACLE_COLOR + (A.X if _COLOR else "")))
            self._start_fusion_watcher()
            return

        ep_parsed_cache: Dict[str, tuple] = {}
        for _ce in capped:
            _cp = urllib.parse.urlparse(_ce)
            ep_parsed_cache[_ce] = (_cp, urllib.parse.parse_qsl(_cp.query, keep_blank_values=True))

        def _run_sample(ep_i: tuple) -> tuple:
            ep, i = ep_i
            parsed, params = ep_parsed_cache[ep]
            return ep, self._fetch_sample(parsed, params, i)

        tasks = [(ep, i) for ep in capped for i in range(samples)]
        results_by_ep: Dict[str, list] = collections.defaultdict(list)
        futs_by_ep: Dict[str, list] = collections.defaultdict(list)
        cancelled_eps: Set[str] = set()

        with ThreadPoolExecutor(max_workers=min(32, len(tasks))) as _pool:
            all_futs: Dict = {}
            for ep_i in tasks:
                f = _pool.submit(_run_sample, ep_i)
                all_futs[f] = ep_i[0]
                futs_by_ep[ep_i[0]].append(f)
            for fut in as_completed(all_futs):
                ep = all_futs[fut]
                if ep in cancelled_eps:
                    continue
                try:
                    _, res = fut.result()
                except Exception:
                    res = None
                if res is not None:
                    results_by_ep[ep].append(res)
                    so_far = results_by_ep[ep]
                    if len(so_far) == 8:
                        ep_hashes = [self._body_sha1(r[2]) for r in so_far]
                        if len(set(ep_hashes)) == 1:
                            cancelled_eps.add(ep)
                            for rf in futs_by_ep[ep]:
                                rf.cancel()

        for ep in capped:
            res_list = results_by_ep.get(ep, [])
            if not res_list:
                continue
            parsed, params = ep_parsed_cache[ep]
            timings: List[float] = []
            sizes: List[int] = []
            statuses: Dict[int, int] = {}
            header_sets: List[Set[str]] = []
            hashes: List[str] = []
            schemas: List[Optional[str]] = []
            body_crs: List[float] = []
            param_resp: Dict[str, List[int]] = {k: [] for k, _ in params}
            for code, hdrs, body, elapsed_us in res_list:
                timings.append(elapsed_us)
                sizes.append(len(body))
                statuses[code] = statuses.get(code, 0) + 1
                header_sets.append(frozenset(hdrs.keys()))
                hashes.append(self._body_sha1(body))
                ct = hdrs.get("content-type", "")
                if "json" in ct:
                    schemas.append(self._json_schema(body))
                elif "html" in ct:
                    schemas.append(str(self._html_tag_vector(body)))
                else:
                    schemas.append(None)
                if body:
                    chunk = body[:4096]
                    body_crs.append(len(zlib.compress(chunk)) / max(len(chunk), 1))
                for k, _ in params:
                    param_resp.setdefault(k, []).append(len(body))
            if not timings:
                continue
            n = len(timings)
            skew = self._skewness(timings)
            if abs(skew) > 1.0:
                t_center = self._trimmed_mean(timings)
                t_scale = self._biweight_midvariance(timings)
                estimator = "biweight"
            else:
                t_center = self._median(timings)
                t_scale = self._mad(timings)
                estimator = "mad"
            t_med = t_center
            t_mad = t_scale
            s_med = self._median([float(x) for x in sizes])
            s_mad = self._mad([float(x) for x in sizes])
            all_hdrs: Set[str] = set()
            for hs in header_sets:
                all_hdrs |= hs
            stable_hdrs: Set[str] = set()
            variable_hdrs: Set[str] = set()
            volatile_hdrs: Set[str] = set()
            for hh in all_hdrs:
                presence = sum(1 for hs in header_sets if hh in hs) / max(n, 1)
                if presence >= 0.9:
                    stable_hdrs.add(hh)
                elif presence >= 0.1:
                    variable_hdrs.add(hh)
                else:
                    volatile_hdrs.add(hh)
            unique_hashes = len(set(hashes))
            body_det = unique_hashes / max(n, 1)
            schema_fp: Optional[str] = None
            non_none = [s for s in schemas if s is not None]
            if non_none:
                ctr = collections.Counter(non_none)
                schema_fp = ctr.most_common(1)[0][0]
            param_sensitivity: Dict[str, float] = {}
            for k, size_list in param_resp.items():
                if len(size_list) < 2:
                    param_sensitivity[k] = 0.0
                    continue
                sz_f = [float(x) for x in size_list]
                med_sz = self._median(sz_f)
                delta = sum(abs(v - med_sz) for v in sz_f) / max(len(sz_f), 1)
                param_sensitivity[k] = min(1.0, delta / max(med_sz, 1))
            if len(timings) >= 4:
                ts = sorted(timings)
                t_p95 = ts[int(len(ts) * 0.95)]
                t_p99 = ts[min(int(len(ts) * 0.99), len(ts) - 1)]
            else:
                t_p95 = max(timings) if timings else 0.0
                t_p99 = t_p95
            ep_key = f"{parsed.scheme}://{parsed.netloc}{parsed.path}"
            self._estimator_type[ep_key] = estimator
            self._baseline[ep_key] = {
                "timing_median": t_med,
                "timing_mad": t_mad,
                "timing_estimator": estimator,
                "timing_p95": t_p95,
                "timing_p99": t_p99,
                "size_median": s_med,
                "size_mad": s_mad,
                "status_distribution": dict(statuses),
                "stable_headers": list(stable_hdrs),
                "variable_headers": list(variable_hdrs),
                "volatile_headers": list(volatile_hdrs),
                "body_determinism": body_det,
                "schema_fingerprint": schema_fp,
                "param_sensitivity": param_sensitivity,
                "seen_hashes": list(set(hashes)),
                "compress_ratio_median": statistics.median(body_crs) if body_crs else 0.5,
                "timing_cv": (statistics.stdev(timings) / max(statistics.mean(timings), 1e-9)) if len(timings) >= 2 else 1.0,
            }
            self._seen_hashes[ep_key] = set(hashes)
        _out(_paint("  [oracle] baseline complete: %d endpoints profiled" % len(self._baseline), _ORACLE_COLOR + (A.X if _COLOR else "")))
        self._start_fusion_watcher()

    def _ep_key(self, url: str) -> str:
        p = urllib.parse.urlparse(url)
        return f"{p.scheme}://{p.netloc}{p.path}"

    def _get_load_factor(self) -> float:
        now = time.monotonic()
        cutoff = now - 60.0
        with self._load_window_lock:
            recent = [t for ts, t in self._load_window if ts >= cutoff]
        if len(recent) < 5:
            return 1.0
        med = self._median(recent)
        return max(med, 1.0)

    def score_probe(self, url: str, method: str, status: int, hdrs: Dict[str, str], body: bytes, timing_us: float, param: Optional[str] = None) -> float:
        with self._load_window_lock:
            self._load_window.append((time.monotonic(), timing_us))
        ep_key = self._ep_key(url)
        bl = self._baseline.get(ep_key)
        if bl is None:
            return 0.0
        t_med = bl["timing_median"]
        t_mad = max(bl["timing_mad"], 1.0)
        s_med = bl["size_median"]
        s_mad = max(bl["size_mad"], 1.0)
        load_factor = self._get_load_factor()
        normalized_timing = timing_us / load_factor
        timing_z = (normalized_timing - t_med) / (1.4826 * t_mad)
        size_z = (len(body) - s_med) / (1.4826 * s_mad)
        status_novel = status not in bl["status_distribution"]
        stable_set = set(bl["stable_headers"])
        variable_set = set(bl["variable_headers"])
        probe_hdrs_set = set(hdrs.keys())
        headers_new = probe_hdrs_set - stable_set - variable_set
        headers_lost = stable_set - probe_hdrs_set
        schema_drift = self._schema_diff(body, bl.get("schema_fingerprint"))
        body_entropy = self._body_entropy_delta(body, ep_key)
        timing_tail = 1.0 if timing_us > bl.get("timing_p99", float("inf")) * 2.5 else 0.0
        raw = (
            _ORACLE_W.timing * max(0.0, abs(timing_z) - 3) +
            0.15             * timing_tail +
            _ORACLE_W.size   * max(0.0, abs(size_z) - 3) +
            _ORACLE_W.status * (1.0 if status_novel else 0.0) +
            _ORACLE_W.header * min(1.0, (len(headers_new) + len(headers_lost) * 1.5) / 3.0) +
            _ORACLE_W.schema * schema_drift +
            _ORACLE_W.body   * body_entropy
        )
        confirmation_boost = self._confirmed_endpoints.get(ep_key, 0.0)
        anomaly = self._sigmoid((raw + confirmation_boost) * 4.0 - 2.0)
        self._update_ep_snapshot(ep_key, status, body)
        delta_record = {
            "url": url,
            "ep_key": ep_key,
            "param": param,
            "timing_z": round(timing_z, 3),
            "size_z": round(size_z, 3),
            "status_novel": status_novel,
            "headers_new": list(headers_new),
            "headers_lost": list(headers_lost),
            "schema_drift": round(schema_drift, 3),
            "body_entropy": round(body_entropy, 4),
            "anomaly": round(anomaly, 4),
        }
        with self._probe_records_lock:
            self._probe_records.append(delta_record)
            self._probes_analyzed += 1
            if anomaly >= _ORACLE_THRESHOLD:
                self._anomaly_count += 1
                self.trigger_unskip(ep_key)
        if param and anomaly >= _ORACLE_THRESHOLD:
            heat_key = (ep_key, param)
            with self._param_heat_lock:
                if heat_key not in self._param_heat:
                    self._param_heat[heat_key] = {"heat": 0.0, "count": 0, "endpoint": ep_key, "param": param}
                self._param_heat[heat_key]["heat"] = round(self._param_heat[heat_key]["heat"] + anomaly, 4)
                self._param_heat[heat_key]["count"] += 1

        if anomaly >= 0.72 and _SCAN_ACTIVE and _ORACLE_ACTIVE and param:
            self._steer_from_anomaly(url, param, anomaly, status, method)

        return anomaly

    def get_param_heat(self, top_n: int = 10) -> List[Dict]:
        with self._param_heat_lock:
            items = sorted(self._param_heat.values(), key=lambda x: x["heat"], reverse=True)
        return items[:top_n]

    def get_param_heat_clustered(self, top_n: int = 10) -> List[Dict]:
        with self._param_heat_lock:
            all_items = list(self._param_heat.values())
        if not all_items:
            return []
        clusters: Dict[str, Dict] = {}
        for item in all_items:
            ep = item["endpoint"]
            par = item["param"]
            parsed = urllib.parse.urlparse(ep)
            parts = [p for p in parsed.path.split("/") if p]
            prefix = "/" + "/".join(parts[:2]) if len(parts) >= 2 else parsed.path or "/"
            ck = prefix + "::" + par
            if ck not in clusters:
                clusters[ck] = {
                    "cluster_prefix": prefix,
                    "param": par,
                    "heat": 0.0,
                    "count": 0,
                    "endpoint_count": 0,
                    "endpoints": [],
                }
            clusters[ck]["heat"] = round(clusters[ck]["heat"] + item["heat"], 4)
            clusters[ck]["count"] += item["count"]
            clusters[ck]["endpoint_count"] += 1
            clusters[ck]["endpoints"].append(ep)
        sorted_clusters = sorted(clusters.values(), key=lambda x: x["heat"], reverse=True)
        return sorted_clusters[:top_n]

    _DIRECTED_INJECTION_MODULES: ClassVar[List[Tuple[str, str]]] = [
        ("sqli error",           "scan_sqli"),
        ("sqli blind timing",    "scan_sqli_blind_timing"),
        ("xss",                  "scan_xss"),
        ("ssti",                 "scan_ssti"),
        ("lfi",                  "scan_lfi"),
        ("command injection",    "scan_cmdi"),
        ("nosql injection",      "scan_nosql"),
        ("open redirect",        "scan_open_redirect"),
        ("xxe xml post",         "scan_xxe"),
        ("idor probe",           "scan_idor"),
        ("mass assignment",      "scan_mass_assignment"),
        ("behavioral matrix",    "scan_behavioral_contradiction_matrix"),
    ]

    def _steer_from_anomaly(
        self,
        url:     str,
        param:   str,
        anomaly: float,
        status:  int,
        method:  str,
    ) -> None:
        ep_key = self._ep_key(url)
        steer_key = (ep_key, param)
        if steer_key in self._steered_pairs:
            return
        self._steered_pairs.add(steer_key)

        import importlib as _il
        scanner_module = _il.import_module(__name__)
        probe_url = _inject_param(url, param, "ORACLE_PROBE_SEED")
        queued = 0

        for idx, (module_label, fn_name) in enumerate(self._DIRECTED_INJECTION_MODULES):
            fn = getattr(scanner_module, fn_name, None)
            if fn is None:
                continue
            queue_label = "oracle::%s::%s::%s" % (fn_name, ep_key, param)
            priority = -anomaly + (0.05 * idx)

            def _make_fn(f, u):
                def _run():
                    return f(u)
                return _run

            with _ORACLE_DIRECTED_LOCK:
                if queue_label not in _ORACLE_DIRECTED_SEEN:
                    _ORACLE_DIRECTED_SEEN.add(queue_label)
                    _heapq.heappush(_ORACLE_DIRECTED_QUEUE, (priority, queue_label, _make_fn(fn, probe_url)))
                    queued += 1

        if queued:
            _out(_paint(
                "  [ORACLE->STEER] anomaly=%.3f on %s param=%s - "
                "%d targeted scans queued" % (
                    anomaly, ep_key[:60], param, queued),
                _ORACLE_COLOR + A.BD + (A.X if _COLOR else "")
            ))

    def _steer_from_fusion(self, ep: str, param: str, fusion: Dict) -> None:
        import importlib as _il
        scanner_module = _il.import_module(__name__)

        probe_url = ep + ("&" if "?" in ep else "?") + param + "=FUSION_PROBE"

        for fn_name, label_suffix in [
            ("scan_behavioral_contradiction_matrix", "bcm"),
            ("scan_kill_chain_oracle",               "kco"),
            ("scan_sqli_blind_timing",               "sqli_timing"),
            ("scan_hidden_param_bayesian",            "hpb"),
        ]:
            fn = getattr(scanner_module, fn_name, None)
            if fn is None:
                continue
            qlabel = "oracle::fusion::%s::%s::%s" % (label_suffix, ep[:40], param)

            def _make_fn(f, u):
                def _run(): return f(u)
                return _run

            _oracle_queue_directed(
                -2.0,
                qlabel,
                _make_fn(fn, probe_url)
            )

        _out(_paint(
            "  [ORACLE->FUSE] %s fusion on %s param=%s - "
            "4 deep-dive scans queued at max priority" % (
                fusion["severity"], ep[:60], param),
            _ORACLE_COLOR + A.BD + (A.X if _COLOR else "")
        ))

    def _update_ep_snapshot(self, ep_key: str, status: int, body: bytes) -> None:
        prev = self._post_probe_snapshots.get(ep_key)
        new_snap = (status, len(body), self._body_sha1(body))
        self._post_probe_snapshots[ep_key] = new_snap
        if prev and prev != new_snap:
            self._cross_ep_changes.append((ep_key, prev, new_snap, time.monotonic()))

    def flush_cross_ep_changes(self) -> List[Dict]:
        with self._probe_records_lock:
            changes = list(self._cross_ep_changes)
            self._cross_ep_changes.clear()

        results = []
        import importlib as _il
        scanner_module = _il.import_module(__name__)

        for ep_key, prev, new_snap, ts in changes:
            prev_status, prev_size, prev_hash = prev
            new_status  = new_snap[0] if isinstance(new_snap, tuple) else new_snap.get("status",   prev_status)
            new_size    = new_snap[1] if isinstance(new_snap, tuple) else new_snap.get("body_len",  prev_size)
            new_hash    = new_snap[2] if isinstance(new_snap, tuple) else new_snap.get("body_hash", prev_hash)

            change_type = None
            if new_status != prev_status:
                change_type = "status_change"
                delta_desc  = "status %d->%d" % (prev_status, new_status)
            elif abs(new_size - prev_size) > max(prev_size * 0.20, 500):
                change_type = "size_shift"
                delta_desc  = "body len %d->%d (delta %+d)" % (
                    prev_size, new_size, new_size - prev_size)
            elif new_hash != prev_hash:
                change_type = "content_change"
                delta_desc  = "body hash changed"
            else:
                continue

            result = {
                "type":     change_type,
                "endpoint": ep_key,
                "delta":    delta_desc,
                "ts":       ts,
            }
            results.append(result)

            if change_type in ("status_change", "size_shift"):
                for fn_name in ("scan_behavioral_contradiction_matrix",
                                "synthesize_application_model"):
                    fn = getattr(scanner_module, fn_name, None)
                    if fn:
                        qlabel = "oracle::xep::%s::%s" % (fn_name, ep_key[:40])
                        _oracle_queue_directed(
                            -1.8,
                            qlabel,
                            lambda f=fn, u=ep_key: f(u)
                        )

                _out(_paint(
                    "  [ORACLE->XEP] cross-endpoint state change at %s (%s) - "
                    "BCM + app model queued" % (ep_key[:60], delta_desc),
                    _ORACLE_COLOR + A.BD + (A.X if _COLOR else "")
                ))

        return results

    def register_confirmation(self, url: str, severity: str) -> None:
        ep_key = self._ep_key(url)
        sev_boost = {"CRIT": 0.20, "HIGH": 0.15, "MED": 0.10, "LOW": 0.05, "ZERO": 0.30}
        boost = sev_boost.get(severity, 0.10)
        self._confirmed_endpoints[ep_key] = min(
            self._confirmed_endpoints.get(ep_key, 0.0) + boost, 0.40
        )

    def compute_fusions(self, findings: List[Tuple[str, str, str, str]]) -> List[Dict]:
        by_ep: Dict[str, List[Tuple[str, str, str, str]]] = collections.defaultdict(list)
        module_anomalies: Dict[str, float] = {}
        with _ORACLE_MODULE_LOCK:
            module_anomalies = dict(_ORACLE_MODULE_MAX_ANOMALY)
        for mod, det, pay, sev in findings:
            by_ep[mod.strip().lower()].append((mod, det, pay, sev))
        by_param: Dict[str, List[Tuple[str, str, str, str]]] = collections.defaultdict(list)
        with self._param_heat_lock:
            hot_params = sorted(self._param_heat.values(), key=lambda x: x["heat"], reverse=True)
        ep_index: Dict[str, List[Tuple[str, str, str, str]]] = collections.defaultdict(list)
        par_index: Dict[str, List[Tuple[str, str, str, str]]] = collections.defaultdict(list)
        for finding in findings:
            mod, det, pay, sev = finding
            for m in _URL_IN_TEXT_RE.finditer(det):
                ep_index[m.group(0)[:80]].append(finding)
            combined = det + " " + (pay or "")
            for m in _FUSE_PARAM_RE.finditer(combined):
                par_index[m.group(1)].append(finding)
        for hp in hot_params[:20]:
            ep = hp["endpoint"]
            par = hp["param"]
            key = ep + "::" + par
            seen_ids: Set[int] = set()
            for f in ep_index.get(ep, []) + par_index.get(par, []):
                fid = id(f)
                if fid not in seen_ids:
                    seen_ids.add(fid)
                    by_param[key].append(f)
        sev_order = ["INFO", "LOW", "MED", "HIGH", "CRIT", "ZERO"]
        fused: List[Dict] = []
        fid_counter = 0
        clusters_seen: Set[str] = set()
        for cluster_key, cluster in by_param.items():
            if len(cluster) < 2:
                continue
            modules_in_cluster = {m.strip().lower() for m, _, _, _ in cluster}
            if len(modules_in_cluster) < 2:
                continue
            total_anomaly = sum(module_anomalies.get(m.strip().lower(), 0.0) for m, _, _, _ in cluster)
            if total_anomaly < 1.5 and len(set(m for m, _, _, _ in cluster)) < 2:
                continue
            cluster_sig = "|".join(sorted(modules_in_cluster))
            if cluster_sig in clusters_seen:
                continue
            clusters_seen.add(cluster_sig)
            matched_rule = None
            for rule_set, hypothesis, min_comp, uplift in _FUSION_RULES:
                if len(rule_set & modules_in_cluster) >= min(min_comp, len(rule_set)) and len(cluster) >= min_comp:
                    matched_rule = (hypothesis, uplift)
                    break
            hypothesis = matched_rule[0] if matched_rule else "multiple correlated signals suggest injection or logic flaw"
            base_uplift = matched_rule[1] if matched_rule else "MED"
            max_sev = max(cluster, key=lambda x: sev_order.index(x[3]) if x[3] in sev_order else 0)[3]
            if len(cluster) >= 3:
                idx = sev_order.index(max_sev) if max_sev in sev_order else 0
                elevated = sev_order[min(idx + 1, len(sev_order) - 1)]
            else:
                elevated = max_sev
            confirmed_components = sum(1 for _, d, _, _ in cluster if d.startswith("[CONFIRMED]"))
            strong_components = sum(
                1 for m, d, p, s in cluster
                if _finding_evidence_profile(m, d, p, s, d.startswith("[CONFIRMED]")).get("exact")
            )
            probable_components = sum(
                1 for m, d, p, s in cluster
                if _finding_evidence_level(m, d, p, s, d.startswith("[CONFIRMED]")) in ("confirmed", "probable")
            )
            confidence_score = (
                min(0.45, 0.12 * len(modules_in_cluster))
                + min(0.30, total_anomaly / 8.0)
                + min(0.25, 0.10 * confirmed_components + 0.05 * strong_components + 0.03 * probable_components)
            )
            if confidence_score < 0.40 or probable_components == 0:
                continue
            uplift_idx = sev_order.index(base_uplift) if base_uplift in sev_order else 3
            el_idx = sev_order.index(elevated) if elevated in sev_order else 3
            final_sev = sev_order[max(uplift_idx, el_idx)]
            if final_sev in ("CRIT", "ZERO") and confidence_score < 0.70:
                final_sev = "HIGH"
            if final_sev == "CRIT" and len(cluster) >= 3 and confidence_score >= 0.70:
                final_sev = "CRIT-FUSED"
            fid_counter += 1
            fid = "fusion.%04d" % fid_counter
            parts = cluster_key.split("::")
            endpoint_label = parts[0] if parts else cluster_key
            param_label = parts[1] if len(parts) > 1 else "unknown"
            fused.append({
                "id": fid,
                "endpoint": endpoint_label,
                "param": param_label,
                "hypothesis": hypothesis,
                "severity": final_sev,
                "component_count": len(cluster),
                "total_anomaly": round(total_anomaly, 3),
                "confidence": round(confidence_score, 3),
                "evidence_quality": "high" if confidence_score >= 0.7 else "medium" if confidence_score >= 0.5 else "low",
                "calibration_warning": "" if confidence_score >= 0.7 else "oracle fusion is not treated as proof without confirmed component evidence",
                "components": [(m.strip().lower(), d[:80]) for m, d, _, _ in cluster],
            })
        self._fused_findings = fused

        for fusion in fused:
            if fusion["severity"] not in ("CRIT", "CRIT-FUSED") or fusion.get("confidence", 0.0) < 0.5:
                continue
            fid = fusion["id"]
            if fid in self._steered_fusions:
                continue
            self._steered_fusions.add(fid)
            ep  = fusion["endpoint"]
            par = fusion["param"]
            self._steer_from_fusion(ep, par, fusion)

        return fused

    def export_baseline(self, path: str, target_url: str) -> None:
        data = {
            "target": target_url,
            "baseline_id": hashlib.md5(target_url.encode()).hexdigest()[:16],
            "timestamp": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            "baselines": self._baseline,
        }
        try:
            with open(path, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2)
            _out(_paint("  [oracle] baseline exported to " + path, _ORACLE_COLOR + (A.X if _COLOR else "")))
        except Exception as e:
            _out(_paint("  [oracle] export failed: " + str(e), A.R))

    def import_baseline(self, path: str, target_url: str) -> bool:
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            stored_id = data.get("baseline_id", "")
            expected_id = hashlib.md5(target_url.encode()).hexdigest()[:16]
            if stored_id != expected_id:
                _out(_paint("  [oracle] baseline target mismatch -- refusing import (stored=%s expected=%s)" % (stored_id, expected_id), A.R))
                return False
            self._baseline = data.get("baselines", {})
            for ep_key, bl in self._baseline.items():
                self._seen_hashes[ep_key] = set(bl.get("seen_hashes", []))
            _out(_paint("  [oracle] baseline imported from %s (%d endpoints)" % (path, len(self._baseline)), _ORACLE_COLOR + (A.X if _COLOR else "")))
            return True
        except Exception as e:
            _out(_paint("  [oracle] import failed: " + str(e), A.R))
            return False

    def trigger_unskip(self, ep_key: str) -> None:
        with _UNSKIP_QUEUE_LOCK:
            if not _SKIPPED_WITH_FETCH:
                return
            candidates = list(_SKIPPED_WITH_FETCH.items())
        for lab, fetch_fn in candidates:
            with _UNSKIP_QUEUE_LOCK:
                already_queued = any(t == lab for t, _ in _UNSKIP_QUEUE)
            if not already_queued:
                with _UNSKIP_QUEUE_LOCK:
                    _UNSKIP_QUEUE.append((lab, fetch_fn))
                _out(_paint("  [oracle] unskip: anomaly triggered re-scan of '%s'" % lab, _ORACLE_COLOR + (A.X if _COLOR else "")))

    def analyze_probe_patterns(self) -> List[Dict]:
        with self._probe_records_lock:
            records = list(self._probe_records)
        findings: List[Dict] = []
        ep_timings: Dict[str, List[float]] = collections.defaultdict(list)
        ep_statuses: Dict[str, List[bool]] = collections.defaultdict(list)
        ep_schemas: Dict[str, List[float]] = collections.defaultdict(list)
        for r in records:
            ep_timings[r["ep_key"]].append(r["timing_z"])
            ep_statuses[r["ep_key"]].append(r["status_novel"])
            ep_schemas[r["ep_key"]].append(r["schema_drift"])
        for ep, zs in ep_timings.items():
            if len(zs) < 8:
                continue
            last8 = zs[-8:]
            if all(last8[i] < last8[i + 1] for i in range(7)) and last8[-1] > 3.0:
                findings.append({
                    "type": "timing_escalation",
                    "endpoint": ep,
                    "message": "[ORACLE] Monotonically increasing response times on %s across last 8 probes (final z=%.2f) - possible resource exhaustion, connection pool saturation, or time-based injection accumulation" % (ep, last8[-1]),
                })
        for ep, novs in ep_statuses.items():
            if len(novs) < 6:
                continue
            alts = sum(1 for i in range(len(novs) - 1) if novs[i] != novs[i + 1])
            if alts >= len(novs) * 0.6:
                findings.append({
                    "type": "status_flapping",
                    "endpoint": ep,
                    "message": "[ORACLE] Status code flapping on %s - access control state is non-deterministic; possible race condition or session-dependent access control" % ep,
                })
        for ep, drifts in ep_schemas.items():
            if len(drifts) < 5:
                continue
            spikes = [i for i, d in enumerate(drifts) if d > 0.3]
            if len(spikes) >= 2:
                findings.append({
                    "type": "schema_instability",
                    "endpoint": ep,
                    "message": "[ORACLE] JSON schema instability on %s - %d schema drift events across probes; API response structure is injection-dependent or environment-dependent" % (ep, len(spikes)),
                })

        import importlib as _il
        scanner_module = _il.import_module(__name__)

        for pf in findings:
            ep = pf.get("endpoint", "")
            if not ep:
                continue
            ptype = pf.get("type", "")

            if ptype == "timing_escalation":
                for fn_name in ("scan_sqli_blind_timing", "scan_cmdi"):
                    fn = getattr(scanner_module, fn_name, None)
                    if fn:
                        qlabel = "oracle::pattern::timing::%s::%s" % (fn_name, ep[:40])
                        _oracle_queue_directed(-1.5, qlabel, lambda f=fn, u=ep: f(u))

            elif ptype == "status_flapping":
                fn = getattr(scanner_module, "scan_race_window_amplified", None)
                if fn:
                    qlabel = "oracle::pattern::flap::%s" % ep[:40]
                    _oracle_queue_directed(-1.5, qlabel, lambda f=fn, u=ep: f(u))

            elif ptype == "schema_instability":
                fn = getattr(scanner_module, "scan_behavioral_contradiction_matrix", None)
                if fn:
                    qlabel = "oracle::pattern::schema::%s" % ep[:40]
                    _oracle_queue_directed(-1.5, qlabel, lambda f=fn, u=ep: f(u))

        return findings

    def get_high_sensitivity_params(self, url: str, threshold: float = 0.15) -> List[str]:
        ep_key = self._ep_key(url)
        bl = self._baseline.get(ep_key, {})
        sens = bl.get("param_sensitivity", {})
        return [k for k, v in sorted(sens.items(), key=lambda x: -x[1]) if v >= threshold]

    def compute_scan_priority_order(
        self,
        pending_modules: List[Tuple[str, Callable, str]],
    ) -> List[Tuple[str, Callable, str]]:
        with self._param_heat_lock:
            heat_by_ep: Dict[str, float] = {}
            for (ep, _), entry in self._param_heat.items():
                heat_by_ep[ep] = heat_by_ep.get(ep, 0.0) + entry.get("heat", 0.0)

        def _module_score(item: Tuple[str, Callable, str]) -> float:
            label, _, base_url = item
            ep_key = self._ep_key(base_url)
            ep_heat = heat_by_ep.get(ep_key, 0.0)
            bl = self._baseline.get(ep_key, {})
            sens_sum = sum(bl.get("param_sensitivity", {}).values())
            conf_boost = self._confirmed_endpoints.get(ep_key, 0.0) * 10.0
            return -(ep_heat + sens_sum + conf_boost)

        return sorted(pending_modules, key=_module_score)

    def should_skip_module(self, module_label: str, url: str) -> bool:
        if not _ORACLE_ACTIVE:
            return False
        ep_key = self._ep_key(url)
        with self._param_heat_lock:
            ep_heat = sum(
                v.get("heat", 0.0)
                for (ep, _), v in self._param_heat.items()
                if ep == ep_key
            )
        bl = self._baseline.get(ep_key, {})
        sens_sum = sum(bl.get("param_sensitivity", {}).values())
        confirmed = self._confirmed_endpoints.get(ep_key, 0.0)

        if confirmed > 0.0:
            return False
        if ep_heat > 0.3 or sens_sum > 0.2:
            return False

        timing_cv = bl.get("timing_cv", 1.0)
        if timing_cv < 0.05 and any(
            kw in module_label.lower()
            for kw in ("timing", "blind", "sleep", "delay")
        ):
            return True

        return False

    def _start_fusion_watcher(self) -> None:
        def _watch() -> None:
            while _SCAN_ACTIVE:
                time.sleep(30.0)
                if not _SCAN_ACTIVE:
                    break
                with _FINDINGS_LOCK:
                    snap = list(_FINDINGS_SUMMARY)
                if not snap:
                    continue
                fusions = self.compute_fusions(snap)
                for f in fusions:
                    if f["severity"] in ("CRIT", "CRIT-FUSED") and f["id"] not in self._alerted_fusions:
                        self._alerted_fusions.add(f["id"])
                        _out(_paint(
                            "  [ORACLE-FUSE] %s fusion detected: %s on %s param=%s (%d components, anomaly=%.2f)" % (
                                f["severity"], f["hypothesis"], f["endpoint"],
                                f["param"], f["component_count"], f["total_anomaly"]
                            ),
                            _ORACLE_COLOR + A.BD + (A.X if _COLOR else "")
                        ))
        t = threading.Thread(target=_watch, daemon=True)
        t.start()

    def stats(self) -> Dict:
        with self._probe_records_lock:
            n = self._probes_analyzed
            an = self._anomaly_count
        return {
            "probes_analyzed": n,
            "anomalies_detected": an,
            "anomaly_rate": round(an / max(n, 1), 4),
            "endpoints_profiled": len(self._baseline),
            "hot_params_tracked": len(self._param_heat),
            "fusions_detected": len(self._fused_findings),
            "confirmed_endpoints": len(self._confirmed_endpoints),
            "cross_ep_changes_detected": len(self._cross_ep_changes),
            "probe_pattern_findings": 0,
        }

def _oracle_run_phase1(base: str) -> None:
    global _ORACLE, _ORACLE_ACTIVE, _SCAN_ACTIVE
    if _NO_ORACLE:
        return
    _SCAN_ACTIVE = True
    _ORACLE = _BehavioralOracle()
    if _ORACLE_IMPORT_FILE:
        ok = _ORACLE.import_baseline(_ORACLE_IMPORT_FILE, base)
        if ok:
            _ORACLE_ACTIVE = True
            return
    with _DISC_ENDPOINTS_LOCK:
        eps = list(_DISCOVERED_ENDPOINTS)
    if not eps:
        eps = [base]
    eps_with_params = [e for e in eps if "?" in e]
    eps_without = [e for e in eps if "?" not in e]
    endpoints_to_profile = (eps_with_params + eps_without)[:_ORACLE_ENDPOINTS_MAX]
    if not endpoints_to_profile:
        endpoints_to_profile = [base]
    if _FOCUS_PARAM:
        endpoints_to_profile = [e for e in endpoints_to_profile if _FOCUS_PARAM in e] or endpoints_to_profile
    _ORACLE.learn_baseline(base, endpoints_to_profile, _ORACLE_ENDPOINTS_MAX, _ORACLE_SAMPLES)
    if _ORACLE_EXPORT_FILE:
        _ORACLE.export_baseline(_ORACLE_EXPORT_FILE, base)
    _ORACLE_ACTIVE = True

def _sigquit_handler(sig, frame) -> None:
    lines = ["\n  [progress] scan running | findings=%d" % len(_FINDINGS_SUMMARY)]
    if _ORACLE is not None:
        hot = _ORACLE.get_param_heat(3)
        for h in hot:
            lines.append("    heat=%.2f  param=%-20s  endpoint=%s" % (h["heat"], h["param"], h["endpoint"]))
    lines.append("  [progress] current module: %s" % _CURRENT_SCAN_MODULE)
    sys.stderr.write("\n".join(lines) + "\n")

try:
    if hasattr(_signal_mod, "SIGQUIT"):
        _signal_mod.signal(_signal_mod.SIGQUIT, _sigquit_handler)
except Exception:
    pass

def _autosave_worker() -> None:
    while True:
        if _AUTOSAVE_STOP.wait(timeout=_AUTOSAVE_INTERVAL):
            break
        path = _AUTOSAVE_FILE
        if not path:
            continue
        try:
            with _FINDINGS_LOCK:
                snap = list(_FINDINGS_SUMMARY)
            data: Dict = {"findings": [{"module": m, "detail": d, "payload": p, "severity": s} for m, d, p, s in snap]}
            if _ORACLE is not None:
                data["oracle"] = _ORACLE.stats()
            with open(path, "w", encoding="utf-8") as f:
                json.dump(data, f)
        except Exception as exc:
            if _VERBOSE:
                _out(_paint("  [autosave] failed to write %s: %s" % (path, exc), A.Y))

_AUTOSAVE_THREAD: Optional[threading.Thread] = None

def _start_autosave(path: str) -> None:
    global _AUTOSAVE_THREAD, _AUTOSAVE_FILE
    _AUTOSAVE_FILE = path
    if _AUTOSAVE_INTERVAL <= 0:
        return
    if _AUTOSAVE_THREAD and _AUTOSAVE_THREAD.is_alive():
        return
    _AUTOSAVE_STOP.clear()
    t = threading.Thread(target=_autosave_worker, daemon=True)
    t.start()
    _AUTOSAVE_THREAD = t

atexit.register(_AUTOSAVE_STOP.set)

def _replay_semantic_key(module: str, detail: str, payload: str) -> str:
    ep_match = re.search(r"https?://[^\s<>\"']+", detail)
    ep = ep_match.group(0)[:80] if ep_match else detail[:40]
    param_match = re.search(r"param[=: ]+([A-Za-z0-9_\-]+)", detail, re.I)
    param = param_match.group(1) if param_match else ""
    return module.strip().lower() + "::" + ep + "::" + param

def _evidence_similarity(old_det: str, new_det: str) -> int:
    s1 = old_det.lower()
    s2 = new_det.lower()
    if not s1 and not s2:
        return 100
    bg_old = frozenset(s1[i:i+2] for i in range(len(s1) - 1))
    bg_new = frozenset(s2[i:i+2] for i in range(len(s2) - 1))
    if not bg_old and not bg_new:
        return 100
    return int(100 * len(bg_old & bg_new) / max(len(bg_old | bg_new), 1))

def _run_replay(replay_file: str) -> None:
    _out(_paint("  [replay] loading probe log from " + replay_file, _ORACLE_COLOR + (A.X if _COLOR else "")))
    try:
        entries = []
        bad_lines = 0
        with open(replay_file, "r", encoding="utf-8-sig") as f:
            for line_no, line in enumerate(f, 1):
                line = line.strip()
                if not line:
                    continue
                try:
                    entries.append(json.loads(line))
                except Exception:
                    bad_lines += 1
                    if bad_lines <= 3:
                        _out(_paint("  [replay] WARNING: invalid JSONL line %d in %s" % (line_no, replay_file), A.Y))
    except Exception as e:
        _out(_paint("  [replay] failed to load: " + str(e), A.R))
        return
    if bad_lines:
        _out(_paint("  [replay] ignored %d malformed replay line(s)" % bad_lines, A.Y))
    if not entries:
        _out(_paint("  [replay] no valid replay entries loaded", A.Y))

    old_findings: Dict[str, Dict] = {}
    for e in entries:
        if "module" not in e:
            continue
        sk = _replay_semantic_key(e.get("module", ""), e.get("detail", ""), e.get("payload", ""))
        old_findings[sk] = e

    with _FINDINGS_LOCK:
        cur_findings = list(_FINDINGS_SUMMARY)
    new_findings: Dict[str, Dict] = {}
    for m, d, p, s in cur_findings:
        sk = _replay_semantic_key(m, d, p)
        new_findings[sk] = {"module": m, "detail": d, "payload": p, "severity": s}

    appeared = [e for k, e in new_findings.items() if k not in old_findings]
    disappeared = [e for k, e in old_findings.items() if k not in new_findings]

    same_key = set(old_findings) & set(new_findings)
    changed_sev = []
    changed_evidence = []
    for k in same_key:
        oe = old_findings[k]
        ne = new_findings[k]
        sim = _evidence_similarity(oe.get("detail", ""), ne.get("detail", ""))
        if oe.get("severity") != ne.get("severity"):
            changed_sev.append({"old": oe, "new": ne, "similarity": sim})
        elif sim < 80:
            changed_evidence.append({"old": oe, "new": ne, "similarity": sim})

    _out(_paint("  " + "=" * 66, A.BD + A.C))
    _out(_paint(
        "  REPLAY DELTA  --  appeared=%d  disappeared=%d  sev-changed=%d  evidence-changed=%d"
        % (len(appeared), len(disappeared), len(changed_sev), len(changed_evidence)),
        A.BD + A.W
    ))
    _out(_paint("  " + "-" * 66, A.D))
    if appeared:
        _out(_paint("  NEW (appeared in this run):", A.G + A.BD))
        for e in appeared[:10]:
            _out("    " + _paint("[%-4s]" % e.get("severity", "?"), A.Y + A.BD)
                 + "  " + e.get("module", "") + "  " + e.get("detail", "")[:60])
    if disappeared:
        _out(_paint("  GONE (not in this run):", A.D))
        for e in disappeared[:10]:
            _out("    " + _paint("[%-4s]" % e.get("severity", "?"), A.D)
                 + "  " + e.get("module", "") + "  " + e.get("detail", "")[:60])
    if changed_sev:
        _out(_paint("  SEVERITY CHANGED:", A.Y + A.BD))
        for e in changed_sev[:5]:
            sim_tag = _paint("  [SIM=%d%%]" % e["similarity"], A.D)
            _out("    " + e["old"].get("module", "") + "  "
                 + _paint(e["old"].get("severity", "?") + " -> " + e["new"].get("severity", "?"), A.Y)
                 + sim_tag)
    if changed_evidence:
        _out(_paint("  EVIDENCE CHANGED (same finding, different detail):", A.Y))
        for e in changed_evidence[:5]:
            sim = e["similarity"]
            sim_col = A.G if sim >= 60 else A.Y
            _out("    " + e["old"].get("module", "") + "  "
                 + _paint("[SIMILARITY=%d%%]" % sim, sim_col + A.BD)
                 + "  " + e["new"].get("detail", "")[:50])
    _out(_paint("  " + "-" * 66, A.D))

def _extract_params(url: str) -> List[str]:
    if _ORACLE is not None and _ORACLE_ACTIVE:
        hot = _ORACLE.get_high_sensitivity_params(url)
        if hot:
            return hot
    return _extract_url_params_basic(url)

def _prompt_url_until_valid() -> Optional[str]:
    while True:
        raw = input(_paint("  Target URL (http/https, or q to quit): ", A.Y)).strip()
        if not raw or raw.lower() in ("q", "quit", "exit"):
            return None
        ok, val = _validate_http_url(raw)
        if ok:
            return val
        _out(_paint("  [!] Invalid: " + val + ". Example: https://example.com", A.R))

def _stdout_tty() -> bool:
    return getattr(sys.stdout, "isatty", lambda: False)()



_REPORT_SEV_ORDER: Dict[str, int] = {"INFO": 0, "LOW": 1, "MED": 2, "HIGH": 3, "CRIT": 4, "ZERO": 5}

_FINDING_STRICT = os.environ.get("SCANNER_LOOSE_FINDINGS", "").strip().lower() not in ("1", "true", "yes", "on")
_VERSION_ONLY_RE = re.compile(
    r"\b(version|banner|fingerprint|vulnerable range|detected version|appears vulnerable|verify patched|outdated|older)\b",
    re.I,
)
_PASSIVE_CONFIG_RE = re.compile(
    r"\b(missing|lacks|not set|no .*header|does not advertise|policy|header|robots|sitemap|security\.txt|referrer|permissions)\b",
    re.I,
)


def _quality_module(label: str) -> Dict[str, Any]:
    lab = (label or "unknown").strip().lower()
    modules = _SCAN_QUALITY.setdefault("modules", {})
    return modules.setdefault(lab, {"status": "pending", "findings": 0, "elapsed": 0.0, "detail": ""})

def _quality_event(kind: str, label: str = "", detail: str = "", elapsed: float = 0.0) -> None:
    lab = (label or "unknown").strip().lower()
    with _SCAN_QUALITY_LOCK:
        if kind in ("planned", "run", "skipped", "failed", "timeout", "deduped"):
            _SCAN_QUALITY[kind] = int(_SCAN_QUALITY.get(kind, 0)) + 1
        if kind == "planned_total":
            _SCAN_QUALITY["planned"] = max(int(_SCAN_QUALITY.get("planned", 0)), int(elapsed))
            return
        if label:
            mod = _quality_module(lab)
            if kind in ("run", "skipped", "failed", "timeout", "completed"):
                mod["status"] = kind
            if detail:
                mod["detail"] = detail[:200]
            if elapsed:
                mod["elapsed"] = round(elapsed, 3)

def _coverage_event(kind: str, value: Any = None, amount: int = 1) -> None:
    with _SCAN_COVERAGE_LOCK:
        if kind == "request":
            _SCAN_COVERAGE["requests"] = int(_SCAN_COVERAGE.get("requests", 0)) + amount
            if value:
                _SCAN_COVERAGE.setdefault("endpoints_requested", set()).add(str(value).split("#")[0])
        elif kind == "param":
            if value:
                _SCAN_COVERAGE.setdefault("params_seen", set()).add(str(value))
        elif kind in ("forms_seen", "forms_fuzzed", "form_fields_fuzzed"):
            _SCAN_COVERAGE[kind] = int(_SCAN_COVERAGE.get(kind, 0)) + amount

def _coverage_record_request(url: str, method: str = "GET", data: Optional[bytes] = None, content_type: Optional[str] = None) -> None:
    _coverage_event("request", url)
    lab = getattr(_SCAN_THREAD, "module", "") or _CURRENT_SCAN_MODULE
    if lab:
        with _SCAN_QUALITY_LOCK:
            mod = _quality_module(str(lab))
            mod["requests"] = int(mod.get("requests", 0) or 0) + 1
    try:
        parsed = urllib.parse.urlparse(url)
        for name in urllib.parse.parse_qs(parsed.query, keep_blank_values=True).keys():
            _coverage_event("param", name)
        if data:
            raw = data.decode("utf-8", "ignore") if isinstance(data, (bytes, bytearray)) else str(data)
            if content_type and "json" in content_type.lower():
                try:
                    obj = json.loads(raw)
                    if isinstance(obj, dict):
                        for name in obj.keys():
                            _coverage_event("param", name)
                except Exception:
                    pass
            else:
                for name in urllib.parse.parse_qs(raw, keep_blank_values=True).keys():
                    _coverage_event("param", name)
    except Exception:
        pass

def _scan_coverage_snapshot() -> Dict[str, Any]:
    with _SCAN_COVERAGE_LOCK:
        endpoints = sorted(str(x) for x in _SCAN_COVERAGE.get("endpoints_requested", set()))
        params = sorted(str(x) for x in _SCAN_COVERAGE.get("params_seen", set()))
        snap = {
            "requests": int(_SCAN_COVERAGE.get("requests", 0)),
            "endpoints_requested": len(endpoints),
            "params_seen": len(params),
            "forms_seen": int(_SCAN_COVERAGE.get("forms_seen", 0)),
            "forms_fuzzed": int(_SCAN_COVERAGE.get("forms_fuzzed", 0)),
            "form_fields_fuzzed": int(_SCAN_COVERAGE.get("form_fields_fuzzed", 0)),
            "sample_endpoints": endpoints[:12],
            "sample_params": params[:24],
        }
    with _DISC_ENDPOINTS_LOCK:
        snap["endpoints_discovered"] = len(_DISCOVERED_ENDPOINTS)
    return snap

def _sync_scan_config_from_globals() -> ScanConfig:
    global _SCAN_CONFIG
    _SCAN_CONFIG = _make_scan_config()
    return _SCAN_CONFIG

def _scan_config_snapshot() -> Dict[str, Any]:
    return scan_config_snapshot(_SCAN_CONFIG, _redact_sensitive_headers)

def _coerce_finding_item(lab: str, raw_item: Any, default_sev: str) -> Optional[Finding]:
    return coerce_finding_item(
        lab,
        raw_item,
        default_sev,
        _REPORT_SEV_ORDER,
        _SCAN_LABEL_CATEGORY.get(lab.strip().lower(), "misc"),
    )

def _build_finding(lab: str, detail: str, payload: str, sev: str) -> Finding:
    confirmed = "[CONFIRMED]" in (detail or "")
    meta = _build_finding_meta(lab, detail, payload, sev, confirmed)
    return Finding(
        module=lab,
        category=str(meta.get("category", "misc")),
        detail=detail,
        payload=payload,
        severity=sev,
        id=meta["id"],
        evidence_level=meta["evidence_level"],
        confidence_score=int(meta["confidence_score"]),
        confirmed=bool(meta["confirmed"]),
        speculative=bool(meta["speculative"]),
        exposure_type=str(meta["exposure_type"]),
        metadata={k: v for k, v in meta.items() if k not in {
            "id", "module", "severity", "evidence_level", "confidence_score",
            "confirmed", "speculative", "exposure_type",
        }},
    )

def _build_finding_meta(lab: str, detail: str, payload: str, sev: str, confirmed: bool) -> Dict[str, Any]:
    fid = _finding_stable_id(lab, detail, payload, sev)
    evidence_level = _finding_evidence_level(lab, detail, payload, sev, confirmed)
    confidence_score = _finding_confidence_score(lab, detail, payload, sev, confirmed)
    confidence = _confidence_label(confidence_score)
    speculative = _is_speculative_exposure(lab, detail, payload, sev, confirmed)
    meta = {
        "id": fid,
        "module": lab,
        "category": _SCAN_LABEL_CATEGORY.get(lab.strip().lower(), "misc"),
        "severity": sev,
        "evidence_level": evidence_level,
        "confidence_score": confidence_score,
        "confidence": confidence,
        "confirmed": confirmed,
        "speculative": speculative,
        "exposure_type": "possible_exposure" if speculative else "finding",
    }
    meta = _intel_enrich_finding_entry(meta | {"detail": detail, "payload": payload}, _REPORT_SEV_ORDER)
    return meta

def _record_finding(lab: str, detail: str, payload: str, sev: str) -> bool:
    global _FINDINGS_COUNT
    fp = _finding_stable_id(lab, detail, payload, sev)
    suppressed, reason = _finding_suppressed(fp, lab, detail, payload, sev)
    if suppressed:
        _quality_event("deduped", lab, "suppressed: " + reason)
        return False
    finding = _build_finding(lab, detail, payload, sev)
    meta = finding.as_json()
    with _FINDINGS_LOCK:
        if fp in _FINDINGS_SEEN:
            _quality_event("deduped", lab)
            return False
        _FINDINGS_SEEN.add(fp)
        _FINDINGS_META[fp] = meta
        _FINDINGS_STRUCTURED.append(finding)
        _FINDINGS_SUMMARY.append(finding.as_tuple())
        _FINDINGS_COUNT += 1
    with _SCAN_QUALITY_LOCK:
        mod = _quality_module(lab)
        mod["findings"] += 1
        mod.setdefault("severity_counts", {})
        mod["severity_counts"][sev] = int(mod["severity_counts"].get(sev, 0)) + 1
        mod.setdefault("evidence_counts", {})
        mod["evidence_counts"][meta["evidence_level"]] = int(mod["evidence_counts"].get(meta["evidence_level"], 0)) + 1
        if meta.get("confirmed"):
            mod["confirmed"] = int(mod.get("confirmed", 0)) + 1
        if meta.get("speculative"):
            mod["speculative"] = int(mod.get("speculative", 0)) + 1
    return True

def _finding_stable_id(lab: str, detail: str, payload: str, sev: str) -> str:
    d = re.sub(r"\b[0-9a-f]{8,}\b", "<hex>", (detail or "").replace("[CONFIRMED] ", ""), flags=re.I)
    d = re.sub(r"https?://[^\s,;'\"<>]+", "<url>", d)
    d = re.sub(r"\b\d{3,}\b", "<num>", d)
    d = re.sub(r"\s+", " ", d.lower()).strip()
    p = re.sub(r"\s+", " ", (payload or "").lower()).strip()[:120]
    src = "\x00".join([(lab or "").strip().lower(), d[:220], p, (sev or "").upper()])
    return "F-" + hashlib.sha256(src.encode("utf-8", "ignore")).hexdigest()[:14]

def _finding_group_key(finding: Any) -> str:
    if isinstance(finding, Finding):
        module, detail, payload, severity = finding.as_tuple()
    else:
        module, detail, payload, severity = finding
    clean = re.sub(r"\[[A-Z ]+\]\s*", "", detail or "")
    clean = re.sub(r"https?://[^\s,;'\"<>]+", "<url>", clean)
    clean = re.sub(r"\b\d+\b", "<num>", clean)
    clean = re.sub(r"\s+", " ", clean.lower()).strip()[:140]
    return hashlib.sha256(("\x00".join([module.lower(), clean, severity])).encode("utf-8", "ignore")).hexdigest()[:14]

def _finding_duplicate_groups() -> List[Dict[str, Any]]:
    groups: Dict[str, Dict[str, Any]] = {}
    structured = list(_FINDINGS_STRUCTURED) or [_build_finding(m, d, p, s) for m, d, p, s in _FINDINGS_SUMMARY]
    for finding in structured:
        key = _finding_group_key(finding)
        group = groups.setdefault(key, {
            "group_id": "G-" + key,
            "module": finding.module,
            "severity": finding.severity,
            "title": finding.detail.replace("[CONFIRMED] ", "")[:180],
            "count": 0,
            "finding_ids": [],
            "payload_samples": [],
        })
        group["count"] += 1
        if finding.id:
            group["finding_ids"].append(finding.id)
        if finding.payload and len(group["payload_samples"]) < 5:
            group["payload_samples"].append(finding.payload[:180])
    return sorted(groups.values(), key=lambda g: (-int(g["count"]), g["severity"], g["module"]))

def _scan_quality_snapshot() -> Dict[str, Any]:
    with _SCAN_QUALITY_LOCK:
        q = json.loads(json.dumps(_SCAN_QUALITY))
    planned = int(q.get("planned", 0))
    run = int(q.get("run", 0))
    failed = int(q.get("failed", 0))
    timeout = int(q.get("timeout", 0))
    coverage = (run / planned) if planned else 0.0
    verified = sum(1 for _, d, _, _ in _FINDINGS_SUMMARY if "[CONFIRMED]" in d)
    total = len(_FINDINGS_SUMMARY)
    confirmed_ratio = (verified / total) if total else 0.0
    oracle_stats = _ORACLE.stats() if _ORACLE is not None else {}
    warnings_out: List[str] = []
    if planned and coverage < 0.5:
        warnings_out.append("low module coverage")
    if failed or timeout:
        warnings_out.append("some modules failed or timed out")
    if not _SCAN_CONFIG.tls_verify:
        warnings_out.append("TLS certificate verification disabled")
    if _ORACLE is not None and oracle_stats.get("probes_analyzed", 0) < 50:
        warnings_out.append("oracle evidence sample is small")
    if _ORACLE is not None and oracle_stats.get("probes_analyzed", 0) < 140:
        warnings_out.append("oracle calibration confidence is limited by sample size")
    q.update({
        "coverage_ratio": round(coverage, 3),
        "confirmed_ratio": round(confirmed_ratio, 3),
        "failed_modules": failed,
        "timed_out_modules": timeout,
        "skipped_modules": int(q.get("skipped", 0)),
        "coverage": _scan_coverage_snapshot(),
        "module_reliability": _module_reliability_snapshot(q),
        "proxy": _proxy_runtime_report(),
        "confidence": "high" if coverage >= 0.75 and not failed and not timeout else "medium" if coverage >= 0.4 else "low",
        "tls_verify": _SCAN_CONFIG.tls_verify,
        "warnings": warnings_out,
    })
    return q

def _module_reliability_snapshot(q: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
    if q is None:
        with _SCAN_QUALITY_LOCK:
            q = json.loads(json.dumps(_SCAN_QUALITY))
    out: List[Dict[str, Any]] = []
    for name, mod in sorted((q.get("modules") or {}).items()):
        status = mod.get("status", "pending")
        findings = int(mod.get("findings", 0) or 0)
        confirmed = int(mod.get("confirmed", 0) or 0)
        speculative = int(mod.get("speculative", 0) or 0)
        score = 100
        if status in ("failed", "timeout"):
            score -= 45
        elif status == "skipped":
            score -= 30
        if findings and not confirmed:
            score -= min(25, findings * 3)
        if speculative:
            score -= min(30, speculative * 5)
        if confirmed:
            score += min(15, confirmed * 3)
        score = max(0, min(100, score))
        grade = "high" if score >= 75 else "medium" if score >= 45 else "low"
        out.append({
            "module": name,
            "status": status,
            "score": score,
            "grade": grade,
            "requests": int(mod.get("requests", 0) or 0),
            "findings": findings,
            "confirmed": confirmed,
            "speculative": speculative,
            "elapsed": mod.get("elapsed", 0.0),
            "detail": mod.get("detail", ""),
        })
    return out

def _finding_confidence_score(lab: str, detail: str, payload: str, sev: str, confirmed: bool) -> int:
    text = (detail + " " + payload).lower()
    rank = _REPORT_SEV_ORDER.get(sev, 0)
    score = rank
    if confirmed:
        score += 4
    if _STRONG_FINDING_RE.search(text):
        score += 4
    if _EXACT_EVIDENCE_RE.search(text):
        score += 5
    if _PROOF_PAIR_RE.search(text):
        score += 3
    if payload and len(payload.strip()) >= 4:
        score += 1
    if _URL_IN_TEXT_RE.search(detail) or _URL_IN_TEXT_RE.search(payload):
        score += 1
    if _WEAK_FINDING_RE.search(text):
        score -= 3
    if _LOW_CONFIDENCE_MODULE_RE.search(lab):
        score -= 2
    if _VERSION_ONLY_RE.search(text) and not _EXACT_EVIDENCE_RE.search(text):
        score -= 4
    if _PASSIVE_CONFIG_RE.search(text) and rank <= _REPORT_SEV_ORDER["MED"]:
        score -= 3
    return max(0, min(100, score * 8))

def _confidence_label(score: int) -> str:
    if score >= 80:
        return "confirmed"
    if score >= 60:
        return "high"
    if score >= 35:
        return "medium"
    return "low"

def _confidence_threshold(label: str) -> int:
    return {"low": 0, "medium": 35, "high": 60, "confirmed": 80}.get((label or "low").lower(), 0)

_REDACT_PATTERNS = [
    (re.compile(r"(?i)(authorization\s*:\s*bearer\s+)[A-Za-z0-9._~+/=-]{8,}"), r"\1<redacted>"),
    (re.compile(r"(?i)(cookie\s*:\s*)[^\r\n]+"), r"\1<redacted>"),
    (re.compile(r"(?i)(set-cookie\s*:\s*)[^\r\n]+"), r"\1<redacted>"),
    (re.compile(r"(?i)\b(api[_-]?key|access[_-]?token|refresh[_-]?token|session[_-]?id|password|passwd|secret)(['\"\s:=]+)[A-Za-z0-9._~+/=-]{6,}"), r"\1\2<redacted>"),
    (re.compile(r"\bAKIA[0-9A-Z]{16}\b"), "<redacted-aws-key>"),
    (re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]{0,2000}------END [A-Z ]*PRIVATE KEY-----"), "<redacted-private-key>"),
]

def _redact_text(value: Any) -> Any:
    if not _REDACT_EVIDENCE or not isinstance(value, str):
        return value
    out = value
    for pattern, repl in _REDACT_PATTERNS:
        out = pattern.sub(repl, out)
    return out

def _evidence_quality_audit() -> List[Dict[str, Any]]:
    weak: List[Dict[str, Any]] = []
    for finding in _structured_findings_for_report() if "_structured_findings_for_report" in globals() else []:
        reasons = []
        if finding.evidence_level in ("possible", "informational"):
            reasons.append("weak evidence level")
        if not finding.payload:
            reasons.append("missing payload/evidence detail")
        if finding.confidence_score < 35:
            reasons.append("low confidence")
        if reasons:
            weak.append({"id": finding.id, "module": finding.module, "severity": finding.severity, "reasons": reasons})
    return weak

def _module_health_audit() -> List[Dict[str, Any]]:
    q = _scan_quality_snapshot()
    out = []
    for item in q.get("module_reliability", []) or []:
        reasons = []
        if item.get("grade") == "low":
            reasons.append("low reliability")
        if item.get("status") in ("failed", "timeout"):
            reasons.append(str(item.get("status")))
        if int(item.get("requests", 0) or 0) > 250:
            reasons.append("high request count")
        if reasons:
            row = dict(item)
            row["reasons"] = reasons
            out.append(row)
    return out

def _sensitive_data_audit() -> List[Dict[str, Any]]:
    patterns = [
        ("email", re.compile(r"\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b", re.I)),
        ("internal_ip", re.compile(r"\b(?:10\.\d{1,3}\.\d{1,3}\.\d{1,3}|192\.168\.\d{1,3}\.\d{1,3}|172\.(?:1[6-9]|2\d|3[01])\.\d{1,3}\.\d{1,3})\b")),
        ("secret_keyword", re.compile(r"(?i)\b(api[_-]?key|access[_-]?token|refresh[_-]?token|secret|passwd|password)\b")),
        ("stack_trace", re.compile(r"(?i)(traceback \(most recent call last\)|exception in thread|at [\w.$]+\(.*:\d+\)|stack trace)")),
        ("cloud_metadata", re.compile(r"\b169\.254\.169\.254\b|metadata\.google\.internal|metadata\.azure\.com", re.I)),
    ]
    hits: List[Dict[str, Any]] = []
    seen: Set[Tuple[str, str, str]] = set()
    for finding in _structured_findings_for_report() if "_structured_findings_for_report" in globals() else []:
        hay = "\n".join([finding.detail or "", finding.payload or ""])
        for name, rx in patterns:
            m = rx.search(hay)
            if not m:
                continue
            sample = _redact_text(m.group(0))[:96]
            key = (finding.id, name, sample)
            if key in seen:
                continue
            seen.add(key)
            hits.append({"finding_id": finding.id, "module": finding.module, "type": name, "sample": sample})
            break
    return hits[:100]

def _request_cache_snapshot() -> Dict[str, Any]:
    out = dict(_REQUEST_CACHE_STATS)
    total = max(1, int(out.get("hits", 0)) + int(out.get("misses", 0)) + int(out.get("inflight_hits", 0)))
    out["enabled"] = _REQUEST_CACHE_ENABLED
    out["hit_rate"] = round((int(out.get("hits", 0)) + int(out.get("inflight_hits", 0))) / total, 3)
    return out

def _redact_obj(value: Any) -> Any:
    if not _REDACT_EVIDENCE:
        return value
    if isinstance(value, dict):
        redacted = {}
        for key, item in value.items():
            if re.search(r"(?i)(authorization|cookie|token|secret|password|api[_-]?key)", str(key)):
                redacted[key] = "<redacted>" if isinstance(item, str) else _redact_obj(item)
            else:
                redacted[key] = _redact_obj(item)
        return redacted
    if isinstance(value, list):
        return [_redact_obj(item) for item in value]
    if isinstance(value, str):
        return _redact_text(value)
    return value

def _load_json_file(path: str, default: Any) -> Any:
    try:
        with open(path, "r", encoding="utf-8-sig") as fh:
            return json.load(fh)
    except Exception:
        return default

def _load_suppressions(path: str) -> None:
    global _SUPPRESSIONS
    try:
        with open(path, "r", encoding="utf-8-sig") as fh:
            raw = json.load(fh)
    except Exception as exc:
        _SUPPRESSIONS = []
        _out(_paint("  [suppress] unable to read %s: %s" % (path, exc), A.Y))
        return
    if isinstance(raw, dict):
        raw = raw.get("suppressions", [])
    if not isinstance(raw, list):
        _SUPPRESSIONS = []
        _out(_paint("  [suppress] invalid suppression JSON: expected list or {suppressions:[...]}", A.Y))
        return
    _SUPPRESSIONS = [x for x in raw if isinstance(x, dict)]
    if _SUPPRESSIONS:
        _out(_paint("  [suppress] loaded %d suppression rule(s)" % len(_SUPPRESSIONS), A.C))

def _load_baseline_ids(path: str) -> None:
    global _BASELINE_FINDING_IDS
    if not os.path.exists(path):
        _BASELINE_FINDING_IDS = set()
        _out(_paint("  [baseline] unable to read %s: file does not exist" % path, A.Y))
        return
    _BASELINE_FINDING_IDS = set(_load_report_findings(path).keys())
    color = A.C if _BASELINE_FINDING_IDS else A.Y
    _out(_paint("  [baseline] loaded %d finding id(s) from %s" % (len(_BASELINE_FINDING_IDS), path), color))

def _load_module_budget_overrides(path: str) -> None:
    global _MODULE_BUDGET_OVERRIDES
    try:
        with open(path, "r", encoding="utf-8-sig") as fh:
            obj = json.load(fh)
    except Exception as exc:
        _MODULE_BUDGET_OVERRIDES = {}
        _out(_paint("  [budget] unable to read %s: %s" % (path, exc), A.Y))
        return
    rows = obj.get("modules", obj) if isinstance(obj, dict) else {}
    clean: Dict[str, Dict[str, float]] = {}
    warnings_count = 0
    if not isinstance(rows, dict):
        _out(_paint("  [budget] invalid module budget JSON: expected object or {modules:{...}}", A.Y))
        rows = {}
    if isinstance(rows, dict):
        for label, cfg in rows.items():
            if not isinstance(cfg, dict):
                warnings_count += 1
                continue
            key = str(label).strip().lower()
            try:
                timeout_val = max(0.0, float(cfg.get("timeout", cfg.get("module_timeout", 0)) or 0))
                request_val = max(0.0, float(cfg.get("requests", cfg.get("max_requests", 0)) or 0))
                clean[key] = {"timeout": timeout_val, "requests": request_val}
            except (TypeError, ValueError):
                warnings_count += 1
    _MODULE_BUDGET_OVERRIDES = clean
    if clean:
        _out(_paint("  [budget] loaded %d module budget override(s)" % len(clean), A.C))
    if warnings_count:
        _out(_paint("  [budget] ignored %d invalid module budget entr%s" % (warnings_count, "y" if warnings_count == 1 else "ies"), A.Y))

def _module_budget_for(label: str) -> Tuple[int, float]:
    cfg = _MODULE_BUDGET_OVERRIDES.get(label.strip().lower(), {})
    reqs = int(cfg.get("requests") or _SCAN_CONFIG.module_request_budget or 0)
    tout = float(cfg.get("timeout") or _SCAN_CONFIG.module_timeout or _MODULE_TIMEOUT)
    return max(0, reqs), max(1.0, tout)

def _extract_retest_url(item: Dict[str, Any], fallback_base: str = "") -> str:
    for key in ("url", "endpoint"):
        val = str(item.get(key, "") or "")
        if val.startswith(("http://", "https://")):
            return val
    payload = str(item.get("payload", "") or "")
    m = re.search(r"https?://[^\s'\"<>]+", payload)
    if m:
        return m.group(0).rstrip("),.;")
    if fallback_base and payload.startswith("/"):
        return _join_url(fallback_base, payload)
    return fallback_base

def _run_retest_report(path: str, fallback_base: str = "") -> int:
    try:
        with open(path, "r", encoding="utf-8-sig") as fh:
            old = json.load(fh)
    except Exception as exc:
        _out(_paint("  [retest] unable to read report %s: %s" % (path, exc), A.R))
        return 2
    if not isinstance(old, dict):
        _out(_paint("  [retest] invalid report %s: expected JSON object" % path, A.R))
        return 2
    findings = old.get("findings", [])
    if not isinstance(findings, list):
        _out(_paint("  [retest] invalid report %s: findings must be a list" % path, A.R))
        return 2
    results: List[Dict[str, Any]] = []
    for item in findings:
        if not isinstance(item, dict):
            continue
        url = _extract_retest_url(item, fallback_base or str(old.get("target", "") or ""))
        if not url:
            results.append({"id": item.get("id", ""), "module": item.get("module", ""), "status": "unknown", "reason": "no replayable URL"})
            continue
        c, h, b, final_url = _req(url, timeout=min(_GLOBAL_TIMEOUT, 8.0), use_cache=False)
        text = b[:4096].decode("utf-8", "ignore")
        detail = str(item.get("detail", "") or "")
        old_status = int(item.get("status", 0) or item.get("response_status", 0) or 0)
        still = bool(old_status and c == old_status) or bool(detail and len(detail) > 24 and detail[:80].lower() in text.lower())
        status = "still_present" if still else "fixed" if c and c < 500 else "unknown"
        results.append({
            "id": item.get("id", ""),
            "module": item.get("module", ""),
            "severity": item.get("severity", item.get("sev", "")),
            "url": url,
            "final_url": final_url,
            "status": status,
            "http_status": c,
        })
    out = {
        "schema_version": "1.0",
        "mode": "retest",
        "source": path,
        "generated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "summary": {k: sum(1 for r in results if r.get("status") == k) for k in ("still_present", "fixed", "unknown")},
        "results": results,
    }
    if _JSON_FILE:
        with open(_JSON_FILE, "w", encoding="utf-8") as fh:
            json.dump(out, fh, indent=2, ensure_ascii=False)
        _out(_paint("  [retest] report saved to " + _JSON_FILE, A.C))
    else:
        _out(json.dumps(out, indent=2, ensure_ascii=False))
    return 1 if any(r.get("status") == "still_present" for r in results) else 0

def _run_module_self_tests() -> int:
    issues: List[str] = []
    warnings_out: List[str] = []
    opts: Set[str] = set()
    labels: Set[str] = set()
    for opt, label, fn in _SCAN_REGISTRY:
        if not opt or not label or not callable(fn):
            issues.append("bad registry row: %r/%r/%r" % (opt, label, fn))
        if opt in opts:
            issues.append("duplicate option: " + opt)
        opts.add(opt)
        labels.add(label.strip().lower())
        try:
            inspect.signature(fn)
        except Exception as exc:
            issues.append("signature unreadable for %s: %s" % (label, exc))
    for label in labels:
        if label not in _SCAN_SEVERITY:
            warnings_out.append("missing severity: " + label)
    if issues:
        _out(_paint("  [self-test] %d issue(s)" % len(issues), A.R))
        for issue in issues[:80]:
            _out(_paint("    - " + issue, A.Y))
        return 1
    if warnings_out:
        _out(_paint("  [self-test] OK with %d warning(s)" % len(warnings_out), A.Y))
        if _VERBOSE:
            for warning in warnings_out[:40]:
                _out(_paint("    - " + warning, A.D))
        else:
            _out(_paint("    run with -v to print warning details", A.D))
        return 0
    _out(_paint("  [self-test] OK: %d registry modules checked" % len(_SCAN_REGISTRY), A.G))
    return 0

def _ci_exit_code() -> int:
    if not _CI_FAIL_ON:
        return 0
    floor = _REPORT_SEV_ORDER.get(_CI_FAIL_ON.upper(), _REPORT_SEV_ORDER.get("HIGH", 3))
    return 1 if any(_REPORT_SEV_ORDER.get(s, 0) >= floor for _, _, _, s in _FINDINGS_SUMMARY) else 0

def _finding_suppressed(fid: str, lab: str, detail: str, payload: str, sev: str) -> Tuple[bool, str]:
    if _ONLY_NEW_FINDINGS and fid in _BASELINE_FINDING_IDS:
        return True, "baseline"
    hay = "\n".join([fid, lab, detail, payload, sev])
    for rule in _SUPPRESSIONS:
        if rule.get("id") and str(rule.get("id")) == fid:
            return True, str(rule.get("reason", "id suppression"))
        if rule.get("module") and str(rule.get("module")).lower() != lab.lower():
            continue
        if rule.get("severity") and str(rule.get("severity")).upper() != sev.upper():
            continue
        pattern = rule.get("regex") or rule.get("pattern")
        if pattern:
            try:
                if not re.search(str(pattern), hay, re.I):
                    continue
            except re.error:
                continue
        return True, str(rule.get("reason", "suppression rule"))
    return False, ""

def _scanner_manifest(args: Optional[object] = None) -> Dict[str, Any]:
    try:
        src_bytes = open(__file__, "rb").read()
        src_hash = hashlib.sha256(src_bytes).hexdigest()
    except Exception:
        src_hash = ""
    return {
        "schema_version": "1.0",
        "tool": _TOOL_NAME,
        "started_at": _SCAN_STARTED_WALL,
        "generated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "scanner_sha256": src_hash,
        "python": sys.version,
        "platform": platform.platform(),
        "argv": sys.argv,
        "args": vars(args) if args is not None else {},
        "module_count": len(_SCAN_REGISTRY) if "_SCAN_REGISTRY" in globals() else 0,
        "modules": [{"option": opt, "label": label, "category": category_for_option(opt), "tags": sorted(_module_tags(opt, label))} for opt, label, _ in globals().get("_SCAN_REGISTRY", [])],
    }


def _finding_evidence_profile(lab: str, detail: str, payload: str, sev: str, confirmed: bool) -> Dict[str, bool]:
    text = detail + " " + payload
    low = text.lower()
    exact = _EXACT_EVIDENCE_RE.search(text) is not None
    strong = _STRONG_FINDING_RE.search(text) is not None
    proof_pair = _PROOF_PAIR_RE.search(text) is not None
    passive = _PASSIVE_CONFIG_RE.search(low) is not None or _LOW_CONFIDENCE_MODULE_RE.search(lab) is not None
    version_only = _VERSION_ONLY_RE.search(low) is not None and not exact
    destructive = re.search(r"\b(written and retrieved|server executed|uid=\d+|root:x:0:0|private key|token issued|mutation .* succeeded|auth bypass|without authentication)\b", low) is not None
    leak = re.search(r"\b(secret|token|credential|private key|api[_ -]?key|password|jwks exposes|symmetric key|hardcoded)\b", low) is not None and exact
    differential = proof_pair or re.search(r"\b(delta|score_gap|true_len|false_len|status\s*(?:change|=)|baseline|variant)\b", low) is not None
    return {
        "exact": exact,
        "strong": strong,
        "proof_pair": proof_pair,
        "passive": passive,
        "version_only": version_only,
        "destructive": destructive,
        "leak": leak,
        "differential": differential,
    }

def _finding_evidence_level(lab: str, detail: str, payload: str, sev: str, confirmed: bool) -> str:
    rank = _REPORT_SEV_ORDER.get(sev, 0)
    score = _finding_confidence_score(lab, detail, payload, sev, confirmed)
    profile = _finding_evidence_profile(lab, detail, payload, sev, confirmed)
    if confirmed or profile["destructive"] or profile["leak"]:
        return "confirmed"
    if profile["version_only"] or profile["passive"]:
        return "informational" if rank <= _REPORT_SEV_ORDER["MED"] else "possible"
    if profile["exact"] and (profile["proof_pair"] or profile["differential"] or score >= 8):
        return "probable"
    if profile["strong"] and score >= 7:
        return "probable"
    if rank <= _REPORT_SEV_ORDER["LOW"] and score < 6:
        return "informational"
    return "possible"

def _is_speculative_exposure(lab: str, detail: str, payload: str, sev: str, confirmed: bool) -> bool:
    if confirmed:
        return False
    low_lab = (lab or "").lower()
    text = ((detail or "") + " " + (payload or "")).lower()
    if not (low_lab.startswith("zd ") or " cve" in low_lab or "cve " in low_lab or "version cve" in low_lab or "cve-" in text):
        return False
    profile = _finding_evidence_profile(lab, detail, payload, sev, confirmed)
    if profile["destructive"] or profile["leak"] or profile["proof_pair"] or "[verified]" in text:
        return False
    proof_words = r"\b(written and retrieved|executed|auth bypass|shell|uid=\d+|root:x:0:0|location=|private key|token issued)\b"
    if re.search(proof_words, text):
        return False
    return True

def _downgrade_speculative_exposure(lab: str, detail: str, payload: str, sev: str, confirmed: bool) -> Tuple[str, str]:
    if not _is_speculative_exposure(lab, detail, payload, sev, confirmed):
        return detail, sev
    clean = detail
    if not clean.startswith("[POSSIBLE EXPOSURE]"):
        clean = "[POSSIBLE EXPOSURE] " + clean
    if "patch status unknown" not in clean.lower():
        clean += " (patch status unknown; no exploit primitive confirmed)"
    rank = _REPORT_SEV_ORDER.get(sev, 0)
    if rank > _REPORT_SEV_ORDER["MED"]:
        sev = "MED"
    return clean, sev

def _normalize_finding_severity(lab: str, detail: str, payload: str, sev: str, confirmed: bool) -> str:
    rank = _REPORT_SEV_ORDER.get(sev, 0)
    profile = _finding_evidence_profile(lab, detail, payload, sev, confirmed)
    level = _finding_evidence_level(lab, detail, payload, sev, confirmed)
    score = _finding_confidence_score(lab, detail, payload, sev, confirmed)
    if _is_speculative_exposure(lab, detail, payload, sev, confirmed):
        return "MED" if rank >= _REPORT_SEV_ORDER["MED"] else sev
    if level == "informational":
        return "INFO" if rank <= _REPORT_SEV_ORDER["LOW"] else "LOW"
    if level == "possible" and rank > _REPORT_SEV_ORDER["HIGH"]:
        return "HIGH"
    if profile["version_only"] and rank > _REPORT_SEV_ORDER["MED"]:
        return "MED"
    if profile["passive"] and not confirmed and not (profile["leak"] or profile["destructive"]) and rank > _REPORT_SEV_ORDER["MED"]:
        return "MED"
    if sev in ("CRIT", "ZERO") and not confirmed:
        if not ((profile["destructive"] or profile["leak"] or profile["proof_pair"]) and score >= 9):
            return "HIGH"
    if sev == "ZERO" and confirmed:
        return "CRIT"
    return sev

def _can_auto_confirm_finding(lab: str, detail: str, payload: str, sev: str, confirmed: bool) -> bool:
    if confirmed:
        return False
    rank = _REPORT_SEV_ORDER.get(sev, 0)
    profile = _finding_evidence_profile(lab, detail, payload, sev, confirmed)
    if profile["version_only"]:
        return False
    if profile["passive"] and not (profile["exact"] and (profile["leak"] or profile["destructive"])):
        return False
    score = _finding_confidence_score(lab, detail, payload, sev, confirmed)
    if profile["destructive"] and rank >= _REPORT_SEV_ORDER["MED"] and score >= 8:
        return True
    if profile["leak"] and rank >= _REPORT_SEV_ORDER["HIGH"] and score >= 8:
        return True
    if profile["exact"] and profile["proof_pair"] and rank >= _REPORT_SEV_ORDER["MED"] and score >= 8:
        return True
    return rank >= _REPORT_SEV_ORDER["CRIT"] and profile["exact"] and score >= 9

def _should_report_finding(lab: str, detail: str, payload: str, sev: str, confirmed: bool) -> bool:
    if _finding_confidence_score(lab, detail, payload, sev, confirmed) < _MIN_CONFIDENCE_SCORE:
        return False
    if not _FINDING_STRICT:
        return True
    text = (detail + " " + payload).lower()
    rank = _REPORT_SEV_ORDER.get(sev, 0)
    profile = _finding_evidence_profile(lab, detail, payload, sev, confirmed)
    strong = profile["strong"]
    exact = profile["exact"]
    weak = _WEAK_FINDING_RE.search(text) is not None or (profile["passive"] and not exact)
    score = _finding_confidence_score(lab, detail, payload, sev, confirmed)
    if sev == "ZERO":
        return exact or (strong and score >= 8)
    if confirmed:
        if exact:
            return score >= 3
        if rank >= _REPORT_SEV_ORDER["HIGH"] and weak and not strong:
            return False
        if profile["version_only"] and not strong:
            return False
        return score >= 4
    if exact and (profile["leak"] or profile["destructive"] or profile["proof_pair"]):
        return score >= 5
    if rank >= _REPORT_SEV_ORDER["HIGH"]:
        return score >= 7 and (strong or exact)
    if rank >= _REPORT_SEV_ORDER["MED"] and weak and not strong:
        return False
    if rank <= _REPORT_SEV_ORDER["LOW"] and weak:
        return False
    return score >= 3



def _print_site_working(base: str) -> bool:
    global _ADAPTIVE_TIMEOUT
    t0 = time.perf_counter()
    code, hdrs, body, _ = _req(base, use_cache=True)
    rtt = time.perf_counter() - t0
    if code == 0:
        _out(_paint("  [!] Unreachable or connection error", A.R))
        return False
    _ADAPTIVE_TIMEOUT = max(2.5, min(rtt * 4, _GLOBAL_TIMEOUT))
    server = hdrs.get("server", "")
    powered = hdrs.get("x-powered-by", "")
    info = ""
    if server:
        info += " server=" + server
    if powered:
        info += " powered-by=" + powered
    _out(
        _paint("  [+] Reachable ", A.G)
        + _paint("HTTP " + str(code), A.C)
        + _paint(info, A.D)
    )
    return True

def _writable_path_hint(path: Optional[str]) -> bool:
    if not path:
        return True
    try:
        folder = os.path.dirname(os.path.abspath(path)) or os.getcwd()
        os.makedirs(folder, exist_ok=True)
        return os.access(folder, os.W_OK)
    except Exception:
        return False

def _print_oob_public_hint(base: str = "") -> bool:
    host = _OOB_HOST or _local_ip()
    port = _OOB_FORCED_PORT or _OOB_PORT or 0
    info = describe_oob(host, port, base, bool(_OOB_HOST))
    shown_port = str(port) if port else "(auto)"
    _out(_paint("  [OOB] listener host=" + str(info["host"]) + " port=" + shown_port, A.C))
    if info["private_listener"] and info["internet_target"]:
        _out(_paint(
            "  [OOB] LAN/private listener cannot receive callbacks from internet targets.",
            A.Y,
        ))
        _out(_paint(
            "  [OOB] Use --oob-host <public-ip-or-domain> plus port forwarding, a tunnel, or a VPS listener.",
            A.Y,
        ))
        if not _OOB_ALLOW_PRIVATE_HOST:
            _out(_paint("  [OOB] For routed lab/private targets, add --oob-allow-private-host.", A.C))
        return False
    _out(_paint("  [OOB] listener address looks usable for this target scope", A.G))
    return True

def _module_tags(option: str, label: str) -> Set[str]:
    text = (str(option) + " " + str(label) + " " + category_for_option(str(option))).lower()
    tags: Set[str] = set()
    if any(k in text for k in ("headers", "tls", "csp", "robots", "sitemap", "security.txt", "tech", "referrer", "permissions", "reporting", "cachecontrol", "sri", "mixed")):
        tags.add("passive")
    if any(k in text for k in ("xss", "sqli", "cmdi", "ssti", "xxe", "lfi", "rfi", "xpath", "nosql", "ldap", "injection", "polyglot")):
        tags.add("injection")
    if any(k in text for k in ("oob", "blind xss", "log4j", "ssrf", "jndi")):
        tags.add("oob")
    if any(k in text for k in ("upload", "putwrite", "race", "massassign", "mutate", "model", "write", "delete", "post", "patch")):
        tags.add("write")
    if any(k in text for k in ("brute", "crack", "defcreds", "lockout", "password", "jwtcrack")):
        tags.add("bruteforce")
    if any(k in text for k in ("headless", "browser", "dom", "click", "websocket", "ws")):
        tags.add("browser")
    if any(k in text for k in ("redis", "mongo", "elastic", "memcached", "smtp", "ftp", "dns", "tls", "subenum", "zone")):
        tags.add("network")
    if str(label).lower() in _SLOW_SCANS or any(k in text for k in ("deep", "oracle", "crawl", "headless", "race", "brute", "fuzz")):
        tags.add("slow")
    if not tags:
        tags.add("active")
    return tags

def _risk_from_tags(tags: Set[str]) -> str:
    if tags & {"write", "bruteforce"}:
        return "intrusive"
    if tags & {"oob", "injection", "network", "browser"}:
        return "active"
    if tags == {"slow"}:
        return "normal"
    if tags <= {"passive", "slow"} or "passive" in tags and not (tags & {"active", "injection", "oob", "write", "bruteforce"}):
        return "passive"
    return "normal"

def _risk_rank(risk: str) -> int:
    return {"passive": 0, "normal": 1, "active": 2, "intrusive": 3}.get(risk, 1)

def _module_allowed(label: str, args: Optional[object] = None) -> Tuple[bool, str]:
    tags = _module_tags("", label)
    risk = _risk_from_tags(tags)
    if _risk_rank(risk) > _risk_rank(_PAYLOAD_SAFETY):
        return False, "payload safety %s blocks %s module" % (_PAYLOAD_SAFETY, risk)
    if risk == "intrusive" and not _AUTHORIZED_HIGH_RISK:
        return False, "intrusive module requires --authorized"
    return True, ""

def _filter_allowed_sections(sections: List[Tuple[str, Callable[[], ScanFindings]]]) -> List[Tuple[str, Callable[[], ScanFindings]]]:
    kept: List[Tuple[str, Callable[[], ScanFindings]]] = []
    blocked = 0
    for label, fn in sections:
        ok, why = _module_allowed(label)
        if ok:
            kept.append((label, fn))
        else:
            blocked += 1
            _quality_event("skipped", label, why)
    if blocked and not _QUIET_MODE:
        _out(_paint("  [safety] skipped %d module(s); use --payload-safety intrusive and --authorized for high-risk scans" % blocked, A.Y))
    return kept

def _adaptive_order_sections(sections: List[Tuple[str, Callable[[], ScanFindings]]]) -> List[Tuple[str, Callable[[], ScanFindings]]]:
    if not sections:
        return sections
    stack = (_DETECTED_STACK or "").lower()
    def score(item: Tuple[str, Callable[[], ScanFindings]]) -> int:
        label = item[0].lower()
        s = 50
        if any(k in label for k in ("technology", "headers", "tls", "waf", "inventory")):
            s -= 20
        if stack and stack != "unknown" and stack in label:
            s -= 25
        if stack == "wordpress" and "wordpress" in label:
            s -= 30
        if stack in ("react", "vue", "nextjs") and any(k in label for k in ("dom", "js", "sourcemap", "client")):
            s -= 20
        if label in _SLOW_SCANS or "deep" in label or "fuzz" in label:
            s += 20
        avg = _module_timing_avg(label)
        if avg:
            if avg < 2.0:
                s -= 8
            elif avg > 15.0:
                s += 12
        if "oob" in label:
            s += 10
        return s
    return sorted(sections, key=score)

def _scan_risk_profile(labels: Optional[List[str]] = None, options: Optional[List[str]] = None, all_modules: bool = False) -> Dict[str, Any]:
    tag_counts: Dict[str, int] = {}
    risks: List[str] = []
    entries = _SCAN_REGISTRY if all_modules else [
        entry for entry in _SCAN_REGISTRY
        if (labels and entry[1] in labels) or (options and entry[0] in options)
    ]
    if not entries and labels:
        entries = [("", label, lambda _b: []) for label in labels]
    for option, label, _ in entries:
        tags = _module_tags(option, label)
        for tag in tags:
            tag_counts[tag] = tag_counts.get(tag, 0) + 1
        risks.append(_risk_from_tags(tags))
    risk = max(risks, key=_risk_rank) if risks else "normal"
    return {"risk": risk, "tag_counts": tag_counts, "module_count": len(entries)}

def _print_target_scope(base: str, args: object) -> None:
    parsed = urllib.parse.urlparse(base)
    host = parsed.hostname or ""
    port = parsed.port or (443 if parsed.scheme == "https" else 80)
    private = host_is_private(host)
    scope = getattr(args, "scope", None) or parsed.netloc
    risk = _scan_risk_profile(all_modules=bool(getattr(args, "all", False))).get("risk", "normal")
    _out(_paint("  [scope] scheme=%s host=%s port=%s private=%s" % (
        parsed.scheme, host, port, "yes" if private else "no",
    ), A.C))
    _out(_paint("  [scope] crawl scope=%s target_class=%s risk=%s" % (
        scope, "private/lab" if private else "public/internet", risk,
    ), A.C))

def _detect_public_ip(timeout: float = 4.0) -> Optional[str]:
    for url in ("https://api.ipify.org", "https://ifconfig.me/ip"):
        try:
            req = urllib.request.Request(url, headers={"User-Agent": _GLOBAL_UA})
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                body = resp.read(128).decode("ascii", "ignore").strip()
            if re.match(r"^[0-9a-fA-F:.]+$", body):
                return body
        except Exception:
            continue
    return None

def _print_public_ip_hint() -> Optional[str]:
    ip = _detect_public_ip()
    if ip:
        _out(_paint("  [net] outbound public IP appears to be " + ip, A.C))
        _out(_paint("  [OOB] If callbacks are port-forwarded here, use --oob-host " + ip, A.C))
    else:
        _out(_paint("  [net] public IP detection failed; try --oob-host <public-ip-or-domain> manually", A.Y))
    return ip

def _load_report_findings(path: str) -> Dict[str, Dict[str, Any]]:
    try:
        with open(path, "r", encoding="utf-8-sig") as fh:
            data = json.load(fh)
    except Exception as exc:
        _out(_paint("  [compare] unable to read baseline %s: %s" % (path, exc), A.R))
        return {}
    if not isinstance(data, (dict, list)):
        _out(_paint("  [compare] invalid baseline %s: expected object or list" % path, A.R))
        return {}
    raw = data.get("findings", data if isinstance(data, list) else [])
    out: Dict[str, Dict[str, Any]] = {}
    if not isinstance(raw, list):
        _out(_paint("  [compare] invalid baseline %s: findings must be a list" % path, A.R))
        return out
    for item in raw:
        if not isinstance(item, dict):
            continue
        fid = str(item.get("id") or "")
        if not fid:
            fid = _finding_stable_id(str(item.get("module", "")), str(item.get("detail", "")), str(item.get("payload", "")), str(item.get("severity", item.get("sev", "INFO"))))
        out[fid] = item
    return out

def _compare_report_file(path: str) -> Dict[str, Any]:
    old = _load_report_findings(path)
    current = {f.id or _finding_stable_id(*f.as_tuple()): f.as_json() for f in (list(_FINDINGS_STRUCTURED) or [_build_finding(m, d, p, s) for m, d, p, s in _FINDINGS_SUMMARY])}
    old_ids = set(old.keys())
    cur_ids = set(current.keys())
    severity_changed: List[Dict[str, str]] = []
    for fid in sorted(old_ids & cur_ids):
        old_sev = str(old[fid].get("severity", old[fid].get("sev", ""))).upper()
        new_sev = str(current[fid].get("severity", current[fid].get("sev", ""))).upper()
        if old_sev != new_sev:
            severity_changed.append({
                "id": fid,
                "from": old_sev,
                "to": new_sev,
                "module": str(current[fid].get("module", old[fid].get("module", ""))),
            })
    new_rows = [dict({"id": fid}, **current.get(fid, {})) for fid in sorted(cur_ids - old_ids)]
    fixed_rows = [dict({"id": fid}, **old.get(fid, {})) for fid in sorted(old_ids - cur_ids)]
    unchanged_ids = sorted((old_ids & cur_ids) - {x["id"] for x in severity_changed})
    result = {
        "baseline": path,
        "new": [x["id"] for x in new_rows],
        "new_findings": new_rows,
        "fixed": [x["id"] for x in fixed_rows],
        "resolved": [x["id"] for x in fixed_rows],
        "fixed_findings": fixed_rows,
        "unchanged": unchanged_ids,
        "severity_changed": severity_changed,
        "changed": [x["id"] for x in severity_changed],
    }
    _out(_paint("  [compare] baseline %s" % path, A.C))
    _out(_paint("  [compare] new=%d fixed=%d severity_changed=%d unchanged=%d" % (
        len(result["new"]), len(result["fixed"]), len(result["severity_changed"]), len(result["unchanged"])
    ), A.C))
    for item in new_rows[:8]:
        fid = item.get("id", "")
        _out(_paint("  [compare] NEW %s %s %s" % (fid, item.get("severity", ""), item.get("module", "")), A.Y))
    for item in fixed_rows[:8]:
        fid = item.get("id", "")
        _out(_paint("  [compare] FIXED %s %s %s" % (fid, item.get("severity", item.get("sev", "")), item.get("module", "")), A.G))
    for item in severity_changed[:8]:
        _out(_paint("  [compare] SEVERITY %s %s->%s %s" % (item["id"], item["from"], item["to"], item["module"]), A.M))
    return result

def _apply_config_file(args: argparse.Namespace, parser: argparse.ArgumentParser, path: str) -> None:
    try:
        with open(path, "r", encoding="utf-8-sig") as fh:
            data = json.load(fh)
    except Exception as exc:
        _out(_paint("  [config] unable to read %s: %s" % (path, exc), A.R))
        raise SystemExit(2)
    if not isinstance(data, dict):
        _out(_paint("  [config] invalid config file: expected object", A.R))
        raise SystemExit(2)
    cfg = data.get("args", data)
    if not isinstance(cfg, dict):
        _out(_paint("  [config] invalid config file: expected object", A.R))
        raise SystemExit(2)
    defaults = {a.dest: a.default for a in parser._actions if getattr(a, "dest", None) and a.dest != "help"}
    for key, value in cfg.items():
        if not hasattr(args, key) or key in ("config", "export_config"):
            continue
        if getattr(args, key) == defaults.get(key):
            setattr(args, key, value)
    _out(_paint("  [config] imported " + path, A.C))

def _export_config_file(path: str, args: argparse.Namespace, base: str = "") -> None:
    export_path = _resolve_output_path(path, "reports") or path
    payload = {
        "schema_version": "1.0",
        "generated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "target": base or getattr(args, "url", "") or "",
        "args": {k: v for k, v in vars(args).items() if k not in ("export_config",)},
        "scan_config": _scan_config_snapshot(),
        "proxy": _proxy_runtime_report(),
    }
    try:
        _write_json_atomic(export_path, payload, label="config export")
        _out(_paint("  [config] exported " + export_path, A.C))
    except Exception as exc:
        _out(_paint("  [config] export failed: " + str(exc), A.R))

def _run_preflight(base: str, args: object) -> int:
    _out(_paint("  [preflight] target " + base, A.BD + A.C))
    ok = True
    parsed = urllib.parse.urlparse(base)
    host = parsed.hostname or ""
    port = parsed.port or (443 if parsed.scheme == "https" else 80)
    try:
        socket.getaddrinfo(host, port)
        _out(_paint("  [preflight] DNS ok for " + host, A.G))
    except Exception as exc:
        ok = False
        _out(_paint("  [preflight] DNS failed for %s: %s" % (host, exc), A.R))
    if not _writable_path_hint(getattr(args, "output", None)):
        ok = False
        _out(_paint("  [preflight] output path is not writable: " + str(getattr(args, "output", "")), A.R))
    if not _writable_path_hint(getattr(args, "json", None)):
        ok = False
        _out(_paint("  [preflight] json path is not writable: " + str(getattr(args, "json", "")), A.R))
    if not _writable_path_hint(getattr(args, "html_report", None)):
        ok = False
        _out(_paint("  [preflight] html report path is not writable: " + str(getattr(args, "html_report", "")), A.R))
    if _GLOBAL_PROXIES:
        ok = _run_proxy_healthcheck(base) and ok
    elif _PROXY_REQUIRED:
        ok = False
        _out(_paint("  [preflight] --proxy-required set but no valid proxies are configured", A.R))
    else:
        _out(_paint("  [preflight] proxy: direct mode", A.C))
    if getattr(args, "oob_public_hint", False) or any(getattr(args, name, False) for name in ("oobssrf", "oobxxe", "oobcmdi", "oobl4j", "oobssti", "blindxss")):
        if getattr(args, "detect_public_ip", False):
            _print_public_ip_hint()
        ok = _print_oob_public_hint(base) and ok
    elif getattr(args, "detect_public_ip", False):
        _print_public_ip_hint()
    reachable = _print_site_working(base)
    ok = reachable and ok
    _out(_paint("  [preflight] " + ("ok" if ok else "failed"), A.G if ok else A.R))
    return 0 if ok else 2

def _want_another_scan() -> bool:
    try:
        ans = input(_paint("\n  Scan another target- (y/n): ", A.Y + A.BD)).strip().lower()
    except EOFError:
        return False
    return ans in ("y", "yes")

_BCM_SENSITIVITY_THRESHOLD: float = 1.5

_BCM_ALL_VALUES: List[str] = list(dict.fromkeys(
    v for cls in _BCM_VALUE_CLASSES.values() for v in cls
))

_BCM_ERROR_RE = re.compile(r"error|exception|invalid|denied|forbidden|unauthorized|syntax", re.I)
_BCM_PRIV_RE  = re.compile(r"admin|role|permission|privilege|user_id|account", re.I)

def scan_behavioral_contradiction_matrix(url: str) -> ScanFindings:
    info_out: ScanFindings = []
    vuln_out: ScanFindings = []

    NUMERIC   = _BCM_VALUE_CLASSES["NUMERIC"]
    ALPHA     = _BCM_VALUE_CLASSES["ALPHA"]
    BOOL      = _BCM_VALUE_CLASSES["BOOL"]
    BOUNDARY  = _BCM_VALUE_CLASSES["BOUNDARY"]
    STRUCTURE = _BCM_VALUE_CLASSES["STRUCTURE"]
    ALL_VALUES = _BCM_ALL_VALUES

    params = (_extract_params(url) or ["id", "user", "page", "q", "type", "status", "role"])[:6]
    parsed = urllib.parse.urlparse(url)
    base_qs = urllib.parse.parse_qsl(parsed.query, keep_blank_values=True)

    _SEC_HDR_NAMES = frozenset({
        "x-frame-options", "content-security-policy", "x-content-type-options",
        "set-cookie", "www-authenticate", "location",
    })

    def _sec_sig(hdrs: Dict) -> frozenset:
        return frozenset(h.lower() for h in hdrs if h.lower() in _SEC_HDR_NAMES)

    def _fingerprint(status: int, text: str, hdrs: Dict) -> tuple:
        chunk = text[:4096].encode("utf-8", "ignore")
        cr = round(len(zlib.compress(chunk)) / max(len(chunk), 1), 2)
        tl = text.lower()
        has_json = tl.lstrip().startswith(("{", "["))
        has_err  = bool(_BCM_ERROR_RE.search(tl))
        return (status, len(text), cr, has_json, has_err, _sec_sig(hdrs))

    _bc, _bh, _bb, _ = _req(url, use_cache=True, timeout=4.0)
    baseline_text = _bb.decode("utf-8", "ignore")
    baseline_fp   = _fingerprint(_bc, baseline_text, _bh)

    def _fetch(param: str, value: str):
        try:
            t0 = time.monotonic()
            c, hdrs, b, _ = _req(_build_param_url(parsed, base_qs, param, value), timeout=4.0)
            elapsed = time.monotonic() - t0
            text = b.decode("utf-8", "ignore")
            return (param, value, _fingerprint(c, text, hdrs), c, text[:8192], elapsed)
        except Exception:
            return None

    matrix:    Dict = {}
    raw_bodies: Dict = {}
    timing_map: Dict = {}
    tasks = [(p, v) for p in params for v in ALL_VALUES]

    with ThreadPoolExecutor(max_workers=min(32, len(tasks))) as ex:
        futs = {ex.submit(_fetch, p, v): (p, v) for p, v in tasks}
        done, _ = _futures_wait(list(futs), timeout=40.0)
        for f in done:
            try:
                r = f.result()
                if r:
                    p_, v_, fp, sc, text, el = r
                    matrix[(p_, v_)]    = fp
                    raw_bodies[(p_, v_)] = (sc, text)
                    timing_map[(p_, v_)] = el
            except Exception:
                pass

    test_c, _, _, _ = _req(url, method="POST", data=b"test=1", timeout=3.0)
    if test_c not in (405, 0):
        def _fetch_post(param: str, value: str, mode: str):
            try:
                if mode == "json":
                    body = json.dumps({param: value}).encode()
                    ct = "application/json"
                else:
                    body = urllib.parse.urlencode({param: value}).encode()
                    ct = "application/x-www-form-urlencoded"
                c, hdrs, b, _ = _req(url, method="POST", data=body, content_type=ct, timeout=4.0)
                text = b.decode("utf-8", "ignore")
                return ("POST:" + param, value, _fingerprint(c, text, hdrs), c, text[:8192], 0.0)
            except Exception:
                return None

        post_tasks = [(p, v, m) for p in params[:4] for v in ALL_VALUES[:6] for m in ("json", "form")]
        with ThreadPoolExecutor(max_workers=min(16, len(post_tasks))) as ex:
            futs2 = {ex.submit(_fetch_post, p, v, m): (p, v, m) for p, v, m in post_tasks}
            done2, _ = _futures_wait(list(futs2), timeout=30.0)
            for f in done2:
                try:
                    r = f.result()
                    if r:
                        kp, v_, fp, sc, text, _ = r
                        matrix[(kp, v_)]    = fp
                        raw_bodies[(kp, v_)] = (sc, text)
                except Exception:
                    pass

    _COOKIE_SURFACE = frozenset({"role", "admin", "debug", "tier", "plan",
                                  "feature", "access", "group", "privilege"})
    ck_params = [p for p in params if p in _COOKIE_SURFACE]
    if ck_params:
        def _fetch_cookie(param: str, value: str):
            try:
                existing = _GLOBAL_HEADERS.get("Cookie", "")
                ck = ((existing + "; ") if existing else "") + param + "=" + value
                c, hdrs, b, _ = _req(url, headers={"Cookie": ck}, timeout=4.0)
                text = b.decode("utf-8", "ignore")
                return ("COOKIE:" + param, value, _fingerprint(c, text, hdrs), c, text[:8192], 0.0)
            except Exception:
                return None

        ck_tasks = [(p, v) for p in ck_params for v in ALL_VALUES]
        with ThreadPoolExecutor(max_workers=min(16, len(ck_tasks))) as ex:
            futs3 = {ex.submit(_fetch_cookie, p, v): (p, v) for p, v in ck_tasks}
            done3, _ = _futures_wait(list(futs3), timeout=20.0)
            for f in done3:
                try:
                    r = f.result()
                    if r:
                        kp, v_, fp, sc, text, _ = r
                        matrix[(kp, v_)]    = fp
                        raw_bodies[(kp, v_)] = (sc, text)
                except Exception:
                    pass

    def _shannon(fps: list) -> float:
        if not fps:
            return 0.0
        counts: Dict[str, int] = {}
        for fp in fps:
            counts[fp] = counts.get(fp, 0) + 1
        n = len(fps)
        return -sum((c / n) * math.log2(c / n) for c in counts.values())

    sensitivity: Dict = {}
    for param in params:
        fps = [matrix[(param, v)] for v in ALL_VALUES
               if (param, v) in matrix and matrix[(param, v)] != baseline_fp]
        sensitivity[param] = _shannon(fps)

    high_sensitive: List[str] = []
    for param in params:
        score = sensitivity.get(param, 0.0)
        if score >= _BCM_SENSITIVITY_THRESHOLD:
            high_sensitive.append(param)
            info_out.append((
                f"parameter '{param}' is high-sensitivity (entropy={score:.2f} bits across response shapes)",
                param,
            ))

    boundary_found: Set[str] = set()
    _PARAM_ALIASES: Dict[str, List[str]] = {
        "id":   ["user_id", "userId", "uid", "_id"],
        "role": ["roles", "group", "groups", "access"],
        "page": ["offset", "skip", "from", "start"],
    }

    for param in high_sensitive:
        if len(vuln_out) >= 20:
            break
        fps_by_val = {v: matrix[(param, v)] for v in ALL_VALUES if (param, v) in matrix}

        for i, v1 in enumerate(ALL_VALUES):
            if len(vuln_out) >= 20:
                break
            for v2 in ALL_VALUES[i + 1:]:
                if len(vuln_out) >= 20:
                    break
                fp1 = fps_by_val.get(v1)
                fp2 = fps_by_val.get(v2)
                if not fp1 or not fp2:
                    continue
                if fp1 == baseline_fp or fp2 == baseline_fp:
                    continue
                s1, l1, cr1 = fp1[0], fp1[1], fp1[2]
                s2, l2, cr2 = fp2[0], fp2[1], fp2[2]
                if s1 == s2 and abs(l1 - l2) > 500 and abs(cr1 - cr2) > 0.15:
                    delta = abs(cr1 - cr2)
                    vuln_out.append((
                        f"contradiction: param '{param}' values '{v1}' and '{v2}' return same status {s1} but divergent body entropy (delta={delta:.2f}) - possible blind injection or hidden conditional",
                        param,
                    ))
                    _EVIDENCE_TABLE[
                        "bcm_a_" + hashlib.md5((url + param + v1 + v2).encode()).hexdigest()[:12]
                    ] = {
                        "test": "A", "param": param, "v1": v1, "v2": v2,
                        "class1": next((c for c, vals in _BCM_VALUE_CLASSES.items() if v1 in vals), "UNKNOWN"),
                        "class2": next((c for c, vals in _BCM_VALUE_CLASSES.items() if v2 in vals), "UNKNOWN"),
                        "delta": round(delta, 3), "url": url,
                    }
                    t1 = timing_map.get((param, v1), 0.0)
                    t2 = timing_map.get((param, v2), 0.0)
                    if abs(t1 - t2) > 1.5 and len(vuln_out) < 20:
                        vuln_out.append((
                            f"timing contradiction: param '{param}' values '{v1}'/'{v2}' differ by {abs(t1 - t2):.2f}s at same status - possible timing-based blind injection",
                            param,
                        ))

        bool_alpha = BOOL + ALPHA
        vals_200 = [v for v in bool_alpha if fps_by_val.get(v, (None,))[0] == 200]
        vals_403 = [v for v in bool_alpha if fps_by_val.get(v, (None,))[0] in (401, 403)]
        if vals_200 and vals_403:
            for v200 in vals_200:
                if len(vuln_out) >= 20:
                    break
                _, text200 = raw_bodies.get((param, v200), (0, ""))
                if _BCM_PRIV_RE.search(text200.lower()):
                    for v403 in vals_403:
                        if len(vuln_out) >= 20:
                            break
                        code403 = fps_by_val[v403][0]
                        vuln_out.append((
                            f"access class contradiction: param '{param}'='{v200}' returns 200 with privilege keywords while param='{v403}' returns {code403} - possible authorization logic flaw",
                            param,
                        ))
                        _EVIDENCE_TABLE[
                            "bcm_" + hashlib.md5((url + param + v200 + v403).encode()).hexdigest()[:12]
                        ] = {
                            "test": "B", "param": param, "v1": v200, "v2": v403,
                            "class1": "ALPHA/BOOL", "class2": "ALPHA/BOOL",
                            "delta": abs(200 - code403), "url": url,
                        }

        numeric_fps   = [fps_by_val[v] for v in NUMERIC   if v in fps_by_val]
        structure_fps = [fps_by_val[v] for v in STRUCTURE if v in fps_by_val]
        if len(numeric_fps) >= 3 and len(structure_fps) >= 3 and len(vuln_out) < 20:
            avg_num = sum(f[2] for f in numeric_fps)   / len(numeric_fps)
            avg_str = sum(f[2] for f in structure_fps) / len(structure_fps)
            if avg_str > avg_num:
                vuln_out.append((
                    f"entropy inversion on param '{param}': malformed input (STRUCTURE) triggers higher response entropy than valid input (NUMERIC) - server may be processing rather than rejecting invalid structure",
                    param,
                ))
                _EVIDENCE_TABLE[
                    "bcm_c_" + hashlib.md5((url + param).encode()).hexdigest()[:12]
                ] = {
                    "test": "C", "param": param, "v1": "STRUCTURE", "v2": "NUMERIC",
                    "class1": "STRUCTURE", "class2": "NUMERIC",
                    "delta": round(avg_str - avg_num, 3), "url": url,
                }

        if param not in boundary_found:
            for boundary_val in ["%00", "undefined"]:
                if param in boundary_found:
                    break
                bp_fp = fps_by_val.get(boundary_val)
                if bp_fp is None:
                    continue
                bp_cr, bp_len, bp_err = bp_fp[2], bp_fp[1], bp_fp[4]
                for nv in [v for v in NUMERIC + ALPHA if fps_by_val.get(v)]:
                    nfp = fps_by_val[nv]
                    if bp_cr < nfp[2] and bp_len > nfp[1] and not bp_err and nfp[4]:
                        if len(vuln_out) < 20:
                            vuln_out.append((
                                f"boundary bypass on param '{param}': value '%00'/'undefined' suppresses error and returns larger/denser body than valid input - possible null-byte injection or parser short-circuit",
                                param,
                            ))
                        boundary_found.add(param)
                        break

        if len(vuln_out) < 20:
            base_val = next((v for v in NUMERIC if (param, v) in matrix), "1")

            def _probe_meth(meth: str, _bv: str = base_val) -> Tuple[str, int]:
                try:
                    c, _, _, _ = _req(
                        _build_param_url(parsed, base_qs, param, _bv),
                        method=meth, timeout=3.0,
                    )
                    return (meth, c)
                except Exception:
                    return (meth, 0)

            with ThreadPoolExecutor(max_workers=5) as _mex:
                _mfuts = {_mex.submit(_probe_meth, m): m
                          for m in ("GET", "POST", "PUT", "PATCH", "DELETE")}
                method_codes: Dict[str, int] = {}
                for _mf in as_completed(_mfuts):
                    try:
                        _mm, _mc = _mf.result()
                        method_codes[_mm] = _mc
                    except Exception:
                        pass
            if method_codes.get("GET", 0) in (401, 403):
                for meth in ("PUT", "DELETE", "PATCH"):
                    if method_codes.get(meth) == 200 and len(vuln_out) < 20:
                        vuln_out.append((
                            f"method sensitivity: param '{param}' accessible via {meth} but blocked via GET - possible broken method-level access control",
                            param,
                        ))

        aliases = _PARAM_ALIASES.get(param, [])
        orig_fp = fps_by_val.get("1") or fps_by_val.get("admin")
        alias_val = "1" if "1" in fps_by_val else "admin"
        if aliases and orig_fp:
            for alias in aliases:
                if len(vuln_out) >= 20:
                    break
                try:
                    c, hdrs, b, _ = _req(
                        _build_multi_param_url(parsed, base_qs, {alias: alias_val}),
                        timeout=3.0,
                    )
                    afp = _fingerprint(c, b.decode("utf-8", "ignore"), hdrs)
                    if afp != orig_fp and afp != baseline_fp:
                        vuln_out.append((
                            f"parameter alias sensitivity: '{alias}' triggers different server behavior than '{param}' with same value - server may have inconsistent access control across aliased parameters",
                            f"{param}->{alias}",
                        ))
                except Exception:
                    pass

        for v in ALL_VALUES:
            if fps_by_val.get(v, (None,))[0] != 200:
                continue
            _, text200 = raw_bodies.get((param, v), (0, ""))
            if not text200 or v not in text200:
                continue
            if v in ("{}", "[]", "<>"):
                if len(vuln_out) < 20:
                    vuln_out.append((
                        f"parameter '{param}' reflects structural input '{v}' verbatim - assess for SSTI or JSON injection",
                        param,
                    ))
                break
            if v in ("admin", "user", "guest") and _BCM_PRIV_RE.search(text200.lower()):
                if len(vuln_out) < 20:
                    vuln_out.append((
                        f"parameter '{param}' reflects access-class value '{v}' in privilege context - possible role display or authorization logic disclosure",
                        param,
                    ))
                break

        num_json = [fps_by_val[v][3] for v in NUMERIC   if v in fps_by_val]
        str_json = [fps_by_val[v][3] for v in STRUCTURE if v in fps_by_val]
        if num_json and str_json and any(num_json) != any(str_json) and len(vuln_out) < 20:
            vuln_out.append((
                f"param '{param}' changes response content-type between value classes - server returns JSON for valid input and non-JSON for invalid; possible error-state disclosure",
                param,
            ))

        num_hdr_sigs   = [fps_by_val[v][5] for v in NUMERIC   if v in fps_by_val]
        alpha_hdr_sigs = [fps_by_val[v][5] for v in ALPHA    if v in fps_by_val]
        if num_hdr_sigs and alpha_hdr_sigs and len(vuln_out) < 20:
            num_sig_set   = set(num_hdr_sigs)
            alpha_sig_set = set(alpha_hdr_sigs)
            if num_sig_set != alpha_sig_set:
                vuln_out.append((
                    f"security header mutation on param '{param}': response security headers change between value classes - server may be granting a session or redirecting for elevated-class input",
                    param,
                ))

    for param in high_sensitive:
        if len(vuln_out) >= 20:
            break
        fps_by_val = {v: matrix[(param, v)] for v in ALL_VALUES if (param, v) in matrix}
        if fps_by_val.get("1", (None,))[0] != 200:
            continue
        for bv in BOUNDARY:
            if fps_by_val.get(bv, (None,))[0] not in (400, 404):
                continue
            try:
                _req(_build_param_url(parsed, base_qs, param, bv), timeout=3.0)
                c2, _, _, _ = _req(_build_param_url(parsed, base_qs, param, "1"), timeout=3.0)
                if c2 in (400, 404) and len(vuln_out) < 20:
                    vuln_out.append((
                        f"negative cache poisoning surface: param '{param}' - boundary probe '{bv}' poisons cache for subsequent valid requests; test for cache-based DoS",
                        param,
                    ))
                    break
            except Exception:
                pass

    for param in high_sensitive:
        if len(vuln_out) >= 20:
            break
        fps_by_val = {v: matrix[(param, v)] for v in ALL_VALUES if (param, v) in matrix}
        common_fp = fps_by_val.get("1") or fps_by_val.get("a")
        if not common_fp:
            continue
        numeric_dominant = (fps_by_val.get("1", (None,))[0] == 200
                             and fps_by_val.get("a", (999,))[0] != 200)
        type_cross = (
            [('{"$gt":0}', "NoSQL-operator"), ("true", "boolean"),
             ("[1,2,3]",   "array"),          ("1e308", "float-overflow")]
            if numeric_dominant else
            [("0",         "integer"),        ("null",      "null"),
             ("undefined", "undefined"),      ("[]",        "array")]
        )
        for xval, xclass in type_cross:
            if len(vuln_out) >= 20:
                break
            try:
                c, hdrs, b, _ = _req(
                    _build_param_url(parsed, base_qs, param, xval), timeout=3.0
                )
                xfp = _fingerprint(c, b.decode("utf-8", "ignore"), hdrs)
                if xfp != common_fp and xfp != baseline_fp:
                    if abs(xfp[2] - common_fp[2]) > 0.3 or xfp[0] != common_fp[0]:
                        vuln_out.append((
                            f"type confusion on param '{param}': value of class {xclass} produces divergent response - server may not be validating input type; assess for type juggling or NoSQL operator injection",
                            param,
                        ))
                        break
            except Exception:
                pass

    if len(high_sensitive) >= 2:
        pairs = [
            (high_sensitive[i], high_sensitive[j])
            for i in range(len(high_sensitive))
            for j in range(i + 1, len(high_sensitive))
        ]

        def _most_common_val(p: str, value_class: List[str]) -> str:
            fps = [matrix.get((p, v)) for v in value_class if (p, v) in matrix]
            fps = [f for f in fps if f]
            if not fps:
                return value_class[0]
            most = max(set(fps), key=fps.count)
            return next((v for v in value_class if matrix.get((p, v)) == most), value_class[0])

        def _cross_fetch(pair: Tuple[str, str]):
            pA, pB = pair
            try:
                pA_n = _most_common_val(pA, NUMERIC)
                pB_n = _most_common_val(pB, ALPHA)
                _, _, b1, _ = _req(_build_multi_param_url(parsed, base_qs, {pA: pA_n,    pB: pB_n}),    timeout=4.0)
                _, _, b2, _ = _req(_build_multi_param_url(parsed, base_qs, {pA: "admin", pB: pB_n}),    timeout=4.0)
                _, _, b3, _ = _req(_build_multi_param_url(parsed, base_qs, {pA: pA_n,    pB: "admin"}), timeout=4.0)
                _, _, b4, _ = _req(_build_multi_param_url(parsed, base_qs, {pA: "admin", pB: "admin"}), timeout=4.0)
                return (pA, pB, len(b1), len(b2), len(b3), len(b4))
            except Exception:
                return None

        with ThreadPoolExecutor(max_workers=12) as ex:
            futs_c = {ex.submit(_cross_fetch, p): p for p in pairs}
            cross_results = []
            for f in as_completed(futs_c):
                try:
                    r = f.result()
                    if r:
                        cross_results.append(r)
                except Exception:
                    pass

        for r in cross_results:
            if len(vuln_out) >= 20:
                break
            pA, pB, l1, l2, l3, l4 = r
            delta_A        = abs(l2 - l1)
            delta_B        = abs(l3 - l1)
            delta_AB       = abs(l4 - l1)
            delta_A_drives = abs(l4 - l3)
            delta_B_drives = abs(l4 - l2)
            if delta_AB > delta_A + delta_B + 200 and len(vuln_out) < 20:
                vuln_out.append((
                    f"cross-parameter interference: params '{pA}' and '{pB}' interact super-additively (combined delta={delta_AB} > sum {delta_A}+{delta_B}) - server access logic couples these parameters; test for multi-parameter privilege escalation",
                    f"{pA},{pB}",
                ))
            if delta_A_drives > delta_B_drives * 3 and delta_A_drives > 200 and len(vuln_out) < 20:
                vuln_out.append((
                    f"asymmetric coupling: '{pA}' gates '{pB}' - changing '{pB}' only matters when '{pA}' is elevated (delta_A_drives={delta_A_drives} >> delta_B_drives={delta_B_drives})",
                    f"{pA}->{pB}",
                ))

    if high_sensitive and _DISCOVERED_ENDPOINTS:
        base_host = parsed.netloc
        sibling_eps = [
            ep for ep in sorted(_DISCOVERED_ENDPOINTS)
            if urllib.parse.urlparse(ep).netloc == base_host and ep != url
        ][:3]
        for ep in sibling_eps:
            if len(vuln_out) >= 20:
                break
            ep_parsed = urllib.parse.urlparse(ep)
            ep_qs = urllib.parse.parse_qsl(ep_parsed.query, keep_blank_values=True)
            ep_param_names = {k for k, _ in ep_qs} | set(_extract_params(ep) or [])
            shared = [p for p in high_sensitive if p in ep_param_names]
            for sp in shared:
                if len(vuln_out) >= 20:
                    break
                fps_by_val = {v: matrix.get((sp, v)) for v in ALL_VALUES if (sp, v) in matrix}
                vals_200 = [v for v in BOOL + ALPHA if fps_by_val.get(v, (None,))[0] == 200]
                vals_403 = [v for v in BOOL + ALPHA if fps_by_val.get(v, (None,))[0] in (401, 403)]
                if not (vals_200 and vals_403):
                    continue
                for v200 in vals_200[:2]:
                    try:
                        c_ep, _, _, _ = _req(
                            _build_param_url(ep_parsed, ep_qs, sp, v200), timeout=4.0
                        )
                        if c_ep == 200 and len(vuln_out) < 20:
                            vuln_out.append((
                                f"[{ep_parsed.path}] BOLA candidate: param '{sp}'='{v200}' returns 200 on secondary endpoint while same param is access-controlled on primary - broken object-level authorization pattern",
                                sp,
                            ))
                    except Exception:
                        pass

    bcm_params: Dict[str, Dict] = {}
    for _bp in params:
        _score = sensitivity.get(_bp, 0.0)
        _contras = [{"detail": d, "param": p} for d, p in vuln_out if p == _bp]
        if _score >= _BCM_SENSITIVITY_THRESHOLD or _contras:
            bcm_params[_bp] = {"sensitivity": round(_score, 3), "contradictions": _contras}
    if bcm_params:
        _EVIDENCE_TABLE["bcm_matrices"] = {"params": bcm_params}

    return info_out + vuln_out[:20]

_AM_UUID_PAT   = re.compile(
    r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$", re.I
)
_AM_NUM_ID_PAT = re.compile(r"^\d+$")
_AM_PATH_INT_RE = re.compile(r"/(\d+)(?=/|$)")

@dataclasses.dataclass
class _StateSnapshot:
    url: str
    method: str
    status: int
    body_hash: str
    body_len: int
    compress_ratio: float
    json_keys: frozenset
    numeric_fields: Dict[str, float]
    id_fields: Dict[str, str]
    has_list: bool
    list_count: int
    header_sig: frozenset

@dataclasses.dataclass
class _InvariantViolation:
    invariant_name: str
    violated_url: str
    trigger_request: str
    pre_snapshot: _StateSnapshot
    post_snapshot: _StateSnapshot
    delta_description: str

def _app_model_snapshot(url: str, method: str = "GET",
                        body: Optional[bytes] = None) -> Optional[_StateSnapshot]:
    try:
        c, h, b, _ = _req(url, method=method, data=body, timeout=5.0)
        if c == 0:
            return None
        raw = b if b else b""
        body_text = raw.decode("utf-8", "ignore")
        body_hash = hashlib.sha256(raw[:8192]).hexdigest()
        body_len = len(raw)
        try:
            compress_ratio = len(zlib.compress(raw[:4096])) / max(len(raw[:4096]), 1)
        except Exception:
            compress_ratio = 1.0
        json_keys: frozenset = frozenset()
        numeric_fields: Dict[str, float] = {}
        id_fields: Dict[str, str] = {}
        has_list = False
        list_count = 0
        try:
            obj = json.loads(body_text)
            if isinstance(obj, dict):
                for k, v in obj.items():
                    json_keys = json_keys | {k}
                    if isinstance(v, dict):
                        for k2 in v:
                            json_keys = json_keys | {k2}
                    if isinstance(v, (int, float)) and not isinstance(v, bool):
                        numeric_fields[k] = float(v)
                    if isinstance(v, str) and any(
                        k.lower().endswith(sfx) for sfx in ("_id", "id")
                    ):
                        id_fields[k] = v
                    if isinstance(v, list) and not has_list:
                        has_list = True
                        list_count = len(v)
            elif isinstance(obj, list):
                has_list = True
                list_count = len(obj)
                if obj and isinstance(obj[0], dict):
                    for k in obj[0]:
                        json_keys = json_keys | {k}
        except Exception:
            pass
        return _StateSnapshot(
            url=url, method=method, status=c,
            body_hash=body_hash, body_len=body_len,
            compress_ratio=compress_ratio,
            json_keys=json_keys, numeric_fields=numeric_fields,
            id_fields=id_fields, has_list=has_list,
            list_count=list_count, header_sig=frozenset(h.keys()),
        )
    except Exception:
        return None

def _am_delta(pre: _StateSnapshot, post: _StateSnapshot,
               inv_name: str, trigger: str) -> str:
    if post.list_count != pre.list_count:
        return (f"resource count at {post.url} changed from "
                f"{pre.list_count} to {post.list_count} after {trigger}")
    for field, val in post.numeric_fields.items():
        pre_val = pre.numeric_fields.get(field)
        if pre_val is not None and pre_val >= 0 and val < 0:
            return (f"field '{field}' at {post.url} went from {pre_val} to {val} "
                    f"(negative value) after {trigger}")
    if pre.status in (401, 403) and post.status == 200:
        return (f"access control at {post.url} changed from protected to open "
                f"after {trigger}")
    missing = pre.json_keys - post.json_keys
    if missing:
        return (f"response schema at {post.url} lost keys {missing} after {trigger} "
                f"? possible information hiding or error suppression")
    for field, val in post.id_fields.items():
        if field in pre.id_fields and val != pre.id_fields[field]:
            return (f"ID namespace at {post.url} produced out-of-pattern value '{val}' "
                    f"after {trigger} - possible ID oracle or injection")
    return f"invariant '{inv_name}' violated at {post.url} after {trigger}"

def _am_impact(v: _InvariantViolation) -> str:
    if v.post_snapshot.list_count > v.pre_snapshot.list_count:
        return ("Mass Assignment / Object Injection: "
                "attacker can create unauthorized resources")
    for field, val in v.post_snapshot.numeric_fields.items():
        if val < 0 and v.pre_snapshot.numeric_fields.get(field, 0) >= 0:
            return ("Business Logic: negative value exploitation "
                    "(balance, credits, quantity - race condition or overflow)")
    if v.pre_snapshot.status in (401, 403) and v.post_snapshot.status == 200:
        return "Broken Access Control: endpoint became accessible after state change"
    if v.pre_snapshot.json_keys - v.post_snapshot.json_keys:
        return "Response Schema Manipulation: attacker-controlled structural change to API response"
    for field in v.post_snapshot.id_fields:
        if field in v.pre_snapshot.id_fields:
            return "IDOR Oracle: ID prediction or enumeration surface"
    return "Business Logic: application state violated its own invariant"

