def _digamma(n: int) -> float:
    if n <= 0:
        return -1e9
    if n == 1:
        return -0.5772156649015329
    x = float(n)
    return math.log(x) - 1.0 / (2 * x) - 1.0 / (12 * x * x) + 1.0 / (120 * x ** 4)

def _chebyshev_knn(
    points: List[Tuple[float, float, float]],
    query:  Tuple[float, float, float],
    k: int,
) -> float:
    dists = sorted(
        max(abs(query[d] - p[d]) for d in range(len(query)))
        for p in points
        if p is not query and p != query
    )
    return max(dists[k - 1], 1e-12) if len(dists) >= k else 1e-12

def _ksg_te(
    source: List[float],
    target: List[float],
    lag:    int = 1,
    k:      int = 4,
) -> float:
    n = min(len(source), len(target)) - lag
    if n < 12:
        return 0.0
    y_next = target[lag: n + lag]
    y_prev = target[:n]
    x_prev = source[:n]

    tri = list(zip(y_next, x_prev, y_prev))
    sum_nx_ny = 0.0
    for i, qi in enumerate(tri):
        eps = _chebyshev_knn(tri, qi, k)
        nx_ny = sum(
            1 for j, pj in enumerate(tri)
            if j != i
            and abs(pj[1] - qi[1]) < eps
            and abs(pj[2] - qi[2]) < eps
        )
        sum_nx_ny += _digamma(max(nx_ny, 1))
    mi_tri = _digamma(k) - sum_nx_ny / n + _digamma(n)

    bi = list(zip(y_next, y_prev))
    sum_ny = 0.0
    for i, qi2 in enumerate(bi):
        eps2 = _chebyshev_knn(
            [(a2, b2, 0.0) for a2, b2 in bi],
            (qi2[0], qi2[1], 0.0),
            k,
        )
        ny = sum(
            1 for j, pj2 in enumerate(bi)
            if j != i and abs(pj2[1] - qi2[1]) < eps2
        )
        sum_ny += _digamma(max(ny, 1))
    mi_bi = _digamma(k) - sum_ny / n + _digamma(n)

    return max(0.0, mi_tri - mi_bi)

def _permutation_te_pvalue(
    source:      List[float],
    target:      List[float],
    observed_te: float,
    lag:         int = 1,
    k:           int = 4,
    n_perm:      int = 199,
) -> float:
    if observed_te < 1e-9:
        return 1.0
    src = list(source)
    null_tes: List[float] = []
    for _ in range(n_perm):
        random.shuffle(src)
        null_tes.append(_ksg_te(src, target, lag, k))
    count_ge = sum(1 for t in null_tes if t >= observed_te)
    return (count_ge + 1) / (n_perm + 1)

def _bh_correction(p_values: List[float], q: float = 0.05) -> List[bool]:
    m = len(p_values)
    if m == 0:
        return []
    ranked = sorted(enumerate(p_values), key=lambda x: x[1])
    significant = [False] * m
    threshold_found = False
    for rank, (orig_idx, p) in enumerate(reversed(ranked)):
        bh_threshold = (m - rank) * q / m
        if p <= bh_threshold:
            threshold_found = True
        if threshold_found:
            significant[orig_idx] = True
    return significant

def _granger_causality(
    source: List[float],
    target: List[float],
    lag:    int = 1,
) -> Tuple[float, float]:
    n = min(len(source), len(target)) - lag
    if n < 10:
        return (0.0, 1.0)
    y    = target[lag: n + lag]
    y_lag = target[:n]
    x_lag = source[:n]
    n_obs = len(y)

    y_mean  = sum(y) / n_obs
    yl_mean = sum(y_lag) / n_obs
    cov_yyl = sum((y[i] - y_mean) * (y_lag[i] - yl_mean) for i in range(n_obs))
    var_yl  = sum((v - yl_mean) ** 2 for v in y_lag)
    a_r = cov_yyl / max(var_yl, 1e-12)
    b_r = y_mean - a_r * yl_mean
    rss1 = sum((y[i] - a_r * y_lag[i] - b_r) ** 2 for i in range(n_obs))

    xl_mean = sum(x_lag) / n_obs
    syy = var_yl
    sxx = sum((v - xl_mean) ** 2 for v in x_lag)
    sxy = sum((y_lag[i] - yl_mean) * (x_lag[i] - xl_mean) for i in range(n_obs))
    syz = sum((y[i] - y_mean) * (y_lag[i] - yl_mean) for i in range(n_obs))
    sxz = sum((y[i] - y_mean) * (x_lag[i] - xl_mean) for i in range(n_obs))
    det = syy * sxx - sxy * sxy
    if abs(det) < 1e-12:
        return (0.0, 1.0)
    a_u = (syz * sxx - sxz * sxy) / det
    b_u = (sxz * syy - syz * sxy) / det
    c_u = y_mean - a_u * yl_mean - b_u * xl_mean
    rss2 = sum(
        (y[i] - a_u * y_lag[i] - b_u * x_lag[i] - c_u) ** 2
        for i in range(n_obs)
    )
    if rss2 < 1e-12:
        return (999.0, 0.001)
    f_stat = ((rss1 - rss2) / 1.0) / (rss2 / max(n_obs - 3, 1))
    p_val = min(1.0, math.exp(-f_stat / 2.0))
    return (max(0.0, f_stat), p_val)


_CSP_SESSIONS:   int = 4
_CSP_SAMPLES:    int = 35
_CSP_PERM_COUNT: int = 199
_CSP_K_KSG:      int = 4

def _csp_observe(
    url:      str,
    n_sess:   int,
    n_req:    int,
    deadline: threading.Event,
) -> Dict[str, Dict]:
    parsed  = urllib.parse.urlparse(url)
    qs      = urllib.parse.parse_qsl(parsed.query, keep_blank_values=True)
    p_names = [k for k, _ in qs] or ["id", "page", "q", "user", "type"]

    _VALUE_POOL = [
        ("1",         1.0), ("2",         2.0), ("admin",     4.0),
        ("0",         0.0), ("true",      3.0), ("false",    -1.0),
        ("null",     -2.0), ("test",      0.5), ("guest",     0.3),
        ("9999",      9.0), ("undefined", -3.0), ("-1",       -0.5),
    ]

    sessions: Dict[str, Dict] = {}
    for i in range(n_sess):
        sid = "S%d_%s" % (i, secrets.token_hex(3))
        sessions[sid] = {
            "token": secrets.token_urlsafe(16),
            "params": {p: [] for p in p_names},
            "features": {
                "status": [], "body_len": [], "cr": [],
                "list_n": [], "t_us": [],
            },
            "timestamps": [],
        }

    def _probe(sid: str, req_idx: int) -> Optional[Dict]:
        if deadline.is_set():
            return None
        sess        = sessions[sid]
        vi          = req_idx % len(_VALUE_POOL)
        pi          = req_idx % len(p_names)
        val_str, val_num = _VALUE_POOL[vi]
        new_qs      = [(k, val_str if k == p_names[pi] else v)
                       for k, v in qs] if qs else [(p_names[pi], val_str)]
        purl        = urllib.parse.urlunparse((
            parsed.scheme, parsed.netloc, parsed.path,
            parsed.params, urllib.parse.urlencode(new_qs), ""
        ))
        try:
            t0 = time.perf_counter()
            code, _, body, _ = _req(purl, timeout=5.0,
                                    headers={"X-Session-Id": sess["token"]})
            elapsed_us = (time.perf_counter() - t0) * 1_000_000
        except Exception:
            return None
        if code == 0:
            return None
        chunk = (body or b"")[:4096]
        cr    = len(zlib.compress(chunk)) / max(len(chunk), 1) if chunk else 0.5
        lc    = 0
        try:
            obj = json.loads(body)
            if isinstance(obj, list):
                lc = len(obj)
            elif isinstance(obj, dict):
                lc = max((len(v) for v in obj.values() if isinstance(v, list)), default=0)
        except Exception:
            pass
        return {
            "sid": sid, "p_name": p_names[pi], "p_num": val_num,
            "status": float(code), "body_len": float(len(body or b"")),
            "cr": cr, "list_n": float(lc), "t_us": elapsed_us,
            "ts": time.monotonic(),
        }

    tasks = [(sid, ri) for sid in sessions for ri in range(n_req)]
    random.shuffle(tasks)

    with ThreadPoolExecutor(max_workers=min(32, n_sess * 8)) as ex:
        futs = {ex.submit(_probe, sid, ri): (sid, ri) for sid, ri in tasks}
        for f in as_completed(futs):
            if deadline.is_set():
                break
            try:
                r = f.result()
                if r is None:
                    continue
                sid  = r["sid"]
                sess = sessions[sid]
                sess["params"][r["p_name"]].append(r["p_num"])
                for feat in ("status", "body_len", "cr", "list_n", "t_us"):
                    sess["features"][feat].append(r[feat])
                sess["timestamps"].append(r["ts"])
            except Exception:
                pass

    return sessions

def _csp_induce_graph(
    sessions:  Dict[str, Dict],
    deadline:  threading.Event,
    n_perm:    int   = 199,
    k_ksg:     int   = 4,
    bh_q:      float = 0.05,
) -> List[_TeEdge]:
    edges:     List[_TeEdge] = []
    sid_list   = list(sessions.keys())
    feat_names = ["status", "body_len", "cr", "list_n", "t_us"]

    all_raw_te:    List[float] = []
    all_raw_tasks: List[Tuple] = []

    for sid, sess in sessions.items():
        if deadline.is_set():
            break
        for p_name, p_vals in sess["params"].items():
            if len(p_vals) < 12:
                continue
            for feat in feat_names:
                f_vals = sess["features"].get(feat, [])
                if len(f_vals) < 12:
                    continue
                te = _ksg_te(p_vals, f_vals, lag=1, k=k_ksg)
                all_raw_te.append(te)
                all_raw_tasks.append((
                    list(p_vals), list(f_vals), 1, sid,
                    "param:%s" % p_name, "feature:%s" % feat
                ))

    if not all_raw_tasks:
        return edges

    def _perm_task(args: tuple) -> float:
        src, tgt, lag, _sid, _sn, _tn, te_obs = args
        return _permutation_te_pvalue(src, tgt, te_obs, lag, k_ksg, n_perm)

    perm_args = [
        (task[0], task[1], task[2], task[3], task[4], task[5], te)
        for task, te in zip(all_raw_tasks, all_raw_te)
    ]
    p_values: List[float] = []
    with ThreadPoolExecutor(max_workers=min(16, len(perm_args))) as ex:
        for pv in ex.map(_perm_task, perm_args):
            p_values.append(1.0 if deadline.is_set() else pv)

    significant = _bh_correction(p_values, q=bh_q)

    for i, task in enumerate(all_raw_tasks):
        src_list, tgt_list, lag, sid, src_name, tgt_name = task
        te_obs = all_raw_te[i]
        if te_obs < 1e-6:
            continue
        g_f, g_p = _granger_causality(src_list, tgt_list, lag)
        edges.append(_TeEdge(
            source     = src_name,   target    = tgt_name,
            te_nats    = te_obs,     te_bits   = te_obs / math.log(2),
            p_value    = p_values[i],significant= significant[i],
            direction  = "within",   lag       = lag,
            session_a  = sid,        session_b = sid,
            n_obs      = min(len(src_list), len(tgt_list)),
            granger_f  = g_f,        granger_p = g_p,
            both_agree = significant[i] and g_p < 0.10,
        ))

    for i in range(len(sid_list)):
        for j in range(i + 1, len(sid_list)):
            if deadline.is_set():
                break
            sid_a, sid_b = sid_list[i], sid_list[j]
            sess_a, sess_b = sessions[sid_a], sessions[sid_b]
            for p_name, p_vals_a in sess_a["params"].items():
                for feat in feat_names:
                    f_vals_b = sess_b["features"].get(feat, [])
                    n = min(len(p_vals_a), len(f_vals_b))
                    if n < 12:
                        continue
                    te = _ksg_te(p_vals_a[:n], f_vals_b[:n], lag=1, k=k_ksg)
                    if te < 0.004:
                        continue
                    pv  = _permutation_te_pvalue(p_vals_a[:n], f_vals_b[:n], te, 1, k_ksg, n_perm)
                    g_f, g_p = _granger_causality(p_vals_a[:n], f_vals_b[:n], 1)
                    edges.append(_TeEdge(
                        source    = "param:%s@%s" % (p_name, sid_a[-4:]),
                        target    = "feature:%s@%s" % (feat, sid_b[-4:]),
                        te_nats   = te,           te_bits   = te / math.log(2),
                        p_value   = pv,           significant= pv < 0.05,
                        direction = "cross_session", lag     = 1,
                        session_a = sid_a,        session_b = sid_b,
                        n_obs     = n,
                        granger_f = g_f,          granger_p = g_p,
                        both_agree= pv < 0.05 and g_p < 0.10,
                    ))

    for sid, sess in sessions.items():
        if deadline.is_set():
            break
        for fa in feat_names:
            for fb in feat_names:
                if fa == fb:
                    continue
                va = sess["features"].get(fa, [])
                vb = sess["features"].get(fb, [])
                for lag in (2, 3):
                    n = min(len(va), len(vb))
                    if n < 14:
                        continue
                    te = _ksg_te(va[:n], vb[:n], lag=lag, k=k_ksg)
                    if te < 0.006:
                        continue
                    pv  = _permutation_te_pvalue(va[:n], vb[:n], te, lag, k_ksg, n_perm)
                    g_f, g_p = _granger_causality(va[:n], vb[:n], lag)
                    edges.append(_TeEdge(
                        source    = "temporal:%s" % fa,
                        target    = "temporal:%s" % fb,
                        te_nats   = te,           te_bits   = te / math.log(2),
                        p_value   = pv,           significant= pv < 0.05,
                        direction = "temporal",   lag       = lag,
                        session_a = sid,          session_b = sid,
                        n_obs     = n - lag,
                        granger_f = g_f,          granger_p = g_p,
                        both_agree= pv < 0.05 and g_p < 0.10,
                    ))

    return sorted(edges, key=lambda e: (0 if e.both_agree else 1, -e.te_bits, e.p_value))

_CSP_DO_VALUES = [
    ("admin", 4.0), ("1", 1.0), ("true", 3.0), ("0", 0.0), ("root", 5.0),
]

def _csp_counterfactual(
    url:        str,
    graph:      List[_TeEdge],
    sessions:   Dict[str, Dict],
    param:      str,
    do_val_str: str,
    do_val_num: float,
    target:     str,
    deadline:   threading.Event,
) -> Optional[_Counterfactual]:
    if deadline.is_set():
        return None
    obs_param:  List[float] = []
    obs_target: List[float] = []
    for sess in sessions.values():
        pv = sess["params"].get(param, [])
        fv = sess["features"].get(target, [])
        n  = min(len(pv), len(fv))
        obs_param.extend(pv[:n])
        obs_target.extend(fv[:n])
    if len(obs_param) < 10:
        return None

    param_parents = [
        e.source for e in graph
        if e.target == "param:%s" % param
        and e.direction == "within"
        and e.both_agree
    ]
    obs_z: Dict[str, List[float]] = {}
    for parent in param_parents[:2]:
        feat_name = parent.replace("param:", "").replace("feature:", "")
        for sess in sessions.values():
            pv2 = sess["params"].get(feat_name,
                  sess["features"].get(feat_name, []))
            if pv2:
                obs_z.setdefault(feat_name, []).extend(pv2[:len(obs_param)])

    n_obs = len(obs_param)

    if obs_z:
        z_name  = list(obs_z.keys())[0]
        z_vals  = obs_z[z_name][:n_obs]
        z_min, z_max = min(z_vals), max(z_vals)
        z_width = (z_max - z_min) / 4.0 + 1e-9
        z_bins  = [min(int((v - z_min) / z_width), 3) for v in z_vals]
        z_counts: Dict[int, int] = {}
        for zb in z_bins:
            z_counts[zb] = z_counts.get(zb, 0) + 1
        pz = {zb: cnt / n_obs for zb, cnt in z_counts.items()}
        cf_mean = 0.0
        for zb, pz_val in pz.items():
            z_center = z_min + (zb + 0.5) * z_width
            weights  = []
            y_vals_z = []
            for i in range(n_obs):
                w_x = math.exp(-0.5 * ((obs_param[i] - do_val_num) / 1.5) ** 2)
                w_z = math.exp(-0.5 * ((z_vals[i] - z_center) / (z_width + 1e-9)) ** 2)
                weights.append(w_x * w_z)
                y_vals_z.append(obs_target[i])
            total_w   = sum(weights) + 1e-12
            local_mean = sum(w * y for w, y in zip(weights, y_vals_z)) / total_w
            cf_mean   += pz_val * local_mean
        adjustment = "backdoor"
    else:
        weights   = [math.exp(-0.5 * ((v - do_val_num) / 1.5) ** 2) for v in obs_param]
        total_w   = sum(weights) + 1e-12
        cf_mean   = sum(w * y for w, y in zip(weights, obs_target)) / total_w
        adjustment = "direct"

    baseline_mean = sum(obs_target) / max(len(obs_target), 1)
    mean_shift    = cf_mean - baseline_mean
    shift_pct     = (mean_shift / max(abs(baseline_mean), 1e-9)) * 100.0

    n_bins  = 8
    t_min, t_max = min(obs_target), max(obs_target)
    t_width = (t_max - t_min) / n_bins + 1e-9
    baseline_hist: Dict[int, float] = {}
    for v in obs_target:
        b = min(int((v - t_min) / t_width), n_bins - 1)
        baseline_hist[b] = baseline_hist.get(b, 0) + 1.0 / n_obs
    cf_hist: Dict[int, float] = {}
    for b, p_base in baseline_hist.items():
        cf_center = t_min + (b + 0.5) * t_width + mean_shift
        new_b     = min(max(int((cf_center - t_min) / t_width), 0), n_bins - 1)
        cf_hist[new_b] = cf_hist.get(new_b, 0.0) + p_base
    kl = sum(
        cf_hist[b] * math.log2(cf_hist[b] / max(baseline_hist.get(b, 1e-10), 1e-10))
        for b in cf_hist if cf_hist[b] > 0
    )
    tv = 0.5 * sum(
        abs(cf_hist.get(b, 0.0) - baseline_hist.get(b, 0.0))
        for b in set(list(cf_hist.keys()) + list(baseline_hist.keys()))
    )
    kl_bits = max(0.0, kl)
    tv      = max(0.0, min(1.0, tv))

    is_sec = (
        any(sp in param.lower() for sp in _CSP_SEC_PARAMS)
        and target in ("status", "list_n", "body_len")
        and kl_bits > 0.10
    )

    def _interp() -> str:
        if kl_bits < 0.05:
            return ("No significant effect: do(%s=%s) produces no detectable "
                    "change in %s" % (param, do_val_str, target))
        if target == "status":
            if mean_shift > 0.5:
                return (
                    "ACCESS PREDICTED: do(%s=%s) shifts predicted status "
                    "from %.0f toward higher codes "
                    "(delta =%+.2f, KL=%.3f bits, TV=%.3f). "
                    "Counterfactual predicts this parameter value would "
                    "grant different access." % (
                        param, do_val_str, baseline_mean, mean_shift, kl_bits, tv)
                )
            elif mean_shift < -0.5:
                return (
                    "BLOCK PREDICTED: do(%s=%s) shifts predicted status "
                    "toward lower codes (delta =%+.2f, KL=%.3f bits). "
                    "This parameter value would likely be blocked or "
                    "rate-limited." % (param, do_val_str, mean_shift, kl_bits)
                )
        if target == "list_n" and shift_pct > 20:
            return (
                "DATA EXPANSION PREDICTED: do(%s=%s) predicts "
                "%+.1f%% change in result list size (KL=%.3f bits). "
                "Possible IDOR: this value would expose additional "
                "records." % (param, do_val_str, shift_pct, kl_bits)
            )
        if target == "t_us" and shift_pct > 50:
            return (
                "TIMING ANOMALY PREDICTED: do(%s=%s) predicts "
                "%+.1f%% response time increase (KL=%.3f bits). "
                "Possible blind injection surface." % (
                    param, do_val_str, shift_pct, kl_bits)
            )
        return (
            "Causal effect: do(%s=%s) shifts %s distribution "
            "by delta =%+.3f (%+.2f%%), KL=%.3f bits, TV=%.3f." % (
                param, do_val_str, target, mean_shift, shift_pct, kl_bits, tv)
        )

    return _Counterfactual(
        param          = param,
        do_value       = do_val_num,
        target         = target,
        url            = url,
        kl_bits        = round(kl_bits, 4),
        tv_distance    = round(tv, 4),
        predicted_mean = round(cf_mean, 4),
        baseline_mean  = round(baseline_mean, 4),
        mean_shift     = round(mean_shift, 4),
        shift_pct      = round(shift_pct, 2),
        confounders    = list(obs_z.keys()),
        adjustment     = adjustment,
        security_flag  = is_sec,
        interpretation = _interp(),
    )

def _csp_verify_cross_session(
    url:      str,
    edge:     _TeEdge,
    sessions: Dict[str, Dict],
    deadline: threading.Event,
) -> Tuple[bool, str]:
    if deadline.is_set():
        return (False, "deadline")
    parsed = urllib.parse.urlparse(url)
    qs     = urllib.parse.parse_qsl(parsed.query, keep_blank_values=True)
    sid_a, sid_b = edge.session_a, edge.session_b
    tok_a = sessions.get(sid_a, {}).get("token", "sess_a")
    tok_b = sessions.get(sid_b, {}).get("token", "sess_b")
    marker = "XCSS_" + secrets.token_hex(4)
    p_name = edge.source.replace("param:", "").split("@")[0]
    probe_qs  = [(k, marker if k == p_name else v) for k, v in qs] if qs \
                else [(p_name, marker)]
    probe_url = urllib.parse.urlunparse((
        parsed.scheme, parsed.netloc, parsed.path,
        parsed.params, urllib.parse.urlencode(probe_qs), ""
    ))
    try:
        _, _, b_before, _ = _req(url, timeout=5.0, headers={"X-Session-Id": tok_b})
        _req(probe_url, timeout=5.0, headers={"X-Session-Id": tok_a})
        time.sleep(0.15)
        _, _, b_after, _  = _req(url, timeout=5.0, headers={"X-Session-Id": tok_b})
    except Exception:
        return (False, "request_error")
    h_before  = hashlib.sha256((b_before or b"")[:2048]).hexdigest()[:12]
    h_after   = hashlib.sha256((b_after  or b"")[:2048]).hexdigest()[:12]
    len_delta = abs(len(b_after or b"") - len(b_before or b""))
    if h_before != h_after or len_delta > 50:
        return (True,
                "Session B response changed after Session A probe "
                "(hash %s->%s, |delta len|=%d)" % (h_before, h_after, len_delta))
    return (False,
            "No empirical state change detected "
            "(TE=%.4f bits predicted coupling)" % edge.te_bits)


def _csp_classify(edge: _TeEdge) -> Tuple[str, str, bool]:
    p_name = edge.source.replace("param:", "").split("@")[0].lower()
    t_name = (edge.target.replace("feature:", "")
                         .replace("temporal:", "")
                         .split("@")[0])
    for sig in _KNOWN_CAUSAL_SIGS:
        if sig["dir"] == "cross_session":
            if edge.direction == "cross_session" and edge.te_bits >= sig["min_te"]:
                return (sig["vc"], sig["mitre"], False)
            continue
        if edge.direction != sig["dir"]:
            continue
        if edge.te_bits < sig["min_te"]:
            continue
        pk_match = (not sig["pk"] or any(kw in p_name for kw in sig["pk"]))
        tf_match = (not sig["tf"] or sig["tf"] == t_name)
        if pk_match and tf_match:
            return (sig["vc"], sig["mitre"], False)
    novel_desc = "NOVEL_CAUSAL:%s->%s@lag%d" % (
        edge.source.split(":")[0][:6],
        edge.target.split(":")[0][:6],
        edge.lag,
    )
    return (novel_desc, "DISCOVERY", True)

def _csp_proof_text(
    edge:     _TeEdge,
    vc:       str,
    mitre:    str,
    cf:       Optional[_Counterfactual],
    verified: Optional[bool],
    steps:    List[Dict],
) -> str:
    conf = min(0.98, (0.35 if not edge.both_agree else 0.55)
               + (1.0 - edge.p_value) * 0.30
               + min(edge.te_bits * 5.0, 0.15)
               + (0.10 if verified else 0.0))
    lines = [
        "--- CAUSAL SECURITY PROOF -------------------------------------",
        "Class:       %s"  % vc.replace("_", " "),
        "MITRE Stage: %s"  % mitre,
        "Confidence:  %.1f%%" % (conf * 100),
        "",
        "-- CAUSAL EVIDENCE ---------------------------------------------",
        "Transfer Entropy:  %.6f nats  (%.6f bits)" % (edge.te_nats, edge.te_bits),
        "Permutation p:     %.4f  (%s)" % (
            edge.p_value,
            "SIGNIFICANT" if edge.significant else "not significant"),
        "Granger F:         %.4f  p=%.4f  (%s)" % (
            edge.granger_f, edge.granger_p,
            "agrees" if edge.granger_p < 0.10 else "does not agree"),
        "Both tests agree:  %s" % (
            "YES - high confidence" if edge.both_agree else "NO - treat as exploratory"),
        "Observations:      %d"  % edge.n_obs,
        "Direction:         %s"  % edge.direction,
        "Causal lag:        %d request(s)" % edge.lag,
        "Causal link:       %s --> %s" % (edge.source, edge.target),
        "",
    ]
    if cf:
        lines += [
            "-- COUNTERFACTUAL PREDICTION ------------------------------------",
            "Intervention:  do(%s = %s)"  % (cf.param, cf.do_value),
            "Adjustment:    %s  (confounders: %s)" % (
                cf.adjustment,
                ", ".join(cf.confounders) if cf.confounders else "none"),
            "KL divergence: %.4f bits" % cf.kl_bits,
            "TV distance:   %.4f"      % cf.tv_distance,
            "Mean shift:    %+.4f (%+.2f%%)" % (cf.mean_shift, cf.shift_pct),
            "Interpretation: %s"       % cf.interpretation,
            "",
        ]
    if verified is not None:
        lines += [
            "-- EMPIRICAL VERIFICATION ---------------------------------------",
            "Result: %s" % ("CONFIRMED" if verified else "UNCONFIRMED (predicted only)"),
            "",
        ]
    lines += ["-- EXPLOIT SEQUENCE ---------------------------------------------"]
    for step in steps:
        lines.append("  Step %d [Session %s]: %s" % (
            step["step"], step.get("session", "A"), step["desc"]))
        if step.get("url"):
            lines.append("    -> %s" % step["url"])
        if step.get("note"):
            lines.append("    info: %s" % step["note"])
    lines += [
        "",
        "-- MATHEMATICAL BASIS -------------------------------------------",
        "Transfer Entropy (KSG estimator) measures DIRECTED information",
        "flow: TE(X->Y) = I(Y_{t+1}; X_t | Y_t). A non-zero, statistically",
        "significant TE proves that past values of X causally reduce",
        "uncertainty about Y's future - beyond Y's own past alone.",
        "This is not correlation. Permutation testing provides a rigorous",
        "null distribution. Granger causality provides an independent",
        "second test. Both-agree edges have dual causal evidence.",
        "---------------------------------------------------------------",
    ]
    return "\n".join(lines)

def synthesize_causal_security_proof(url: str) -> ScanFindings:
    out: ScanFindings = []
    _deadline = threading.Event()
    _timer = threading.Timer(180.0, _deadline.set)
    _timer.daemon = True
    _timer.start()

    try:
        _out(_paint(
            "  [causal] collecting %d-session x %d-sample observation matrix..." % (
                _CSP_SESSIONS, _CSP_SAMPLES),
            A.C))

        sessions = _csp_observe(url, _CSP_SESSIONS, _CSP_SAMPLES, _deadline)
        total_obs = sum(len(s["features"]["status"]) for s in sessions.values())
        if total_obs < 24:
            out.append((
                "[causal] insufficient observations (%d) - "
                "target unresponsive or heavily rate-limited" % total_obs,
                "url=%s" % url,
            ))
            return out

        _out(_paint(
            "  [causal] %d observations collected - inducing causal graph "
            "(KSG TE + permutation p-values + Granger)..." % total_obs,
            A.C))

        graph = _csp_induce_graph(
            sessions, _deadline,
            n_perm=_CSP_PERM_COUNT,
            k_ksg=_CSP_K_KSG,
        )

        n_sig  = sum(1 for e in graph if e.significant)
        n_both = sum(1 for e in graph if e.both_agree)
        n_xs   = sum(1 for e in graph if e.direction == "cross_session")
        n_tmp  = sum(1 for e in graph if e.direction == "temporal")

        _out(_paint(
            "  [causal] graph: %d edges total, %d significant (BH q=0.05), "
            "%d both-test agreement, %d cross-session, %d temporal" % (
                len(graph), n_sig, n_both, n_xs, n_tmp),
            A.C))

        if not any(e.significant for e in graph):
            out.append((
                "[causal] no significant causal edges detected - "
                "application responses appear causally independent of parameters "
                "(all TE p-values > 0.05 after BH correction)",
                "url=%s total_obs=%d edges_raw=%d" % (url, total_obs, len(graph)),
            ))
            return out

        _out(_paint("  [causal] computing counterfactual distributions...", A.C))

        cf_results: List[_Counterfactual] = []
        sig_edges = [e for e in graph if e.significant and e.direction == "within"]
        cf_tasks: List[Tuple[str, str, float, str]] = []
        for edge in sig_edges[:16]:
            p_name = edge.source.replace("param:", "")
            if any(sp in p_name.lower() for sp in _CSP_SEC_PARAMS):
                for do_str, do_num in _CSP_DO_VALUES[:3]:
                    cf_tasks.append((p_name, do_str, do_num,
                                     edge.target.replace("feature:", "")))

        for p_name, do_str, do_num, t_feat in cf_tasks[:20]:
            if _deadline.is_set():
                break
            cf = _csp_counterfactual(
                url, graph, sessions, p_name, do_str, do_num, t_feat, _deadline
            )
            if cf and cf.kl_bits >= 0.06:
                cf_results.append(cf)

        cf_results.sort(key=lambda c: -c.kl_bits)

        _out(_paint("  [causal] verifying cross-session causal edges...", A.C))

        cross_verified: Dict[str, Tuple[bool, str]] = {}
        for edge in [e for e in graph
                     if e.direction == "cross_session" and e.significant][:4]:
            if _deadline.is_set():
                break
            verified, evidence = _csp_verify_cross_session(
                url, edge, sessions, _deadline
            )
            cross_verified[edge.source + edge.target] = (verified, evidence)

        _out(_paint(
            "  [causal] classifying causal patterns and synthesizing proofs...",
            A.C))

        proofs:   List[_CausalProof] = []
        seen_vc:  Set[str] = set()
        parsed_u  = urllib.parse.urlparse(url)
        qs_u      = urllib.parse.parse_qsl(parsed_u.query, keep_blank_values=True)

        for edge in [e for e in graph if e.significant][:20]:
            if _deadline.is_set():
                break
            vc, mitre, is_novel = _csp_classify(edge)
            dedup_key = vc + edge.direction
            if dedup_key in seen_vc and not is_novel:
                continue
            seen_vc.add(dedup_key)

            p_name = edge.source.replace("param:", "").split("@")[0]
            t_name = edge.target.replace("feature:", "").split("@")[0]
            best_cf = next(
                (c for c in cf_results
                 if c.param == p_name and c.target == t_name and c.security_flag),
                next((c for c in cf_results if c.param == p_name), None),
            )

            if edge.direction == "within":
                exploit_val = "admin" if any(
                    sp in p_name for sp in ["role", "admin", "privilege"]
                ) else "1"
                probe_qs  = [(k, exploit_val if k == p_name else v)
                             for k, v in qs_u] if qs_u else [(p_name, exploit_val)]
                probe_url = urllib.parse.urlunparse((
                    parsed_u.scheme, parsed_u.netloc, parsed_u.path,
                    parsed_u.params, urllib.parse.urlencode(probe_qs), ""
                ))
                steps: List[Dict] = [
                    {"step": 1, "session": "A",
                     "desc": "Intervene on '%s' with value '%s'" % (p_name, exploit_val),
                     "url": probe_url,
                     "note": "TE(param->%s)=%.4f bits, p=%.4f, Granger F=%.2f" % (
                         t_name, edge.te_bits, edge.p_value, edge.granger_f)},
                    {"step": 2, "session": "A",
                     "desc": "Observe %s in response - counterfactual predicts "
                             "divergence of KL=%.3f bits" % (
                                 t_name, best_cf.kl_bits if best_cf else 0.0),
                     "url": url,
                     "note": best_cf.interpretation if best_cf else ""},
                ]
                verified_flag: Optional[bool] = None

            elif edge.direction == "cross_session":
                xkey = edge.source + edge.target
                verified_flag, verif_evidence = cross_verified.get(
                    xkey, (False, "not tested")
                )
                sid_a  = edge.session_a
                tok_a  = sessions.get(sid_a, {}).get("token", "sess_a")
                probe_qs_a = [(k, "admin" if k == p_name else v)
                              for k, v in qs_u] if qs_u else [(p_name, "admin")]
                probe_url_a = urllib.parse.urlunparse((
                    parsed_u.scheme, parsed_u.netloc, parsed_u.path,
                    parsed_u.params, urllib.parse.urlencode(probe_qs_a), ""
                ))
                steps = [
                    {"step": 1, "session": "A",
                     "desc": "Send probe in Session A: '%s'=admin" % p_name,
                     "url": probe_url_a,
                     "note": "Cross-session TE=%.4f bits p=%.4f" % (
                         edge.te_bits, edge.p_value)},
                    {"step": 2, "session": "B",
                     "desc": "Observe %s change in Session B" % t_name,
                     "url": url,
                     "note": verif_evidence},
                ]

            else:
                steps = [
                    {"step": i + 1, "session": "A",
                     "desc": "Request %d of %d (maintain temporal sequence)" % (
                         i + 1, edge.lag + 1),
                     "url": url,
                     "note": ("Temporal TE(%s->%s) lag=%d: %.4f bits" % (
                         edge.source, edge.target, edge.lag, edge.te_bits)
                         if i == 0 else "")}
                    for i in range(edge.lag + 1)
                ]
                verified_flag = None

            proof_text = _csp_proof_text(edge, vc, mitre, best_cf, verified_flag, steps)
            conf = min(0.98, (0.35 if not edge.both_agree else 0.55)
                       + (1.0 - edge.p_value) * 0.30
                       + min(edge.te_bits * 5.0, 0.15)
                       + (0.10 if verified_flag else 0.0))
            proof_id = "CSP_%s_%s" % (
                vc[:8],
                hashlib.sha256(
                    (edge.source + edge.target + edge.direction).encode()
                ).hexdigest()[:6]
            )
            causal_path: List[str] = [edge.source, edge.target]
            if best_cf:
                causal_path = [
                    "do(%s=%s)" % (best_cf.param, best_cf.do_value),
                    edge.source,
                    edge.target,
                ]
            proofs.append(_CausalProof(
                proof_id       = proof_id,
                vuln_class     = vc,
                causal_path    = causal_path,
                exploit_steps  = steps,
                counterfactual = best_cf,
                confidence     = round(conf, 4),
                te_bits        = round(edge.te_bits, 6),
                p_value        = round(edge.p_value, 4),
                granger_agrees = edge.both_agree,
                sessions       = len(sessions),
                novel          = is_novel,
                proof_text     = proof_text,
                mitre_stage    = mitre,
            ))

        proofs.sort(key=lambda pr: (-pr.confidence, pr.p_value))

        for proof in proofs:
            sev = (
                "ZERO" if proof.both_agree and proof.confidence >= 0.75 else
                "HIGH" if proof.both_agree or proof.confidence >= 0.60 else
                "MED"
            )
            detail = (
                "[CONFIRMED] causal security proof: %s  confidence=%.1f%%  "
                "TE=%.4f bits  p=%.4f  Granger=%s  sessions=%d  novel=%s\n%s" % (
                    proof.vuln_class,
                    proof.confidence * 100,
                    proof.te_bits,
                    proof.p_value,
                    "agrees" if proof.granger_agrees else "disagrees",
                    proof.sessions,
                    proof.novel,
                    proof.proof_text,
                )
            )
            payload = "MITRE=%s  path=%s  proof_id=%s" % (
                proof.mitre_stage,
                "?>".join(proof.causal_path),
                proof.proof_id,
            )
            out.append((detail, payload))

        if not proofs:
            out.append((
                "[causal] causal graph computed but no security-relevant "
                "proofs synthesized - no significant causal edges survived "
                "classification",
                "url=%s sig_edges=%d both_agree=%d" % (url, n_sig, n_both),
            ))

        return out

    finally:
        _timer.cancel()
        _deadline.set()

_AIF_BUDGET: int = 80
_AIF_REPLAY_N: int = 3
_AIF_REPLAY_THRESHOLD: int = 2
_AIF_TIMEOUT: float = 60.0
_AIF_MIN_DELTA_BYTES: int = 64
_AIF_PAC_EPSILON: float = 0.10
_AIF_PAC_DELTA: float = 0.05

_AIF_ID_PARAM_RE  = re.compile(r'\b(id|uid|user|tenant|org|account)\b', re.I)
_AIF_UUID_RE_FULL = re.compile(
    r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', re.I)
_AIF_NUMPATH_RE   = re.compile(r'(?<=/)\d+(?=[/#-]|$)')
_AIF_WS_RE = re.compile(r'\s+')

@dataclasses.dataclass
class _AifWitness:
    req_a: str
    req_b: str
    resp_a_hash: str
    resp_b_hash: str
    invariant_id: str
    replay_results: List[bool]
    canonical_delta: str
    witness_sha256: str
    severity: str

@dataclasses.dataclass
class _AifInvariant:
    id: str
    description: str
    predicate: object
    expected_relation: str

def _aif_synthesize_alt_value(name: str, value: str) -> str:
    try:
        return str(int(value) + 1)
    except ValueError:
        pass
    if _AIF_UUID_RE_FULL.match(value):
        import uuid as _uuidmod
        return str(_uuidmod.uuid4())
    if value and len(value) > 1:
        return value[:-1] + ("b" if value[-1] != "b" else "c")
    return "alt_" + (name[:6] if name else "val")

def _aif_enumerate_dimensions(url: str) -> Dict[str, List]:
    parsed = urllib.parse.urlparse(url)
    dims: Dict[str, List] = {}

    nums = _AIF_NUMPATH_RE.findall(parsed.path)
    if nums:
        n = int(nums[-1])
        dims["path_id"] = [str(n), str(n + 1 if n > 1 else n + 100)]

    uuids = _AIF_UUID_RE_FULL.findall(parsed.path + "?" + parsed.query)
    if uuids:
        import uuid as _uuidmod
        dims["path_uuid"] = [uuids[-1], str(_uuidmod.uuid4())]

    for k, v in urllib.parse.parse_qsl(parsed.query, keep_blank_values=True):
        if _AIF_ID_PARAM_RE.search(k) and v:
            dims.setdefault("qparam_" + k, [v, _aif_synthesize_alt_value(k, v)])

    dims["has_auth"] = [bool(
        _GLOBAL_HEADERS.get("Cookie") or
        _GLOBAL_HEADERS.get("Authorization") or
        _GLOBAL_HEADERS.get("X-API-Key")
    )]
    return dims

def _aif_synthesize_invariants(url: str, dims: Dict[str, List]) -> List[_AifInvariant]:
    parsed = urllib.parse.urlparse(url)
    base_path_url = "%s://%s%s" % (parsed.scheme, parsed.netloc, parsed.path)
    invs: List[_AifInvariant] = []

    if "path_id" in dims:
        id_a, id_b = dims["path_id"]
        needle = "/" + id_a
        pos = url.rfind(needle)
        rest_start = pos + len(needle)
        if pos >= 0 and (rest_start >= len(url) or url[rest_start] in "/-#"):
            url_b = url[:pos] + "/" + id_b + url[rest_start:]
            if url_b != url:
                def _mkidor(ua=url, ub=url_b):
                    return ({"url": ua, "method": "GET", "headers": {}, "data": None},
                            {"url": ub, "method": "GET", "headers": {}, "data": None})
                invs.append(_AifInvariant(
                    "idor", "IDOR path id %s vs %s" % (id_a, id_b),
                    _mkidor, "distinguished"))

    if "path_uuid" in dims:
        uuid_a, uuid_b = dims["path_uuid"]
        url_b_u = url.replace(uuid_a, uuid_b, 1)
        if url_b_u != url:
            def _mkuuid(ua=url, ub=url_b_u):
                return ({"url": ua, "method": "GET", "headers": {}, "data": None},
                        {"url": ub, "method": "GET", "headers": {}, "data": None})
            invs.append(_AifInvariant(
                "idor", "IDOR UUID %s vs %s" % (uuid_a[:8], uuid_b[:8]),
                _mkuuid, "distinguished"))

    for dim_k in list(dims.keys()):
        if not dim_k.startswith("qparam_"):
            continue
        if len(dims[dim_k]) < 2:
            continue
        val_a, val_b = dims[dim_k][0], dims[dim_k][1]
        pname = dim_k[len("qparam_"):]
        url_b_q = _inject_param(url, pname, val_b)
        def _mkqidor(ua=url, ub=url_b_q):
            return ({"url": ua, "method": "GET", "headers": {}, "data": None},
                    {"url": ub, "method": "GET", "headers": {}, "data": None})
        invs.append(_AifInvariant(
            "idor", "IDOR qparam %s: %s vs %s" % (pname, val_a, val_b),
            _mkqidor, "distinguished"))

    def _mktenant(u=url):
        return (
            {"url": u, "method": "GET",
             "headers": {"X-Tenant-ID": "aif_tenant_a", "X-Org-ID": "aif_org_a"}, "data": None},
            {"url": u, "method": "GET",
             "headers": {"X-Tenant-ID": "aif_tenant_b", "X-Org-ID": "aif_org_b"}, "data": None},
        )
    invs.append(_AifInvariant(
        "tenant_isolation", "Tenant isolation: X-Tenant-ID a vs b",
        _mktenant, "distinguished"))

    def _mkverb(u=base_path_url):
        return ({"url": u, "method": "GET",    "headers": {}, "data": None},
                {"url": u, "method": "DELETE",  "headers": {}, "data": None})
    invs.append(_AifInvariant(
        "verb_tampering", "Verb tampering: GET vs DELETE on %s" % parsed.path,
        _mkverb, "distinguished"))

    def _mkidem(u=url):
        return ({"url": u, "method": "GET", "headers": {}, "data": None},
                {"url": u, "method": "GET", "headers": {}, "data": None})
    invs.append(_AifInvariant(
        "idempotence", "Idempotence: same request twice",
        _mkidem, "equivalent"))

    if dims.get("has_auth", [False])[0]:
        def _mkauth(u=url):
            return (
                {"url": u, "method": "GET", "headers": {}, "data": None},
                {"url": u, "method": "GET",
                 "headers": {"Cookie": "", "Authorization": "", "X-API-Key": ""},
                 "data": None},
            )
        invs.append(_AifInvariant(
            "auth_bypass_api", "Auth bypass: authenticated vs no credentials",
            _mkauth, "distinguished"))

    def _mkcap(u=url):
        return ({"url": u, "method": "GET", "headers": {}, "data": None},
                {"url": u, "method": "GET", "headers": {"Cookie": ""}, "data": None})
    invs.append(_AifInvariant(
        "capability_revocation", "Capability revocation: token vs no token",
        _mkcap, "distinguished"))

    _rbac_body = json.dumps({"admin": True, "role": "admin"}).encode()
    def _mkrbac(u=base_path_url, bd=_rbac_body):
        return (
            {"url": u, "method": "GET",  "headers": {}, "data": None},
            {"url": u, "method": "PATCH",
             "headers": {"Content-Type": "application/json"}, "data": bd},
        )
    invs.append(_AifInvariant(
        "field_level_rbac", "Field-level RBAC: GET vs PATCH admin",
        _mkrbac, "distinguished"))

    path_parts = [p for p in parsed.path.split("/") if p]
    num_idxs = [i for i, p in enumerate(path_parts) if p.isdigit()]
    if len(num_idxs) >= 2:
        parent_idx = num_idxs[-2]
        alt_parts = list(path_parts)
        alt_parts[parent_idx] = str(int(alt_parts[parent_idx]) + 1)
        alt_path = "/" + "/".join(alt_parts)
        url_b_par = "%s://%s%s" % (parsed.scheme, parsed.netloc, alt_path)
        if parsed.query:
            url_b_par += "?" + parsed.query
        def _mkparent(ua=url, ub=url_b_par):
            return ({"url": ua, "method": "GET", "headers": {}, "data": None},
                    {"url": ub, "method": "GET", "headers": {}, "data": None})
        invs.append(_AifInvariant(
            "idor", "Direct object via wrong parent path",
            _mkparent, "distinguished"))

    return invs

def _aif_select_next_probe(
    posteriors: Dict[str, List[float]],
    tested_counts: Dict[str, int],
    pending: List[_AifInvariant],
) -> Optional[_AifInvariant]:
    if not pending:
        return None

    def _hbin(p: float) -> float:
        if p <= 1e-10 or p >= 1.0 - 1e-10:
            return 0.0
        return -(p * math.log2(p) + (1.0 - p) * math.log2(1.0 - p))

    budget_per = max(1, _AIF_BUDGET // max(len(pending), 1))
    best, best_inv = -1.0, None
    for inv in pending:
        a, b_v = posteriors.get(inv.id, [1.0, 1.0])
        p = a / (a + b_v)
        h = _hbin(p)
        ratio = min(1.0, tested_counts.get(inv.id, 0) / budget_per)
        score = h * (1.0 - ratio)
        if score > best:
            best, best_inv = score, inv
    return best_inv

def _aif_canonicalize(status: int, headers: Dict[str, str], body: bytes) -> str:
    text = body.decode("utf-8", "replace")
    text = _AIF_NONCE_RE.sub("<NONCE>", text)
    text = _AIF_WS_RE.sub(" ", text).strip()
    try:
        obj = json.loads(text)
        text = json.dumps(obj, sort_keys=True, separators=(",", ":"))
    except (ValueError, TypeError):
        pass
    return "%d|%s" % (status, text[:8192])

def _aif_responses_equivalent(
    canon_a: str, canon_b: str, status_a: int, status_b: int
) -> bool:
    if canon_a == canon_b:
        return True
    if status_a != status_b:
        return False
    words_a = canon_a.split()
    words_b = canon_b.split()
    def _sh(ws: List[str]) -> Set[str]:
        return set("%s %s" % (ws[i], ws[i+1]) for i in range(len(ws)-1)) if len(ws) > 1 else set(ws)
    sa2, sb2 = _sh(words_a), _sh(words_b)
    union = sa2 | sb2
    if not union:
        return True
    return len(sa2 & sb2) / len(union) > 0.95

def _aif_witness_fires(
    inv: _AifInvariant,
    status_a: int, canon_a: str, body_a: bytes,
    status_b: int, canon_b: str, body_b: bytes,
) -> bool:
    ok_a = 200 <= status_a < 300
    ok_b = 200 <= status_b < 300
    delta = abs(len(body_a) - len(body_b))
    eq = _aif_responses_equivalent(canon_a, canon_b, status_a, status_b)

    if inv.expected_relation == "distinguished":
        if not ok_a:
            return False
        if inv.id in ("auth_bypass_api", "tenant_isolation", "capability_revocation"):
            return ok_b and (eq or delta < _AIF_MIN_DELTA_BYTES)
        return ok_b
    else:
        return not eq and (delta >= _AIF_MIN_DELTA_BYTES or status_a != status_b)

def _aif_probe_invariant(
    inv: _AifInvariant,
    deadline: threading.Event,
    req_counter: List[int],
    budget: int,
) -> Optional[_AifWitness]:
    if deadline.is_set() or req_counter[0] >= budget:
        return None
    try:
        req_a_d, req_b_d = inv.predicate()
    except Exception:
        return None

    def _do(rd: Dict) -> tuple:
        try:
            hdrs = {k: v for k, v in rd.get("headers", {}).items() if v}
            return _req(
                rd["url"], method=rd.get("method", "GET"),
                headers=hdrs if hdrs else None, data=rd.get("data"),
                timeout=_GLOBAL_TIMEOUT,
            )
        except Exception:
            return 0, {}, b"", rd.get("url", "")

    try:
        if deadline.is_set() or req_counter[0] >= budget:
            return None
        sa, ha, ba, _ = _do(req_a_d)
        req_counter[0] += 1
        if sa == 0 or deadline.is_set() or req_counter[0] >= budget:
            return None
        sb, hb, bb, _ = _do(req_b_d)
        req_counter[0] += 1
        if sb == 0:
            return None
        ca = _aif_canonicalize(sa, ha, ba)
        cb = _aif_canonicalize(sb, hb, bb)
        if not _aif_witness_fires(inv, sa, ca, ba, sb, cb, bb):
            return None
        sev = ("CRIT" if inv.id in ("idor", "tenant_isolation", "auth_bypass_api") else
               "HIGH" if inv.id in ("verb_tampering", "capability_revocation", "field_level_rbac")
               else "MED")
        return _AifWitness(
            req_a=req_a_d["url"], req_b=req_b_d["url"],
            resp_a_hash=hashlib.sha256(ca.encode()).hexdigest(),
            resp_b_hash=hashlib.sha256(cb.encode()).hexdigest(),
            invariant_id=inv.id, replay_results=[],
            canonical_delta="status_%d_vs_%d body_delta_%d_bytes" % (sa, sb, abs(len(ba)-len(bb))),
            witness_sha256="", severity=sev,
        )
    except Exception:
        return None

def _aif_verify_witness(
    candidate: _AifWitness,
    inv: _AifInvariant,
    deadline: threading.Event,
    req_counter: List[int],
    budget: int,
) -> Optional[_AifWitness]:
    results: List[bool] = []
    for _ in range(_AIF_REPLAY_N):
        if deadline.is_set() or req_counter[0] >= budget:
            break
        time.sleep(0.1 + random.random() * 0.2)
        try:
            ra, rb = inv.predicate()
        except Exception:
            results.append(False)
            continue
        try:
            def _rr(rd: Dict) -> tuple:
                hdrs = {k: v for k, v in rd.get("headers", {}).items() if v}
                return _req(
                    rd["url"], method=rd.get("method", "GET"),
                    headers=hdrs if hdrs else None, data=rd.get("data"),
                    timeout=_GLOBAL_TIMEOUT,
                )
            sa, ha, ba, _ = _rr(ra)
            req_counter[0] += 1
            if sa == 0:
                results.append(False)
                continue
            sb, hb, bb, _ = _rr(rb)
            req_counter[0] += 1
            if sb == 0:
                results.append(False)
                continue
            ca = _aif_canonicalize(sa, ha, ba)
            cb = _aif_canonicalize(sb, hb, bb)
            results.append(_aif_witness_fires(inv, sa, ca, ba, sb, cb, bb))
        except Exception:
            results.append(False)
    candidate.replay_results = results
    return candidate if sum(results) >= _AIF_REPLAY_THRESHOLD else None

def _aif_seal_witness(w: _AifWitness) -> str:
    return hashlib.sha256(
        json.dumps({
            "req_a": w.req_a, "req_b": w.req_b,
            "resp_a_hash": w.resp_a_hash, "resp_b_hash": w.resp_b_hash,
            "invariant_id": w.invariant_id,
        }, sort_keys=True).encode()
    ).hexdigest()

def _aif_compute_pac_bounds(
    invariant_classes: List[str],
    tested_counts: Dict[str, int],
    confirmed_counts: Dict[str, int],
) -> str:
    lines = []
    for cls in sorted(set(invariant_classes)):
        if confirmed_counts.get(cls, 0) > 0:
            continue
        n = tested_counts.get(cls, 0)
        if n == 0:
            continue
        upper = 1.0 - (_AIF_PAC_DELTA ** (1.0 / n))
        lines.append(
            "invariant %s: no violation found in %d probes; "
            "with %.0f%% confidence, true violation rate < %.1f%%" % (
                cls, n, (1.0 - _AIF_PAC_DELTA) * 100.0, upper * 100.0)
        )
    return "\n".join(lines)

def falsify_authorization_invariants(url: str) -> ScanFindings:
    out: ScanFindings = []
    _deadline = threading.Event()
    _timer = threading.Timer(_AIF_TIMEOUT, _deadline.set)
    _timer.daemon = True
    _timer.start()
    req_counter: List[int] = [0]
    budget = _AIF_BUDGET
    try:
        dims = _aif_enumerate_dimensions(url)

        invariants = _aif_synthesize_invariants(url, dims)
        if not invariants:
            out.append(("[aif] no testable authorization dimensions found", "url=%s" % url))
            return out

        posteriors: Dict[str, List[float]] = {}
        tested_counts: Dict[str, int] = {}
        confirmed_counts: Dict[str, int] = {}
        candidates: List[tuple] = []
        exhausted: Set[int] = set()
        max_per_inv = max(3, budget // max(len(invariants), 1))

        while not _deadline.is_set() and req_counter[0] < budget:
            active = [inv for inv in invariants if id(inv) not in exhausted]
            if not active:
                break
            inv = _aif_select_next_probe(posteriors, tested_counts, active)
            if inv is None:
                break
            cand = _aif_probe_invariant(inv, _deadline, req_counter, budget)
            tested_counts[inv.id] = tested_counts.get(inv.id, 0) + 1
            a, b_v = posteriors.get(inv.id, [1.0, 1.0])
            if cand is not None:
                posteriors[inv.id] = [a + 1, b_v]
                candidates.append((inv, cand))
                exhausted.add(id(inv))
            else:
                posteriors[inv.id] = [a, b_v + 1]
            if tested_counts.get(inv.id, 0) >= max_per_inv:
                exhausted.add(id(inv))
            if _GLOBAL_DELAY > 0.0:
                time.sleep(_GLOBAL_DELAY)

        confirmed: List[_AifWitness] = []
        _aif_seal_lock = threading.Lock()

        def _aif_verify_and_seal(
            _inv: object, _cand: object
        ) -> Optional[object]:
            if _deadline.is_set() or req_counter[0] >= budget:
                return None
            _verified = _aif_verify_witness(_cand, _inv, _deadline, req_counter, budget)
            if _verified is not None:
                _verified.witness_sha256 = _aif_seal_witness(_verified)
                return (_inv, _verified)
            return None

        with ThreadPoolExecutor(max_workers=min(max(len(candidates), 1), 4)) as _vpool:
            _vfuts = [_vpool.submit(_aif_verify_and_seal, inv, cand)
                      for inv, cand in candidates]
            for _vf in _vfuts:
                try:
                    _res = _vf.result(timeout=30.0)
                    if _res is not None:
                        _rinv, _rverified = _res
                        with _aif_seal_lock:
                            confirmed_counts[_rinv.id] = (
                                confirmed_counts.get(_rinv.id, 0) + 1)
                            confirmed.append(_rverified)
                except Exception:
                    pass

        pac = _aif_compute_pac_bounds(
            [inv.id for inv in invariants], tested_counts, confirmed_counts)

        _hpp_re_id = re.compile(r"[-&]([a-zA-Z_][a-zA-Z0-9_]*(?:id|user|uid|account"
                                r"|role|token|key|resource|obj))=([^&]+)", re.I)
        for w in list(confirmed):
            if _deadline.is_set() or req_counter[0] >= budget:
                break
            _req_b_url = w.req_b
            if not _req_b_url.startswith("http"):
                continue
            for _pm in _hpp_re_id.finditer(_req_b_url):
                _pname, _pval_b = _pm.group(1), _pm.group(2)
                _safe_val = "1"
                _hpp_url = _req_b_url + ("&" if "?" in _req_b_url else "?") + (
                    "%s=%s" % (_pname, _safe_val)
                )
                _hpp_st, _, _hpp_body, _ = _req(_hpp_url, timeout=8.0)
                req_counter[0] += 1
                if (_hpp_st == 200
                        and len(_hpp_body) > 50
                        and _hpp_body == (
                            _req(_req_b_url, timeout=8.0)[2]
                        )):
                    req_counter[0] += 1
                    out.append((
                        "[aif] HTTP Parameter Pollution amplification: invariant "
                        "'%s' - sending %s=%s&%s=%s (safe first) yields same "
                        "unauthorized access as %s=%s alone; auth middleware "
                        "reads first param, app reads last" % (
                            w.invariant_id, _pname, _safe_val,
                            _pname, _pval_b[:30],
                            _pname, _pval_b[:30]),
                        "witness=%s url=%s" % (w.witness_sha256[:16], _hpp_url[:80])
                    ))
                    break

        for w in confirmed:
            rp = sum(w.replay_results)
            human = "req_a=%s | req_b=%s - delta: %s" % (
                w.req_a[:70], w.req_b[:70], w.canonical_delta)
            detail = (
                "[CONFIRMED] authorization invariant violated: %s - "
                "witness reproduces %d/%d - SHA256: %s\n%s" % (
                    w.invariant_id, rp, _AIF_REPLAY_N, w.witness_sha256[:16], human)
            )
            payload = "invariant=%s witness=%s req_a=%s req_b=%s" % (
                w.invariant_id, w.witness_sha256[:32], w.req_a[:60], w.req_b[:60])
            out.append((detail, payload))

        if pac:
            out.append(("[aif] PAC coverage bounds:\n" + pac,
                        "url=%s probes=%d" % (url, req_counter[0])))

        if not out:
            out.append((
                "[aif] no authorization invariant violations confirmed in %d probes "
                "(all below %d/%d reproduction threshold)" % (
                    req_counter[0], _AIF_REPLAY_THRESHOLD, _AIF_REPLAY_N),
                "url=%s probes=%d" % (url, req_counter[0]),
            ))
        return out

    except Exception as e:
        out.append(("[aif] error: %s" % str(e), "url=%s" % url))
        return out

    finally:
        _timer.cancel()
        _deadline.set()

_DAGE_BUDGET        : int   = 100
_DAGE_MAX_DEPTH     : int   = 3
_DAGE_TIMEOUT       : float = 70.0
_DAGE_REPLAY_N      : int   = 3
_DAGE_REPLAY_THRESH : int   = 2
_DAGE_PAC_DELTA     : float = 0.05
_DAGE_MAX_NODES     : int   = 48
_DAGE_MIN_BODY      : int   = 32

_DAGE_URL_IN_BODY_RE = re.compile(r'"(/(?:[A-Za-z0-9_\-]+/){1,5}[^"]{1,80})"')
_DAGE_NUMSEG_RE      = re.compile(r'(?<=/)\d{1,15}(?=[/#-]|$)')
_DAGE_UUID_RE        = re.compile(
    r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', re.I
)
_DAGE_AUTH_HDRS = frozenset((
    "authorization", "cookie", "x-api-key",
    "x-auth-token", "x-access-token", "x-session-token",
))
_DAGE_EXT_BYPASSES   = (".json", ".xml", ".csv")
_DAGE_FMT_BYPASSES   = ("format=json", "output=json", "_format=json", "type=json")

@dataclasses.dataclass
class _DageNode:
    url          : str
    rid          : str
    rtype        : str
    depth        : int
    source       : str
    parent_url   : str
    auth_status  : int
    auth_blen    : int
    auth_fp      : str
    embedded_rids: List[str] = dataclasses.field(default_factory=list)
    embedded_urls: List[str] = dataclasses.field(default_factory=list)

@dataclasses.dataclass
class _DageAccess:
    anon_status: int
    anon_blen  : int
    anon_fp    : str
    protected  : bool

@dataclasses.dataclass
class _DageWitness:
    attack_chain  : List[str]
    request_chain : List[Dict]
    gap_url       : str
    gap_type      : str
    description   : str
    delta         : str
    replay_results: List[bool]
    sha256        : str
    severity      : str

def _dage_rtype(url: str) -> str:
    path = url.split("?")[0].rstrip("/")
    segs = [
        s for s in path.split("/")
        if s
        and not _DAGE_NUMSEG_RE.fullmatch(s)
        and not _DAGE_UUID_RE.fullmatch(s)
    ]
    return segs[-1].lower() if segs else "resource"

def _dage_rtype_segment(url: str) -> str:
    path = url.split("?")[0].rstrip("/")
    parts = path.split("/")
    for seg in reversed(parts):
        if seg and not _DAGE_NUMSEG_RE.fullmatch(seg) and not _DAGE_UUID_RE.fullmatch(seg):
            return seg
    return ""

def _dage_rid(url: str) -> str:
    path = url.split("?")[0]
    m = _DAGE_NUMSEG_RE.search(path)
    if m:
        return m.group(0)
    m = _DAGE_UUID_RE.search(path)
    if m:
        return m.group(0)
    segs = path.rstrip("/").split("/")
    return segs[-1][:48] if segs else "root"

def _dage_probe(
    url: str,
    strip_auth: bool = False,
    method: str = "GET",
    timeout: float = 12.0,
    extra_headers: Optional[Dict[str, str]] = None,
) -> Tuple[int, int, str, str]:
    try:
        hdrs: Optional[Dict[str, str]] = None
        if strip_auth and _GLOBAL_HEADERS:
            cancel = {k: "" for k in _GLOBAL_HEADERS if k.lower() in _DAGE_AUTH_HDRS}
            hdrs = cancel if cancel else None
        if extra_headers:
            hdrs = dict(hdrs) if hdrs else {}
            hdrs.update(extra_headers)
        st, _, body = _req(url, method, None, hdrs, timeout)
        blen = len(body or b"")
        raw  = (body or b"")[:768].decode("utf-8", errors="replace")
        norm = _DAGE_NONCE_RE.sub("__N__", raw)
        norm = re.sub(r'\s+', ' ', norm)
        fp   = hashlib.sha1(norm.encode()).hexdigest()[:16]
        return st, blen, fp, raw
    except Exception:
        return 0, 0, "err", ""

def _dage_parse_embedded(excerpt: str, base_url: str) -> Tuple[List[str], List[str]]:
    rids: List[str] = []
    for m in _DAGE_ID_FIELD_RE.finditer(excerpt):
        val = m.group("val").strip('"')
        if _DAGE_UUID_RE.fullmatch(val) or re.fullmatch(r'\d{1,15}', val):
            rids.append(val)
    rids += _DAGE_UUID_RE.findall(excerpt)
    abs_urls: List[str] = []
    for m in _DAGE_URL_IN_BODY_RE.finditer(excerpt):
        abs_urls.append(urllib.parse.urljoin(base_url, m.group(1)))
    for m in _DAGE_HREF_RE.finditer(excerpt):
        abs_urls.append(urllib.parse.urljoin(base_url, m.group(1)))
    return list(dict.fromkeys(rids)), list(dict.fromkeys(abs_urls))

def _dage_neighbors(url: str, n: int = 3) -> List[str]:
    path, _, qs = url.partition("?")
    ms = list(_DAGE_NUMSEG_RE.finditer(path))
    if not ms:
        return []
    last   = ms[-1]
    base_n = int(last.group(0))
    seen: Set[str] = set()
    result: List[str] = []
    for delta in range(1, n + 1):
        for cid in (base_n + delta, max(1, base_n - delta)):
            nb = path[:last.start()] + str(cid) + path[last.end():] + ("?" + qs if qs else "")
            if nb not in seen:
                seen.add(nb); result.append(nb)
    return result[:n]

def _dage_seal(w: "_DageWitness") -> str:
    return hashlib.sha256(
        json.dumps({
            "attack_chain": w.attack_chain,
            "gap_url":      w.gap_url,
            "gap_type":     w.gap_type,
            "description":  w.description,
            "delta":        w.delta,
        }, sort_keys=True).encode()
    ).hexdigest()

def discover_authorization_graph_exploits(url: str) -> ScanFindings:
    out: ScanFindings = []
    _dl  = threading.Event()
    _tmr = threading.Timer(_DAGE_TIMEOUT, _dl.set)
    _tmr.start()
    req_n: List[int] = [0]

    bfs_cap = max(20, _DAGE_BUDGET * 40 // 100)
    ann_cap = max(10, _DAGE_BUDGET * 40 // 100)
    cf_cap  = bfs_cap + ann_cap + max(8, _DAGE_BUDGET * 15 // 100)

    try:
        s_st, s_blen, s_fp, s_exc = _dage_probe(url)
        req_n[0] += 1
        if s_st == 0 or _dl.is_set():
            return out

        nodes   : Dict[str, _DageNode] = {}
        visited : Set[str]             = set()
        _bfs_q  : List                 = []
        _ctr    : List[int]            = [0]

        def _push(depth: int, nu: str, src: str, par: str) -> None:
            if nu not in visited:
                visited.add(nu)
                _heapq.heappush(_bfs_q, (depth, _ctr[0], nu, src, par))
                _ctr[0] += 1

        _push(0, url, "seed", "")
        rids0, links0 = _dage_parse_embedded(s_exc, url)
        nodes[url] = _DageNode(
            url=url, rid=_dage_rid(url), rtype=_dage_rtype(url),
            depth=0, source="seed", parent_url="",
            auth_status=s_st, auth_blen=s_blen, auth_fp=s_fp,
            embedded_rids=rids0, embedded_urls=links0,
        )
        for lk in links0[:6]:
            _push(1, lk, "link", url)
        for nb in _dage_neighbors(url, n=3):
            _push(1, nb, "neighbor", url)

        while (
            _bfs_q and not _dl.is_set()
            and req_n[0] < bfs_cap
            and len(nodes) < _DAGE_MAX_NODES
        ):
            depth, _, nu, src, par = _heapq.heappop(_bfs_q)
            if depth > _DAGE_MAX_DEPTH:
                continue
            st, blen, fp, exc = _dage_probe(nu)
            req_n[0] += 1
            if st == 0:
                continue
            rids, links = _dage_parse_embedded(exc, nu)
            nodes[nu] = _DageNode(
                url=nu, rid=_dage_rid(nu), rtype=_dage_rtype(nu),
                depth=depth, source=src, parent_url=par,
                auth_status=st, auth_blen=blen, auth_fp=fp,
                embedded_rids=rids, embedded_urls=links,
            )
            if depth < _DAGE_MAX_DEPTH:
                for lk in links[:4]:
                    _push(depth + 1, lk, "link", nu)
                if depth < 2:
                    for nb in _dage_neighbors(nu, n=2):
                        _push(depth + 1, nb, "neighbor", nu)

        access: Dict[str, _DageAccess] = {}
        ann_limit = bfs_cap + ann_cap
        for nu in list(nodes):
            if _dl.is_set() or req_n[0] >= ann_limit:
                break
            ast, ablen, afp, _ = _dage_probe(nu, strip_auth=True)
            req_n[0] += 1
            access[nu] = _DageAccess(
                anon_status=ast, anon_blen=ablen, anon_fp=afp,
                protected=(ast in (401, 403)),
            )

        rid_index: Dict[str, List[str]] = {}
        for nu, node in nodes.items():
            for rid in node.embedded_rids:
                rid_index.setdefault(rid, []).append(nu)

        _UNTESTED = _DageAccess(anon_status=-1, anon_blen=0, anon_fp="", protected=False)

        candidates: List[_DageWitness] = []
        n_cf_probes = 0

        for nu, node in nodes.items():
            if _dl.is_set() or req_n[0] >= cf_cap:
                break
            ar = access.get(nu)
            if ar is None:
                continue

            if (not ar.protected
                    and ar.anon_status == 200
                    and ar.anon_blen > _DAGE_MIN_BODY
                    and node.source in ("link", "seed")
                    and node.rtype in _DAGE_SENSITIVE_RTYPES):
                par_ar = access.get(node.parent_url)
                if par_ar and par_ar.protected:
                    candidates.append(_DageWitness(
                        attack_chain=[node.parent_url, nu],
                        request_chain=[
                            {"url": node.parent_url, "method": "GET"},
                            {"url": nu,              "method": "GET"},
                        ],
                        gap_url=nu, gap_type="direct_anon",
                        description=(
                            "Sensitive %s (id=%s) publicly accessible (anon=%d) "
                            "while authenticated parent %s returns %d; "
                            "resource only discoverable via authenticated traversal"
                            % (node.rtype, node.rid, ar.anon_status,
                               node.parent_url, par_ar.anon_status)
                        ),
                        delta="parent_anon=%d node_anon=%d" % (par_ar.anon_status, ar.anon_status),
                        replay_results=[], sha256="", severity="HIGH",
                    ))

            if ar.protected and node.source != "neighbor":
                public_embs = [
                    eu for eu in rid_index.get(node.rid, [])
                    if eu != nu
                    and not access.get(eu, _UNTESTED).protected
                    and access.get(eu, _DageAccess(0, 0, "", False)).anon_status == 200
                ]
                rtype_seg = _dage_rtype_segment(nu)
                for emb_url in public_embs[:2]:
                    if _dl.is_set() or req_n[0] >= cf_cap:
                        break
                    ep = urllib.parse.urlparse(emb_url)
                    ep_base = ep.scheme + "://" + ep.netloc + ep.path.rstrip("/")
                    candidates_urls = list(dict.fromkeys([
                        ep_base + "/" + rtype_seg + "/" + node.rid,
                        ep_base + "/" + node.rid,
                    ]))
                    for indirect in candidates_urls:
                        if indirect in visited or indirect == nu:
                            continue
                        visited.add(indirect)
                        i_st, i_blen, _, _ = _dage_probe(indirect, strip_auth=True)
                        req_n[0] += 1; n_cf_probes += 1
                        if i_st == 200 and i_blen > _DAGE_MIN_BODY:
                            candidates.append(_DageWitness(
                                attack_chain=[emb_url, indirect],
                                request_chain=[
                                    {"url": emb_url,  "method": "GET"},
                                    {"url": indirect, "method": "GET"},
                                ],
                                gap_url=indirect, gap_type="indirect_bypass",
                                description=(
                                    "Protected %s (id=%s) blocked at %s (anon=%d) "
                                    "but accessible without auth via nested path %s - "
                                    "authorization check absent at parent endpoint"
                                    % (node.rtype, node.rid, nu, ar.anon_status, indirect)
                                ),
                                delta="direct_anon=%d indirect_anon=%d blen=%d" % (
                                    ar.anon_status, i_st, i_blen),
                                replay_results=[], sha256="", severity="CRIT",
                            ))
                            break

            if (node.source == "neighbor"
                    and not ar.protected
                    and ar.anon_status == 200
                    and ar.anon_blen > _DAGE_MIN_BODY):
                orig_ar   = access.get(node.parent_url)
                orig_node = nodes.get(node.parent_url)
                if (orig_ar and orig_ar.protected
                        and orig_node and orig_node.auth_status == 200):
                    n_cf_probes += 1
                    candidates.append(_DageWitness(
                        attack_chain=[node.parent_url, nu],
                        request_chain=[
                            {"url": node.parent_url, "method": "GET"},
                            {"url": nu,              "method": "GET"},
                        ],
                        gap_url=nu, gap_type="structural_idor",
                        description=(
                            "Collection OLAC non-uniform: %s id=%s requires auth "
                            "(anon=%d) but sibling id=%s is open (anon=%d)"
                            % (_dage_rtype(node.parent_url),
                               _dage_rid(node.parent_url), orig_ar.anon_status,
                               node.rid, ar.anon_status)
                        ),
                        delta="protected_id=%s open_id=%s" % (
                            _dage_rid(node.parent_url), node.rid),
                        replay_results=[], sha256="", severity="HIGH",
                    ))

            if ar.protected:
                all_embs = rid_index.get(node.rid, [])
                pub_embs = [
                    e for e in all_embs
                    if e != nu
                    and not access.get(e, _UNTESTED).protected
                    and access.get(e, _DageAccess(0, 0, "", False)).anon_status == 200
                ]
                for pub_emb in pub_embs[:1]:
                    if _dl.is_set() or req_n[0] >= cf_cap:
                        break
                    pp = urllib.parse.urlparse(pub_emb)
                    alt_url = (pp.scheme + "://" + pp.netloc
                               + pp.path.rstrip("/") + "/" + node.rid)
                    if alt_url in visited or alt_url == nu:
                        continue
                    visited.add(alt_url)
                    a_st, a_blen, _, _ = _dage_probe(alt_url, strip_auth=True)
                    req_n[0] += 1; n_cf_probes += 1
                    if a_st == 200 and a_blen > _DAGE_MIN_BODY:
                        candidates.append(_DageWitness(
                            attack_chain=[pub_emb, alt_url],
                            request_chain=[
                                {"url": pub_emb,  "method": "GET"},
                                {"url": alt_url,  "method": "GET"},
                            ],
                            gap_url=alt_url, gap_type="parent_swap",
                            description=(
                                "Parent-swap confused-deputy: %s (id=%s) blocked at "
                                "%s (anon=%d) but accessible via public parent path "
                                "%s (anon=%d) - resource-level re-validation absent"
                                % (node.rtype, node.rid, nu, ar.anon_status,
                                   alt_url, a_st)
                            ),
                            delta="direct_anon=%d alt_anon=%d" % (ar.anon_status, a_st),
                            replay_results=[], sha256="", severity="CRIT",
                        ))

            if ar.protected and node.source != "neighbor":
                base_path = nu.split("?")[0]
                ext_targets = (
                    [base_path + e for e in _DAGE_EXT_BYPASSES]
                    + [nu + ("&" if "?" in nu else "?") + f for f in _DAGE_FMT_BYPASSES]
                )
                for bypass_url in ext_targets:
                    if _dl.is_set() or req_n[0] >= cf_cap:
                        break
                    if bypass_url in visited:
                        continue
                    visited.add(bypass_url)
                    b_st, b_blen, _, _ = _dage_probe(bypass_url, strip_auth=True)
                    req_n[0] += 1; n_cf_probes += 1
                    if b_st == 200 and b_blen > _DAGE_MIN_BODY:
                        suffix = bypass_url[len(nu):]
                        candidates.append(_DageWitness(
                            attack_chain=[nu, bypass_url],
                            request_chain=[
                                {"url": nu,          "method": "GET"},
                                {"url": bypass_url,  "method": "GET"},
                            ],
                            gap_url=bypass_url, gap_type="extension_bypass",
                            description=(
                                "Protected %s (id=%s) blocked at %s (anon=%d) "
                                "but accessible without auth as %s (anon=%d) - "
                                "format-negotiation or extension routing selects "
                                "a code path that bypasses auth middleware"
                                % (node.rtype, node.rid, nu, ar.anon_status,
                                   bypass_url, b_st)
                            ),
                            delta="base_anon=%d bypass_anon=%d suffix=%r" % (
                                ar.anon_status, b_st, suffix),
                            replay_results=[], sha256="", severity="HIGH",
                        ))
                        break

            if ar.protected and node.source != "neighbor":
                if _dl.is_set() or req_n[0] >= cf_cap:
                    continue
                h_st, h_blen, _, _ = _dage_probe(nu, strip_auth=True, method="HEAD")
                req_n[0] += 1; n_cf_probes += 1
                if h_st == 200:
                    candidates.append(_DageWitness(
                        attack_chain=[nu],
                        request_chain=[{"url": nu, "method": "HEAD"}],
                        gap_url=nu, gap_type="head_bypass",
                        description=(
                            "Protected %s (id=%s): GET returns %d without auth "
                            "but HEAD returns %d - method-level auth check absent "
                            "on HEAD verb; confirms resource existence + metadata "
                            "without body, leaks presence/size information"
                            % (node.rtype, node.rid, ar.anon_status, h_st)
                        ),
                        delta="get_anon=%d head_anon=%d" % (ar.anon_status, h_st),
                        replay_results=[], sha256="", severity="MED",
                    ))

            if ar.protected and node.source != "neighbor":
                for _verb in ("OPTIONS", "DELETE", "PUT", "TRACE"):
                    if _dl.is_set() or req_n[0] >= cf_cap:
                        break
                    v_st, v_blen, _, _ = _dage_probe(nu, strip_auth=True, method=_verb)
                    req_n[0] += 1; n_cf_probes += 1
                    if v_st in (200, 201, 204):
                        candidates.append(_DageWitness(
                            attack_chain=[nu],
                            request_chain=[{"url": nu, "method": _verb}],
                            gap_url=nu, gap_type="verb_bypass",
                            description=(
                                "Protected %s (id=%s): GET returns %d without auth "
                                "but %s returns %d - HTTP verb auth check absent; "
                                "unauthorized state mutation or data access possible"
                                % (node.rtype, node.rid, ar.anon_status, _verb, v_st)
                            ),
                            delta="get_anon=%d %s_anon=%d" % (ar.anon_status, _verb, v_st),
                            replay_results=[], sha256="", severity="HIGH",
                        ))
                        break

            if ar.protected and node.source != "neighbor":
                _tunnel_headers = [
                    {"X-HTTP-Method-Override": "GET"},
                    {"X-Method-Override": "GET"},
                    {"X-HTTP-Method": "GET"},
                    {"_method": "GET"},
                ]
                for _th in _tunnel_headers:
                    if _dl.is_set() or req_n[0] >= cf_cap:
                        break
                    _th_st, _th_blen, _, _ = _dage_probe(
                        nu, strip_auth=True, method="POST",
                        extra_headers=_th,
                    )
                    req_n[0] += 1; n_cf_probes += 1
                    if _th_st == 200 and _th_blen > _DAGE_MIN_BODY:
                        _hdr_name = list(_th.keys())[0]
                        candidates.append(_DageWitness(
                            attack_chain=[nu],
                            request_chain=[{"url": nu, "method": "POST",
                                            "headers": _th}],
                            gap_url=nu, gap_type="method_tunnel",
                            description=(
                                "Protected %s (id=%s): GET blocked (anon=%d) but "
                                "POST with %s: GET returns %d - method override "
                                "tunnels through auth guard that only checks "
                                "the transport HTTP method"
                                % (node.rtype, node.rid, ar.anon_status,
                                   _hdr_name, _th_st)
                            ),
                            delta="get_anon=%d tunnel_anon=%d header=%s" % (
                                ar.anon_status, _th_st, _hdr_name),
                            replay_results=[], sha256="", severity="CRIT",
                        ))
                        break

            if ar.protected and node.source != "neighbor":
                _parsed_nu = urllib.parse.urlparse(nu)
                _nu_path = _parsed_nu.path
                _ver_re = re.compile(r"/v(\d+)/")
                _vm = _ver_re.search(_nu_path)
                if _vm:
                    _cur_ver = int(_vm.group(1))
                    for _dver in range(max(0, _cur_ver - 3), _cur_ver):
                        if _dl.is_set() or req_n[0] >= cf_cap:
                            break
                        _old_path = _ver_re.sub("/v%d/" % _dver, _nu_path, count=1)
                        _old_url = urllib.parse.urlunparse(
                            (_parsed_nu.scheme, _parsed_nu.netloc,
                             _old_path, "", "", "")
                        )
                        if _old_url in visited:
                            continue
                        visited.add(_old_url)
                        _dv_st, _dv_blen, _, _ = _dage_probe(
                            _old_url, strip_auth=True)
                        req_n[0] += 1; n_cf_probes += 1
                        if _dv_st == 200 and _dv_blen > _DAGE_MIN_BODY:
                            candidates.append(_DageWitness(
                                attack_chain=[nu, _old_url],
                                request_chain=[
                                    {"url": nu,       "method": "GET"},
                                    {"url": _old_url, "method": "GET"},
                                ],
                                gap_url=_old_url, gap_type="version_downgrade",
                                description=(
                                    "Protected %s (id=%s) at %s (anon=%d) "
                                    "but /v%d/ endpoint %s returns %d without auth - "
                                    "older API version lacks auth middleware added in v%d"
                                    % (node.rtype, node.rid, nu, ar.anon_status,
                                       _dver, _old_url, _dv_st, _cur_ver)
                                ),
                                delta="v%d_anon=%d v%d_anon=%d" % (
                                    _cur_ver, ar.anon_status, _dver, _dv_st),
                                replay_results=[], sha256="", severity="CRIT",
                            ))
                            break

        confirmed: List[_DageWitness] = []
        _dage_req_lock = threading.Lock()

        def _dage_replay(cand: _DageWitness) -> Optional[_DageWitness]:
            if _dl.is_set():
                return None
            fires = 0
            _method = cand.request_chain[-1].get("method", "GET")
            for _ in range(_DAGE_REPLAY_N):
                with _dage_req_lock:
                    if req_n[0] >= _DAGE_BUDGET:
                        break
                r_st, r_blen, _, _ = _dage_probe(
                    cand.request_chain[-1]["url"],
                    strip_auth=True,
                    method=_method,
                )
                with _dage_req_lock:
                    req_n[0] += 1
                if r_st == 200 and (r_blen > _DAGE_MIN_BODY or _method == "HEAD"):
                    fires += 1
            cand.replay_results = [True] * fires + [False] * (_DAGE_REPLAY_N - fires)
            if fires < _DAGE_REPLAY_THRESH:
                return None
            cand.sha256 = _dage_seal(cand)
            return cand

        with ThreadPoolExecutor(max_workers=min(max(len(candidates), 1), 4)) as _rpl:
            _rpl_futs = [_rpl.submit(_dage_replay, c) for c in candidates]
            for _rf in _rpl_futs:
                try:
                    _rc = _rf.result(timeout=20.0)
                    if _rc is not None:
                        confirmed.append(_rc)
                except Exception:
                    pass

        n_nodes  = len(nodes)
        n_probes = req_n[0]
        n_tested = max(1, n_cf_probes)
        pac_upper = 1.0 - (_DAGE_PAC_DELTA ** (1.0 / n_tested))
        pac_note  = (
            "Graph: %d nodes, %d requests, %d cf-probes. "
            "PAC: with %.0f%% confidence, <=%.1f%% bypass probability undetected."
            % (n_nodes, n_probes, n_cf_probes,
               (1.0 - _DAGE_PAC_DELTA) * 100.0, pac_upper * 100.0)
        )

        for w in confirmed:
            fires = sum(w.replay_results)
            out.append((
                "[DAGE] Authorization graph topology bypass -- %s\n"
                "  Type:    %s\n"
                "  Detail:  %s\n"
                "  Chain:   %s\n"
                "  Replay:  %d/%d  SHA256: %s\n"
                "  %s"
                % (
                    w.severity, w.gap_type, w.description,
                    " => ".join(w.attack_chain),
                    fires, _DAGE_REPLAY_N, w.sha256,
                    pac_note,
                ),
                w.gap_url,
            ))

        if not confirmed and n_nodes >= 3:
            out.append((
                "[DAGE] No topology-level authorization gaps found "
                "across %d-node resource graph. %s" % (n_nodes, pac_note),
                url,
            ))

        return out

    finally:
        _tmr.cancel()
        _dl.set()

_RACE_CONCURRENT_N    : int   = 10
_RACE_BURST_COUNT     : int   = 2
_RACE_BUDGET          : int   = 120
_RACE_BARRIER_TIMEOUT : float = 4.0
_RACE_MIN_DIVERGE     : int   = 2

_RACE_WRITE_METHODS = frozenset({"POST", "PUT", "PATCH"})





_RACE_CREATION_PATHS = [
    "/api/users", "/api/accounts", "/api/sessions",
    "/api/registrations", "/register", "/signup", "/auth/register",
]


def _race_burst(
    url: str,
    method: str,
    body: Optional[bytes],
    n: int,
    req_n: List[int],
    budget: int,
    extra_headers: Optional[Dict[str, str]] = None,
) -> List[Tuple[int, int, bytes]]:
    if req_n[0] + n > budget:
        return []
    results: List[Tuple[int, int, bytes]] = []
    _lock = threading.Lock()
    barrier = threading.Barrier(n + 1, timeout=_RACE_BARRIER_TIMEOUT)

    def _worker() -> None:
        try:
            barrier.wait()
            st, _, resp_body, _ = _req(url, method, body,
                                       headers=extra_headers, timeout=5.0)
            with _lock:
                results.append((st, len(resp_body), resp_body[:512]))
        except Exception:
            pass

    threads = [threading.Thread(target=_worker, daemon=True) for _ in range(n)]
    for t in threads:
        t.start()
    try:
        barrier.wait()
    except threading.BrokenBarrierError:
        pass
    for t in threads:
        t.join(timeout=_RACE_BARRIER_TIMEOUT + 5.0)
    req_n[0] += n
    return results

def discover_race_window(base: str) -> ScanFindings:
    out: ScanFindings = []
    req_n: List[int] = [0]
    seen: Set[str] = set()
    deadline = time.monotonic() + min(55.0, max(20.0, _MODULE_TIMEOUT * 0.6))
    ep_base = base.rstrip("/")

    def _emit(msg: str, evidence: str, key: str) -> None:
        if key not in seen:
            seen.add(key)
            out.append((msg, evidence))

    st0, _, body0, _ = _req(base)
    req_n[0] += 1
    if st0 == 0:
        return out

    text0 = body0.decode("utf-8", "ignore")
    race_targets: List[Tuple[str, str, Optional[bytes], str]] = []

    for m in _RACE_FORM_ACTION_RE.finditer(text0):
        action = (m.group(1) or m.group(4) or "").strip()
        fmethod = (m.group(2) or m.group(3) or "GET").upper()
        if fmethod in _RACE_WRITE_METHODS and _RACE_KEYWORD_RE.search(action):
            furl = action if action.startswith("http") else ep_base + "/" + action.lstrip("/")
            race_targets.append((furl, fmethod, None, "form:" + action[:60]))

    for path in _RACE_PROBE_PATHS:
        if req_n[0] >= _RACE_BUDGET or time.monotonic() > deadline:
            break
        url = ep_base + path
        st, _, _, _ = _req(url, "HEAD")
        req_n[0] += 1
        if st not in (0, 404):
            race_targets.append((url, "POST", None, "probe:" + path))

    with _DISC_ENDPOINTS_LOCK:
        _disc_snap = sorted(_DISCOVERED_ENDPOINTS)
    _race_target_urls = {t[0] for t in race_targets}
    for _disc_url in _disc_snap[:25]:
        if req_n[0] >= _RACE_BUDGET or time.monotonic() > deadline:
            break
        if _disc_url in _race_target_urls:
            continue
        _dp = urllib.parse.urlparse(_disc_url).path.lower()
        if _RACE_KEYWORD_RE.search(_dp):
            race_targets.append((_disc_url, "POST", None, "discovered:" + _dp[:60]))
            _race_target_urls.add(_disc_url)

    baseline: Dict[str, Optional[float]] = {}
    for url, _, _, _ in race_targets:
        if req_n[0] >= _RACE_BUDGET or time.monotonic() > deadline:
            break
        st, _, rbody, _ = _req(url, "GET")
        req_n[0] += 1
        if st and rbody:
            m_val = _RACE_VALUE_RE.search(rbody.decode("utf-8", "ignore"))
            if m_val:
                try:
                    baseline[url] = float(m_val.group(1))
                except ValueError:
                    pass

    for url, method, body, label in race_targets:
        if time.monotonic() > deadline:
            break
        if req_n[0] + _RACE_CONCURRENT_N * _RACE_BURST_COUNT + 1 > _RACE_BUDGET:
            break

        _req(url, "HEAD")
        req_n[0] += 1

        burst_a_hits = 0
        burst_b_hits = 0
        burst_c_match: Optional[str] = None

        for _bi in range(_RACE_BURST_COUNT):
            if req_n[0] + _RACE_CONCURRENT_N > _RACE_BUDGET:
                break
            results = _race_burst(url, method, body, _RACE_CONCURRENT_N, req_n, _RACE_BUDGET)
            if not results:
                continue

            codes = [r[0] for r in results]
            sizes = [r[1] for r in results]
            n_ok  = sum(1 for c in codes if 200 <= c < 300)

            if n_ok >= _RACE_MIN_DIVERGE:
                burst_a_hits += 1
            if len(set(sizes)) > 1 and n_ok > 0:
                burst_b_hits += 1
            if burst_c_match is None:
                for _, _, preview in results:
                    txt = preview.decode("utf-8", "ignore")
                    m_err = _RACE_ERROR_RE.search(txt)
                    if m_err:
                        burst_c_match = m_err.group(0)
                        break

            time.sleep(0.04)

        if burst_a_hits >= 2:
            _emit(
                "[RACE] Limit overrun: %s %s - %d/%d burst rounds had "
                "%d+ concurrent successes; no atomic guard on limited operation" % (
                    method, url, burst_a_hits, _RACE_BURST_COUNT, _RACE_MIN_DIVERGE),
                "label=%s" % label,
                "A:" + url,
            )
        elif burst_b_hits >= 2:
            _emit(
                "[RACE] Intermediate state exposed: %s %s - response sizes diverged "
                "in %d/%d burst rounds under concurrent load" % (
                    method, url, burst_b_hits, _RACE_BURST_COUNT),
                "label=%s" % label,
                "B:" + url,
            )
        if burst_c_match:
            _emit(
                "[RACE] Server acknowledged race at %s %s - response contained: '%s'" % (
                    method, url, burst_c_match[:80]),
                "label=%s" % label,
                "C:" + url,
            )

    _etag_checked: Set[str] = set()
    for url, method, body, label in race_targets:
        if url in _etag_checked:
            continue
        if req_n[0] + _RACE_CONCURRENT_N + 1 > _RACE_BUDGET or time.monotonic() > deadline:
            break
        _, _etag_hdr, _, _ = _req(url, "GET")
        req_n[0] += 1
        etag = _etag_hdr.get("etag", "").strip().strip('"')
        if not etag:
            continue
        _etag_checked.add(url)
        _etag_results = _race_burst(
            url, "PUT", body or b"{}",
            _RACE_CONCURRENT_N, req_n, _RACE_BUDGET,
            extra_headers={"If-Match": etag},
        )
        if not _etag_results:
            continue
        _etag_ok = sum(1 for _es, _, _ in _etag_results if 200 <= _es < 300)
        if _etag_ok >= _RACE_MIN_DIVERGE:
            _emit(
                "[RACE][CRITICAL] ETag optimistic-lock bypass at PUT %s - "
                "%d of %d concurrent PUTs with If-Match: %s returned 2xx; "
                "conditional writes not atomically enforced (TOCTOU on ETag)" % (
                    url, _etag_ok, _RACE_CONCURRENT_N, etag[:24]),
                "label=%s etag=%s" % (label, etag[:40]),
                "ETAG:" + url,
            )

    _IDEM_HDR_NAMES = (
        "Idempotency-Key", "X-Idempotency-Key",
        "X-Request-Id", "X-Unique-Request-Id",
    )
    _IDEM_BODY_RE = re.compile(
        rb'"(?:amount|price|total|qty|count|quantity)"\s*:\s*(\d+)'
    )
    for url, method, body, label in race_targets:
        if method not in _RACE_WRITE_METHODS:
            continue
        if req_n[0] + _RACE_CONCURRENT_N + 3 > _RACE_BUDGET or time.monotonic() > deadline:
            break
        _idem_hdr: Optional[str] = None
        for _ihn in _IDEM_HDR_NAMES:
            _pi_st, _, _, _ = _req(url, method, body or b"{}",
                                    headers={_ihn: "probe-" + hashlib.md5(
                                        os.urandom(4)).hexdigest()[:8]})
            req_n[0] += 1
            if _pi_st not in (0, 400, 405, 422):
                _idem_hdr = _ihn
                break
        if not _idem_hdr:
            continue
        _ia_results: List[Tuple[int, bytes]] = []
        _ia_lock = threading.Lock()
        _ia_barrier = threading.Barrier(_RACE_CONCURRENT_N + 1,
                                         timeout=_RACE_BARRIER_TIMEOUT)
        def _ia_worker(
            _b: threading.Barrier = _ia_barrier,
            _u: str = url, _m: str = method,
            _bd: bytes = body or b"{}",
            _h: str = _idem_hdr,
        ) -> None:
            _uk = "idem-" + hashlib.md5(os.urandom(8)).hexdigest()[:16]
            try:
                _b.wait()
                _is, _, _ib, _ = _req(_u, _m, _bd, headers={_h: _uk}, timeout=5.0)
                with _ia_lock:
                    _ia_results.append((_is, _ib[:256]))
            except Exception:
                pass
        _ia_threads = [threading.Thread(target=_ia_worker, daemon=True)
                       for _ in range(_RACE_CONCURRENT_N)]
        for _t in _ia_threads: _t.start()
        try: _ia_barrier.wait()
        except threading.BrokenBarrierError: pass
        for _t in _ia_threads: _t.join(timeout=_RACE_BARRIER_TIMEOUT + 5.0)
        req_n[0] += _RACE_CONCURRENT_N
        _ia_ok = sum(1 for _s, _ in _ia_results if 200 <= _s < 300)
        if _ia_ok >= _RACE_MIN_DIVERGE:
            _emit(
                "[RACE][CRITICAL] Idempotency-Key unlimited duplication at %s %s - "
                "%d/%d concurrent requests with unique %s keys all returned 2xx; "
                "each unique key triggers a real operation - unlimited double-spend" % (
                    method, url, _ia_ok, _RACE_CONCURRENT_N, _idem_hdr),
                "label=%s header=%s" % (label, _idem_hdr),
                "IDEM_DUP:" + url,
            )
        if req_n[0] + 2 <= _RACE_BUDGET and body and _IDEM_BODY_RE.search(body):
            _fixed_key = "kcache-" + hashlib.md5(url.encode()).hexdigest()[:12]
            _ib_r1, _, _, _ = _req(url, method, body,
                                    headers={_idem_hdr: _fixed_key}, timeout=5.0)
            req_n[0] += 1
            _mutated = _IDEM_BODY_RE.sub(b'"amount": -9999', body, count=1)
            _ib_r2, _, _, _ = _req(url, method, _mutated,
                                    headers={_idem_hdr: _fixed_key}, timeout=5.0)
            req_n[0] += 1
            if _ib_r1 == _ib_r2 and 200 <= _ib_r1 < 300:
                _emit(
                    "[RACE] Idempotency cache-poisoning at %s %s - "
                    "server returned %d for mutated body (amount=-9999) using same "
                    "key; idempotency cache not bound to request body hash - "
                    "replay with fraudulent amount confirms as success" % (
                        method, url, _ib_r1),
                    "label=%s header=%s key=%s" % (label, _idem_hdr, _fixed_key),
                    "IDEM_CACHE:" + url,
                )

    _STATE_TRANSITION_RE = re.compile(
        r"/(?:confirm|cancel|complete|capture|approve|reject|publish|activate"
        r"|deactivate|suspend|resume|finalize|process|settle|close|open|lock"
        r"|unlock|enable|disable|archive|restore|submit|accept|decline"
        r"|execute|trigger|checkout|ship|fulfill|refund|void|expire)",
        re.I,
    )
    _state_seen: Set[str] = set()
    for url, method, body, label in list(race_targets):
        if url in _state_seen:
            continue
        _up = urllib.parse.urlparse(url).path
        if not _STATE_TRANSITION_RE.search(_up):
            continue
        if req_n[0] + _RACE_CONCURRENT_N * 2 + 1 > _RACE_BUDGET or time.monotonic() > deadline:
            break
        _state_seen.add(url)
        _req(url, "HEAD"); req_n[0] += 1
        _sr1 = _race_burst(url, method or "POST", body,
                           _RACE_CONCURRENT_N, req_n, _RACE_BUDGET)
        _sr2 = _race_burst(url, method or "POST", body,
                           _RACE_CONCURRENT_N, req_n, _RACE_BUDGET)
        _ok1 = sum(1 for s, _, _ in _sr1 if 200 <= s < 300)
        _ok2 = sum(1 for s, _, _ in _sr2 if 200 <= s < 300)
        if _ok1 >= _RACE_MIN_DIVERGE and _ok2 >= 1:
            _emit(
                "[RACE][CRITICAL] State machine race at %s %s - "
                "burst 1: %d/%d succeeded; burst 2 (post-transition): %d/%d succeeded; "
                "transition is not atomic - multiple concurrent callers can advance "
                "the same state simultaneously" % (
                    method or "POST", url,
                    _ok1, _RACE_CONCURRENT_N, _ok2, _RACE_CONCURRENT_N),
                "label=%s path=%s" % (label, _up),
                "STATE:" + url,
            )
        elif _ok1 >= 2:
            _emit(
                "[RACE] Concurrent state transitions at %s %s - "
                "%d/%d simultaneous requests accepted in burst 1; "
                "state transition may not be guarded by exclusive lock" % (
                    method or "POST", url, _ok1, _RACE_CONCURRENT_N),
                "label=%s path=%s" % (label, _up),
                "STATE_SOFT:" + url,
            )

    _creation_path_tmpls: List[Tuple[str, str]] = [
        ("/api/users",
         r'{"username":"rc<TS>","password":"Rc1!<TS>","email":"rc<TS>@x.test"}'),
        ("/api/accounts",
         r'{"name":"rc<TS>","email":"rc<TS>@x.test"}'),
        ("/api/registrations",
         r'{"email":"rc<TS>@x.test","password":"Rc1!<TS>"}'),
        ("/register",
         r'{"username":"rc<TS>","password":"Rc1!<TS>"}'),
        ("/signup",
         r'{"email":"rc<TS>@x.test","password":"Rc1!<TS>"}'),
    ]
    for path, _tmpl in _creation_path_tmpls:
        _ts = "%x" % (int(time.time() * 1000) & 0xFFFFFF)
        pay = _tmpl.replace("<TS>", _ts).encode()
        if req_n[0] + _RACE_CONCURRENT_N > _RACE_BUDGET or time.monotonic() > deadline:
            break
        url = ep_base + path
        st_chk, _, _, _ = _req(url, "HEAD")
        req_n[0] += 1
        if st_chk in (0, 404):
            continue

        results = _race_burst(url, "POST", pay, _RACE_CONCURRENT_N, req_n, _RACE_BUDGET)
        if not results:
            continue

        created = [(st, sz, pv) for st, sz, pv in results if st in (200, 201)]
        if len(created) < _RACE_MIN_DIVERGE:
            continue

        ids_found: Set[str] = set()
        for _, _, preview in created:
            m_id = _DAGE_ID_FIELD_RE.search(preview.decode("utf-8", "ignore"))
            if m_id:
                ids_found.add(m_id.group("val"))

        if len(ids_found) < len(created):
            _emit(
                "[RACE][CRITICAL] Duplicate-resource race at POST %s - "
                "%d concurrent POSTs returned %d success responses but only %d unique IDs; "
                "the same record was created more than once" % (
                    url, _RACE_CONCURRENT_N, len(created), len(ids_found)),
                "duplicate IDs: %s" % str(ids_found),
                "D_dup:" + url,
            )
        else:
            _emit(
                "[RACE] Concurrent-creation race at POST %s - "
                "%d of %d simultaneous POSTs returned 2xx; "
                "uniqueness constraint may not be atomically enforced" % (
                    url, len(created), _RACE_CONCURRENT_N),
                "IDs: %s" % str(ids_found),
                "D_multi:" + url,
            )

    for url, _, _, _ in race_targets:
        if url not in baseline or baseline[url] is None:
            continue
        if req_n[0] >= _RACE_BUDGET or time.monotonic() > deadline:
            break
        old_val = baseline[url]
        _, _, rbody, _ = _req(url, "GET")
        req_n[0] += 1
        if not rbody:
            continue
        m_val = _RACE_VALUE_RE.search(rbody.decode("utf-8", "ignore"))
        if m_val:
            try:
                new_val = float(m_val.group(1))
                if new_val < 0.0 and old_val >= 0.0:
                    _emit(
                        "[RACE] Numeric underflow confirmed at %s - "
                        "resource value %.2f -> %.2f after concurrent writes; "
                        "limit enforcement is not atomic" % (url, old_val, new_val),
                        "before=%.2f after=%.2f" % (old_val, new_val),
                        "E:" + url,
                    )
            except ValueError:
                pass

    n_findings = len([f for f in out if not f[0].startswith("[RACE] Race surface")])
    out.append((
        "[RACE] Race surface scan complete - %d endpoints probed, "
        "%d requests fired, %d race conditions found" % (
            len(race_targets), req_n[0], n_findings),
        "budget=%d used=%d surfaces=%d" % (_RACE_BUDGET, req_n[0], len(race_targets)),
    ))
    return out

_SMUG_STALL_TIMEOUT  : float = 5.0
_SMUG_BASELINE_N     : int   = 4
_SMUG_CONFIRM_RATIO  : float = 2.5
_SMUG_BUDGET         : int   = 80


_H2_PREFACE            = b"PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n"
_H2D_BUDGET            : int   = 60

_H2_FRAME_DATA         = 0x0
_H2_FRAME_HEADERS      = 0x1
_H2_FRAME_PRIORITY     = 0x2
_H2_FRAME_RST_STREAM   = 0x3
_H2_FRAME_SETTINGS     = 0x4
_H2_FRAME_PUSH_PROMISE = 0x5
_H2_FRAME_PING         = 0x6
_H2_FRAME_GOAWAY       = 0x7
_H2_FRAME_WINDOW_UPDATE= 0x8
_H2_FRAME_CONTINUATION = 0x9

_H2_FLAG_END_STREAM    = 0x1
_H2_FLAG_END_HEADERS   = 0x4
_H2_FLAG_ACK           = 0x1

_H2_SETTINGS_ENABLE_PUSH            = 0x2
_H2_SETTINGS_MAX_CONCURRENT_STREAMS = 0x3
_H2_SETTINGS_INITIAL_WINDOW_SIZE    = 0x4

def _smug_raw(
    host: str,
    port: int,
    use_ssl: bool,
    raw: bytes,
    read_timeout: float = 8.0,
) -> Tuple[bytes, float]:
    t0 = time.perf_counter()
    data = b""
    try:
        s = socket.create_connection((host, port), timeout=read_timeout)
        s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        if use_ssl:
            _ctx = ssl.create_default_context()
            _ctx.check_hostname = False
            _ctx.verify_mode = ssl.CERT_NONE
            s = _ctx.wrap_socket(s, server_hostname=host)
        s.settimeout(read_timeout)
        s.sendall(raw)
        while True:
            try:
                chunk = s.recv(8192)
                if not chunk:
                    break
                data += chunk
                if len(data) > 65536:
                    break
            except socket.timeout:
                break
        try:
            s.close()
        except Exception:
            pass
    except Exception:
        pass
    return data, time.perf_counter() - t0

def _smug_status(data: bytes) -> int:
    if not data:
        return 0
    try:
        return int(data.split(b" ", 2)[1])
    except Exception:
        return 0

def _smug_keepalive_pair(
    host: str,
    port: int,
    use_ssl: bool,
    req1: bytes,
    req2: bytes,
    inter_sleep: float = 0.12,
) -> Tuple[bytes, bytes]:
    r1, r2 = b"", b""
    try:
        s = socket.create_connection((host, port), timeout=8.0)
        s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        if use_ssl:
            _ctx = ssl.create_default_context()
            _ctx.check_hostname = False
            _ctx.verify_mode = ssl.CERT_NONE
            s = _ctx.wrap_socket(s, server_hostname=host)
        s.settimeout(6.0)
        s.sendall(req1)
        time.sleep(inter_sleep)
        try:
            while True:
                c = s.recv(4096)
                if not c or len(r1) > 32768:
                    break
                r1 += c
                if b"\r\n\r\n" in r1:
                    break
        except socket.timeout:
            pass
        s.sendall(req2)
        try:
            while True:
                c = s.recv(8192)
                if not c or len(r2) > 32768:
                    break
                r2 += c
                if b"\r\n\r\n" in r2:
                    break
        except socket.timeout:
            pass
        try:
            s.close()
        except Exception:
            pass
    except Exception:
        pass
    return r1, r2

def discover_smuggling_oracle(base: str) -> ScanFindings:
    out: ScanFindings = []
    _seen: Set[str] = set()
    _probe_n: List[int] = [0]

    parsed = urllib.parse.urlparse(base)
    _host = parsed.hostname or ""
    _port = parsed.port or (443 if parsed.scheme == "https" else 80)
    _ssl  = parsed.scheme == "https"
    _path = (parsed.path or "/").encode()
    _host_hdr = (
        ("%s:%d" % (_host, _port)).encode()
        if _port not in (80, 443)
        else _host.encode()
    )

    if not _host:
        return out

    def _emit(msg: str, ev: str, key: str) -> None:
        if key not in _seen:
            _seen.add(key)
            out.append((msg, ev))

    def _probe(raw: bytes, timeout: float = 6.0) -> Tuple[bytes, float]:
        _probe_n[0] += 1
        return _smug_raw(_host, _port, _ssl, raw, read_timeout=timeout)

    _BASE_REQ = (
        b"GET " + _path + b" HTTP/1.1\r\n"
        b"Host: " + _host_hdr + b"\r\n"
        b"Connection: close\r\n\r\n"
    )
    _b_times: List[float] = []
    for _ in range(_SMUG_BASELINE_N):
        _, _t = _probe(_BASE_REQ, timeout=6.0)
        if _t > 0.02:
            _b_times.append(_t)
    if len(_b_times) < 2:
        out.append(("[smug] unreachable - cannot establish TCP baseline", base))
        return out
