_SSTI_BUDGET = 90

_SSTI_POLYGLOT    = "{{7*7}}${7*7}<%= 7*7 %>#{7*7}*{7*7}{7*7}"
_SSTI_POLY_RESULT = "49"





_SSTI_J2_SUBCLASS_PROBE   = "{{''.__class__.__mro__[1].__subclasses__()}}"
