        args.cachepoisonxfh, args.oauthpkce, args.samlsig,
        args.redisunauth, args.esunauth, args.mongounauth, args.k8setcd,
        getattr(args, "zero_day", False),
        getattr(args, "coopeep", False), getattr(args, "docpol", False),
