def scan_headers(base: str) -> ScanFindings:
    return _scan_headers_impl(_scan_context(), base, _SECURITY_HEADERS, _DEPRECATED_HEADERS)

def scan_sensitive_paths(base: str, workers: int) -> ScanFindings:
    out: ScanFindings = []

    def one(path: str) -> Optional[Tuple[str, str]]:
        u = _join_url(base, path)
        hc, _, _, _ = _req(u, method="HEAD")
        if hc in (404, 410):
            return None
        if hc == 405:
            pass
        elif hc not in (200, 206, 301, 302, 403):
            return None
        c, _, b, _ = _req(u)
        if c in (200, 206, 301, 302, 403) and len(b) > 20:
            if c == 403:
                return ("restricted path is reachable HTTP " + str(c), path)
            low = b[:8000].lower()
            if path.endswith(".env") and (b"=" in b[:5000] or b"password" in low or b"secret" in low):
                return ("sensitive .env file may be exposed", path)
            if ".git" in path and b"repositoryformatversion" in low:
                return ("git config exposed", path)
            if "swagger" in path or "api-docs" in path:
                if b"swagger" in low or b"openapi" in low:
                    return ("API documentation exposed", path)
            if path in ("/admin", "/administrator", "/wp-login.php") and c == 200:
                return ("administrative interface accessible", path)
        return None

    with ThreadPoolExecutor(max_workers=workers) as ex:
        futs = {ex.submit(one, p): p for p in _SENSITIVE_PATHS}
        for f in as_completed(futs):
            r = f.result()
            if r:
                out.append(r)
    return out

_XSS_FORM_FIELDS = ["q", "search", "name", "message", "comment", "text", "body", "content", "subject", "input"]

def _xss_check_reflect(text: str, canary: str, pay: str) -> bool:
    if canary not in text:
        return False
    cidx = text.find(canary)
    window = text[max(0, cidx - 256):cidx + 256].lower()
    dec = unescape(pay)
    if pay not in window and dec.lower() not in window and urllib.parse.unquote_plus(pay).lower() not in window:
        return False
    if "<" in pay:
        encoded_version = pay.lower().replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")
        if encoded_version in window and pay.lower() not in window:
            return False
    for npay, nbody in _XSS_TAG_CHECKS:
        if npay in pay.lower() and nbody in window:
            return True
    return False

def _xss_confirm(url: str, surface: str, param: str, method: str = "GET") -> Optional[str]:
    for probe in _XSS_EXEC_PROBES:
        if method == "GET":
            _, chdrs, cbody, _ = _req(_inject_param(url, param, probe))
        else:
            body_data = urllib.parse.urlencode({param: probe}).encode()
            _, chdrs, cbody, _ = _req(url, method="POST", data=body_data,
                                      content_type="application/x-www-form-urlencoded")
        ct = chdrs.get("content-type", "")
        if "json" in ct or ("xml" in ct and "html" not in ct):
            continue
        ctext = cbody.decode("utf-8", "ignore")
        if probe in ctext:
            idx = ctext.find(probe)
            pre = ctext[max(0, idx - 200):idx]
            if "<!--" in pre[max(0, len(pre) - 80):] and "-->" not in pre[max(0, len(pre) - 80):]:
                continue
            if pre.rfind("<") > pre.rfind(">"):
                continue
            return probe
    return None

_XSS_FORMS_RE = re.compile(r'<form[^>]*action=["\']?([^"\'> ]*)["\']?[^>]*>(.*?)</form>', re.S | re.I)

def scan_xss(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url)
    if not params:
        params = list(_XSS_DEFAULT_PARAMS)
    canary = "xsscanary" + hashlib.md5(os.urandom(6)).hexdigest()[:8]
    url_params = params[:16]

    with ThreadPoolExecutor(max_workers=10) as ex:
        bfuts: Dict = {ex.submit(_req, _inject_param(url, p, "hello")): p for p in url_params}
        clean: List[str] = []
        for f in as_completed(bfuts):
            p = bfuts[f]
            try:
                if canary not in f.result()[2].decode("utf-8", "ignore"):
                    clean.append(p)
            except Exception:
                pass
        pfuts: Dict = {}
        for p in clean:
            for pay in _XSS_PAYLOADS:
                tagged = pay + "<!--" + canary + "-->"
                pfuts[ex.submit(_req, _inject_param(url, p, tagged))] = ("GET", p, pay)
        seen_url: Set[str] = set()
        for f in as_completed(pfuts):
            method, p, pay = pfuts[f]
            if p in seen_url:
                continue
            try:
                text = f.result()[2].decode("utf-8", "ignore")
            except Exception:
                continue
            if _xss_check_reflect(text, canary, pay):
                seen_url.add(p)
                probe = _xss_confirm(url, "url", p, "GET")
                label = "[CONFIRMED] reflected XSS" if probe else "possible reflected XSS"
                out.append((label + " on param " + p, probe or pay))

    _, _, base_body, _ = _req(url, use_cache=True)
    base_html = base_body.decode("utf-8", "ignore")
    seen_post: Set[str] = set()
    _post_lock = threading.Lock()
    post_combos = []
    for m in _XSS_FORMS_RE.finditer(base_html):
        action = m.group(1) or ""
        form_url_p = _join_url(url, action) if action else url
        for field in _XSS_FORM_FIELDS:
            for pay in _XSS_PAYLOADS[:8]:
                post_combos.append((form_url_p, field, pay))

    def _post_probe(combo):
        furl, field, pay = combo
        with _post_lock:
            if field in seen_post:
                return None
        tagged = pay + "<!--" + canary + "-->"
        body_data = urllib.parse.urlencode({field: tagged}).encode()
        _, _, rb, _ = _req(furl, method="POST", data=body_data,
                           content_type="application/x-www-form-urlencoded")
        text = rb.decode("utf-8", "ignore")
        if _xss_check_reflect(text, canary, pay):
            with _post_lock:
                if field not in seen_post:
                    seen_post.add(field)
                    return (furl, field, pay)
        return None

    if post_combos:
        with ThreadPoolExecutor(max_workers=8) as post_ex:
            for res in post_ex.map(_post_probe, post_combos):
                if res:
                    furl, field, pay = res
                    probe = _xss_confirm(furl, "post", field, "POST")
                    label = "[CONFIRMED] reflected XSS" if probe else "possible reflected XSS"
                    out.append((label + " in POST field " + field, probe or pay))

    json_canary = "xssjson" + hashlib.md5(os.urandom(4)).hexdigest()[:6]
    for api_path in ("/api/search", "/api/query", "/search", "/api/v1/search"):
        api_url = _join_url(url, api_path)
        for field in ("q", "query", "search", "term"):
            pay = "<svg onload=alert(1)><!--" + json_canary + "-->"
            jbody = json.dumps({field: pay}).encode()
            _, _, rb, _ = _req(api_url, method="POST", data=jbody, content_type="application/json")
            text = rb.decode("utf-8", "ignore")
            if json_canary in text and "<svg" in text.lower():
                out.append(("possible reflected XSS via JSON body field=%s at %s" % (field, api_path), pay))
                break

    return out

def _sqli_check_surface(probe_url: str, method: str, body_tpl: Optional[bytes],
                        ct: Optional[str], label: str) -> ScanFindings:
    s_out: ScanFindings = []
    try:
        _, _, base_b, _ = _req(probe_url, method=method, data=body_tpl, content_type=ct)
        if _SQL_ERR_RE.search(base_b.decode("utf-8", "ignore")):
            return s_out
    except Exception:
        return s_out

    for pay in _SQLI_ALL_PAYLOADS:
        try:
            if body_tpl is not None:
                probe_data = body_tpl.replace(b"__SQL_SLOT__", pay.encode())
                c, _, b, _ = _req(probe_url, method=method, data=probe_data, content_type=ct)
            else:
                c, _, b, _ = _req(probe_url, method=method)
            text = b.decode("utf-8", "ignore")
            if _SQL_ERR_RE.search(text):
                db = next((name for pat, name in _DB_FINGERPRINTS if pat.search(text)), "unknown DB")
                nonce = hashlib.md5(os.urandom(4)).hexdigest()[:6]
                if body_tpl is not None:
                    benign_data = body_tpl.replace(b"__SQL_SLOT__", nonce.encode())
                    _, _, bb, _ = _req(probe_url, method=method, data=benign_data, content_type=ct)
                else:
                    _, _, bb, _ = _req(probe_url)
                if not _SQL_ERR_RE.search(bb.decode("utf-8", "ignore")):
                    s_out.append(("[CONFIRMED] SQL injection (error-based, %s) surface=%s" % (db, label), pay))
                    return s_out
                else:
                    s_out.append(("SQL error signal surface=%s" % label, pay))
                    return s_out
        except Exception:
            pass

    nonce = hashlib.md5(os.urandom(4)).hexdigest()[:4]

    def _bool_req(pay: str) -> bytes:
        if body_tpl is not None:
            d = body_tpl.replace(b"__SQL_SLOT__", pay.encode())
            _, _, b, _ = _req(probe_url, method=method, data=d, content_type=ct)
        else:
            _, _, b, _ = _req(probe_url)
        return b

    try:
        ra = _bool_req("1 OR %s=%s" % (nonce[:2], nonce[:2]))
        rb = _bool_req("1 OR %s=%s" % (nonce[:2], nonce[:2]))
        rf = _bool_req("1 AND %s=%s" % (nonce[:2], nonce[2:]))
        la, lb, lf = len(ra), len(rb), len(rf)
        twin = abs(la - lb) <= max(64, int(la * 0.02))
        divergent = abs(la - lf) > max(128, int(la * 0.05))
        if twin and divergent:
            s_out.append(("[CONFIRMED] SQL injection (boolean-blind) surface=%s" % label,
                          "1 OR %s=%s" % (nonce[:2], nonce[:2])))
            return s_out
    except Exception:
        pass

    for time_pay, delay in _TIME_PAYLOADS[:3]:
        try:
            t0 = time.perf_counter()
            if body_tpl is not None:
                d = body_tpl.replace(b"__SQL_SLOT__", time_pay.encode())
                _req(probe_url, method=method, data=d, content_type=ct, timeout=delay + 4.0)
            else:
                _req(probe_url, timeout=delay + 4.0)
            elapsed = time.perf_counter() - t0
            if elapsed >= delay * 0.85:
                s_out.append(("SQL injection (time-based blind, %.1fs delay) surface=%s" % (elapsed, label), time_pay))
                return s_out
        except Exception:
            pass

    return s_out

def scan_sqli(url: str) -> ScanFindings:
    out: ScanFindings = []

    params = _extract_params(url) or ["id", "user", "cat", "page", "item", "q",
                                       "search", "name", "order", "sort", "filter"]
    params = params[:10]
    with ThreadPoolExecutor(max_workers=10) as ex:
        futs: Dict = {}
        for p in params:
            for pay in _SQLI_ALL_PAYLOADS:
                futs[ex.submit(_req, _inject_param(url, p, pay))] = (p, pay)
        seen_params: Set[str] = set()
        for f in as_completed(futs):
            p, pay = futs[f]
            if p in seen_params:
                continue
            try:
                _, _, body, _ = f.result()
            except Exception:
                continue
            text = body.decode("utf-8", "ignore")
            if _SQL_ERR_RE.search(text):
                db = next((n for pat, n in _DB_FINGERPRINTS if pat.search(text)), "unknown DB")
                nonce = hashlib.md5(os.urandom(4)).hexdigest()[:6]
                _, _, bb, _ = _req(_inject_param(url, p, nonce))
                if not _SQL_ERR_RE.search(bb.decode("utf-8", "ignore")):
                    seen_params.add(p)
                    out.append(("[CONFIRMED] SQL injection (error-based, %s) on param %s" % (db, p), pay))
                    continue
                out.append(("SQL error signal on param " + p, pay))
                seen_params.add(p)

    confirmed_out: ScanFindings = []
    for det, pay in out:
        if "[CONFIRMED]" in det:
            confirmed_out.append((det, pay))
            continue
        param = det.split("param ")[-1].strip()
        nonce = hashlib.md5(os.urandom(4)).hexdigest()[:6]
        true_a  = "1 OR " + nonce[:1] + "=" + nonce[:1]
        true_b  = "1' OR '" + nonce[:1] + "'='" + nonce[:1]
        false_v = "1 AND " + nonce[:1] + "=" + nonce[:2]
        try:
            _, _, ra, _ = _req(_inject_param(url, param, true_a))
            _, _, rb, _ = _req(_inject_param(url, param, true_b))
            _, _, rf, _ = _req(_inject_param(url, param, false_v))
            la, lb, lf = len(ra), len(rb), len(rf)
            twin = abs(la - lb) <= max(64, int(la * 0.02))
            divergent = abs(la - lf) > max(128, int(la * 0.05))
            if twin and divergent:
                confirmed_out.append(("[CONFIRMED] SQL injection (boolean-blind) on param " + param, pay))
                continue
        except Exception:
            pass
        _, _, benign_b, _ = _req(_inject_param(url, param, nonce))
        if not _SQL_ERR_RE.search(benign_b.decode("utf-8", "ignore")):
            confirmed_out.append(("[CONFIRMED] SQL injection (error-based) on param " + param, pay))
        else:
            confirmed_out.append((det, pay))
    out = confirmed_out

    if out:
        return out

    _SQLI_HEADERS = [
        "X-Forwarded-For", "X-Real-IP", "User-Agent", "Referer",
        "X-Originating-IP", "X-Remote-IP", "X-Client-IP",
    ]
    for hdr in _SQLI_HEADERS:
        for pay in _SQLI_PAYLOADS[:8] + _WAF_BYPASS[:4]:
            try:
                _, _, b, _ = _req(url, headers={hdr: pay})
                text = b.decode("utf-8", "ignore")
                if _SQL_ERR_RE.search(text):
                    db = next((n for pat, n in _DB_FINGERPRINTS if pat.search(text)), "unknown DB")
                    _, _, bb, _ = _req(url, headers={hdr: "safe_value_127"})
                    if not _SQL_ERR_RE.search(bb.decode("utf-8", "ignore")):
                        out.append(("[CONFIRMED] SQL injection (error-based, %s) in header %s" % (db, hdr), pay))
                        return out
            except Exception:
                pass

    _POST_PARAMS = params[:5] + ["username", "password", "email", "search", "query", "login"]
    for param in _POST_PARAMS[:6]:
        body_tpl = ("%s=__SQL_SLOT__&submit=1" % param).encode()
        found = _sqli_check_surface(url, "POST", body_tpl, "application/x-www-form-urlencoded",
                                    "POST body param=%s" % param)
        if found:
            out.extend(found)
            return out

    _JSON_KEYS = ["id", "user_id", "search", "query", "name", "username", "email", "filter"]
    for key in _JSON_KEYS[:5]:
        body_tpl = json.dumps({key: "__SQL_SLOT__"}).encode()
        found = _sqli_check_surface(url, "POST", body_tpl, "application/json",
                                    "JSON body key=%s" % key)
        if found:
            out.extend(found)
            return out

    parsed = urllib.parse.urlparse(url)
    path_parts = [p for p in parsed.path.split("/") if p]
    for i, seg in enumerate(path_parts[-2:]):
        if seg.isdigit() or (len(seg) < 20 and seg.isalnum()):
            for pay in ["'", "''", "'--", "1' OR '1'='1", "1 AND 1=1"]:
                new_parts = path_parts[:]
                idx = len(path_parts) - 2 + i
                new_parts[idx] = seg + pay
                new_path = "/" + "/".join(new_parts)
                new_url = parsed.scheme + "://" + parsed.netloc + new_path
                if parsed.query:
                    new_url += "?" + parsed.query
                try:
                    _, _, b, _ = _req(new_url)
                    text = b.decode("utf-8", "ignore")
                    if _SQL_ERR_RE.search(text):
                        db = next((n for pat, n in _DB_FINGERPRINTS if pat.search(text)), "unknown DB")
                        out.append(("[CONFIRMED] SQL injection (error-based, %s) in path segment %s" % (db, seg), pay))
                        return out
                except Exception:
                    pass

    return out

_LFI_DEFAULT_PARAMS = [
    "file", "path", "page", "include", "doc", "folder", "load", "template",
    "view", "module", "section", "theme", "layout", "conf", "read", "show",
]

def _run_param_injection_scan(
    url: str,
    payloads: List[str],
    hit_fn: Callable[[str, str, str], Optional[str]],
    baseline_token: str,
    out_suffix: str,
    default_params: List[str],
    post_fields: List[str],
    max_params: int = 14,
    max_workers: int = 10,
    post_payload_limit: int = 8,
) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url) or list(default_params)
    params = params[:max_params]

    baseline_cache: Dict[str, Optional[str]] = {}
    for p in params:
        try:
            _, _, bb, _ = _req(_inject_param(url, p, baseline_token))
            baseline_cache[p] = bb.decode("utf-8", "ignore")
        except Exception:
            baseline_cache[p] = None

    seen: Set[str] = set()
    with ThreadPoolExecutor(max_workers=max_workers) as ex:
        futs: Dict = {ex.submit(_req, _inject_param(url, p, pay)): (p, pay)
                      for p in params for pay in payloads}
        for f in as_completed(futs):
            p, pay = futs[f]
            if p in seen:
                continue
            try:
                text = f.result()[2].decode("utf-8", "ignore")
            except Exception:
                continue
            bl = baseline_cache.get(p)
            if bl is None:
                continue
            msg = hit_fn(text, bl, pay)
            if msg:
                seen.add(p)
                out.append((msg + out_suffix + "param " + p, pay))

    seen_post: Set[str] = set()
    for field in post_fields:
        if field in seen:
            continue
        try:
            bd_base = urllib.parse.urlencode({field: baseline_token}).encode()
            _, _, rb_base, _ = _req(url, method="POST", data=bd_base,
                                    content_type="application/x-www-form-urlencoded")
            post_baseline: Optional[str] = rb_base.decode("utf-8", "ignore")
        except Exception:
            post_baseline = None
        if post_baseline is None:
            continue
        for pay in payloads[:post_payload_limit]:
            try:
                bd = urllib.parse.urlencode({field: pay}).encode()
                _, _, rb, _ = _req(url, method="POST", data=bd,
                                   content_type="application/x-www-form-urlencoded")
                text = rb.decode("utf-8", "ignore")
                msg = hit_fn(text, post_baseline, pay)
                if msg and field not in seen_post:
                    seen_post.add(field)
                    out.append((msg + "in POST field " + field, pay))
                    break
            except Exception:
                pass
    return out

def _lfi_hit(text: str, base: str, pay: str) -> Optional[str]:
    if _LFI_CONFIRM_RE.search(text) and not _LFI_CONFIRM_RE.search(base):
        if "root:x:0:0" in text or "root:" in text and ":/bin/" in text:
            return "[CONFIRMED] LFI (/etc/passwd) "
        if "[extensions]" in text.lower() and ("fonts" in text.lower() or "mci" in text.lower()):
            return "[CONFIRMED] LFI (win.ini) "
        if "PD9waHA" in text:
            return "[CONFIRMED] LFI (php source via filter) "
        if "environ" in pay and ("PATH=" in text or "HOME=" in text or "USER=" in text):
            return "[CONFIRMED] LFI (/proc/self/environ) "
    return None

def scan_lfi(url: str) -> ScanFindings:
    return _run_param_injection_scan(
        url=url,
        payloads=_LFI_PAYLOADS,
        hit_fn=_lfi_hit,
        baseline_token="lfi_baseline",
        out_suffix="on ",
        default_params=list(_LFI_DEFAULT_PARAMS),
        post_fields=["file", "path", "page", "include", "doc", "template", "view"],
        max_params=14,
        max_workers=10,
        post_payload_limit=8,
    )

_CMDI_DEFAULT_PARAMS = [
    "cmd", "host", "ip", "exec", "ping", "target", "addr", "url",
    "server", "hostname", "address", "domain", "query", "command",
]

def _cmdi_hit(text: str, base: str) -> bool:
    if _CMDI_NIX_RE.search(text) and not _CMDI_NIX_RE.search(base):
        return True
    if _CMDI_WIN_RE.search(text) and not _CMDI_WIN_RE.search(base):
        return True
    return False

def scan_cmdi(url: str) -> ScanFindings:
    _hit: Callable[[str, str, str], Optional[str]] = \
        lambda t, b, p: "[CONFIRMED] command injection " if _cmdi_hit(t, b) else None
    out = _run_param_injection_scan(
        url=url,
        payloads=_CMDI_PAYLOADS[:12],
        hit_fn=_hit,
        baseline_token="cmdi_baseline",
        out_suffix="on ",
        default_params=list(_CMDI_DEFAULT_PARAMS),
        post_fields=["cmd", "host", "ip", "exec", "command", "ping", "target", "query"],
        max_params=14,
        max_workers=10,
        post_payload_limit=8,
    )

    def _probe_json_field(field: str) -> ScanFindings:
        try:
            jb_base = json.dumps({field: "cmdi_baseline"}).encode()
            _, _, rb_base, _ = _req(url, method="POST", data=jb_base, content_type="application/json")
            json_baseline = rb_base.decode("utf-8", "ignore")
        except Exception:
            json_baseline = ""
        for pay in (";id", "|id", "$(id)"):
            try:
                jb = json.dumps({field: pay}).encode()
                _, _, rb, _ = _req(url, method="POST", data=jb, content_type="application/json")
                if _cmdi_hit(rb.decode("utf-8", "ignore"), json_baseline):
                    return [("[CONFIRMED] command injection via JSON field=" + field, pay)]
            except Exception:
                pass
        sleep_pay = "; sleep 3"
        try:
            t0 = time.time()
            jb = json.dumps({field: sleep_pay}).encode()
            _req(url, method="POST", data=jb, content_type="application/json", timeout=5.0)
            dt = time.time() - t0
            if dt >= 2.8:
                return [("possible blind command injection via JSON sleep (field=%s, delay=%.1fs)"
                         % (field, dt), sleep_pay)]
        except Exception:
            pass
        return []

    out += _par_scan(_probe_json_field, ["cmd", "host", "command", "ip", "exec"])
    return out

def scan_ssti(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url)
    if not params:
        params = ["template", "name", "view", "msg", "q", "page", "input",
                  "search", "text", "subject", "content", "body", "tpl", "render"]
    a = random.randint(400, 999)
    b = random.randint(400, 999)
    canary = str(a * b)
    _PROBES: List[Tuple[str, str]] = [
        ("{{%d*%d}}"              % (a, b), "Jinja2/Twig/Nunjucks"),
        ("${%d*%d}"               % (a, b), "Freemarker/SpEL/Mako"),
        ("<%%=%d*%d%%>"           % (a, b), "ERB/EJS"),
        ("#{%d*%d}"               % (a, b), "Ruby/Slim"),
        ("*{%d*%d}"               % (a, b), "Spring SpEL"),
        ("@(%d*%d)"               % (a, b), "Razor (.NET)"),
        ("{php}echo %d*%d;{/php}" % (a, b), "Smarty"),
        ("{{=%d*%d}}"             % (a, b), "Pebble"),
        ("#set($x=%d*%d)$x"      % (a, b), "Velocity"),
        ("[[${%d*%d}]]"           % (a, b), "Thymeleaf"),
        ("{=%d*%d}"               % (a, b), "Latte"),
    ]
    _CONFIRM_PROBES: List[Tuple[str, str, str]] = [
        ("{{7*'7'}}", "7777777",  "Jinja2"),
        ("{{7*'7'}}", "49",       "Twig"),
        ("${7*7}",    "49",       "Freemarker/SpEL"),
        ("<%= 7*7 %>","49",       "ERB"),
        ("#{7*7}",    "49",       "Ruby/Slim"),
        ("*{7*7}",    "49",       "Spring SpEL"),
        ("{php}echo 7*7;{/php}", "49", "Smarty"),
        ("{{=7*7}}",  "49",       "Pebble"),
        ("#set($x=7*7)$x", "49", "Velocity"),
        ("<%=7*7%>",  "49",       "EJS"),
        ("[[${7*7}]]","49",       "Thymeleaf"),
        ("{=7*7}",    "49",       "Latte"),
    ]
    def _confirm_engine(inject_fn) -> str:
        for cprobe, cexp, engine in _CONFIRM_PROBES:
            try:
                _, _, cbody, _ = inject_fn(cprobe)
                if cexp in cbody.decode("utf-8", "ignore"):
                    return engine
            except Exception:
                pass
        return "unknown"
    seen: Set[str] = set()
    baseline0 = _req(url)[2].decode("utf-8", "ignore")
    for param in params[:8]:
        baseline = _req(_inject_param(url, param, "ssti_test_xyz"))[2].decode("utf-8", "ignore")
        if canary in baseline:
            continue
        key = "GET:" + param
        if key in seen:
            continue
        for pay, hint in _PROBES:
            _, _, body, _ = _req(_inject_param(url, param, pay))
            if canary in body.decode("utf-8", "ignore"):
                engine = _confirm_engine(
                    lambda p, _p=param: _req(_inject_param(url, _p, p)))
                seen.add(key)
                out.append(("[CONFIRMED] SSTI (%s) on GET param %s" % (
                    hint if engine == "unknown" else engine, param), pay))
                break
    for param in params[:6]:
        key = "POST:" + param
        if key in seen:
            continue
        try:
            bl = _req(url, method="POST",
                      data=urllib.parse.urlencode({param: "ssti_test_xyz"}).encode(),
                      content_type="application/x-www-form-urlencoded")[2].decode("utf-8", "ignore")
            if canary in bl:
                continue
        except Exception:
            continue
        for pay, hint in _PROBES:
            try:
                _, _, body, _ = _req(url, method="POST",
                                     data=urllib.parse.urlencode({param: pay}).encode(),
                                     content_type="application/x-www-form-urlencoded")
                if canary in body.decode("utf-8", "ignore"):
                    engine = _confirm_engine(
                        lambda p, _p=param: _req(
                            url, method="POST",
                            data=urllib.parse.urlencode({_p: p}).encode(),
                            content_type="application/x-www-form-urlencoded"))
                    seen.add(key)
                    out.append(("[CONFIRMED] SSTI (%s) on POST param %s" % (
                        hint if engine == "unknown" else engine, param), pay))
                    break
            except Exception:
                pass
    _SSTI_HEADERS = [
        "User-Agent", "Referer", "X-Forwarded-For", "X-Real-IP",
        "X-Forwarded-Host", "Accept-Language", "Origin", "X-Custom-Header",
    ]
    for hdr in _SSTI_HEADERS:
        key = "HDR:" + hdr
        if key in seen:
            continue
        for pay, hint in _PROBES[:6]:
            try:
                _, _, body, _ = _req(url, headers={hdr: pay})
                if canary in body.decode("utf-8", "ignore") and canary not in baseline0:
                    engine = _confirm_engine(
                        lambda p, _h=hdr: _req(url, headers={_h: p}))
                    seen.add(key)
                    out.append(("[CONFIRMED] SSTI (%s) via header %s" % (
                        hint if engine == "unknown" else engine, hdr), pay))
                    break
            except Exception:
                pass
    existing_cookies = _GLOBAL_HEADERS.get("Cookie", "")
    _COOKIE_NAMES = ["username", "user", "name", "display_name", "lang", "locale", "theme", "session_data"]
    for cname in _COOKIE_NAMES[:5]:
        key = "COOKIE:" + cname
        if key in seen:
            continue
        for pay, hint in _PROBES[:6]:
            try:
                pfx = (existing_cookies + "; ") if existing_cookies else ""
                cval = pfx + cname + "=" + urllib.parse.quote(pay)
                _, _, body, _ = _req(url, headers={"Cookie": cval})
                if canary in body.decode("utf-8", "ignore") and canary not in baseline0:
                    engine = _confirm_engine(
                        lambda p, _cn=cname: _req(url, headers={"Cookie": (
                            (existing_cookies + "; ") if existing_cookies else ""
                        ) + _cn + "=" + urllib.parse.quote(p)}))
                    seen.add(key)
                    out.append(("[CONFIRMED] SSTI (%s) via cookie %s" % (
                        hint if engine == "unknown" else engine, cname), pay))
                    break
            except Exception:
                pass
    return out

_CRLF_DEFAULT_PARAMS = [
    "redirect", "next", "url", "return", "goto", "dest", "target",
    "redir", "location", "lang", "language", "ref", "callback",
]

def scan_crlf(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url)
    if not params:
        params = list(_CRLF_DEFAULT_PARAMS)

    def _crlf_hit(hdrs: Dict[str, str], body: bytes) -> bool:
        if "injected=1" in hdrs.get("set-cookie", "").lower():
            return True
        if "crlf" in hdrs.get("x-injected", "").lower():
            return True
        if "evil.example.com" in hdrs.get("location", ""):
            return True
        text = body.decode("utf-8", "ignore")
        return "<script>alert(1)</script>" in text and "injected" in text.lower()

    def _probe_param(param: str) -> ScanFindings:
        for pay in _CRLF_PAYLOADS:
            _, hdrs, body, _ = _req(_inject_param(url, param, pay))
            if _crlf_hit(hdrs, body):
                return [("[CONFIRMED] CRLF injection on param " + param, pay)]
        return []

    out += _par_scan(_probe_param, params[:10])

    for hdr_name in ("X-Forwarded-For", "Referer", "X-Forwarded-Host"):
        for pay in _CRLF_PAYLOADS[:3]:
            _, hdrs, body, _ = _req(url, headers={hdr_name: "test.com" + pay.replace("%0d", "\r").replace("%0a", "\n")})
            if _crlf_hit(hdrs, body):
                out.append(("[CONFIRMED] CRLF injection via header " + hdr_name, pay))
                break

    parsed = urllib.parse.urlparse(url)
    path_pay = urllib.parse.quote("\r\nSet-Cookie: injected=1", safe="")
    test_path = f"{parsed.scheme}://{parsed.netloc}{parsed.path}" + path_pay
    _, hdrs, body, _ = _req(test_path)
    if _crlf_hit(hdrs, body):
        out.append(("[CONFIRMED] CRLF injection in URL path", path_pay))

    return out

class _NoRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None

def scan_open_redirect(url: str) -> ScanFindings:
    out: ScanFindings = []
    p = urllib.parse.urlparse(url)
    base_root = p.scheme + "://" + p.netloc + "/"
    opener = urllib.request.build_opener(
        _NoRedirectHandler(),
        urllib.request.HTTPSHandler(context=_CTX),
    )
    seen: Set[str] = set()

    def _check_redirect(test_url: str, probe: str) -> Optional[str]:
        req = urllib.request.Request(test_url, headers={"Referer": base_root, "User-Agent": _GLOBAL_UA})
        try:
            with opener.open(req, timeout=_GLOBAL_TIMEOUT) as resp:
                code = resp.getcode()
                loc = resp.headers.get("location", "") or ""
        except urllib.error.HTTPError as e:
            code = e.code
            loc = e.headers.get("location", "") or ""
        except Exception:
            return None
        if code in (301, 302, 303, 307, 308) and "evil.example.com" in loc:
            return loc
        if code in (301, 302, 303, 307, 308) and "javascript:" in loc.lower():
            return loc
        return None

    def _probe_redirect_param(param: str) -> ScanFindings:
        for probe in _OPEN_REDIRECT_PROBES:
            loc = _check_redirect(_inject_param(base_root + "?", param, probe), probe)
            if loc:
                return [("[CONFIRMED] open redirect via param " + param + " -> " + loc[:60], probe)]
        return []

    out += _par_scan(_probe_redirect_param, list(_OPEN_REDIRECT_PARAMS))

    for probe in _OPEN_REDIRECT_PROBES[:4]:
        bd = urllib.parse.urlencode({"url": probe, "next": probe, "redirect": probe}).encode()
        req = urllib.request.Request(url, data=bd, headers={
            "User-Agent": _GLOBAL_UA,
            "Content-Type": "application/x-www-form-urlencoded",
        })
        try:
            with opener.open(req, timeout=_GLOBAL_TIMEOUT) as resp:
                code = resp.getcode()
                loc = resp.headers.get("location", "") or ""
        except urllib.error.HTTPError as e:
            code = e.code
            loc = e.headers.get("location", "") or ""
        except Exception:
            continue
        if code in (301, 302, 303, 307, 308) and "evil.example.com" in loc:
            out.append(("[CONFIRMED] open redirect via POST body", probe))
            break

    return out

