def scan_nosql(url: str) -> ScanFindings:
    params = _extract_params(url)
    if not params:
        params = ["id", "user", "filter", "search", "q", "username", "email", "password"]

    def _probe_get(param: str) -> ScanFindings:
        _, _, base_body, _ = _req(_inject_param(url, param, "test_baseline_xyz"))
        base_text = base_body.decode("utf-8", "ignore")
        base_len = len(base_text)
        base_err = bool(_RE_NOSQL_ERR.search(base_text))
        for pay in _NOSQL_PAYLOADS + _NOSQL_URL_BYPASS:
            _, _, body, _ = _req(_inject_param(url, param, pay))
            text = body.decode("utf-8", "ignore")
            if _RE_NOSQL_ERR.search(text) and not base_err:
                return [("[CONFIRMED] NoSQL injection error on param " + param, pay)]
            if abs(len(text) - base_len) > 500 and not base_err:
                return [("NoSQL injection candidate on param %s (size diff %d)" % (
                    param, len(text) - base_len), pay)]
        return []

    def _probe_json(field: str) -> ScanFindings:
        _, _, base_b, _ = _req(url, method="POST",
                               data=json.dumps({field: "invalid_baseline_xyz"}).encode(),
                               content_type="application/json")
        base_t = base_b.decode("utf-8", "ignore")
        base_err = bool(_RE_NOSQL_ERR.search(base_t))
        for op_obj in _NOSQL_JSON_PAYLOADS[:3]:
            jb = json.dumps({field: op_obj}).encode()
            _, _, rb, _ = _req(url, method="POST", data=jb, content_type="application/json")
            text = rb.decode("utf-8", "ignore")
            if _RE_NOSQL_ERR.search(text) and not base_err:
                return [("[CONFIRMED] NoSQL injection via JSON field %s operator %s" % (
                    field, list(op_obj.keys())[0]), str(op_obj))]
            if "token" in text.lower() or "session" in text.lower() or len(text) > len(base_t) + 200:
                return [("NoSQL auth bypass candidate via JSON field %s" % field, str(op_obj))]
        return []

    out = _par_scan(_probe_get, params[:12])
    out += _par_scan(_probe_json, ["username", "password", "email", "user", "id", "filter"])
    return out

def scan_ldap(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url)
    if not params:
        params = ["user", "username", "cn", "filter", "q", "search"]
    for param in params[:8]:
        _, _, base_body, _ = _req(_inject_param(url, param, "test"))
        base_text = base_body.decode("utf-8", "ignore")
        for pay in _LDAP_PAYLOADS:
            test = _inject_param(url, param, pay)
            _, _, body, _ = _req(test)
            text = body.decode("utf-8", "ignore")
            if _RE_LDAP_ERR.search(text) and not _RE_LDAP_ERR.search(base_text):
                out.append(("[CONFIRMED] LDAP injection error on param " + param, pay))
                break
    return out

_GRAPHQL_FULL_INTROSPECTION = b'{"query":"{__schema{queryType{name}mutationType{name}subscriptionType{name}types{name kind fields{name args{name type{name kind ofType{name kind}}}type{name kind ofType{name kind}}}}}}"}'
_GRAPHQL_BATCH_INTROSPECT   = b'[{"query":"{__typename}"},{"query":"{__schema{queryType{name}}}"}]'
_GRAPHQL_SUBSCRIPTION_PROBE = b'{"query":"subscription{__typename}"}'

_GRAPHQL_CONFIRMED_ENDPOINT: Dict[str, str] = {}

def scan_graphql(base: str) -> ScanFindings:
    out: ScanFindings = []
    endpoints = ["/graphql", "/api/graphql", "/v1/graphql", "/query", "/graphiql",
                 "/api/v1/graphql", "/graph", "/gql", "/api/gql"]
    confirmed_endpoint: Optional[str] = None
    for path in endpoints:
        u = _join_url(base, path)
        c, _, b, _ = _req(u, method="POST", data=_GRAPHQL_BODY, content_type="application/json")
        t = b.decode("utf-8", "ignore")
        tls = re.sub(r"\s+", "", t.lower())
        if c == 200 and "__schema" in tls and ("querytype" in tls or "mutationtype" in tls):
            out.append(("GraphQL introspection enabled", path))
            confirmed_endpoint = path
            _GRAPHQL_CONFIRMED_ENDPOINT[urllib.parse.urlparse(base).netloc] = path
            break

    if confirmed_endpoint:
        u = _join_url(base, confirmed_endpoint)

        c2, _, b2, _ = _req(u, method="POST", data=_GRAPHQL_FULL_INTROSPECTION, content_type="application/json")
        t2 = b2.decode("utf-8", "ignore").lower()
        if "mutationtype" in t2.replace(" ", "") and '"name"' in t2:
            if re.search(r'"name"\s*:\s*"(?:delete|remove|update|create|admin|reset|grant)', t2):
                out.append(("GraphQL introspection exposes privileged mutations", confirmed_endpoint))

        c3, _, b3, _ = _req(u, method="POST", data=_GRAPHQL_BATCH_INTROSPECT, content_type="application/json")
        t3 = b3.decode("utf-8", "ignore")
        if t3.strip().startswith("[") and "__typename" in t3 and "__schema" in t3:
            out.append(("GraphQL batch queries enabled (amplification/rate-limit bypass)", confirmed_endpoint))

        c4, _, b4, _ = _req(u, method="POST", data=_GRAPHQL_SUBSCRIPTION_PROBE, content_type="application/json")
        t4 = b4.decode("utf-8", "ignore")
        if c4 == 200 and "subscription" in t4.lower() and "error" not in t4.lower():
            out.append(("GraphQL subscriptions enabled (real-time data channel)", confirmed_endpoint))

    return out

def scan_directory_listing(base: str) -> ScanFindings:
    code, _, body, _ = _req(base)
    if code != 200:
        return []
    low = body[:200000].lower()
    if (
        b"index of /" in low
        or b"<title>index of " in low
        or b"directory listing for" in low
        or b"[to parent directory]" in low
        or (b"parent directory</a>" in low and b"last modified" in low)
    ):
        return [("directory listing may be enabled", "")]
    return []

def _fetch_if_exists(url: str, timeout: float = 4.0) -> Optional[Tuple[int, bytes]]:
    hc, _, _, _ = _req(url, method="HEAD", timeout=timeout)
    if hc in (404, 410):
        return None
    if hc != 405 and hc not in (200, 201, 301, 302, 403):
        return None
    c, _, b, _ = _req(url, timeout=timeout)
    if c == 0:
        return None
    return (c, b)

def scan_backup_extensions(url: str) -> ScanFindings:
    out: ScanFindings = []
    p = urllib.parse.urlparse(url)
    site = p.scheme + "://" + p.netloc
    path = p.path or "/"
    trials: List[str] = []
    if path.endswith("/"):
        trials.extend([path + "index.php", path + "index.html", path + "default.aspx"])
    else:
        trials.append(path)
    suffixes = [".bak", ".old", "~", ".swp", ".save", ".tmp", "_bak", ".orig", ".copy"]
    candidates: List[str] = []
    for t in trials[:4]:
        for suf in suffixes:
            cand = t + suf
            candidates.append(urllib.parse.urljoin(site + "/", cand.lstrip("/")))

    def _probe(u: str) -> Optional[Tuple[str, str]]:
        result = _fetch_if_exists(u)
        if result is None:
            return None
        c, b = result
        if c != 200 or len(b) < 20:
            return None
        bl = b[:8000].lower()
        if b"<-php" in b[:12000] or b"-----begin" in bl or b"db_password" in bl or b"aws_secret" in bl:
            return ("backup or source file may be exposed", u)
        return None

    with ThreadPoolExecutor(max_workers=12) as ex:
        for result in ex.map(_probe, candidates):
            if result:
                out.append(result)
    return out

def scan_host_header(url: str) -> ScanFindings:
    p = urllib.parse.urlparse(url)
    marker = "vulnscan-hostcheck.invalid"
    base = urllib.parse.urlunparse((p.scheme, p.netloc, p.path or "/", "", p.query, ""))
    code, hdrs, body, _ = _req(
        base,
        headers={"Host": marker, "X-Forwarded-Host": marker, "X-Original-URL": "/"},
    )
    if code == 0:
        return []
    loc = (hdrs.get("location") or "").lower()
    text = body.decode("utf-8", "ignore").lower()
    if marker in text or marker in loc:
        return [("host header is reflected in response (password-reset poisoning risk)", marker)]
    return []

