def scan_sqli_blind_timing(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url) or ["id"]
    payloads = [
        "1' AND SLEEP(4)-- -",
        "1'; WAITFOR DELAY '0:0:4'--",
        "1'; SELECT pg_sleep(4)--",
        "1 AND (SELECT * FROM (SELECT(SLEEP(4)))a)--",
        "1' OR SLEEP(4)--",
    ]
    started = time.monotonic()
    total_budget = min(45.0, max(18.0, _MODULE_TIMEOUT * 0.55))

    def _baseline_once(param_name: str) -> Optional[float]:
        u = _inject_param(url, param_name, "1")
        code, _, _, _, dt = _req_with_time(u, timeout=7.0)
        if code == 0:
            return None
        return dt

    for param in params[:4]:
        if time.monotonic() - started > total_budget:
            break
        samples: List[float] = []
        with ThreadPoolExecutor(max_workers=3) as ex:
            futs = [ex.submit(_baseline_once, param) for _ in range(3)]
            for fut in as_completed(futs):
                try:
                    dt = fut.result()
                except Exception:
                    dt = None
                if dt is not None:
                    samples.append(dt)
        if len(samples) < 3:
            continue
        base_avg = statistics.mean(samples)
        base_std = statistics.stdev(samples) if len(samples) > 1 else 0.0
        if base_std > max(1.2, base_avg * 0.75):
            extra = _baseline_once(param)
            if extra is not None:
                samples.append(extra)
                base_avg = statistics.mean(samples)
                base_std = statistics.stdev(samples) if len(samples) > 1 else 0.0
        if base_avg > 5.0 or base_std > max(1.8, base_avg):
            continue
        threshold = base_avg + max(2.5, base_std * 3.0)
        for pay in payloads:
            if time.monotonic() - started > total_budget:
                break
            u2 = _inject_param(url, param, pay)
            _, _, _, _, dt2 = _req_with_time(u2, timeout=9.0)
            if dt2 > threshold:
                _, _, _, _, dt3 = _req_with_time(u2, timeout=9.0)
                label = "[CONFIRMED]" if dt3 > threshold else "possible"
                out.append((label + " blind time-based SQLi on param " + param
                            + " (response %.1fs vs baseline %.1fs)" % (dt2, base_avg), pay))
                break
    return out

def scan_jwt_issues(base: str) -> ScanFindings:
    out: ScanFindings = []
    code, hdrs, body, _ = _req(base)
    if code == 0:
        return out
    text = body.decode("utf-8", "ignore") + " " + str(hdrs.get("set-cookie", ""))
    seen: set = set()
    for m in _JWT_RE.finditer(text):
        token = m.group(0)
        if token in seen:
            continue
        seen.add(token)
        parts = token.split(".")
        if len(parts) != 3:
            continue
        try:
            pad = "=" * (-len(parts[0]) % 4)
            hdr_raw = base64.urlsafe_b64decode(parts[0] + pad)
            jo = json.loads(hdr_raw.decode("utf-8", "ignore"))
        except Exception:
            continue
        alg = str(jo.get("alg", "")).upper()
        if alg in ("NONE", "NONE/NONE", "NONE+HS256"):
            out.append(("JWT uses insecure algorithm " + alg, token[:80]))
        if "kid" in jo:
            out.append(("JWT kid header present (key confusion risk)", token[:80]))
        if str(jo.get("jku", "")).startswith("http"):
            out.append(("JWT jku URL allows remote JWKS (hijacking risk)", str(jo.get("jku", ""))[:120]))
        if not jo.get("exp"):
            out.append(("JWT has no expiry claim", token[:80]))
    return out

