def scan_auth_bypass_headers(url: str) -> ScanFindings:
    c0, _, _, _ = _req(url)
    if c0 not in (401, 403):
        return []
    hdrs = {
        "X-Forwarded-For": "127.0.0.1",
        "X-Real-IP": "127.0.0.1",
        "X-Client-IP": "127.0.0.1",
        "X-Originating-IP": "127.0.0.1",
        "X-Remote-IP": "127.0.0.1",
        "X-Remote-Addr": "127.0.0.1",
        "X-Custom-IP-Authorization": "127.0.0.1",
    }
    c1, _, b1, _ = _req(url, headers=hdrs)
    if c1 == 200 and len(b1) > 200:
        return [("401/403 bypassed with IP spoofing headers", "X-Forwarded-For: 127.0.0.1")]
    c2, _, _, _ = _req(url, headers={"X-Original-URL": "/admin", "X-Rewrite-URL": "/admin"})
    if c2 == 200 and c0 == 403:
        return [("rewrite headers may alter routed path behind proxy", "X-Original-URL: /admin")]
    return []

def scan_path_traversal_url(base: str) -> ScanFindings:
    p = urllib.parse.urlparse(base)
    path = p.path or "/"
    raw1 = path.rstrip("/") + "/..%2f..%2f..%2f..%2fetc%2fpasswd"
    raw2 = path.rstrip("/") + "/%2e%2e%2f%2e%2e%2f%2e%2e%2f%2e%2e%2fetc%2fpasswd"
    for raw in (raw1, raw2):
        if not raw.startswith("/"):
            raw = "/" + raw
        u = urllib.parse.urlunparse((p.scheme, p.netloc, raw, "", "", ""))
        _, _, b, _ = _req(u)
        if b"root:x:0:0" in b[:40000]:
            return [("path traversal may expose system files", raw)]
    uq = _inject_param(base, "file", "....//....//....//....//etc/passwd")
    _, _, b2, _ = _req(uq)
    if b"root:x:0:0" in b2[:40000]:
        return [("path traversal via param file exposes system files", "....//....//....//....//etc/passwd")]
    return []

def scan_external_script_sri(base: str) -> ScanFindings:
    code, _, body, _ = _req(base)
    if code != 200:
        return []
    t = body.decode("utf-8", "ignore")
    for m in re.finditer(r"<script[^>]*src\s*=\s*[\"']([^\"'>]+)[\"']", t, re.I):
        src = m.group(1).strip()
        if not src.startswith(("http://", "https://", "//")):
            continue
        tag = m.group(0).lower()
        if "integrity=" in tag:
            continue
        if "nonce=" in tag and "strict" in t.lower():
            continue
        return [("external script loaded without Subresource Integrity", src)]
    return []

def scan_http_alternate_entry(base: str) -> ScanFindings:
    p = urllib.parse.urlparse(base)
    if p.scheme != "https":
        return []
    http_u = urllib.parse.urlunparse(("http", p.netloc, p.path or "/", p.params, p.query, p.fragment))
    c, _, _, _ = _req(http_u, timeout=8.0)
    if c in (200, 301, 302, 307, 308, 401, 403):
        return [("plaintext HTTP reachable (MITM / downgrade risk)", http_u)]
    return []

def scan_xss_filter_bypass(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url) or ["q", "search", "id", "name"]
    for param in params[:8]:
        for pay in _XSS_BYPASS_PAYLOADS:
            test = _inject_param(url, param, pay)
            _, _, body, _ = _req(test)
            text = body.decode("utf-8", "ignore")
            tl = text.lower()
            dec = urllib.parse.unquote_plus(pay)
            udec = unescape(dec)
            if pay not in text and dec not in text and udec not in text and urllib.parse.unquote(dec) not in text:
                if "onload" in pay.lower() and "onload" in tl and ("<svg" in tl or "svg/" in tl):
                    out.append(("possible XSS filter bypass on param " + param, pay))
                    break
                if "alert" in pay.lower() and ("<script" in tl or "onload=" in tl or "onerror=" in tl):
                    out.append(("possible XSS filter bypass on param " + param, pay))
                    break
            else:
                if "svg" in pay.lower() and "onload" in pay.lower() and ("<svg" in tl or "onload" in tl):
                    out.append(("possible XSS filter bypass on param " + param, pay))
                    break
                if "<script" in pay.lower() and "<script" in tl:
                    out.append(("possible XSS filter bypass on param " + param, pay))
                    break
    return out

