def _cve_probe_drupal(base: str) -> ScanFindings:
    path = "/CHANGELOG.txt"
    dc, _, db, _ = _req(base.rstrip("/") + path)
    if dc == 200:
        dm = re.search(r"Drupal (\d+\.\d+)", db.decode("utf-8", "ignore"))
        if dm:
            ver = dm.group(1)
            if int(ver.split(".")[0]) < 8:
                return [("Drupalgeddon risk: Drupal " + ver + " (CVE-2018-7600 / CVE-2014-3704)", path)]
    return []

