    path = "/wp-login.php"
    wc, _, wb, _ = _req(base.rstrip("/") + path)
    if wc == 200 and b"wp-login" in wb.lower():
        return [("WordPress login exposed: assess for CVE-2020-28032 and brute-force risk", path)]
