def scan_css_injection(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url)
    css_params = [p for p in params
                  if re.search(r"style|color|theme|css|skin|font|bg|background|class|design", p, re.I)]
    if not css_params:
        css_params = params[:6]
    if not css_params:
        return out
    payloads = [
        "red;}</style><script>alert(1)</script><style>",
        "expression(alert(document.domain))",
        "</style><img src=x onerror=alert(1)>",
        "background:url(//evil.example.com/x.css)",
        "url('javascript:alert(1)')",
    ]
    canary = "csscanary" + hashlib.md5(os.urandom(4)).hexdigest()[:6]
    for param in css_params[:4]:
        baseline = _req(_inject_param(url, param, "blue"))[2].decode("utf-8", "ignore")
        for pay in payloads:
            tagged = pay + "/*" + canary + "*/"
            _, _, body, _ = _req(_inject_param(url, param, tagged))
            text = body.decode("utf-8", "ignore")
            if canary in text and (pay in text or unescape(pay) in text):
                out.append(("CSS injection: unescaped style value reflected via param " + param, pay))
                break
    return out

def scan_websocket_hijacking(base: str) -> ScanFindings:
    out: ScanFindings = []
    parsed = urllib.parse.urlparse(base)
    ws_paths = ["/ws", "/websocket", "/socket", "/socket.io/", "/chat",
                "/realtime", "/live", "/stream", "/events", "/notifications", "/hub"]
    found_urls: List[str] = []
    for path in ws_paths:
        u = parsed.scheme + "://" + parsed.netloc + path
        c, hdrs, _, _ = _req(u, timeout=4.0)
        if c == 101 or hdrs.get("upgrade", "").lower() == "websocket":
            found_urls.append(u)
    _, _, html, _ = _req(base)
    for m in re.finditer(r'["\']((wss-|https-)://[^"\'<>\s]{4,120})["\']',
                         html.decode("utf-8", "ignore"), re.I):
        candidate = m.group(1)
        if "ws" in candidate.lower():
            found_urls.append(candidate)
    for ws_url in list(dict.fromkeys(found_urls))[:5]:
        c2, h2, _, _ = _req(ws_url, headers={
            "Upgrade": "websocket",
            "Connection": "Upgrade",
            "Sec-WebSocket-Version": "13",
            "Sec-WebSocket-Key": base64.b64encode(os.urandom(16)).decode(),
            "Origin": "https://evil.example.com",
        }, timeout=4.0)
        acao = h2.get("access-control-allow-origin", "")
        origin_ok = h2.get("sec-websocket-accept", "")
        if c2 == 101 or origin_ok:
            if acao in ("*",) or "evil.example.com" in acao or not acao:
                out.append(("cross-site WebSocket hijacking (CSWSH): upgrade accepted from evil origin", ws_url))
            else:
                out.append(("WebSocket endpoint found: Origin restriction present (manual verify)", ws_url))
    return out


def scan_redos(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = _extract_params(url) or ["q", "search", "query", "input", "term", "name", "email", "pattern"]
    long_payloads = [
        "a" * 50 + "!",
        ("a" * 10 + "@") * 5,
        "a" * 30 + "b" + "a" * 30,
        "x" * 80,
        "(" * 15 + "a" + ")" * 15,
    ]
    for param in params[:4]:
        _, _, _, _, dt_base = _req_with_time(_inject_param(url, param, "test"))
        for pay in long_payloads:
            _, _, _, _, dt = _req_with_time(_inject_param(url, param, pay))
            if dt > dt_base + 3.0 and dt > 4.0:
                out.append(("possible ReDoS: %.1fs delay vs baseline %.1fs on param %s" % (dt, dt_base, param),
                            pay[:60]))
                break
    return out

def scan_content_type_confusion(url: str) -> ScanFindings:
    out: ScanFindings = []
    c0, _, b0, _ = _req(url)
    if c0 == 0:
        return out
    probes: List[Tuple[str, str]] = [
        ('{"__proto__":{"polluted":"yes"}}',   "application/json"),
        ('<root><test>1</test></root>',         "application/xml"),
        ('{"test":"value"}',                    "text/plain"),
        ('[1,2,3]',                             "application/json"),
        ('test=1&other=2',                      "application/json"),
    ]
    for body_str, ct in probes:
        c1, h1, b1, _ = _req(url, method="POST", data=body_str.encode(), content_type=ct)
        if c1 in (0, 400, 415):
            continue
        resp_ct = h1.get("content-type", "")
        if c1 == 200 and "json" in ct and "xml" in resp_ct:
            out.append(("content-type confusion: JSON body accepted, XML response returned", ct + " -> " + resp_ct))
        elif c1 == 200 and abs(len(b1) - len(b0)) > 150:
            out.append(("content-type confusion: unexpected body differential for " + ct,
                        "POST status=" + str(c1) + " body_delta=" + str(abs(len(b1) - len(b0)))))
    return out

def scan_xssi(url: str) -> ScanFindings:
    out: ScanFindings = []
    parsed = urllib.parse.urlparse(url)
    json_paths = [
        "/api/user", "/api/me", "/api/profile", "/user/info",
        "/account", "/api/data", "/data.json",
    ]
    candidates = [url] + [parsed.scheme + "://" + parsed.netloc + p for p in json_paths]
    for probe_url in candidates[:7]:
        c, hdrs, body, _ = _req(probe_url)
        if c != 200 or not body:
            continue
        ct = hdrs.get("content-type", "")
        text = body.decode("utf-8", "ignore").strip()
        if "json" not in ct.lower() and not (text.startswith("[") or text.startswith("{")):
            continue
        is_array = text.startswith("[")
        has_prefix = text.startswith(")]}'") or text.startswith("//") or text.startswith("/*")
        acao = hdrs.get("access-control-allow-origin", "")
        if is_array and not has_prefix and not acao:
            out.append(("XSSI: JSON array response includable cross-origin (no anti-hijacking prefix)", probe_url))
        if acao == "*" and not has_prefix and "json" in ct.lower():
            out.append(("XSSI: JSON endpoint exposes wildcard CORS with no prefix -- data readable cross-origin", probe_url))
    return out

def scan_reflected_file_download(url: str) -> ScanFindings:
    out: ScanFindings = []
    parsed = urllib.parse.urlparse(url)
    for ext in (".bat", ".cmd", ".ps1"):
        probe = f"{parsed.scheme}://{parsed.netloc}{parsed.path}" + ext
        if parsed.query:
            probe += "?" + parsed.query
        c, hdrs, _, _ = _req(probe)
        cd = hdrs.get("content-disposition", "")
        if c == 200 and "attachment" in cd.lower():
            m = re.search(r'filename=["\']?([^"\';\s]+)', cd, re.I)
            fn = m.group(1) if m else ""
            if ext in fn.lower():
                out.append(("reflected file download: server echoes attacker-controlled extension in filename", probe))
                break
    params = _extract_params(url)
    rfd_params = [p for p in params if re.search(r"callback|jsonp|download|file|name|export", p, re.I)]
    for param in rfd_params[:4]:
        for payload in ["evil.bat", "file.cmd", "payload.ps1"]:
            probe = _inject_param(url, param, payload)
            c, hdrs, _, _ = _req(probe)
            cd = hdrs.get("content-disposition", "")
            if "attachment" in cd.lower() and any(e in cd.lower() for e in (".bat", ".cmd", ".ps1")):
                out.append(("possible RFD: Content-Disposition filename controlled by param " + param, probe))
                break
    return out

def scan_null_byte(url: str) -> ScanFindings:
    out: ScanFindings = []
