def scan_zd_jenkins_cli_read(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, hdrs, b, _ = _req(_join_url(base, "/login"))
    jenkins_ver = hdrs.get("x-jenkins", "") or hdrs.get("x-hudson", "")
    if not jenkins_ver and c == 200:
        text = b.decode("utf-8", "ignore")
        if "jenkins" not in text.lower() and "hudson" not in text.lower():
            return out
        ver_m = re.search(r'Jenkins\s+ver\.\s+([0-9.]+)', text, re.I)
        jenkins_ver = ver_m.group(1) if ver_m else ""
    if not jenkins_ver and c not in (200, 302, 403):
        return out
    c2, _, _, _ = _req(_join_url(base, "/cli"))
    if c2 == 200:
        out.append(("Jenkins CLI endpoint accessible", "/cli"))
    if jenkins_ver:
        try:
            parts = [int(x) for x in jenkins_ver.split(".")[:2]]
            vuln = parts[0] < 2 or (parts[0] == 2 and len(parts) > 1 and parts[1] < 442)
            if vuln:
                out.append(("[CONFIRMED] Jenkins version " + jenkins_ver + " vulnerable to CVE-2024-23897 (arbitrary file read via CLI, CVSS 9.8)", jenkins_ver))
                return out
        except Exception:
            pass
        out.append(("Jenkins server detected (CVE-2024-23897 CVSS 9.8): verify version >= 2.442",
                    "X-Jenkins: " + jenkins_ver))
    else:
        out.append(("Jenkins instance detected (CVE-2024-23897 CVSS 9.8): verify patch level", base))
    return out

def scan_zd_php_cgi_argv(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, hdrs, b, _ = _req(base, use_cache=True)
    powered = hdrs.get("x-powered-by", "").lower()
    server = hdrs.get("server", "").lower()
    is_php = "php" in powered or "php" in server
    probe_url = base.rstrip("/") + "/--s"
    c2, _, b2, _ = _req(probe_url)
    if c2 == 200 and b2:
        text2 = b2.decode("utf-8", "ignore")
        if "<?php" in text2 or "<?=" in text2 or "<?" in text2[:200]:
            out.append(("[CONFIRMED] PHP-CGI source disclosure probe succeeded (CVE-2024-4577 surface, CVSS 9.8)",
                        "probe: /--s"))
            return out
    ver_url = base.rstrip("/") + "/--v"
    c3, _, b3, _ = _req(ver_url)
    if c3 == 200 and b3:
        text3 = b3.decode("utf-8", "ignore")
        if "PHP" in text3 and "cgi" in text3.lower():
            ver_m = re.search(r"PHP (\d+\.\d+\.\d+)", text3)
            if ver_m:
                ver = ver_m.group(1)
                out.append(("[CONFIRMED] PHP-CGI version " + ver + " detected (CVE-2024-4577 CVSS 9.8): verify patched",
                            "probe: /--v"))
    if is_php and not out:
        out.append(("PHP detected (CVE-2024-4577 PHP-CGI argv injection CVSS 9.8): verify CGI mode + patch",
                    "X-Powered-By: " + hdrs.get("x-powered-by", "")))
    return out

def scan_zd_openssh_regression(base: str) -> ScanFindings:
    out: ScanFindings = []
    host = urllib.parse.urlparse(base).hostname or ""
    if not host:
        return out
    try:
        s = socket.create_connection((host, 22), timeout=3)
        banner = b""
        try:
            banner = s.recv(256)
        except Exception:
            pass
        s.close()
        banner_str = banner.decode("utf-8", "ignore").strip()
        if "openssh" not in banner_str.lower():
            return out
        ver_m = re.search(r"OpenSSH[_\s](\d+)\.(\d+)", banner_str, re.I)
        if not ver_m:
            out.append(("OpenSSH detected on port 22 (CVE-2024-6387 regreSSHion CVSS 8.1): verify version",
                        "banner: " + banner_str[:80]))
            return out
        major, minor = int(ver_m.group(1)), int(ver_m.group(2))
        vuln = (major == 8 and minor >= 5) or (major == 9 and minor <= 7) or (major < 4) or (major == 4 and minor < 4)
        ver = str(major) + "." + str(minor)
        if vuln:
            out.append(("[CONFIRMED] OpenSSH " + ver + " is in vulnerable range for CVE-2024-6387 (race condition RCE as root, CVSS 8.1)",
                        "banner: " + banner_str[:80]))
        else:
            out.append(("OpenSSH version " + ver + " detected on port 22 (CVE-2024-6387 regreSSHion): verify patch",
                        "banner: " + banner_str[:80]))
    except Exception:
        pass
    return out

def scan_zd_confluence_ssti(base: str) -> ScanFindings:
    out: ScanFindings = []
    for path in ["/wiki/login.action", "/login.action", "/wiki/"]:
        url = _join_url(base, path)
        c, hdrs, b, _ = _req(url)
        if c not in (200, 302, 303, 301):
            continue
        text = b.decode("utf-8", "ignore")
        if "confluence" not in text.lower() and "atlassian" not in text.lower():
            continue
        ver = hdrs.get("x-confluence-version", "")
        if not ver:
            ver_m = re.search(r'ajs-version-number"\s+content="([^"]+)"', text)
            ver = ver_m.group(1) if ver_m else ""
        vm_c, _, _, _ = _req(_join_url(base, "/template/aui/text-inline.vm"))
        if vm_c not in (404, 410):
            out.append(("Confluence template path accessible (/template/aui/text-inline.vm) - CVE-2023-22527 surface",
                        "HTTP " + str(vm_c)))
        if ver:
            try:
                parts = [int(x) for x in ver.split(".")[:3]]
                while len(parts) < 3:
                    parts.append(0)
                vuln = tuple(parts) < (8, 5, 4)
                if vuln:
                    out.append(("[CONFIRMED] Confluence version " + ver + " vulnerable to CVE-2023-22527 (SSTI CVSS 10.0)",
                                ver))
                    return out
            except Exception:
                pass
        out.append(("Confluence instance detected (CVE-2023-22527 CVSS 10.0): verify patched to 8.5.4+/7.19.18+",
                    "path: " + path))
        return out
    return out

