            vuln = (tuple(parts) < (16, 5, 6) or
                    (parts[0] == 16 and parts[1] == 6 and parts[2] < 4) or
                    (parts[0] == 16 and parts[1] == 7 and parts[2] < 2))
            if vuln:
                out.append(("[CONFIRMED] GitLab version " + ver +
                            " vulnerable to CVE-2023-7028 (account takeover via password reset CVSS 10.0)",
                            "version: " + ver))
                return out
            out.append(("GitLab version " + ver + " detected "
                        "(CVE-2023-7028 account takeover CVSS 10.0): verify patched to 16.7.2+ / 16.6.4+ / 16.5.6+",
                        "version: " + ver))
