def scan_zd_sap_netweaver_vc_upload(base: str) -> ScanFindings:
    out: ScanFindings = []
    is_sap = False
    sap_ver = ""

    for path in ["/irj/portal", "/webdynpro/dispatcher/", "/sap/public/ping",
                 "/sap/bc/gui/sap/its/webgui/", "/sap/public/bc/its/mimes/", "/"]:
        c, hdrs, b, _ = _req(_join_url(base, path), use_cache=(path == "/"))
        text = b.decode("utf-8", "ignore")
        hdr_str = " ".join(hdrs.values()).lower()
        if ("sap netweaver" in text.lower() or
                "sap portal" in text.lower() or
                "webdynpro" in text.lower() or
                "sap_sessionid" in hdr_str or
                any(h.lower().startswith("x-sap") for h in hdrs) or
                ("sap" in hdrs.get("server", "").lower()) or
                ("/irj/" in text and "sap" in text.lower())):
            is_sap = True
            vm = re.search(r'[Ss][Aa][Pp]\s+[Nn]et[Ww]eaver[^0-9]*([\d]+\.[\d]+(?:\s*SP[\d]+)?)', text)
            if vm:
                sap_ver = vm.group(1).strip()
            break

    if not is_sap:
        c2, hdrs2, b2, _ = _req(_join_url(base, "/developmentserver/metadatauploader"))
        text2 = b2.decode("utf-8", "ignore")
        if c2 not in (404, 0) and any(k in text2.lower() for k in ("sap", "netweaver", "visual composer", "metadata")):
            is_sap = True

    if not is_sap:
        return out

    c_vc, hdrs_vc, b_vc, _ = _req(_join_url(base, "/developmentserver/metadatauploader"))
    text_vc = b_vc.decode("utf-8", "ignore")

    if c_vc == 200 and len(b_vc) > 0:
        boundary = "----ScannerProbe" + hashlib.md5(base.encode()).hexdigest()[:12]
        body = (
            "--" + boundary + "\r\n"
            "Content-Disposition: form-data; name=\"upfile\"; filename=\"probe.txt\"\r\n"
            "Content-Type: text/plain\r\n\r\n"
            "PROBE\r\n"
            "--" + boundary + "--\r\n"
        ).encode()
        c_up, _, b_up, _ = _req(
            _join_url(base, "/developmentserver/metadatauploader"),
            method="POST",
            data=body,
            content_type="multipart/form-data; boundary=" + boundary,
        )
        text_up = b_up.decode("utf-8", "ignore")
        if c_up in (200, 201) and any(k in text_up.lower() for k in
                                       ("success", "upload", "file", "ok", "stored", "saved")):
            out.append((
                "[CONFIRMED] SAP NetWeaver Visual Composer metadatauploader accepted unauthenticated file upload "
                "(CVE-2025-31324 CVSS 10.0)" + (" version " + sap_ver if sap_ver else "") +
                ": apply SAP Note 3594142 and disable Visual Composer immediately",
                "/developmentserver/metadatauploader",
            ))
            return out
        if c_up not in (401, 403, 0):
            out.append((
                "[CONFIRMED] SAP NetWeaver /developmentserver/metadatauploader reachable unauthenticated "
                "(CVE-2025-31324 CVSS 10.0)" + (" version " + sap_ver if sap_ver else "") +
                ": endpoint present without auth challenge - apply SAP Note 3594142 immediately",
                "/developmentserver/metadatauploader",
            ))
            return out

    if c_vc in (401, 403):
        pass
    elif c_vc not in (404, 0):
        out.append((
            "[CONFIRMED] SAP NetWeaver Visual Composer metadatauploader endpoint accessible "
            "(CVE-2025-31324 unauth file upload RCE CVSS 10.0)" + (" version " + sap_ver if sap_ver else "") +
            ": verify authentication enforcement and apply SAP Note 3594142",
            "/developmentserver/metadatauploader",
        ))
        return out

    if sap_ver:
        out.append((
            "SAP NetWeaver " + sap_ver + " detected (CVE-2025-31324 Visual Composer unauth RCE CVSS 10.0): "
            "verify SAP Note 3594142 applied and Visual Composer disabled if unused",
            "version: " + sap_ver,
        ))
    else:
        out.append((
            "SAP NetWeaver portal detected (CVE-2025-31324 Visual Composer unauth file upload RCE CVSS 10.0): "
            "verify SAP Note 3594142 applied",
            base,
        ))
    return out

def scan_coop_coep_corp(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, hdrs, _, _ = _req(base, use_cache=True)
    if c == 0:
        return out
    coop = hdrs.get("cross-origin-opener-policy", "")
    coep = hdrs.get("cross-origin-embedder-policy", "")
    corp = hdrs.get("cross-origin-resource-policy", "")
    if not coop:
        out.append(("Cross-Origin-Opener-Policy header missing", ""))
    elif coop.lower() not in ("same-origin", "same-origin-allow-popups"):
        out.append(("Cross-Origin-Opener-Policy overly permissive: " + coop, coop))
    if not coep:
        out.append(("Cross-Origin-Embedder-Policy header missing", ""))
    elif coep.lower() not in ("require-corp", "credentialless"):
        out.append(("Cross-Origin-Embedder-Policy overly permissive: " + coep, coep))
    if not corp:
        out.append(("Cross-Origin-Resource-Policy header missing", ""))
    elif corp.lower() not in ("same-origin", "same-site"):
        out.append(("Cross-Origin-Resource-Policy overly permissive: " + corp, corp))
    return out

def scan_document_policy(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, hdrs, _, _ = _req(base, use_cache=True)
    if c == 0:
        return out
    dp  = hdrs.get("document-policy", "")
    oac = hdrs.get("origin-agent-cluster", "")
    if not dp:
        out.append(("Document-Policy header missing", ""))
    if not oac:
        out.append(("Origin-Agent-Cluster header missing (no process key isolation)", ""))
    elif oac.strip() == "?0":
        out.append(("Origin-Agent-Cluster: -0 opts out of isolation", oac))
    return out

