def scan_zd_erlang_otp_ssh_cve_2025_32433(base: str) -> ScanFindings:
    out: ScanFindings = []
    host = urllib.parse.urlparse(base).hostname or ""
    if not host:
        return out
    is_erlang_ssh = False
    banner_ver = ""
    for port in (22, 2222, 2223, 4369):
        try:
            with socket.create_connection((host, port), timeout=4) as s:
                banner = s.recv(256).decode("utf-8", "ignore").strip()
                if "erlang" in banner.lower() or "erts" in banner.lower() or "otp" in banner.lower():
                    is_erlang_ssh = True
                    m = re.search(r'OTP[_\s-]?([0-9]+\.[0-9]+(?:\.[0-9]+)?)', banner, re.I)
                    if m:
                        banner_ver = m.group(1)
                    out.append(("[CONFIRMED] Erlang/OTP SSH banner detected on port %d (CVE-2025-32433 pre-auth RCE CVSS 10.0, KEV 2025-04-28)"
                                ": upgrade OTP to 27.3.3+/26.2.5.11+/25.3.2.21+" % port,
                                "port=%d banner=%s" % (port, banner[:80])))
                    break
                elif "ssh" in banner.lower():
                    m_ver = re.search(r'SSH-2\.0-([A-Za-z_]+)[_\s/]([0-9.]+)', banner)
                    if m_ver and "erlang" in m_ver.group(1).lower():
                        is_erlang_ssh = True
                        banner_ver = m_ver.group(2)
                        out.append(("[CONFIRMED] Erlang SSH identified on port %d (CVE-2025-32433 CVSS 10.0, KEV 2025-04-28)"
                                    ": upgrade OTP to 27.3.3+/26.2.5.11+" % port,
                                    "banner=%s" % banner[:80]))
                        break
        except Exception:
            pass
    if not is_erlang_ssh:
        for path in ["/", "/api", "/management", "/console"]:
            c, hdrs, b, _ = _req(_join_url(base, path))
            text = b.decode("utf-8", "ignore")
            if any(k in text.lower() for k in ("rabbitmq", "couchdb", "erlang", "beam", "emqx")):
                out.append(("Erlang-based service detected (CVE-2025-32433 OTP SSH pre-auth RCE CVSS 10.0, KEV 2025-04-28)"
                            ": verify OTP version >= 27.3.3/26.2.5.11/25.3.2.21",
                            path))
                break
    return out

