        out.append(("ProjectSend%s detected - CVE-2024-11680 CVSS 9.8 unauthenticated file upload allows "
                    "webshell / RCE; CVE-2024-11079 second vuln; upgrade to r1750+" % (
                        " " + ps_ver if ps_ver else ""), "/upload.php"))
