def scan_xff_ip_bypass(url: str) -> ScanFindings:
    import urllib.parse as _up
    out: ScanFindings = []
    p = _up.urlparse(url)
    base = "%s://%s" % (p.scheme, p.netloc)
    target_url = url
    st0, _, _, _ = _req(target_url)
    if st0 not in (401, 403, 429, 451):
        for apath in ["/admin", "/internal", "/management", "/actuator", "/debug", "/server-status"]:
            probe = _up.urlunparse((p.scheme, p.netloc, apath, "", "", ""))
            st_a, _, _, _ = _req(probe)
            if st_a in (401, 403):
                target_url = probe
                st0 = st_a
                break
        else:
            return out
    _BYPASS_HEADERS = [
        "X-Forwarded-For", "X-Real-IP", "X-Originating-IP",
        "X-Remote-Addr", "X-Client-IP", "True-Client-IP",
        "CF-Connecting-IP", "Forwarded", "X-Forwarded-Host",
        "X-Cluster-Client-IP", "X-ProxyUser-Ip",
    ]
    _BYPASS_IPS = ["127.0.0.1", "::1", "localhost", "10.0.0.1", "192.168.1.1", "172.16.0.1"]
    for header in _BYPASS_HEADERS:
        for ip in _BYPASS_IPS:
            val = ("for=%s" % ip) if header == "Forwarded" else ip
            st1, _, body1, _ = _req(target_url, extra_headers={header: val})
            if st1 in (200, 201, 202) and st0 in (401, 403, 429):
                out.append((
                    "[CONFIRMED] IP restriction bypass via %s header at %s" % (header, target_url),
                    "%s: %s changed response HTTP %d -> %d - server trusts client-supplied IP header for access control; attacker spoofs internal IP to reach admin/restricted endpoints"
                    % (header, ip, st0, st1),
                    "CRIT",
                ))
                return out
            if st1 == 302 and st0 == 403:
                out.append((
                    "[PROBABLE] Partial IP bypass redirect via %s at %s" % (header, target_url),
                    "%s: %s returned 302 vs baseline 403 - possible partial bypass; follow redirect chain"
                    % (header, ip),
                    "HIGH",
                ))
    return out


def scan_backup_file_discovery(url: str) -> ScanFindings:
    import urllib.parse as _up
    out: ScanFindings = []
    p = _up.urlparse(url)
    path = p.path or "/"
    segments = path.rstrip("/").split("/")
    last = segments[-1] if segments else ""
    base_dir = "/".join(segments[:-1]) or "/"
    candidates: list = []
    if "." in last:
        stem, ext = last.rsplit(".", 1)
        for suf in [".bak", ".old", ".orig", ".backup", ".tmp", ".copy", "~", ".swp", ".gz", ".zip"]:
            candidates.append(base_dir + "/" + last + suf)
            candidates.append(base_dir + "/" + stem + suf)
        candidates.append(base_dir + "/" + stem + "." + ext + ".bak")
    else:
        for suf in [".bak", ".old", ".backup", "~", ".tmp", ".zip"]:
            candidates.append(path.rstrip("/") + suf)
    _COMMON = [
        "/backup.sql", "/dump.sql", "/database.sql", "/db.sql", "/db_backup.sql",
        "/backup.zip", "/backup.tar.gz", "/site.tar.gz", "/www.zip", "/html.zip",
        "/.htpasswd", "/.htaccess.bak", "/config.php.bak", "/config.bak",
        "/settings.bak", "/web.config.bak", "/wp-config.php.bak", "/wp-config.php.old",
        "/secrets.yml", "/database.yml", "/credentials.yml", "/config.yml.bak",
        "/application.properties.bak", "/application.yml.bak",
    ]
    candidates.extend(_COMMON)
    for ep in list(_DISCOVERED_ENDPOINTS)[:25]:
        ep_path = _up.urlparse(ep).path
        ep_last = ep_path.split("/")[-1]
        if "." in ep_last:
            ep_stem = ep_last.rsplit(".", 1)[0]
            ep_dir = ep_path.rsplit("/", 1)[0]
            for suf in [".bak", ".old", "~"]:
                candidates.append(ep_path + suf)
                candidates.append(ep_dir + "/" + ep_stem + suf)
    seen: set = set()
    for cpath in candidates:
        if cpath in seen:
            continue
        seen.add(cpath)
        probe = _up.urlunparse((p.scheme, p.netloc, cpath, "", "", ""))
        st, hdrs, body, _ = _req(probe)
        if st != 200 or not body or len(body) < 50:
            continue
        ct = hdrs.get("content-type", "").lower()
        body_head = body[:300].decode("utf-8", errors="replace")
        if "html" in ct and "<html" in body_head.lower():
            continue
        severity = "HIGH"
        label = "backup file"
        lc = cpath.lower()
        if any(k in lc for k in [".sql", "dump", "database", "db.", "db_"]):
            severity, label = "CRIT", "database dump"
        elif any(k in lc for k in [".zip", ".tar", ".gz"]):
            severity, label = "CRIT", "archive"
        elif any(k in lc for k in ["config", "secret", "credential", "htpasswd", "password"]):
            severity, label = "CRIT", "config/credential backup"
        out.append((
            "[EXPOSED] %s at %s" % (label, probe),
            "HTTP 200, %dB - %s publicly accessible without authentication; may contain source code, database credentials, private keys, or full application state"
            % (len(body), label),
            severity,
        ))
    return out


def scan_git_exposure(url: str) -> ScanFindings:
    import urllib.parse as _up
    out: ScanFindings = []
    p = _up.urlparse(url)
    base = "%s://%s" % (p.scheme, p.netloc)
    _GIT_PATHS = [
        "/.git/HEAD", "/.git/config", "/.git/COMMIT_EDITMSG",
        "/.git/description", "/.git/packed-refs",
        "/.git/refs/heads/master", "/.git/refs/heads/main",
        "/.git/logs/HEAD", "/.git/index", "/.gitignore", "/.gitmodules",
        "/.git/ORIG_HEAD", "/.git/MERGE_HEAD",
    ]
    _HEAD_RE = re.compile(r'^ref:\s+refs/heads/\S+', re.M)
    _CONFIG_RE = re.compile(r'\[core\]|\[remote\s|url\s*=\s*\S+', re.I)
    _COMMIT_RE = re.compile(r'^[a-f0-9]{40}', re.M)
    _IGNORE_RE = re.compile(r'^(?:\*\.|#|!|\s*/)', re.M)
    confirmed = False
    for gpath in _GIT_PATHS:
        probe = base + gpath
        st, hdrs, body, _ = _req(probe)
        if st != 200 or not body:
            continue
        body_text = body.decode("utf-8", errors="replace")
        ct = hdrs.get("content-type", "").lower()
        if "html" in ct and "<html" in body_text.lower() and not confirmed:
            continue
        if (_HEAD_RE.search(body_text) or _CONFIG_RE.search(body_text)
                or _COMMIT_RE.search(body_text) or _IGNORE_RE.search(body_text)):
            severity = "CRIT" if "config" in gpath or "index" in gpath else "HIGH"
            out.append((
                "[EXPOSED] Git repository artifact at %s" % probe,
                "HTTP 200, %dB - %s publicly readable; attacker can reconstruct full source code history by walking object graph ('.git/objects/') or using tools like 'git-dumper'"
                % (len(body), gpath),
                severity,
            ))
            confirmed = True
        elif st == 200 and 10 < len(body) < 5000 and "<html" not in body_text.lower():
            out.append((
                "[PROBABLE] Possible git artifact at %s" % probe,
                "HTTP 200, %dB non-HTML response at git path - partial git exposure; manual verification recommended"
                % len(body),
                "MED",
            ))
    return out


def scan_env_file_exposure(url: str) -> ScanFindings:
    import urllib.parse as _up
    out: ScanFindings = []
