def scan_integer_overflow(url: str) -> ScanFindings:
    out: ScanFindings = []
    params = list(_extract_params(url))
    if not params:
        return out
    _EDGE_VALUES = [
        ("2147483647",              "INT32_MAX"),
        ("2147483648",              "INT32_MAX+1"),
        ("-2147483648",             "INT32_MIN"),
        ("-2147483649",             "INT32_MIN-1"),
        ("9223372036854775807",     "INT64_MAX"),
        ("9223372036854775808",     "INT64_MAX+1"),
        ("-1",                      "negative one"),
        ("-99999",                  "large negative"),
        ("0",                       "zero"),
        ("99999999999999999999999", "arbitrary large"),
        ("1e308",                   "float overflow"),
        ("NaN",                     "NaN"),
        ("Infinity",                "Infinity"),
    ]
    _OVERFLOW_RE = re.compile(
        r'(?:overflow|out of range|integer.*invalid|value too large'
        r'|BIGINT.*range|numeric.*field.*overflow|OverflowError'
        r'|ArithmeticException|NumberFormatException|integer overflow)',
        re.I,
    )
    _BIZLOGIC_RE = re.compile(r'(?:\bfree\b|complimentary|unlimited|premium|\$0\.00|-\$[0-9])', re.I)
    st0, _, body0, _ = _req(url)
    body0_text = (body0 or b"").decode("utf-8", errors="replace")
    for param in params[:5]:
        for val, label in _EDGE_VALUES:
            probe_url = _inject_param(url, param, val)
            st1, _, body1, _ = _req(probe_url)
            body1_text = (body1 or b"").decode("utf-8", errors="replace")
            if _OVERFLOW_RE.search(body1_text) and not _OVERFLOW_RE.search(body0_text):
                out.append((
                    "[CONFIRMED] Integer overflow error on param '%s' value %s at %s" % (param, label, url),
                    "Value '%s' (%s) triggered: '%s' - numeric input is not bounds-checked before processing; may enable price manipulation, quantity abuse, or application DoS"
                    % (val, label, _OVERFLOW_RE.search(body1_text).group(0)[:80]),
                    "HIGH",
                ))
                break
            if _BIZLOGIC_RE.search(body1_text) and not _BIZLOGIC_RE.search(body0_text):
                out.append((
                    "[CONFIRMED] Business logic bypass via integer edge case on '%s' at %s" % (param, url),
                    "Value '%s' (%s) triggered unexpected response indicator: '%s' - price/quantity manipulation via integer boundary condition"
                    % (val, label, _BIZLOGIC_RE.search(body1_text).group(0)[:60]),
                    "CRIT",
                ))
                break
            if st1 == 500 and st0 != 500:
                out.append((
                    "[PROBABLE] Server crash on integer edge case '%s' on param '%s' at %s" % (label, param, url),
                    "Value '%s' caused HTTP 500 - unhandled numeric boundary condition; may indicate deeper type confusion or missing input validation"
                    % val,
                    "MED",
                ))
    return out


def scan_dom_secrets(url: str) -> ScanFindings:
    import urllib.parse as _up
    out: ScanFindings = []
    p = _up.urlparse(url)
    base = "%s://%s" % (p.scheme, p.netloc)
    st0, hdrs0, body0, _ = _req(url)
    if not body0:
        return out
    body_text = body0.decode("utf-8", errors="replace")
    _JS_SRC_RE = re.compile(r'<script[^>]*\bsrc=["\']([^"\']+\.js[^"\']*)["\']', re.I)
    js_urls: list = []
    for src in _JS_SRC_RE.findall(body_text)[:12]:
        if src.startswith("http"):
            js_urls.append(src)
        elif src.startswith("//"):
            js_urls.append(p.scheme + ":" + src)
        elif src.startswith("/"):
            js_urls.append(base + src)
    _PATTERNS = [
        (re.compile(r'(?:api[_-]?key|apikey)\s*[=:]\s*["\']([A-Za-z0-9\-_]{20,})["\']', re.I),
         "API key", "CRIT"),
        (re.compile(r'(?:secret|private[_-]?key)\s*[=:]\s*["\']([A-Za-z0-9\-_/+=]{20,})["\']', re.I),
         "secret/private key", "CRIT"),
        (re.compile(r'(?:password|passwd)\s*[=:]\s*["\']([^\'"]{8,})["\']', re.I),
         "hardcoded password", "CRIT"),
        (re.compile(r'(AKIA[0-9A-Z]{16})', re.I),
         "AWS access key ID", "CRIT"),
        (re.compile(r'(sk_(?:live|test)_[A-Za-z0-9]{24,})',),
         "Stripe secret key", "CRIT"),
        (re.compile(r'(?:bearer|Authorization)\s*[=:]\s*["\']([A-Za-z0-9\-_.]{32,})["\']', re.I),
         "hardcoded auth token", "CRIT"),
        (re.compile(r'(xox[bpars]\-[0-9A-Za-z\-]{16,})',),
         "Slack token", "HIGH"),
        (re.compile(r'(AIza[0-9A-Za-z\-_]{35})',),
         "Google API key", "HIGH"),
        (re.compile(r'(?:jwt[_-]?secret|jwt[_-]?key)\s*[=:]\s*["\']([^\'"]{8,})["\']', re.I),
         "JWT secret", "CRIT"),
        (re.compile(r'(?:github[_-]?token|GH_TOKEN)\s*[=:]\s*["\']?([a-z0-9_]{36,})', re.I),
         "GitHub token", "CRIT"),
        (re.compile(r'(github_pat_[A-Za-z0-9_]{20,})'),
         "GitHub fine-grained token", "CRIT"),
        (re.compile(r'(gh[pousr]_[A-Za-z0-9_]{20,})'),
         "GitHub token", "CRIT"),
        (re.compile(r'(xox[baprs]-[A-Za-z0-9-]{20,})'),
         "Slack token", "CRIT"),
        (re.compile(r'(SG\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,})'),
         "SendGrid API key", "CRIT"),
        (re.compile(r'((?:postgres|mysql|mongodb(?:\+srv)?|redis)://[^\'"\s<]{8,180})', re.I),
         "database connection string", "CRIT"),
        (re.compile(r'(?:internal|debug|admin)[_-]?(?:url|endpoint|host)\s*[=:]\s*["\']([^\'"]{10,})["\']', re.I),
         "internal endpoint URL", "MED"),
        (re.compile(r'(?:private[_-]?key|-----BEGIN (?:RSA |EC )?PRIVATE KEY-----)',),
         "PEM private key", "CRIT"),
    ]
    sources: list = [(url, body_text)]
    for js_url in js_urls[:10]:
        _, _, js_body, _ = _req(js_url)
        if js_body:
            sources.append((js_url, js_body.decode("utf-8", errors="replace")))
    seen: set = set()
    for src_url, src_text in sources:
        for pattern, label, severity in _PATTERNS:
            for m in pattern.finditer(src_text):
                val = m.group(1) if m.lastindex and m.lastindex >= 1 else m.group(0)
                key = (label, val[:16])
                if key in seen:
                    continue
                seen.add(key)
                out.append((
                    "[EXPOSED] %s in client-side code at %s" % (label, src_url),
                    "Pattern matched: '%s' - hardcoded secret in JavaScript/HTML is readable by any visitor; rotate immediately and audit git history for prior exposure"
                    % m.group(0)[:120],
                    severity,
                ))
        for m in re.finditer(r'["\']([A-Za-z0-9_\-+/=]{32,160})["\']', src_text[:500000]):
            candidate = m.group(1)
            if len(set(candidate)) < 12:
                continue
            ent = _entropy(candidate)
            if ent >= 4.2 and not re.fullmatch(r"[0-9a-fA-F]{32,64}", candidate):
                key = ("entropy", candidate[:16])
                if key in seen:
                    continue
                seen.add(key)
                out.append((
                    "high-entropy client string may be a secret",
                    "source=%s entropy=%.2f sample=%s..." % (src_url, ent, candidate[:16]),
                    "HIGH",
                ))
    p = urllib.parse.urlparse(url)
    origin = p.scheme + "://" + p.netloc
    workflow_paths = ["/cart", "/checkout", "/api/cart", "/api/checkout", "/coupon", "/redeem", "/transfer", "/api/transfer"]
    for path in workflow_paths:
        target = origin + path
        body = urllib.parse.urlencode({"price": "0", "amount": "-1", "quantity": "-1", "discount": "100", "role": "admin"}).encode()
        c, _, b, _ = _req(target, method="POST", data=body, content_type="application/x-www-form-urlencoded", timeout=6)
        tl = b[:8000].decode("utf-8", "ignore")
        if c in (200, 201, 202) and success_re.search(tl) and not re.search(r"invalid|error|denied|forbidden", tl, re.I):
            out.append(("[CONFIRMED] business workflow boundary payload accepted", "endpoint=%s status=%d body=price=0&amount=-1&quantity=-1&discount=100" % (target, c)))
    return out[:40]

def scan_client_storage_exposure(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, _, b, _ = _req(base, use_cache=True)
    if c == 0 or not b:
        return out
    html = b.decode("utf-8", "ignore")
    parsed = urllib.parse.urlparse(base)
    origin = parsed.scheme + "://" + parsed.netloc
    sources: List[Tuple[str, str]] = [(base, html)]
    js_urls: List[str] = []
    for src in re.findall(r'<script[^>]+src=["\']([^"\']+\.js(?:\?[^"\']*)?)["\']', html, re.I):
        full = urllib.parse.urljoin(base, src)
        sp = urllib.parse.urlparse(full)
        if sp.scheme in ("http", "https") and sp.netloc == parsed.netloc and full not in js_urls:
            js_urls.append(full)
    for js_url in js_urls[:14]:
        jc, jh, jb, _ = _req(js_url, timeout=5)
        if jc != 200 or not jb:
            continue
        ct = jh.get("content-type", "").lower()
        if ct and not any(x in ct for x in ("javascript", "ecmascript", "text/plain", "application/octet-stream")):
            continue
        sources.append((js_url, jb[:260000].decode("utf-8", "ignore")))

    storage_call_re = re.compile(
        r'\b(localStorage|sessionStorage)\s*\.\s*setItem\s*\(\s*[\'"]([^\'"]{1,80})[\'"]|\b(localStorage|sessionStorage)\s*\[\s*[\'"]([^\'"]{1,80})[\'"]\s*\]',
        re.I,
    )
    indexeddb_re = re.compile(r'\bindexedDB\.open\s*\(\s*[\'"]([^\'"]{1,80})[\'"]', re.I)
    cookie_re = re.compile(r'document\.cookie\s*=\s*[`\'"]([^`\'"]{1,220})', re.I)
    secret_name_re = re.compile(r'(?i)(token|jwt|session|secret|password|passwd|refresh|access|api[_-]?key|auth|csrf)')
    wildcard_postmsg_re = re.compile(r'\.postMessage\s*\([^,]{1,500},\s*[\'"]\*[\'"]', re.I | re.S)
    seen: Set[str] = set()

    def _add(title: str, detail: str) -> None:
        key = title + "|" + detail[:100]
        if key not in seen:
            seen.add(key)
            out.append((title, detail))

    for src_url, code in sources:
        for sm in storage_call_re.finditer(code):
            storage = sm.group(1) or sm.group(3) or "storage"
            key = sm.group(2) or sm.group(4) or ""
            if secret_name_re.search(key):
                _add("[CONFIRMED] browser storage used for sensitive key", "source=%s storage=%s key=%s" % (src_url, storage, key[:80]))
        for db_name in indexeddb_re.findall(code):
            if secret_name_re.search(db_name):
                _add("IndexedDB database name suggests client-side secret storage", "source=%s db=%s" % (src_url, db_name[:80]))
        for cookie_value in cookie_re.findall(code):
            low = cookie_value.lower()
            if any(k in low for k in ("token", "jwt", "session", "auth", "csrf")):
                missing = [flag for flag in ("secure", "samesite", "path=") if flag not in low]
                if "httponly" not in low:
                    missing.append("httponly unavailable from JS")
                if missing:
                    _add("JavaScript sets sensitive cookie without full hardening", "source=%s missing=%s cookie=%s" % (src_url, ",".join(missing), cookie_value[:120]))
        if wildcard_postmsg_re.search(code) and secret_name_re.search(code):
            _add("postMessage wildcard target used near sensitive token terms", "source=%s targetOrigin=*" % src_url)
        for m in re.finditer(r'\b(?:Bearer\s+)?(?:eyJ[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{8,}|sk_(?:live|test)_[A-Za-z0-9]{20,}|AIza[0-9A-Za-z_-]{35}|AKIA[0-9A-Z]{16})', code):
            _add("[CONFIRMED] hardcoded credential-like value in client code", "source=%s sample=%s" % (src_url, m.group(0)[:80]))
    return out[:25]

def scan_well_known_trust_files(base: str) -> ScanFindings:
    out: ScanFindings = []
    paths = [
        "/.well-known/assetlinks.json",
        "/.well-known/apple-app-site-association",
        "/apple-app-site-association",
        "/.well-known/webfinger-resource=acct:admin@" + (urllib.parse.urlparse(base).hostname or "localhost"),
        "/.well-known/openid-configuration",
        "/.well-known/oauth-authorization-server",
        "/.well-known/mta-sts.txt",
        "/.well-known/change-password",
    ]
    sensitive_re = re.compile(r'(?i)(admin|internal|staging|dev|debug|localhost|127\.0\.0\.1|token|secret|private)')
    for path in paths:
        url = _join_url(base, path)
        c, h, b, _ = _req(url, timeout=5)
        if c in (0, 404, 410):
            continue
        text = b[:200000].decode("utf-8", "ignore")
        if path.endswith("assetlinks.json") and c == 200 and "delegate_permission/common.handle_all_urls" in text:
            out.append(("Android assetlinks delegates all URL handling", url))
            if text.count("sha256_cert_fingerprints") > 5:
                out.append(("Android assetlinks contains many certificate fingerprints", "url=%s count=%d" % (url, text.count("sha256_cert_fingerprints"))))
        elif "apple-app-site-association" in path and c == 200 and ("applinks" in text or "webcredentials" in text):
            out.append(("Apple app-site-association exposed", url))
            if re.search(r'"paths"\s*:\s*\[\s*"\*"', text) or re.search(r'"components"\s*:\s*\[\s*\{\s*"/"\s*:\s*"\*"', text):
                out.append(("Apple app-site-association uses wildcard path association", url))
            if "webcredentials" in text:
                out.append(("Apple webcredentials association exposed", url))
        elif "webfinger" in path and c == 200 and ("subject" in text or "links" in text):
            out.append(("WebFinger endpoint responds for admin account probe", url))
            if sensitive_re.search(text):
                out.append(("WebFinger response leaks sensitive-looking relation or endpoint", text[:160]))
        elif "openid-configuration" in path or "oauth-authorization-server" in path:
            if c == 200 and ("issuer" in text or "authorization_endpoint" in text):
                out.append(("OIDC/OAuth metadata exposed", url))
                if sensitive_re.search(text):
                    out.append(("OIDC/OAuth metadata contains internal-looking endpoint", text[:180]))
                try:
                    cfg = json.loads(text)
                    jwks_uri = str(cfg.get("jwks_uri", ""))
                    if jwks_uri.startswith("http://"):
                        out.append(("OIDC jwks_uri uses plaintext HTTP", jwks_uri))
                except Exception:
                    pass
        elif path.endswith("mta-sts.txt") and c == 200:
            if "mode: enforce" not in text.lower():
                out.append(("MTA-STS policy is not enforce mode", text[:160]))
        elif path.endswith("change-password") and c in (200, 302, 303, 307, 308):
            loc = h.get("location", "")
            if c == 200:
                out.append((".well-known/change-password returns page directly", url))
            elif loc:
                out.append((".well-known/change-password redirect configured", "location=" + loc[:160]))
    return out[:25]

def scan_origin_policy_drift_graph(base: str) -> ScanFindings:
    out: ScanFindings = []
    parsed = urllib.parse.urlparse(base)
    origin = parsed.scheme + "://" + parsed.netloc
    seed_paths = [
        "/", "/login", "/signin", "/auth/login", "/account", "/profile",
        "/dashboard", "/settings", "/admin", "/api/me", "/api/user",
        "/api/session", "/graphql", "/oauth/authorize",
    ]
    endpoints: List[str] = []
    seen_urls: Set[str] = set()

    def _add_url(raw: str) -> None:
        full = urllib.parse.urljoin(base, raw).split("#")[0]
        up = urllib.parse.urlparse(full)
        if up.scheme not in ("http", "https") or up.netloc != parsed.netloc:
            return
        clean = urllib.parse.urlunparse((up.scheme, up.netloc, up.path or "/", "", up.query, ""))
        if clean not in seen_urls:
            seen_urls.add(clean)
            endpoints.append(clean)

    for path in seed_paths:
        _add_url(path)
    with _DISC_ENDPOINTS_LOCK:
        for ep in sorted(_DISCOVERED_ENDPOINTS)[:80]:
            if re.search(r'/(?:api|auth|login|account|profile|dashboard|admin|settings|user|session|graphql|oauth)', ep, re.I):
                _add_url(ep)
    c0, h0, b0, _ = _req(base, timeout=5, use_cache=True)
    html0 = b0.decode("utf-8", "ignore") if b0 else ""
    for href in re.findall(r'(?:href|action)=["\']([^"\']{1,180})["\']', html0, re.I):
        if re.search(r'(?:login|account|profile|dashboard|admin|settings|api|graphql|oauth|session|user)', href, re.I):
            _add_url(href)

    policy_headers = (
        "content-security-policy", "x-frame-options", "referrer-policy",
        "permissions-policy", "cross-origin-opener-policy",
        "cross-origin-embedder-policy", "cross-origin-resource-policy",
        "strict-transport-security", "x-content-type-options",
    )
    sensitive_re = re.compile(r'(?i)(logout|sign out|dashboard|account|profile|settings|admin|csrf|token|session|email|user|password|billing|invoice|apikey|api_key)')
    records: List[Dict[str, object]] = []

    def _classify(url: str, code: int, hdrs: Dict[str, str], body: bytes) -> str:
        path = urllib.parse.urlparse(url).path.lower()
        ct = hdrs.get("content-type", "").lower()
        text = body[:60000].decode("utf-8", "ignore")
        if "json" in ct or path.startswith("/api") or path in ("/graphql",):
            return "api"
        if re.search(r'/(?:login|signin|auth|oauth)', path):
            return "auth"
        if re.search(r'/(?:account|profile|dashboard|settings|admin|billing)', path) or sensitive_re.search(text):
            return "sensitive_page"
        return "page"

    def _score_policy(hdrs: Dict[str, str], cls: str) -> int:
        score = 0
        if hdrs.get("content-security-policy"):
            score += 3
        if hdrs.get("x-frame-options") or "frame-ancestors" in hdrs.get("content-security-policy", "").lower():
            score += 2
        if hdrs.get("referrer-policy"):
            score += 1
        if hdrs.get("x-content-type-options", "").lower() == "nosniff":
            score += 1
        if hdrs.get("cross-origin-opener-policy"):
            score += 1
        if cls in ("auth", "sensitive_page") and "no-store" in hdrs.get("cache-control", "").lower():
            score += 2
        return score

    def _fetch_record(url: str) -> Optional[Dict[str, object]]:
        c, h, b, _ = _req(url, timeout=5)
        if c == 0 or c in (404, 410):
            return None
        cls = _classify(url, c, h, b)
        return {
            "url": url,
            "code": c,
            "class": cls,
            "len": len(b),
            "policy": {k: h.get(k, "") for k in policy_headers},
            "cache": h.get("cache-control", ""),
            "vary": h.get("vary", ""),
            "cors": h.get("access-control-allow-origin", ""),
            "score": _score_policy(h, cls),
            "body": b[:60000],
        }

    with ThreadPoolExecutor(max_workers=10) as ex:
        futs = [ex.submit(_fetch_record, u) for u in endpoints[:36]]
        for fut in as_completed(futs):
            try:
                rec = fut.result()
            except Exception:
                rec = None
            if rec:
                records.append(rec)

    if not records:
        return out

    by_class: Dict[str, List[Dict[str, object]]] = collections.defaultdict(list)
    for rec in records:
        by_class[str(rec["class"])].append(rec)
        url = str(rec["url"])
        cls = str(rec["class"])
        cache = str(rec["cache"]).lower()
        cors = str(rec["cors"])
        body = rec.get("body", b"")
        policy = rec.get("policy", {})
        body_head = body[:200].decode("utf-8", "ignore").lstrip() if isinstance(body, (bytes, bytearray)) else ""
        if cls in ("auth", "sensitive_page") and ("public" in cache or "max-age" in cache) and "no-store" not in cache:
            out.append(("origin policy drift: sensitive route appears cacheable", "url=%s cache-control=%s" % (url, rec["cache"])))
        if cls in ("api", "auth", "sensitive_page") and cors == "*":
            out.append(("origin policy drift: sensitive/API route allows wildcard CORS", "url=%s class=%s" % (url, cls)))
        if cls in ("auth", "sensitive_page") and not str(policy.get("content-security-policy", "")):
            out.append(("origin policy drift: sensitive page missing CSP", url))
        if cls == "api" and body_head.startswith(("{", "[")) and not str(policy.get("x-content-type-options", "")):
            out.append(("origin policy drift: JSON-like API missing X-Content-Type-Options", url))
        if sensitive_re.search(body.decode("utf-8", "ignore")) and "origin" not in str(rec["vary"]).lower() and cors:
            out.append(("origin policy drift: credential-looking response has CORS without Vary: Origin", "url=%s acao=%s" % (url, cors)))

    for cls, items in by_class.items():
        if len(items) < 2:
            continue
        best = max(items, key=lambda r: int(r["score"]))
        worst = min(items, key=lambda r: int(r["score"]))
        gap = int(best["score"]) - int(worst["score"])
        if gap >= 4:
            missing = [
                h for h, v in dict(best["policy"]).items()
                if v and not dict(worst["policy"]).get(h)
            ]
            out.append((
                "origin policy drift graph: route class '%s' has inconsistent security posture" % cls,
                "best=%s worst=%s score_gap=%d missing_on_worst=%s" % (
                    best["url"], worst["url"], gap, ",".join(missing[:5]) or "policy-strength"
                ),
            ))

    variant_bases = [str(r["url"]) for r in records if str(r["class"]) in ("auth", "sensitive_page", "api")][:8]
    for url in variant_bases:
        up = urllib.parse.urlparse(url)
        variants = [
            urllib.parse.urlunparse((up.scheme, up.netloc, up.path.rstrip("/") + "/", "", up.query, "")),
            urllib.parse.urlunparse((up.scheme, up.netloc, up.path + "%2f", "", up.query, "")),
            urllib.parse.urlunparse((up.scheme, up.netloc, up.path + ";", "", up.query, "")),
        ]
        base_rec = next((r for r in records if r["url"] == url), None)
        if not base_rec:
            continue
        base_score = int(base_rec["score"])
        for vu in variants:
            if vu == url:
                continue
            vr = _fetch_record(vu)
            if not vr or int(vr["code"]) not in (200, 204, 301, 302, 303, 307, 308):
                continue
            if int(vr["score"]) + 3 <= base_score and abs(int(vr["len"]) - int(base_rec["len"])) < max(800, int(base_rec["len"]) * 0.35):
                out.append((
                    "origin policy drift graph: path variant loses policy headers",
                    "base=%s variant=%s score=%d->%d" % (url, vu, base_score, int(vr["score"])),
                ))
                break
    deduped: ScanFindings = []
    seen: Set[str] = set()
    for title, detail in out:
        key = title + "|" + detail[:140]
        if key in seen:
            continue
        seen.add(key)
        deduped.append((title, detail))
    return deduped[:30]


