def scan_chrono_diff(base: str, prev_scan_path: Optional[str] = None, min_age_hours: float = 6.0) -> ScanFindings:
    out: ScanFindings = []
    if not prev_scan_path:
        return out
    try:
        prev_entries: Dict[str, Dict] = {}
        bad_lines = 0
        with open(prev_scan_path, "r", encoding="utf-8-sig") as f:
            for line_no, line in enumerate(f, 1):
                line = line.strip()
                if not line:
                    continue
                try:
                    e = json.loads(line)
                    if "module" in e:
                        sk = e.get("module", "") + "::" + e.get("detail", "")[:60]
                        prev_entries[sk] = e
                except Exception:
                    bad_lines += 1
                    if bad_lines <= 3:
                        out.append(("chrono diff: invalid JSONL line %d in previous scan" % line_no, prev_scan_path))
        if not prev_entries:
            if bad_lines:
                out.append(("chrono diff: no valid previous scan entries loaded", "file=%s malformed_lines=%d" % (prev_scan_path, bad_lines)))
            return out
        if bad_lines:
            out.append(("chrono diff: ignored malformed previous scan lines", "file=%s malformed_lines=%d" % (prev_scan_path, bad_lines)))
    except Exception as ex:
        return [("chrono diff: could not load previous scan: " + str(ex), prev_scan_path)]

    with _FINDINGS_LOCK:
        cur = list(_FINDINGS_SUMMARY)

    cur_keys: Dict[str, Dict] = {}
    for m, d, p, s in cur:
        sk = m + "::" + d[:60]
        cur_keys[sk] = {"module": m, "detail": d, "payload": p, "severity": s}

    sev_order = ["INFO", "LOW", "MED", "HIGH", "CRIT", "ZERO"]
    for sk, prev_e in prev_entries.items():
        if sk in cur_keys:
            ps = prev_e.get("severity", "LOW")
            cs = cur_keys[sk].get("severity", "LOW")
            pi = sev_order.index(ps) if ps in sev_order else 0
            ci = sev_order.index(cs) if cs in sev_order else 0
            if pi > ci + 1:
                out.append(("[CONFIRMED] auth boundary DOWNGRADE: %s was %s now %s" % (prev_e.get("module", ""), ps, cs), sk[:80]))
            elif ci > pi + 1:
                out.append(("auth boundary UPGRADE (newly critical): %s was %s now %s" % (cur_keys[sk].get("module", ""), ps, cs), sk[:80]))

    new_endpoints = [cur_keys[sk] for sk in cur_keys if sk not in prev_entries]
    for e in new_endpoints[:10]:
        out.append(("chrono: NEW since last scan: %s" % e.get("module", ""), e.get("detail", "")[:80]))

    gone_endpoints = [prev_entries[sk] for sk in prev_entries if sk not in cur_keys]
    for e in gone_endpoints[:10]:
        out.append(("chrono: GONE since last scan: %s" % e.get("module", ""), e.get("detail", "")[:80]))

    return out

def scan_deploy_freshness(base: str) -> ScanFindings:
    out: ScanFindings = []
    probe_paths = [
        "/", "/static/", "/assets/", "/js/", "/css/", "/dist/",
        "/api/", "/v1/", "/v2/", "/public/", "/media/",
    ]
    now = time.time()
    age_map: Dict[str, float] = {}

    for path in probe_paths:
        url = base.rstrip("/") + path
        try:
            code, hdrs, body, _ = _req(url)
            if code == 0 or code == 404:
                continue
            lm = hdrs.get("last-modified", "")
            if lm:
                try:
                    import email.utils
                    ts = email.utils.parsedate_to_datetime(lm).timestamp()
                    age_days = (now - ts) / 86400
                    age_map[path] = age_days
                except Exception:
                    pass
            st_hdr = hdrs.get("server-timing", "")
            if "boot" in st_hdr.lower() or "startup" in st_hdr.lower():
                out.append(("deploy freshness: Server-Timing boot marker exposed at " + path, st_hdr[:80]))
            if body:
                txt = body[:4096].decode("utf-8", "replace")
                hash_assets = re.findall(r'(?:src|href)=["\'][^"\']*\.[a-f0-9]{7,12}\.(js|css)["\']', txt, re.I)
                if hash_assets:
                    out.append(("deploy freshness: content-hashed assets found (immutable cache strategy) at " + path, "assets=%d" % len(hash_assets)))
        except Exception:
            continue

    for path, age_days in age_map.items():
        if age_days > 730:
            out.append(("[CONFIRMED] HIGH stale-code risk: %s last modified %.0f days ago (>24 months)" % (path, age_days), "age=%.0fd" % age_days))
        elif age_days > 365:
            out.append(("stale-code risk: %s last modified %.0f days ago (>12 months)" % (path, age_days), "age=%.0fd" % age_days))

    if age_map:
        oldest_path = max(age_map, key=lambda k: age_map[k])
        oldest_age = age_map[oldest_path]
        out.append(("deploy freshness summary: oldest subtree=%s age=%.0fd; newest=%.0fd" % (
            oldest_path, oldest_age, min(age_map.values())), "paths=%d" % len(age_map)))

    return out

def scan_schema_fuzz(base: str) -> ScanFindings:
    out: ScanFindings = []
    if _ORACLE is None or not _ORACLE_ACTIVE:
        return out

    json_endpoints = [
        ep for ep, bl in _ORACLE._baseline.items()
        if bl.get("schema_fingerprint") and "{" in (bl.get("schema_fingerprint") or "")
    ]

    if not json_endpoints:
        return out

    def _type_confuse_probes(obj: object) -> List[object]:
        if isinstance(obj, int) or isinstance(obj, float):
            return ["injection_string", None, [], {}, True]
        elif isinstance(obj, str):
            return [0, None, [], True]
        elif isinstance(obj, bool):
            return [0, "true", None]
        elif isinstance(obj, list):
            return [{"__type_confused": True}]
        elif isinstance(obj, dict):
            return [[1, 2, 3], "confused_type"]
        return [None]

    for ep_key in json_endpoints[:10]:
        bl = _ORACLE._baseline[ep_key]
        try:
            code0, hdrs0, body0, _ = _req(ep_key)
            if code0 == 0:
                continue
            if "json" not in hdrs0.get("content-type", ""):
                continue
            baseline_obj = json.loads(body0)
        except Exception:
            continue

        if not isinstance(baseline_obj, dict):
            continue

        for field, val in list(baseline_obj.items())[:5]:
            probes = _type_confuse_probes(val)
            for probe_val in probes[:3]:
                try:
                    payload = json.dumps({**baseline_obj, field: probe_val})
                    code, hdrs, body, _ = _req(
                        ep_key, method="POST",
                        headers={"Content-Type": "application/json"},
                        data=payload.encode()
                    )
                    if code == 0:
                        continue
                    bl_status = bl.get("status_distribution", {})
                    baseline_ok = any(int(k) < 400 for k in bl_status if str(k).isdigit())
                    if baseline_ok and code >= 500:
                        out.append(("[CONFIRMED] schema fuzz: 5xx on type confusion field=%s type=%s->%s at %s" % (
                            field, type(val).__name__, type(probe_val).__name__, ep_key),
                            "payload_field=%s" % field))
                    elif baseline_ok and code < 400:
                        try:
                            resp_obj = json.loads(body)
                            if type(resp_obj.get(field)) != type(val):
                                out.append(("schema fuzz: type-coercion accepted: field=%s %s->%s at %s" % (
                                    field, type(val).__name__, type(probe_val).__name__, ep_key),
                                    "coerced_field=%s" % field))
                        except Exception:
                            pass
                except Exception:
                    continue

    return out


def scan_error_linguistics(base: str) -> ScanFindings:
    out: ScanFindings = []
    probe_paths = ["/", "/api/", "/api/v1/", "/login", "/search", "/user", "/admin"]
    error_triggers = ["'", "\"", "--", "%27", "<script>", "${7*7}", "../../../../etc/passwd"]
    leakage_scores: Dict[str, Tuple[str, int]] = {}

    for path in probe_paths:
        url = base.rstrip("/") + path
        for trigger in error_triggers[:3]:
            probe_url = url + "?q=" + urllib.parse.quote(trigger) + "&id=" + urllib.parse.quote(trigger)
            try:
                code, hdrs, body, _ = _req(probe_url)
                if code == 0 or code < 400:
                    continue
                text = body[:8192].decode("utf-8", "replace").lower()
                if not text:
                    continue
                best_genre = "custom-opaque"
                best_score = 0
                for genre, tokens in _ERROR_TOKENS.items():
                    score = sum(1 for tok in tokens if tok in text)
                    if score > best_score:
                        best_score = score
                        best_genre = genre
                if path not in leakage_scores or best_score > leakage_scores[path][1]:
                    leakage_scores[path] = (best_genre, best_score)
            except Exception:
                continue

    if leakage_scores:
        sorted_scores = sorted(leakage_scores.items(), key=lambda x: x[1][1], reverse=True)
        for path, (genre, score) in sorted_scores[:10]:
            sev_tag = "[CONFIRMED] " if genre == "stack-trace-leaky" and score >= 3 else ""
            out.append(("%serror linguistics: %s  genre=%s  leakage_score=%d" % (sev_tag, path, genre, score),
                        "genre=%s" % genre))

    return out

def scan_dead_code_paths(base: str) -> ScanFindings:
    out: ScanFindings = []
    _ADMIN_TOKENS = {"admin", "debug", "internal", "console", "panel", "manage", "dev", "test", "staging", "backdoor", "config", "setup", "install"}

    with _DISC_ENDPOINTS_LOCK:
        reachable = set(_DISCOVERED_ENDPOINTS)

    js_refs: Set[str] = set()
    try:
        code0, hdrs0, body0, _ = _req(base, use_cache=True)
        if code0 and body0:
            html_text = body0.decode("utf-8", "replace")
            js_urls = re.findall(r'<script[^>]+src=["\']([^"\']+\.js[^"\']*)["\']', html_text, re.I)
            for js_url in js_urls[:5]:
                full_js = _join_url(base, js_url)
                try:
                    jscode, _, jsbody, _ = _req(full_js)
                    if jscode == 200 and jsbody:
                        jstext = jsbody[:65536].decode("utf-8", "replace")
                        paths_in_js = re.findall(r'["\'](\/-[a-z][a-z0-9_\-/]{2,60})["\']', jstext, re.I)
                        for p in paths_in_js:
                            if p.startswith("/") and len(p) > 2:
                                js_refs.add(p.split("?")[0].split("#")[0])
                except Exception:
                    continue
    except Exception:
        pass

    ref_paths: Set[str] = set()
    for src_path in ["/robots.txt", "/sitemap.xml", "/sitemap_index.xml"]:
        try:
            code, hdrs, body, _ = _req(base.rstrip("/") + src_path)
            if code == 200 and body:
                txt = body.decode("utf-8", "replace")
                paths_found = re.findall(r'(?:Disallow:|Allow:|<loc>)(https?://[^\s<]+|/[^\s<]+)', txt)
                for p in paths_found:
                    if p.startswith("http"):
                        parsed_p = urllib.parse.urlparse(p)
                        p = parsed_p.path
                    ref_paths.add(p.split("?")[0])
        except Exception:
            continue

    all_code_paths = js_refs | ref_paths

    def _normalize_path(p: str) -> str:
        return "/" + p.strip("/").lower()

    reachable_norm = {_normalize_path(r) for r in reachable}

    for p in all_code_paths:
        norm_p = _normalize_path(p)
        if norm_p not in reachable_norm and len(norm_p) > 2:
            parts = norm_p.strip("/").split("/")
            is_admin = any(tok in _ADMIN_TOKENS for tok in parts)
            sev_tag = "[CONFIRMED] " if is_admin else ""
            label = "dead code path (admin-flavored)" if is_admin else "dead code path"
            out.append(("%s%s: %s (found in code, not crawler-reachable)" % (sev_tag, label, norm_p), "source=%s" % ("js" if p in js_refs else "sitemap")))

    return out[:20]

def scan_session_identity_drift(base: str) -> ScanFindings:
    out: ScanFindings = []
    if _ORACLE is None:
        return out

    with _ORACLE._probe_records_lock:
        records = list(_ORACLE._probe_records)

    if not records:
        return out

    session_ids: List[str] = []
    jwt_claims: List[Dict] = []

    for path in ["/", "/login", "/api/auth", "/api/session", "/api/me"]:
        url = base.rstrip("/") + path
        try:
            code, hdrs, body, _ = _req(url)
            if code == 0:
                continue
            sc = hdrs.get("set-cookie", "")
            if not sc:
                continue
            for cookie_part in sc.split(";"):
                cookie_part = cookie_part.strip()
                if "=" in cookie_part:
                    k, v = cookie_part.split("=", 1)
                    k = k.strip().lower()
                    if k in ("sessionid", "phpsessid", "jsessionid", "session", "sid", "connect.sid", "asp.net_sessionid"):
                        session_ids.append(v.strip())
                    if k == "path" and "/admin" in v:
                        out.append(("session identity: cookie with path=/admin scope set on %s" % path, "path_scope=/admin"))
            jwt_match = _RE_JWT_PARTS.search(body.decode("utf-8", "replace"))
            if jwt_match:
                try:
                    payload_b64 = jwt_match.group(0).split(".")[1]
                    padding = 4 - len(payload_b64) % 4
                    if padding != 4:
                        payload_b64 += "=" * padding
                    claims = json.loads(base64.b64decode(payload_b64 + "==").decode("utf-8", "replace"))
                    jwt_claims.append(claims)
                except Exception:
                    pass
        except Exception:
            continue

    if len(session_ids) >= 3:
        unique = len(set(session_ids))
        if unique == 1:
            out.append(("[CONFIRMED] session fixation: identical session ID returned across %d probes" % len(session_ids),
                        "session_id=%s" % session_ids[0][:20]))
        else:
            combined = "".join(session_ids)
            if combined:
                freq = collections.Counter(combined)
                entropy = -sum(v / len(combined) * math.log2(v / len(combined))
                               for v in freq.values() if v > 0)
                if entropy < 3.5:
                    out.append(("[CONFIRMED] predictable session ID: low entropy=%.2f bits/char across %d samples" % (entropy, len(session_ids)),
                                "samples=%d" % len(session_ids)))

    if len(jwt_claims) >= 2:
        first_claims = set(jwt_claims[0].keys())
        for later in jwt_claims[1:]:
            new_claims = set(later.keys()) - first_claims
            for nc in new_claims:
                if any(priv_word in nc.lower() for priv_word in ["admin", "role", "scope", "perm", "group"]):
                    out.append(("[CONFIRMED] privilege drift: JWT gained new privileged claim '%s' across scan" % nc,
                                "claim=%s" % nc))
            first_claims |= set(later.keys())

    return out

def scan_token_flow_graph(base: str) -> ScanFindings:
    out: ScanFindings = []
    try:
        parsed_base = urllib.parse.urlparse(base)
        base_host = parsed_base.hostname or ""
        parts = base_host.split(".")
        reg_domain = ".".join(parts[-2:]) if len(parts) >= 2 else base_host
    except Exception:
        return out

    try:
        code, hdrs, body, _ = _req(base, use_cache=True)
        if code == 0 or not body:
            return out
        html_text = body.decode("utf-8", "replace")
    except Exception:
        return out

    external_srcs: Set[str] = set()
    for url_match in re.finditer(r'(?:src|href|action|data-src)=["\']((https?://)[^"\']+)["\']', html_text, re.I):
        url_str = url_match.group(1)
        try:
            ph = urllib.parse.urlparse(url_str).hostname or ""
            if ph and reg_domain not in ph:
                external_srcs.add(ph)
        except Exception:
            pass

    auth_cookies = bool(re.search(r'(sessionid|phpsessid|jsessionid|token|auth)[^;]*', hdrs.get("set-cookie", ""), re.I))
    auth_header = bool(hdrs.get("authorization", "") or hdrs.get("www-authenticate", ""))

    known_third_party_trackers = {
        "google-analytics.com", "analytics.google.com", "doubleclick.net",
        "facebook.com", "fbcdn.net", "twitter.com", "linkedin.com",
        "hotjar.com", "segment.com", "mixpanel.com", "amplitude.com",
        "fullstory.com", "intercom.io", "heap.io",
    }

    for ext_host in external_srcs:
        is_tracker = any(tracker in ext_host for tracker in known_third_party_trackers)
        if auth_cookies or auth_header:
            sev_tag = "[CONFIRMED] " if is_tracker else ""
            note = " (analytics/tracking)" if is_tracker else ""
            out.append(("%stoken flow: auth material may reach external host%s: %s" % (sev_tag, note, ext_host),
                        "origin=%s  destination=%s" % (base_host, ext_host)))
        else:
            out.append(("token flow graph: external resource at %s (no auth detected)" % ext_host, "host=%s" % ext_host))

    if not external_srcs:
        out.append(("token flow graph: no external origins detected (good isolation)", "reg_domain=%s" % reg_domain))

    return out


def scan_waf_bypass_surface(base: str) -> ScanFindings:
    out: ScanFindings = []
    with _FINDINGS_LOCK:
        waf_findings = [(m, d) for m, d, _, _ in _FINDINGS_SUMMARY if "waf" in m.lower()]

    detected_waf: Optional[str] = None
    for _, det in waf_findings:
        det_lower = det.lower()
        for waf_name in _WAF_BYPASS_GAPS:
            if waf_name in det_lower:
                detected_waf = waf_name
                break
        if detected_waf:
            break

    if not detected_waf:
        try:
            code, hdrs, body, _ = _req(base + "/-<script>test</script>")
            server = hdrs.get("server", "").lower()
            via = hdrs.get("via", "").lower()
            body_text = body[:2048].decode("utf-8", "replace").lower()
            for waf_name in _WAF_BYPASS_GAPS:
                if waf_name.split()[0] in (server + via + body_text):
                    detected_waf = waf_name
                    break
        except Exception:
            pass

    if not detected_waf:
        out.append(("waf bypass surface: no WAF detected - skip analysis", "no_waf=true"))
        return out

    gaps = _WAF_BYPASS_GAPS.get(detected_waf, [])
    out.append(("waf bypass surface: detected WAF=%s, testing %d gap patterns" % (detected_waf, len(gaps)), "waf=%s" % detected_waf))

    baseline_code = 0
    try:
        bc, _, _, _ = _req(base)
        baseline_code = bc
    except Exception:
        pass

    for gap_name, header_name, header_val in gaps:
        try:
            extra_hdrs = {header_name: header_val} if header_val else {}
            test_code, test_hdrs, test_body, _ = _req(base, headers=extra_hdrs)
            if test_code == 0:
                continue
            reflected = header_val and header_val in test_body.decode("utf-8", "replace")
            if test_code == baseline_code and not reflected:
                out.append(("waf bypass surface: gap open - %s [%s: %s] passes through %s" % (
                    gap_name, header_name, header_val[:30], detected_waf), "gap=%s" % gap_name))
            elif reflected:
                out.append(("[CONFIRMED] waf bypass surface: header reflected! %s [%s] reflected in response" % (
                    gap_name, header_name), "gap=%s_reflected" % gap_name))
        except Exception:
            continue

    return out

def scan_self_consistency(base: str) -> ScanFindings:
    out: ScanFindings = []
    with _DISC_ENDPOINTS_LOCK:
        discovered = set(_DISCOVERED_ENDPOINTS)

    candidate_paths: List[str] = []
    for ep in list(discovered)[:30]:
        parsed = urllib.parse.urlparse(ep)
        path = parsed.path
        id_match = re.search(r"(/[a-z][a-z0-9_/\-]*)/([\d]+)$", path, re.I)
        if id_match:
            collection = id_match.group(1)
            resource_id = id_match.group(2)
            candidate_paths.append((ep, collection, resource_id))

    for collection in ["/api/users", "/api/items", "/api/products", "/api/orders", "/api/accounts"]:
        for rid in ["1", "2"]:
            ep = base.rstrip("/") + collection + "/" + rid
            candidate_paths.append((ep, collection, rid))

    checked: Set[str] = set()
    for ep, collection, resource_id in candidate_paths[:15]:
        if collection in checked:
            continue
        checked.add(collection)
        v1_url = base.rstrip("/") + collection + "/" + resource_id
        v2_url = base.rstrip("/") + collection + "?id=" + resource_id
        v3_url = base.rstrip("/") + collection + "/find"

        try:
            c1, h1, b1, _ = _req(v1_url)
            c2, h2, b2, _ = _req(v2_url)
            c3, h3, b3, _ = _req(v3_url, method="POST",
                                   headers={"Content-Type": "application/json"},
                                   body=json.dumps({"id": int(resource_id)}).encode())
        except Exception:
            continue

        codes = [c for c in [c1, c2, c3] if c > 0]
        if not codes:
            continue

        ok_codes = {c for c in codes if 200 <= c < 300}
        deny_codes = {c for c in codes if c in (401, 403)}
        if ok_codes and deny_codes:
            out.append(("[CONFIRMED] self-consistency: broken authz on %s - some access paths return %s, others %s" % (
                collection, str(ok_codes), str(deny_codes)),
                "v1=%d v2=%d v3=%d path=%s" % (c1, c2, c3, collection)))
        elif len(set(codes)) > 1:
            out.append(("self-consistency: inconsistent responses for %s - codes: GET/id=%d GET-id=%d POST/find=%d" % (
                collection, c1, c2, c3), "collection=%s" % collection))

        if c1 in (401, 403) and c2 < 300 and len(b2) > len(b1) + 50:
            out.append(("[CONFIRMED] self-consistency: query-param variant bypasses access control on %s" % collection,
                        "canonical=403 query_variant=200"))

    return out

_ADMIN_TOKENS_HPB: Set[str] = {
    "admin", "debug", "secret", "key", "cmd", "command",
    "exec", "eval", "file", "path",
}


_HPB_LEARNED_PARAMS: Dict[str, float] = {}

_HIDDEN_PARAM_PRIOR = _HPB_STATIC_PRIOR

@dataclasses.dataclass
class _HpbArm:
    name: str
    alpha: float
    beta: float
    probes: int
    surface: str
    confirmed: bool
    score_history: List[float]

@dataclasses.dataclass
class _HpbSurface:
    name: str
    builder: Callable
    weight: float

def _hpb_surf_get(url: str, param: str, tok: str) -> Tuple[str, str, Optional[bytes], Dict[str, str]]:
    sep = "&" if "?" in url else "?"
    return (
        f"{url}{sep}{urllib.parse.quote_plus(param)}={urllib.parse.quote_plus(tok)}",
        "GET", None, {},
    )

def _hpb_surf_post_form(url: str, param: str, tok: str) -> Tuple[str, str, Optional[bytes], Dict[str, str]]:
    return (url, "POST", urllib.parse.urlencode({param: tok}).encode(),
            {"Content-Type": "application/x-www-form-urlencoded"})

def _hpb_surf_post_json(url: str, param: str, tok: str) -> Tuple[str, str, Optional[bytes], Dict[str, str]]:
    return url, "POST", json.dumps({param: tok}).encode(), {"Content-Type": "application/json"}

def _hpb_surf_header(url: str, param: str, tok: str) -> Tuple[str, str, Optional[bytes], Dict[str, str]]:
    return url, "GET", None, {"X-" + param.replace("_", "-").title(): tok}

def _hpb_surf_path(url: str, param: str, tok: str) -> Tuple[str, str, Optional[bytes], Dict[str, str]]:
    path_url = (url.rstrip("/") + "/" + urllib.parse.quote_plus(param)
                + "/" + urllib.parse.quote_plus(tok))
    return path_url, "GET", None, {}

def _hpb_surf_cookie(url: str, param: str, tok: str) -> Tuple[str, str, Optional[bytes], Dict[str, str]]:
    return url, "GET", None, {"Cookie": f"{param}={tok}"}

_HPB_PROBE_SURFACES: List[_HpbSurface] = build_hpb_probe_surfaces(
    _HpbSurface,
    {
        "get": _hpb_surf_get,
        "post_form": _hpb_surf_post_form,
        "post_json": _hpb_surf_post_json,
        "header": _hpb_surf_header,
        "path": _hpb_surf_path,
        "cookie": _hpb_surf_cookie,
    },
)

_HPB_BUDGET: int = 90

def _beta_sample(a: float, b: float) -> float:
    a = max(a, 1e-9)
    b = max(b, 1e-9)
    for _ in range(2000):
        u = random.random() ** (1.0 / a)
        v = random.random() ** (1.0 / b)
        s = u + v
        if 0.0 < s <= 1.0:
            return u / s
    return a / (a + b)

@dataclasses.dataclass
class _HpbBaseline:
    status: int
    body_len: int
    compress_ratio: float
    json_keys: frozenset
    content_type: str
    body_text: str

def _hpb_baseline_snapshot(code: int, hdrs: Dict, body: bytes) -> _HpbBaseline:
    raw = body if body else b""
    body_text = raw.decode("utf-8", "ignore")
    try:
        compress_ratio = len(zlib.compress(raw[:4096])) / max(len(raw[:4096]), 1)
    except Exception:
        compress_ratio = 1.0
    json_keys: frozenset = frozenset()
    try:
        obj = json.loads(body_text)
        if isinstance(obj, dict):
            json_keys = frozenset(obj.keys())
        elif isinstance(obj, list) and obj and isinstance(obj[0], dict):
            json_keys = frozenset(obj[0].keys())
    except Exception:
        pass
    return _HpbBaseline(
        status=code, body_len=len(raw), compress_ratio=compress_ratio,
        json_keys=json_keys, content_type=hdrs.get("content-type", ""),
        body_text=body_text[:4096],
    )

_HPB_HTML_NAME_RE = re.compile(r'(?:name|id)=["\']([A-Za-z_][\w\-]{0,49})["\']', re.I)
_HPB_DATA_ATTR_RE = re.compile(r'data-(?:param|key)=["\']([A-Za-z_][\w\-]{0,49})["\']', re.I)
_HPB_META_NAME_RE = re.compile(r'<meta[^>]+name=["\']([A-Za-z_][\w]{0,29})["\']', re.I)
_HPB_JS_FETCH_QS_RE = re.compile(r'[-&]([A-Za-z_][\w]{0,49})=', re.I)
_HPB_JS_URLPARAMS_RE = re.compile(r'\.(?:get|append)\(["\']([A-Za-z_][\w]{0,49})["\']', re.I)
_HPB_JS_OBJ_KEY_RE = re.compile(r'\b([A-Za-z_][\w]{1,49})\s*:', re.I)
_HPB_PARAM_VALID_RE = re.compile(r'^[A-Za-z_][\w\-]{0,49}$')
_HPB_ERR_RE = re.compile(r'\b(error|invalid|required|missing)\b', re.I)

def _hpb_build_wordlist(
    base: str,
    html: str,
    js_sources: List[Tuple[str, str]],
) -> List[Tuple[str, float]]:
    merged: Dict[str, float] = {}

    def _add(name: str, weight: float) -> None:
        if _HPB_PARAM_VALID_RE.match(name) and len(name) <= 50:
            n = name.lower()
            merged[n] = max(merged.get(n, 0.0), weight)

    for name, w in _HPB_STATIC_PRIOR:
        _add(name, w)

    for m in _HPB_HTML_NAME_RE.finditer(html):
        _add(m.group(1), 12.0)
    for m in _HPB_DATA_ATTR_RE.finditer(html):
        _add(m.group(1), 12.0)
    for m in _HPB_META_NAME_RE.finditer(html):
        if len(m.group(1)) <= 30:
            _add(m.group(1), 12.0)
    for pat in (r'href=["\'][^"\']*\-([^"\'#\s]+)', r'action=["\'][^"\']*\-([^"\'#\s]+)'):
        for m in re.finditer(pat, html, re.I):
            for k, _ in urllib.parse.parse_qsl(m.group(1), keep_blank_values=True):
                _add(k, 12.0)

    for _sname, js_text in js_sources:
        for m in _HPB_JS_FETCH_QS_RE.finditer(js_text):
            _add(m.group(1), 14.0)
        for m in _HPB_JS_REQ_KEY_RE.finditer(js_text):
            _add(m.group(1), 14.0)
        for m in _HPB_JS_URLPARAMS_RE.finditer(js_text):
            _add(m.group(1), 14.0)
        for blk in re.finditer(
            r'(?:data|params|body|payload)\s*:\s*\{([^}]{0,500})\}', js_text, re.I
        ):
            for km in _HPB_JS_OBJ_KEY_RE.finditer(blk.group(1)):
                _add(km.group(1), 14.0)
        for blk in re.finditer(
            r'axios\.(?:post|put|patch)\s*\([^,]+,\s*\{([^}]{0,500})\}', js_text, re.I
        ):
            for km in _HPB_JS_OBJ_KEY_RE.finditer(blk.group(1)):
                _add(km.group(1), 14.0)

    for name in list(merged.keys()):
        for variant in _HPB_SEMANTIC_VARIANTS.get(name, []):
            _add(variant, merged[name] * 0.6)

    netloc = urllib.parse.urlparse(base).netloc
    for lkey, prob in _HPB_LEARNED_PARAMS.items():
        knetloc, _, kname = lkey.partition(":")
        if knetloc == netloc and kname:
            _add(kname, prob * 30.0)

    return sorted(merged.items(), key=lambda x: x[1], reverse=True)[:800]

def _hpb_score(
    baseline: _HpbBaseline,
    probe_code: int,
    probe_hdrs: Dict,
    probe_body: bytes,
    token: str,
) -> float:
    pb = probe_body or b""
    probe_text = pb.decode("utf-8", "ignore")
    probe_len = len(pb)
    s1 = 1.0 if probe_code != baseline.status else 0.0
    s2 = min(abs(probe_len - baseline.body_len) / max(baseline.body_len, 1), 1.0)
    try:
        probe_cr = len(zlib.compress(pb[:4096])) / max(len(pb[:4096]), 1)
    except Exception:
        probe_cr = baseline.compress_ratio
    s3 = min(abs(probe_cr - baseline.compress_ratio), 1.0)
    s4 = 1.0 if probe_hdrs.get("content-type", "") != baseline.content_type else 0.0
    s5 = 0.0
    try:
        obj = json.loads(probe_text)
        pk: frozenset = frozenset()
        if isinstance(obj, dict):
            pk = frozenset(obj.keys())
        elif isinstance(obj, list) and obj and isinstance(obj[0], dict):
            pk = frozenset(obj[0].keys())
        union = baseline.json_keys | pk
        if union:
            s5 = 1.0 - len(baseline.json_keys & pk) / len(union)
    except Exception:
        pass
    s6 = (1.0 if _HPB_ERR_RE.search(probe_text) and
          not _HPB_ERR_RE.search(baseline.body_text) else 0.0)
    s7 = 1.0 if token and token in probe_text else 0.0
    return max(0.0, min(
        1.0, s1*0.25 + s2*0.20 + s3*0.20 + s4*0.10 + s5*0.15 + s6*0.05 + s7*0.05
    ))

def _hpb_probe_surface(
    url: str, param: str, token: str, surface: _HpbSurface,
) -> Tuple[int, Dict, bytes]:
    try:
        probe_url, method, body, headers = surface.builder(url, param, token)
        c, h, b, _ = _req(probe_url, method=method, data=body,
                           headers=headers if headers else None, timeout=5.0)
        return c, h, b or b""
    except Exception:
        return 0, {}, b""

def _hpb_select_endpoints(base: str) -> List[str]:
    parsed = urllib.parse.urlparse(base)
    candidates: List[str] = [base]
    with _DISC_ENDPOINTS_LOCK:
        for ep in _DISCOVERED_ENDPOINTS:
            if urllib.parse.urlparse(ep).netloc == parsed.netloc:
                candidates.append(ep)
    seen_paths: Set[str] = set()
    unique: List[str] = []
    for ep in candidates:
        p = urllib.parse.urlparse(ep).path
        if p not in seen_paths:
            seen_paths.add(p)
            unique.append(ep)
    with_qs = [u for u in unique if "?" in u]
    without_qs = [u for u in unique if "?" not in u]
    return (with_qs + without_qs)[:10]

def _hpb_thompson_loop(
    ep_url: str,
    arms: Dict[str, _HpbArm],
    baseline: _HpbBaseline,
    budget: int,
    deadline: threading.Event,
) -> List[Tuple[str, str, float]]:
    confirmed: List[Tuple[str, str, float]] = []
    token = "HPB_" + secrets.token_urlsafe(8)
    spent = 0
    surface_scores: Dict[str, Dict[str, float]] = {nm: {} for nm in arms}

    while spent < budget and not deadline.is_set():
        sampled: List[Tuple[float, str]] = [
            (_beta_sample(arm.alpha, arm.beta), nm)
            for nm, arm in arms.items() if not arm.confirmed
        ]
        if not sampled:
            break
        sampled.sort(reverse=True)
        batch_names = [nm for _, nm in sampled[:20]]

        probe_tasks: List[Tuple[str, _HpbSurface]] = []
        for nm in batch_names:
            for surf in _HPB_PROBE_SURFACES:
                if spent + len(probe_tasks) >= budget:
                    break
                probe_tasks.append((nm, surf))
            if spent + len(probe_tasks) >= budget:
                break
        if not probe_tasks:
            break

        futures_map: Dict = {}
        with ThreadPoolExecutor(max_workers=12) as _hpb_ex:
            for nm, surf in probe_tasks:
                if deadline.is_set():
                    break
                fut = _hpb_ex.submit(_hpb_probe_surface, ep_url, nm, token, surf)
                futures_map[fut] = (nm, surf.name)

            completed = 0
            for fut in as_completed(futures_map):
                if deadline.is_set():
                    break
                nm, sname = futures_map[fut]
                try:
                    pc, ph, pb_b = fut.result()
                    if pc > 0:
                        sc = _hpb_score(baseline, pc, ph, pb_b, token)
                        if sc > 0.15:
                            arms[nm].alpha += sc * 4.0
                        else:
                            arms[nm].beta += 1.0
                        arms[nm].probes += 1
                        arms[nm].score_history = (arms[nm].score_history + [sc])[-5:]
                        surface_scores[nm][sname] = max(
                            surface_scores[nm].get(sname, 0.0), sc
                        )
                except Exception:
                    pass
                completed += 1
                spent += 1
                if completed % 10 == 0:
                    for n2 in batch_names:
                        if arms[n2].confirmed:
                            continue
                        ss = surface_scores[n2]
                        hi = [s for s, sv in ss.items() if sv >= 0.35]
                        if len(hi) >= 2 or any(sv >= 0.70 for sv in ss.values()):
                            arms[n2].confirmed = True
                            best = max(ss, key=ss.get) if ss else "GET"
                            post = arms[n2].alpha / (arms[n2].alpha + arms[n2].beta)
                            confirmed.append((n2, best, post))

        for nm in batch_names:
            if arms[nm].confirmed:
                continue
            ss = surface_scores[nm]
            hi = [s for s, sv in ss.items() if sv >= 0.35]
            if len(hi) >= 2 or any(sv >= 0.70 for sv in ss.values()):
                arms[nm].confirmed = True
                best = max(ss, key=ss.get) if ss else "GET"
                post = arms[nm].alpha / (arms[nm].alpha + arms[nm].beta)
                confirmed.append((nm, best, post))

    return confirmed

def _hpb_exploit(
    base: str,
    param: str,
    surface_name: str,
    baseline: _HpbBaseline,
) -> ScanFindings:
    out: ScanFindings = []
    surf = next(
        (s for s in _HPB_PROBE_SURFACES if s.name == surface_name),
        _HPB_PROBE_SURFACES[0],
    )

    def _p(val: str) -> Tuple[int, Dict, bytes]:
        return _hpb_probe_surface(base, param, val, surf)

    def _test_idor() -> ScanFindings:
        results: ScanFindings = []
        try:
            hashes = []
            for v in ("1", "2", "0", "-1", "9999"):
                c, _, b = _p(v)
                if c in (200, 201):
                    hashes.append(hashlib.sha256(b[:8192]).hexdigest())
            if len(set(hashes)) > 1:
                results.append((
                    f"hidden param '{param}' is an IDOR surface: "
                    "different values return different resources",
                    f"param={param} surface={surface_name} "
                    f"distinct_responses={len(set(hashes))}",
                ))
        except Exception:
            pass
        return results

    def _test_injection() -> ScanFindings:
        results: ScanFindings = []
        try:
            for payload in ("'", '"', "<script>", "../", "{{7*7}}", ";id"):
                c, h, b = _p(payload)
                sc = _hpb_score(baseline, c, h, b, payload)
                if sc > 0.5:
                    results.append((
                        f"hidden param '{param}' has injection signal: high response "
                        f"divergence from injection probe '{payload}' (score={sc:.2f})",
                        f"param={param} payload={payload!r} score={sc:.2f}",
                    ))
                    break
        except Exception:
            pass
        return results

    def _test_boolean() -> ScanFindings:
        results: ScanFindings = []
        try:
            for tv, fv in (("true", "false"), ("1", "0"), ("yes", "no")):
                c_t, _, b_t = _p(tv)
                c_f, _, b_f = _p(fv)
                if c_t > 0 and c_f > 0:
                    ld = abs(len(b_t) - len(b_f)) / max(len(b_t), len(b_f), 1)
                    if ld > 0.3 or c_t != c_f:
                        results.append((
                            f"hidden param '{param}' is a boolean gate: server behavior "
                            "differs on true/false values - possible feature flag or "
                            "access control switch",
                            f"param={param} true_code={c_t} false_code={c_f} "
                            f"len_diff={ld:.2f}",
                        ))
                        break
        except Exception:
            pass
        return results

    def _test_admin() -> ScanFindings:
        results: ScanFindings = []
        try:
            if any(tok in param.lower() for tok in _ADMIN_TOKENS_HPB):
                for val in ("true", "1", "admin", "root", "yes"):
                    c, _, b = _p(val)
                    b_text = b.decode("utf-8", "ignore")
                    try:
                        obj = json.loads(b_text)
                        pk = frozenset(obj.keys()) if isinstance(obj, dict) else frozenset()
                    except Exception:
                        pk = frozenset()
                    new_keys = pk - baseline.json_keys
                    if new_keys or (baseline.status in (401, 403) and c == 200):
                        results.append((
                            f"[CONFIRMED] hidden param '{param}' with value '{val}' "
                            "changes access level - possible privilege escalation "
                            "via undocumented admin parameter",
                            f"param={param} val={val!r} new_keys={new_keys}",
                        ))
                        break
        except Exception:
            pass
        return results

    def _test_reflection() -> ScanFindings:
        results: ScanFindings = []
        try:
            refl = "HPB_REFL_" + secrets.token_urlsafe(8)
            c, _, b = _p(refl)
            if refl in b.decode("utf-8", "ignore"):
                results.append((
                    f"hidden param '{param}' reflects input verbatim "
                    "? test for XSS, SSTI, and open redirect",
                    f"param={param} reflected=true surface={surface_name}",
                ))
        except Exception:
            pass
        return results

    with ThreadPoolExecutor(max_workers=5) as _ex:
        futs = [
            _ex.submit(_test_idor),
            _ex.submit(_test_injection),
            _ex.submit(_test_boolean),
            _ex.submit(_test_admin),
            _ex.submit(_test_reflection),
        ]
        for fut in as_completed(futs):
            try:
                out.extend(fut.result())
            except Exception:
                pass

    return out

def _hpb_save_learned(base: str, arms: Dict[str, _HpbArm]) -> None:
    netloc = urllib.parse.urlparse(base).netloc
    for name, arm in arms.items():
        if arm.probes > 0:
            _HPB_LEARNED_PARAMS[f"{netloc}:{name}"] = (
                arm.alpha / (arm.alpha + arm.beta)
            )
    if _AUTOSAVE_FILE:
        try:
            with open(_AUTOSAVE_FILE + ".hpb.json", "w", encoding="utf-8") as _hpb_f:
                json.dump(_HPB_LEARNED_PARAMS, _hpb_f)
        except Exception:
            pass

def scan_hidden_param_bayesian(base: str, budget: Optional[int] = None) -> ScanFindings:
    out: ScanFindings = []
    probe_budget = budget or _HPB_BUDGET
    _hpb_dl = threading.Event()
    _hpb_t = threading.Timer(90.0, _hpb_dl.set)
    _hpb_t.daemon = True
    _hpb_t.start()
    try:
        if _AUTOSAVE_FILE:
            try:
                lpath = _AUTOSAVE_FILE + ".hpb.json"
                if os.path.exists(lpath):
                    with open(lpath, encoding="utf-8") as _hpb_lf:
                        _HPB_LEARNED_PARAMS.update(json.load(_hpb_lf))
            except Exception:
                pass

        code0, hdrs0, body0, _ = _req(base, use_cache=True)
        if code0 == 0:
            return out
        baseline = _hpb_baseline_snapshot(code0, hdrs0, body0)

        html_text = (body0 or b"").decode("utf-8", "ignore")
        js_sources = _extract_js_files(base, html_text)
        wordlist = _hpb_build_wordlist(base, html_text, js_sources)

        netloc = urllib.parse.urlparse(base).netloc
        arms: Dict[str, _HpbArm] = {}
        for wname, w in wordlist:
            boost = 3.0 if f"{netloc}:{wname}" in _HPB_LEARNED_PARAMS else 1.0
            arms[wname] = _HpbArm(
                name=wname, alpha=w * boost, beta=1.0, probes=0,
                surface="", confirmed=False, score_history=[],
            )

        endpoints = _hpb_select_endpoints(base)
        all_confirmed: List[Tuple[str, str, float]] = []
        budget_per_ep = max(20, probe_budget // len(endpoints))

        for ep_url in endpoints:
            if _hpb_dl.is_set():
                break
            try:
                ep_c, ep_h, ep_b, _ = _req(ep_url)
                if ep_c == 0:
                    continue
                ep_base = _hpb_baseline_snapshot(ep_c, ep_h, ep_b)
            except Exception:
                continue
            all_confirmed.extend(
                _hpb_thompson_loop(ep_url, arms, ep_base, budget_per_ep, _hpb_dl)
            )

        if all_confirmed and len(endpoints) > 1 and not _hpb_dl.is_set():
            for xparam, xsurf_name, _ in all_confirmed[:5]:
                xsurf = next(
                    (s for s in _HPB_PROBE_SURFACES if s.name == xsurf_name),
                    _HPB_PROBE_SURFACES[0],
                )
                for xep in endpoints[1:3]:
                    if _hpb_dl.is_set():
                        break
                    try:
                        xc, xh, xb = _hpb_probe_surface(
                            xep, xparam,
                            "HPB_X_" + secrets.token_urlsafe(4), xsurf,
                        )
                        if xc > 0:
                            xsc = _hpb_score(baseline, xc, xh, xb, "")
                            if xsc > 0.35:
                                all_confirmed.append(
                                    (xparam, xsurf_name + "@" + xep, xsc)
                                )
                    except Exception:
                        pass

        seen_params: Set[str] = set()
        for param, surf_name, posterior in all_confirmed:
            if _hpb_dl.is_set():
                break
            if param in seen_params:
                continue
            seen_params.add(param)
            surf_display = surf_name.split("@")[0]
            sev = "[CONFIRMED] " if any(
                tok in param.lower() for tok in _ADMIN_TOKENS_HPB
            ) else "[FOUND] "
            out.append((
                f"{sev}hidden param '{param}' discovered via {surf_display} "
                f"(posterior={posterior:.2f}, budget={probe_budget})",
                f"param={param} surface={surf_display} posterior={posterior:.2f}",
            ))
            out.extend(_hpb_exploit(base, param, surf_display, baseline))

        if not all_confirmed:
            top5 = sorted(
                arms.values(),
                key=lambda a: a.alpha / (a.alpha + a.beta),
                reverse=True,
            )[:5]
            out.append((
                "hidden param bayesian: no params confirmed - "
                f"top candidates: {', '.join(a.name for a in top5)} "
                f"(budget={probe_budget})",
                "budget_exhausted=true",
            ))

        _hpb_save_learned(base, arms)

    except Exception as exc:
        out.append((
            f"hidden param bayesian: scan error - {exc}",
            f"error={exc!r}",
        ))
    finally:
        _hpb_t.cancel()

    return out


def scan_stack_coherence(base: str) -> ScanFindings:
    out: ScanFindings = []
    signals: Dict[str, str] = {}

    try:
        code, hdrs, body, tls_info = _req(base, use_cache=True)
        if code == 0:
            return out
    except Exception:
        return out

    server_hdr = hdrs.get("server", "").strip()
    if server_hdr:
        signals["server_header"] = server_hdr.lower()

    powered_by = hdrs.get("x-powered-by", "").strip()
    if powered_by:
        signals["x_powered_by"] = powered_by.lower()

    set_cookie = hdrs.get("set-cookie", "").lower()
    if "phpsessid" in set_cookie:
        signals["cookie_naming"] = "php"
    elif "jsessionid" in set_cookie:
        signals["cookie_naming"] = "java/tomcat"
    elif "asp.net_sessionid" in set_cookie:
        signals["cookie_naming"] = "aspnet"
    elif "_rails_session" in set_cookie:
        signals["cookie_naming"] = "rails"
    elif "laravel_session" in set_cookie:
        signals["cookie_naming"] = "laravel"
    elif "connect.sid" in set_cookie:
        signals["cookie_naming"] = "nodejs/express"
    elif "django" in set_cookie or "csrftoken" in set_cookie:
        signals["cookie_naming"] = "django"

    if body:
        html_text = body[:8192].decode("utf-8", "replace")
        if re.search(r"<!--.*-generated by wordpress", html_text, re.I):
            signals["html_comment"] = "wordpress"
        elif re.search(r"<!--.*-drupal", html_text, re.I):
            signals["html_comment"] = "drupal"
        elif re.search(r"<!--.*-joomla", html_text, re.I):
            signals["html_comment"] = "joomla"
        if re.search(r"next\.js|__next", html_text, re.I):
            signals["js_bundle"] = "nextjs"
        elif re.search(r"nuxt|__nuxt", html_text, re.I):
            signals["js_bundle"] = "nuxt"
        elif re.search(r"react|reactdom", html_text, re.I):
            signals["js_bundle"] = "react"
        elif re.search(r"angular|ng-version", html_text, re.I):
            signals["js_bundle"] = "angular"

    try:
        fav_code, _, fav_body, _ = _req(base.rstrip("/") + "/favicon.ico")
        if fav_code == 200 and fav_body:
            fav_hash = hashlib.md5(fav_body).hexdigest()[:8]
            if fav_hash in _FAVICON_HASHES:
                signals["favicon"] = _FAVICON_HASHES[fav_hash].lower()
    except Exception:
        pass

    if not signals:
        out.append(("stack coherence: no fingerprint signals collected", "signals=0"))
        return out

    _TECH_FAMILIES: Dict[str, str] = {
        "php": "php", "laravel": "php", "wordpress": "php", "drupal": "php", "joomla": "php",
        "java": "jvm", "tomcat": "jvm", "spring": "jvm", "jboss": "jvm",
        "aspnet": "dotnet", "iis": "dotnet", ".net": "dotnet",
        "nodejs": "node", "express": "node", "nextjs": "node", "nuxt": "node",
        "ruby": "ruby", "rails": "ruby",
        "python": "python", "django": "python", "flask": "python",
        "go": "go", "golang": "go",
        "nginx": "nginx", "apache": "apache",
    }

    def _infer_family(val: str) -> Optional[str]:
        v = val.lower()
        for key, fam in _TECH_FAMILIES.items():
            if key in v:
                return fam
        return None

    families = set()
    signal_details = []
    for sig_name, sig_val in signals.items():
        fam = _infer_family(sig_val)
        if fam:
            families.add(fam)
        signal_details.append("%s=%s(%s)" % (sig_name, sig_val[:20], fam or "?"))

    non_proxy_families = {f for f in families if f not in ("nginx", "apache")}

    if len(non_proxy_families) >= 2:
        out.append(("[CONFIRMED] stack coherence LOW: conflicting fingerprints suggest proxy deception or misconfiguration - families=%s" % str(sorted(non_proxy_families)),
                    "signals=[%s]" % ", ".join(signal_details[:6])))
    elif len(families) >= 2 and "nginx" in families or "apache" in families:
        out.append(("stack coherence: proxy layer detected (normal) - nginx/apache + %s" % str(non_proxy_families),
                    "signals=[%s]" % ", ".join(signal_details[:6])))
    elif len(signals) >= 3 and len(families) == 1:
        out.append(("stack coherence HIGH: all %d signals agree on %s (no deception detected)" % (len(signals), str(families)),
                    "signals=[%s]" % ", ".join(signal_details[:6])))
    else:
        out.append(("stack coherence: %d signal(s) collected, %d family/families" % (len(signals), len(families)),
                    "signals=[%s]" % ", ".join(signal_details[:6])))

    if non_proxy_families and len(non_proxy_families) == 1:
        global _DETECTED_STACK
        detected = next(iter(non_proxy_families))
        if _DETECTED_STACK == "unknown":
            _DETECTED_STACK = detected

    return out

def _wasm_uleb128(data: bytes, pos: int) -> Tuple[int, int]:
    val = 0
    shift = 0
    n = 0
    while pos + n < len(data):
        b = data[pos + n]
        n += 1
        val |= (b & 0x7F) << shift
        shift += 7
        if not (b & 0x80):
            break
    return val, n

def _wasm_sleb128(data: bytes, pos: int) -> Tuple[int, int]:
    val = 0
    shift = 0
    n = 0
    while pos + n < len(data):
        b = data[pos + n]
        n += 1
        val |= (b & 0x7F) << shift
        shift += 7
        if not (b & 0x80):
            if shift < 64 and (b & 0x40):
                val |= -(1 << shift)
            break
    return val, n

def _wasm_name(data: bytes, pos: int) -> Tuple[str, int]:
    if pos >= len(data):
        return "", 0
    length, nb = _wasm_uleb128(data, pos)
    end = pos + nb + length
    if end > len(data):
        return "", nb
    try:
        s = data[pos + nb:end].decode("utf-8", "replace")
    except Exception:
        s = ""
    return s, nb + length

def _wasm_parse_exports_section(sec: bytes) -> List[str]:
    names: List[str] = []
    pos = 0
    try:
        count, nb = _wasm_uleb128(sec, pos)
        pos += nb
        for _ in range(min(count, 4000)):
            if pos >= len(sec):
                break
            name, nb = _wasm_name(sec, pos)
            pos += nb
            if pos >= len(sec):
                break
            pos += 1
            _, nb = _wasm_uleb128(sec, pos)
            pos += nb
            if name:
                names.append(name)
    except Exception:
        pass
    return names

def _wasm_parse_imports_section(sec: bytes) -> List[Tuple[str, str]]:
    items: List[Tuple[str, str]] = []
    pos = 0
    try:
        count, nb = _wasm_uleb128(sec, pos)
        pos += nb
        for _ in range(min(count, 4000)):
            if pos >= len(sec):
                break
            mod, nb = _wasm_name(sec, pos)
            pos += nb
            field, nb = _wasm_name(sec, pos)
            pos += nb
            if pos >= len(sec):
                break
            kind = sec[pos]
            pos += 1
            if kind == 0:
                _, nb = _wasm_uleb128(sec, pos)
                pos += nb
            elif kind == 1:
                pos += 1
                flags = sec[pos] if pos < len(sec) else 0
                pos += 1
                _, nb = _wasm_uleb128(sec, pos)
                pos += nb
                if flags & 1:
                    _, nb = _wasm_uleb128(sec, pos)
                    pos += nb
            elif kind == 2:
                flags = sec[pos] if pos < len(sec) else 0
                pos += 1
                _, nb = _wasm_uleb128(sec, pos)
                pos += nb
                if flags & 1:
                    _, nb = _wasm_uleb128(sec, pos)
                    pos += nb
            elif kind == 3:
                pos += 2
            items.append((mod, field))
    except Exception:
        pass
    return items

def _wasm_parse_data_section(sec: bytes) -> List[str]:
    strings: List[str] = []
    pos = 0
    try:
        count, nb = _wasm_uleb128(sec, pos)
        pos += nb
        for _ in range(min(count, 1000)):
            if pos >= len(sec):
                break
            flags, nb = _wasm_uleb128(sec, pos)
            pos += nb
            if flags in (0, 2):
                if flags == 2:
                    _, nb = _wasm_uleb128(sec, pos)
                    pos += nb
                op = sec[pos] if pos < len(sec) else 0
                pos += 1
                if op in (0x41, 0x42):
                    _, nb = _wasm_sleb128(sec, pos)
                    pos += nb
                if pos < len(sec) and sec[pos] == 0x0B:
                    pos += 1
            size, nb = _wasm_uleb128(sec, pos)
            pos += nb
            if pos + size > len(sec):
                break
            segment = sec[pos:pos + size]
            pos += size
            buf = bytearray()
            for byte_val in segment:
                if 32 <= byte_val < 127:
                    buf.append(byte_val)
                else:
                    if len(buf) >= 8:
                        strings.append(buf.decode("ascii", "replace"))
                    buf = bytearray()
            if len(buf) >= 8:
                strings.append(buf.decode("ascii", "replace"))
    except Exception:
        pass
    return strings

def _wasm_parse_name_custom_section(sec: bytes) -> List[str]:
    names: List[str] = []
    pos = 0
    try:
        while pos < len(sec):
            subsec_id = sec[pos]
            pos += 1
            subsec_size, nb = _wasm_uleb128(sec, pos)
            pos += nb
            if pos + subsec_size > len(sec):
                break
            sub = sec[pos:pos + subsec_size]
            pos += subsec_size
            if subsec_id == 1:
                p2 = 0
                cnt, nb2 = _wasm_uleb128(sub, p2)
                p2 += nb2
                for _ in range(min(cnt, 4000)):
                    if p2 >= len(sub):
                        break
                    _, nb2 = _wasm_uleb128(sub, p2)
                    p2 += nb2
                    nm, nb2 = _wasm_name(sub, p2)
                    p2 += nb2
                    if nm:
                        names.append(nm)
    except Exception:
        pass
    return names

def scan_wasm_analysis(base: str) -> ScanFindings:
    out: ScanFindings = []

    _COMMON_WASM_PATHS = [
        "/app.wasm", "/main.wasm", "/index.wasm", "/bundle.wasm",
        "/pkg/app_bg.wasm", "/pkg/index_bg.wasm", "/wasm/app.wasm",
        "/static/app.wasm", "/static/main.wasm", "/assets/app.wasm",
        "/dist/app.wasm", "/build/app.wasm", "/js/app.wasm",
        "/wasm_exec.wasm", "/go.wasm", "/output.wasm",
    ]

    _SUSP_KWS = frozenset([
        "admin", "root", "bypass", "backdoor", "debug_shell", "internal",
        "hidden", "secret", "sudo", "override", "unlock", "crack", "exploit",
        "shell", "rce", "inject", "traversal", "delete_all", "drop_table",
        "exec_cmd", "run_system", "eval_code", "auth_bypass", "get_password",
        "dump_db", "read_env", "write_file", "set_admin", "make_admin",
    ])

    _DANGEROUS_WASI = frozenset([
        "path_open", "path_remove_file", "path_rename", "path_unlink_file",
        "path_create_directory", "path_symlink", "sock_accept", "sock_connect",
        "fd_write", "fd_read", "proc_raise", "sched_yield",
    ])

    _SECRET_PATS: List[Tuple[re.Pattern, str]] = [
        (re.compile(r'AKIA[0-9A-Z]{16}'), "AWS Access Key ID"),
        (re.compile(r'-----BEGIN (?:RSA |EC |DSA )?PRIVATE KEY'), "Private Key"),
        (re.compile(r'eyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{5,}'), "JWT Token"),
        (re.compile(r'(?:mongodb|postgres|postgresql|mysql|redis|amqp|rabbitmq)://\S{8,}', re.I), "DB Connection String"),
        (re.compile(r'ghp_[A-Za-z0-9]{36}'), "GitHub PAT"),
        (re.compile(r'sk-[A-Za-z0-9]{48}'), "OpenAI Secret Key"),
        (re.compile(r'xox[bpoas]-[A-Za-z0-9\-]{24,}'), "Slack Token"),
        (re.compile(r'(?i)(?:password|passwd|secret|api[_-]?key|auth[_-]?token)\s*[=:]\s*["\']?([A-Za-z0-9!@#$%^&*_\-+=/]{8,40})["\']?'), "Hardcoded Credential"),
        (re.compile(r'(?i)private[_-]?key\s*[=:]\s*["\']?([A-Za-z0-9+/=]{16,})["\']?'), "Private Key Value"),
    ]

    wasm_urls: Set[str] = set()

    c, _, b, _ = _req(base)
    if c == 200 and b:
        text = b.decode("utf-8", "ignore")
        for m in re.finditer(r'["\']([^"\'<>\s]*\.wasm(?:\?[^"\'<>\s]*)?)["\']', text):
            ref = m.group(1)
            wasm_urls.add(_join_url(base, ref) if not ref.startswith("http") else ref)
        for js_src in re.findall(r'<script[^>]+src=["\']([^"\']+\.js(?:\?[^"\']*)?)["\']', text, re.I)[:8]:
            js_url = _join_url(base, js_src) if not js_src.startswith("http") else js_src
            cj, _, bj, _ = _req(js_url)
            if cj == 200 and bj:
                for m in re.finditer(r'["\']([^"\'<>\s]*\.wasm(?:\?[^"\'<>\s]*)?)["\']',
                                     bj[:131072].decode("utf-8", "ignore")):
                    ref = m.group(1)
                    wasm_urls.add(_join_url(base, ref) if not ref.startswith("http") else ref)

    for path in _COMMON_WASM_PATHS:
        cp, _, bp, _ = _req(_join_url(base, path))
        if cp == 200 and len(bp) >= 8 and bp[:4] == b"\x00asm":
            wasm_urls.add(_join_url(base, path))

    if not wasm_urls:
        return out

    out.append(("WebAssembly modules discovered: %d - parsing binary for secrets, backdoors, dangerous imports" % len(wasm_urls),
                "urls: " + " | ".join(list(wasm_urls)[:4])))

    for wasm_url in list(wasm_urls)[:8]:
        cw, _, bw, _ = _req(wasm_url)
        if cw != 200 or len(bw) < 8 or bw[:4] != b"\x00asm":
            continue

        exports: List[str] = []
        imports: List[Tuple[str, str]] = []
        data_strings: List[str] = []
        custom_fn_names: List[str] = []

        pos = 8
        while pos < len(bw):
            try:
                sec_id = bw[pos]
                pos += 1
                sec_size, nb = _wasm_uleb128(bw, pos)
                pos += nb
                if pos + sec_size > len(bw):
                    break
                sec_data = bw[pos:pos + sec_size]
                pos += sec_size
                if sec_id == 7:
                    exports = _wasm_parse_exports_section(sec_data)
                elif sec_id == 2:
                    imports = _wasm_parse_imports_section(sec_data)
                elif sec_id == 11:
                    data_strings = _wasm_parse_data_section(sec_data)
                elif sec_id == 0:
                    cname, cnb = _wasm_name(sec_data, 0)
                    if cname == "name":
                        custom_fn_names = _wasm_parse_name_custom_section(sec_data[cnb:])
            except Exception:
                break

        all_fn_names = list(set(exports + custom_fn_names))
        mod_short = wasm_url.split("/")[-1].split("?")[0] or wasm_url[-40:]

        susp = [n for n in all_fn_names if any(kw in n.lower() for kw in _SUSP_KWS)]
        if susp:
            out.append(("[CONFIRMED] WASM exports suspicious function names suggesting backdoor/admin functionality",
                        "module=%s functions=%s" % (mod_short, str(susp[:6]))))

        wasi_hits = [(mod, fn) for mod, fn in imports
                     if "wasi" in mod.lower() and fn in _DANGEROUS_WASI]
        if wasi_hits:
            out.append(("[CONFIRMED] WASM uses dangerous WASI imports (filesystem/network/process access)",
                        "module=%s imports=%s" % (mod_short, str(wasi_hits[:5]))))

        all_data_text = "\n".join(data_strings)
        for pat, label in _SECRET_PATS:
            m = pat.search(all_data_text)
            if m:
                snippet = m.group(0)[:80]
                out.append(("[CONFIRMED] %s found hardcoded in WASM binary data segment - immediate secret rotation required" % label,
                            "module=%s value=%s" % (mod_short, snippet)))

        for s in data_strings:
            if 24 <= len(s) <= 120 and _shannon_entropy(s) > 4.8:
                if re.match(r'^[A-Za-z0-9+/=_\-]{24,}$', s):
                    out.append(("High-entropy string in WASM data segment - possible hardcoded API key or token",
                                "module=%s value=%s" % (mod_short, s[:60])))
                    break

        for mod_name, fn_name in imports:
            if mod_name in ("env", "__wbindgen_externref_xform__") and any(
                kw in fn_name.lower() for kw in ("eval", "exec", "system", "popen", "spawn", "shell")
            ):
                out.append(("[CONFIRMED] WASM imports dangerous host function - possible code execution bridge",
                            "module=%s import=%s::%s" % (mod_short, mod_name, fn_name)))

        if all_fn_names or imports or data_strings:
            out.append(("WASM module analyzed: exports=%d imports=%d data_strings=%d size=%dKB" % (
                len(exports), len(imports), len(data_strings), len(bw) // 1024),
                wasm_url))

    return out

def scan_import_map_injection(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, _, b, _ = _req(base)
    if c != 200 or not b:
        return out
    text = b.decode("utf-8", "ignore")
    im_blocks = re.findall(r'<script[^>]+type=["\']importmap["\'][^>]*>(.*?)</script>', text, re.S | re.I)
    if not im_blocks:
        return out
    out.append(("Import map present - check for user-controlled specifier injection", "importmap found in HTML"))
    for block in im_blocks:
        try:
            data = json.loads(block)
            imports = data.get("imports", {}) or {}
            scopes = data.get("scopes", {}) or {}
        except Exception:
            out.append(("[CONFIRMED] Import map JSON is malformed - may indicate template injection into importmap", "malformed importmap"))
            continue
        all_urls = list(imports.values())
        for scope_map in scopes.values():
            if isinstance(scope_map, dict):
                all_urls.extend(scope_map.values())
        host = urllib.parse.urlparse(base).netloc
        for u in all_urls:
            if isinstance(u, str) and u.startswith("http"):
                mapped_host = urllib.parse.urlparse(u).netloc
                if mapped_host and mapped_host != host:
                    out.append(("[CONFIRMED] Import map loads ES modules from cross-origin host - supply chain risk",
                                "external specifier: " + u[:120]))
        for specifier in imports.keys():
            if any(ch in specifier for ch in ["${", "{{", "<%"]):
                out.append(("[CONFIRMED] Import map specifier contains template expression - possible injection",
                            "specifier: " + specifier[:80]))
    return out

def scan_fetch_metadata_policy(base: str) -> ScanFindings:
    out: ScanFindings = []
    cross_site_headers = {
        "Sec-Fetch-Site":  "cross-site",
        "Sec-Fetch-Mode":  "navigate",
        "Sec-Fetch-Dest":  "document",
        "Sec-Fetch-User":  "?1",
    }
    same_origin_headers = {
        "Sec-Fetch-Site":  "same-origin",
        "Sec-Fetch-Mode":  "navigate",
        "Sec-Fetch-Dest":  "document",
    }
    c_cross, _, b_cross, _ = _req(base, headers=cross_site_headers)
    c_same,  _, b_same,  _ = _req(base, headers=same_origin_headers)
    if c_cross in (200, 301, 302) and c_same in (200, 301, 302):
        if c_cross == c_same:
            out.append(("Fetch Metadata policy not enforced: server accepts Sec-Fetch-Site:cross-site identically to same-origin - no CSRF barrier",
                        "cross=%d same=%d" % (c_cross, c_same)))
    for priv_path in ["/admin", "/dashboard", "/api/internal", "/settings", "/account"]:
        c_p, _, _, _ = _req(_join_url(base, priv_path), headers=cross_site_headers)
        c_s, _, _, _ = _req(_join_url(base, priv_path), headers=same_origin_headers)
        if c_p in (200,) and c_s in (200,):
            out.append(("Fetch Metadata policy missing on privileged path - cross-site requests accepted without restriction",
                        "path: " + priv_path))
            break
    if out:
        out[0] = (out[0][0], out[0][1] + " - set Sec-Fetch-Site enforcement in middleware")
    return out

def scan_oauth_implicit_flow(base: str) -> ScanFindings:
    out: ScanFindings = []
    oauth_paths = ["/oauth/authorize", "/authorize", "/connect/authorize",
                   "/oauth2/authorize", "/auth/authorize", "/o/oauth2/auth",
                   "/login/oauth/authorize", "/.well-known/openid-configuration"]
    oidc_url = _join_url(base, "/.well-known/openid-configuration")
    c_oidc, _, b_oidc, _ = _req(oidc_url)
    if c_oidc == 200 and b_oidc:
        try:
            oidc_cfg = json.loads(b_oidc)
            grant_types = oidc_cfg.get("grant_types_supported", [])
            response_types = oidc_cfg.get("response_types_supported", [])
            if "implicit" in grant_types or "token" in " ".join(response_types):
                out.append(("[CONFIRMED] OIDC discovery advertises implicit flow (response_type=token) - tokens exposed in URL fragment",
                            "grant_types=" + str(grant_types[:5])))
                return out
        except Exception:
            pass
    for path in oauth_paths:
        test_url = _join_url(base, path) + "?response_type=token&client_id=test&redirect_uri=https://example.com/cb&scope=openid"
        c, hdrs, b, _ = _req(test_url)
        loc = hdrs.get("location", "")
        text = b.decode("utf-8", "ignore")
        if "access_token" in loc or "access_token" in text:
            out.append(("[CONFIRMED] OAuth implicit flow accepted (response_type=token): access token issued without PKCE",
                        "endpoint: " + path))
            return out
        if c in (200, 302) and any(k in text.lower() for k in ("authorize", "token", "oauth")):
            out.append(("OAuth endpoint may accept implicit flow - manual verification recommended",
                        "endpoint: " + path))
            return out
    return out

def scan_iis_shortname(base: str) -> ScanFindings:
    out: ScanFindings = []
    parsed = urllib.parse.urlparse(base)
    host = parsed.netloc
    scheme = parsed.scheme
    probe_url = scheme + "://" + host + "/a~1/a"
    try:
        c_probe, _, _, _ = _req(probe_url)
    except Exception:
        return out
    baseline_url = scheme + "://" + host + "/" + "a" * 10 + "/a"
    try:
        c_baseline, _, _, _ = _req(baseline_url)
    except Exception:
        return out
    if c_probe == 404 and c_baseline == 404:
        return out
    if c_probe in (400, 404) and c_baseline == 404:
        return out
    if c_probe != c_baseline:
        out.append(("IIS short filename (8.3 tilde) enumeration possible - server differentiates ~1 paths",
                    "probe=%d baseline=%d path=*~1/a" % (c_probe, c_baseline)))
        prefix_hits: List[str] = []
        for char in "abcdefghijklmnopqrstuvwxyz0123456789":
            url = scheme + "://" + host + "/" + char + "~1/a"
            try:
                c2, _, _, _ = _req(url)
            except Exception:
                continue
            if c2 != c_baseline:
                prefix_hits.append(char)
        if prefix_hits:
            out.append(("[CONFIRMED] IIS 8.3 short filename: found file/folder prefixes: " + "".join(prefix_hits[:8]),
                        "tilde enumeration confirmed"))
    return out

def scan_memcached_exposure(base: str) -> ScanFindings:
    out: ScanFindings = []
    host = urllib.parse.urlparse(base).hostname or ""
    if not host:
        return out
    try:
        s = socket.create_connection((host, 11211), timeout=3)
        s.sendall(b"stats\r\n")
        data = b""
        s.settimeout(2)
        try:
            while True:
                chunk = s.recv(1024)
                if not chunk:
                    break
                data += chunk
                if b"END\r\n" in data or b"ERROR" in data:
                    break
        except Exception:
            pass
        s.close()
        if b"STAT " in data:
            ver_m = re.search(rb"STAT version ([^\r\n]+)", data)
            ver = ver_m.group(1).decode() if ver_m else "unknown"
            out.append(("[CONFIRMED] Memcached unauthenticated access on port 11211 - stats command accepted",
                        "version: " + ver))
            s2 = socket.create_connection((host, 11211), timeout=3)
            s2.sendall(b"stats cachedump 1 5\r\n")
            keys_data = b""
            try:
                keys_data = s2.recv(2048)
            except Exception:
                pass
            s2.close()
            if b"ITEM " in keys_data:
                out.append(("[CONFIRMED] Memcached cache dump readable - key names exposed",
                            "keys: " + keys_data[:200].decode("utf-8", "replace")))
    except Exception:
        pass
    return out

def scan_webdav_exposure(base: str) -> ScanFindings:
    out: ScanFindings = []
    propfind_body = b"""<?xml version="1.0" encoding="utf-8"?>
<propfind xmlns="DAV:"><prop><displayname/><getlastmodified/><resourcetype/></prop></propfind>"""
    c_pf, hdrs_pf, b_pf, _ = _req(base, method="PROPFIND", data=propfind_body,
                                   content_type="application/xml",
                                   headers={"Depth": "1"})
    if c_pf == 207 or (c_pf in (200,) and b"DAV:" in b_pf):
        out.append(("[CONFIRMED] WebDAV PROPFIND enabled - directory traversal and file listing possible",
                    "status: %d" % c_pf))
        dav_hdr = hdrs_pf.get("dav", hdrs_pf.get("DAV", ""))
        if dav_hdr:
            out.append(("WebDAV capabilities: " + dav_hdr[:120], "DAV header"))
    c_opts, hdrs_opts, _, _ = _req(base, method="OPTIONS")
    allow = hdrs_opts.get("allow", "")
    if any(m in allow.upper() for m in ("PROPFIND", "PROPPATCH", "MKCOL", "COPY", "MOVE", "LOCK")):
        out.append(("WebDAV methods advertised via OPTIONS - write-capable methods may allow file upload",
                    "allow: " + allow[:120]))
    canary = "webdav-probe-" + hashlib.md5(base.encode()).hexdigest()[:8] + ".txt"
    c_put, _, _, _ = _req(_join_url(base, "/" + canary), method="PUT",
                          data=b"webdav-write-test", content_type="text/plain")
    if c_put in (200, 201, 204):
        c_get, _, b_get, _ = _req(_join_url(base, "/" + canary))
        if c_get == 200 and b"webdav-write-test" in b_get:
            out.append(("[CONFIRMED] WebDAV arbitrary file write via PUT - unauthenticated file creation possible",
                        "PUT /" + canary + " -> 200"))
            _req(_join_url(base, "/" + canary), method="DELETE")
    return out

def scan_php_info_exposure(base: str) -> ScanFindings:
    out: ScanFindings = []
    paths = ["/phpinfo.php", "/info.php", "/test.php", "/php.php", "/php_info.php",
             "/phpversion.php", "/_phpinfo.php", "/server-status",
             "/server-info", "/status.php", "/check.php", "/debug.php"]
    for path in paths:
        c, _, b, _ = _req(_join_url(base, path))
        if c != 200 or len(b) < 200:
            continue
        text = b.decode("utf-8", "ignore")
        if "PHP Version" in text and "phpinfo()" in text:
            ver_m = re.search(r"PHP Version\s+([\d.]+)", text)
            ver = ver_m.group(1) if ver_m else "unknown"
            out.append(("[CONFIRMED] phpinfo() page exposed: version " + ver + " - discloses config, extensions, env vars",
                        "path: " + path))
        elif "server-status" in path and "Apache" in text and "Server uptime" in text:
            out.append(("[CONFIRMED] Apache mod_status exposed at " + path + " - reveals workers, requests, internal IPs",
                        "path: " + path))
        elif "server-info" in path and ("Apache" in text or "Configuration" in text) and "httpd" in text.lower():
            out.append(("[CONFIRMED] Apache mod_info exposed at " + path + " - reveals loaded modules and config directives",
                        "path: " + path))
    return out

def scan_prometheus_exposure(base: str) -> ScanFindings:
    out: ScanFindings = []
    paths = ["/metrics", "/actuator/prometheus", "/prometheus", "/stats/prometheus",
             "/internal/metrics", "/debug/metrics", "/_metrics", "/api/metrics",
             "/q/metrics", "/manage/prometheus"]
