def scan_graphql_introspection_bypass(base: str) -> ScanFindings:
    out: ScanFindings = []
    _GQL_PATHS = ["/graphql", "/api/graphql", "/v1/graphql", "/query", "/gql",
                  "/api/query", "/graphiql", "/playground"]

    found: List[str] = []
    for path in _GQL_PATHS:
        u = _join_url(base, path)
        c, _, b, _ = _req(u, timeout=4.0)
        if c != 0 and (b"graphql" in b.lower() or b"__typename" in b
                       or b"errors" in b or b"data" in b):
            found.append(u)
    if not found:
        return out

    _INTRO_QUERY_JSON = b'{"query":"{__schema{types{name}}}"}'
    _INTRO_QUERY_RAW  = b"{__schema{types{name}}}"
    _TYPENAME_QUERY   = b'{"query":"{__typename}"}'
    _FIELD_PROBE      = b'{"query":"{nonExistentField_xyzzy123}"}'

    for ep in found[:3]:
        ep_path = urllib.parse.urlparse(ep).path

        c, _, b, _ = _req(
            ep + "?query=" + urllib.parse.quote("{__schema{types{name}}}"),
            timeout=4.0,
        )
        if c not in (0, 400, 403, 405) and b"__schema" in b and b"types" in b:
            out.append(("graphql introspection bypass via GET at " + ep_path,
                        "introspection block only applies to POST - GET returns full schema"))
            continue

        c, _, b, _ = _req(ep, method="POST", data=_INTRO_QUERY_RAW,
                           headers={"Content-Type": "application/graphql"}, timeout=4.0)
        if c not in (0, 400, 403) and b"__schema" in b and b"types" in b:
            out.append(("graphql introspection bypass via Content-Type:application/graphql at " + ep_path,
                        "application/graphql content-type bypasses introspection block"))
            continue

        for hdr in ("x-allow-introspection", "x-introspection-override", "x-debug", "x-graphql-debug"):
            c, _, b, _ = _req(ep, method="POST", data=_INTRO_QUERY_JSON,
                               headers={"Content-Type": "application/json", hdr: "true"}, timeout=4.0)
            if c not in (0, 400, 403) and b"__schema" in b and b"types" in b:
                out.append(("graphql introspection bypass via header %s at %s" % (hdr, ep_path),
                            "request header unlocks schema introspection"))
                break

        c, _, b, _ = _req(ep, method="POST", data=_FIELD_PROBE,
                           headers={"Content-Type": "application/json"}, timeout=4.0)
        resp = b.decode("utf-8", "ignore")
        if "Did you mean" in resp or "suggestions" in resp.lower():
            suggestions = re.findall(r'Did you mean ["\`]?(\w+)', resp)
            if not suggestions:
                suggestions = re.findall(r'"(\w+)"', resp[:400])
            if suggestions:
                out.append(("graphql field suggestions leak schema with introspection disabled at " + ep_path,
                            "leaked field names: " + ", ".join(suggestions[:8])))

        c, _, b, _ = _req(ep, method="POST", data=_TYPENAME_QUERY,
                           headers={"Content-Type": "application/json"}, timeout=4.0)
        if c not in (0,) and (b'"__typename"' in b or b'"data"' in b):
            out.append(("graphql endpoint active: __typename probe returns data at " + ep_path,
                        "endpoint confirmed; schema reachable even with introspection disabled"))

    return out

