        ".logo{font-weight:700;font-size:1.1em;color:var(--accent);margin-right:32px}\n"
        ".tabs{display:flex;gap:4px}\n"
        ".tab{padding:6px 16px;border-radius:6px;cursor:pointer;font-size:0.88em;"
        "color:var(--text-dim);transition:all 0.15s;user-select:none}\n"
        ".tab.active{background:var(--accent);color:#fff}\n"
        ".tab:hover:not(.active){background:var(--surface2);color:var(--text)}\n"
        ".panel{display:none;padding:24px;max-width:1400px;margin:0 auto}\n"
        ".panel.active{display:block}\n"
        ".card{background:var(--surface);border:1px solid var(--border);border-radius:10px;"
        "padding:20px;margin-bottom:16px}\n"
        ".sev-badge{display:inline-block;padding:2px 8px;border-radius:4px;font-size:0.78em;font-weight:700}\n"
        ".sev-badge.sev-ZERO{background:var(--zero);color:#fca5a5}\n"
