def scan_backup_archive_smart(base: str) -> ScanFindings:
    p = urllib.parse.urlparse(base)
    stem = (p.hostname or "site").split(".")[0]
    names = ["backup", "site", stem, "www", "prod", "db", "database"]
    paths = []
    for name in names:
        for ext in [".zip", ".tar.gz", ".tgz", ".bak", ".sql", ".7z", ".old"]:
            paths.append("/" + name + ext)
    return _probe_paths(base, paths[:80], ["create table", "insert into", "pk", "zip", "backup"], "Backup/archive")

def _extract_page_urls(base: str) -> str:
    c, h, b, _ = _req(base, timeout=6, use_cache=True)
    if c == 0:
        return ""
    return b[:300000].decode("utf-8", "ignore") + "\n" + json.dumps(h)

def scan_cloud_bucket_exposure(base: str) -> ScanFindings:
    text = _extract_page_urls(base)
    refs = sorted(set(re.findall(r"https?://[A-Za-z0-9_.-]+(?:s3[.-][A-Za-z0-9-]+\.amazonaws\.com|\.s3\.amazonaws\.com|storage\.googleapis\.com|blob\.core\.windows\.net)[^\"'\s<)]*", text, re.I)))
    return [("Cloud bucket URL exposed in client content", ", ".join(refs[:20]))] if refs else []

def scan_firebase_exposure_deep(base: str) -> ScanFindings:
    text = _extract_page_urls(base)
    refs = sorted(set(re.findall(r"https?://[A-Za-z0-9-]+\.firebaseio\.com|[A-Za-z0-9-]+\.firebaseapp\.com", text, re.I)))
    out = [("Firebase reference exposed in client content", ", ".join(refs[:20]))] if refs else []
    out += scan_firebase_open_db(base)
    return out[:20]

def scan_supabase_exposure(base: str) -> ScanFindings:
    text = _extract_page_urls(base)
    refs = sorted(set(re.findall(r"https?://[A-Za-z0-9-]+\.supabase\.co|eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}", text)))
    return [("Supabase URL/key material exposed in client content", ", ".join(refs[:12]))] if refs else []

def scan_cloud_blob_url_detection(base: str) -> ScanFindings:
    return scan_cloud_bucket_exposure(base)

def scan_oauth_redirect_uri_weakness(base: str) -> ScanFindings:
    text = _extract_page_urls(base)
    urls = sorted(set(re.findall(r"https?://[^\"'\s<]+(?:authorize|oauth)[^\"'\s<]+", text, re.I)))
    weak = [u for u in urls if re.search(r"redirect_uri=https-%3A%2F%2F|redirect_uri=http", u, re.I)]
    return [("OAuth authorize URL exposes redirect_uri in client content", "\n".join(weak[:10] or urls[:10]))] if urls else []

def scan_saml_metadata_security(base: str) -> ScanFindings:
    out = _probe_paths(base, ["/saml/metadata", "/saml2/metadata", "/metadata", "/Shibboleth.sso/Metadata"], ["entitydescriptor", "singlesignonservice", "x509certificate"], "SAML metadata")
    weak = _probe_paths(base, ["/saml/metadata", "/saml2/metadata"], ["rsa-sha1", "sha1"], "SAML weak algorithm")
    return out + weak

def scan_websocket_auth_cors(base: str) -> ScanFindings:
    out = scan_websocket(base) + scan_websocket_hijacking(base)
    text = _extract_page_urls(base)
    urls = sorted(set(re.findall(r"wss?://[^\"'\s<)]+", text, re.I)))
    if urls:
        out.append(("WebSocket URLs found in client content", ", ".join(urls[:20])))
    return out[:25]

def scan_cors_preflight_cache_weakness(base: str) -> ScanFindings:
    c, h, b, _ = _req(base, method="OPTIONS", headers={"Origin": "https://evil.example", "Access-Control-Request-Method": "POST"}, timeout=6)
    acao = h.get("access-control-allow-origin", "")
    max_age = h.get("access-control-max-age", "")
    out: ScanFindings = []
    if acao in ("*", "https://evil.example"):
        out.append(("CORS preflight reflects/wildcards untrusted origin", "ACAO=%s ACMA=%s" % (acao, max_age)))
    if max_age.isdigit() and int(max_age) > 86400:
        out.append(("CORS preflight cache lifetime is very long", "Access-Control-Max-Age=%s" % max_age))
    return out

def scan_csp_bypass_suggestions(base: str) -> ScanFindings:
    c, h, b, _ = _req(base, timeout=6, use_cache=True)
    csp = h.get("content-security-policy", "")
    out = scan_csp_bypass_gadgets(base)
    if csp:
        for token in ["unsafe-inline", "unsafe-eval", "data:", "*"]:
            if token in csp:
                out.append(("CSP contains bypass-prone source token", token))
    return out[:25]

def scan_security_txt_parser(base: str) -> ScanFindings:
    out = scan_security_txt(base)
    c, _, b, _ = _req(_join_url(base, "/.well-known/security.txt"), timeout=5, use_cache=True)
    text = b.decode("utf-8", "ignore")
    if c == 200:
        missing = [k for k in ["Contact:", "Expires:", "Policy:"] if k.lower() not in text.lower()]
        if missing:
            out.append(("security.txt missing recommended fields", ", ".join(missing)))
    return out

def scan_dependency_license_risk(base: str) -> ScanFindings:
    out = scan_dependency_inventory(base)
    for path in ["/package-lock.json", "/yarn.lock", "/pnpm-lock.yaml", "/composer.lock"]:
        c, _, b, _ = _req(_join_url(base, path), timeout=5, use_cache=True)
        if c == 200 and len(b) > 50:
            out.append(("Dependency lockfile exposed; review license and CVE risk", path))
    return out[:30]

def scan_sourcemap_secret_scanner(base: str) -> ScanFindings:
    out = scan_sourcemap_reconstruction(base)
    text = _extract_page_urls(base)
    maps = sorted(set(re.findall(r"[^\"'\s<)]+\.js\.map", text, re.I)))[:20]
    for raw in maps:
        u = urllib.parse.urljoin(base, raw)
        c, _, b, _ = _req(u, timeout=6, use_cache=True)
        sample = b[:250000].decode("utf-8", "ignore")
        hits = sorted(set(re.findall(r"(?i)(api[_-]?key|secret|token|password|private[_-]?key|aws_access_key_id)", sample)))
        if c == 200 and hits:
            out.append(("Source map contains secret-looking identifiers", "%s hits=%s" % (u, ",".join(hits[:10]))))
    return out[:30]

def scan_robots_sitemap_scoring(base: str) -> ScanFindings:
    out: ScanFindings = []
    for path in ["/robots.txt", "/sitemap.xml"]:
        c, _, b, _ = _req(_join_url(base, path), timeout=5, use_cache=True)
        text = b.decode("utf-8", "ignore")
        sensitive = re.findall(r"/(?:admin|backup|debug|private|api|internal|staging|test)[^\s<]*", text, re.I)
        if c == 200 and sensitive:
            out.append(("%s exposes sensitive-looking crawl targets" % path, ", ".join(sorted(set(sensitive))[:30])))
    return out

def scan_graphql_schema_aware(base: str) -> ScanFindings:
    endpoints = [_join_url(base, p) for p in ("/graphql", "/api/graphql", "/query")]
    out: ScanFindings = []
    q = {"query": "{ __schema { queryType { fields { name } } mutationType { fields { name } } } }"}
    for ep in endpoints:
        c, h, b, _ = _req(ep, method="POST", data=json.dumps(q).encode(), headers={"Content-Type": "application/json"}, timeout=8)
        if c == 0:
            continue
        text = b.decode("utf-8", "ignore")
        if "__schema" in text and "fields" in text:
            names = sorted(set(re.findall(r'"name"\s*:\s*"([^"]+)"', text)))
            risky = [n for n in names if re.search(r"delete|create|update|admin|user|token|password|role", n, re.I)]
            out.append(("[CONFIRMED] GraphQL schema introspection available", "endpoint=%s fields=%s" % (ep, ",".join(names[:80]))))
            if risky:
                out.append(("GraphQL schema exposes sensitive-looking operations", "endpoint=%s operations=%s" % (ep, ",".join(risky[:40]))))
            break
    return out

def scan_sqlmap_export(base: str) -> ScanFindings:
    urls = sorted(set(_discover_frontier_urls(base, limit=40) + [base]))
    candidates = [u for u in urls if urllib.parse.urlparse(u).query]
    if not candidates:
        candidates = [base + ("&" if "?" in base else "?") + "id=1"]
    lines = []
    for u in candidates[:60]:
        cmd = "sqlmap -u %s --batch --random-agent" % json.dumps(u)
        if _GLOBAL_HEADERS.get("Cookie"):
            cmd += " --cookie " + json.dumps(_GLOBAL_HEADERS.get("Cookie", ""))
        if _GLOBAL_HEADERS.get("Authorization"):
            cmd += " --headers " + json.dumps("Authorization: " + _GLOBAL_HEADERS["Authorization"])
        lines.append(cmd)
    if _SQLMAP_EXPORT_FILE:
        try:
            with open(_SQLMAP_EXPORT_FILE, "w", encoding="utf-8") as fh:
                fh.write("\n".join(lines) + "\n")
        except Exception as exc:
            return [("sqlmap export failed", str(exc))]
    return [("sqlmap handoff generated %d candidate command(s)" % len(lines), _SQLMAP_EXPORT_FILE or "\n".join(lines[:10]))]

def scan_fuzzer_mode(base: str) -> ScanFindings:
    words = ["admin", "login", "api", "debug", "backup", ".env", ".git/config", "server-status", "swagger.json", "openapi.json"]
    if _FUZZ_WORDLIST_FILE and os.path.exists(_FUZZ_WORDLIST_FILE):
        try:
            with open(_FUZZ_WORDLIST_FILE, encoding="utf-8", errors="ignore") as fh:
                words = [x.strip() for x in fh if x.strip() and not x.startswith("#")][:600]
        except Exception:
            pass
    else:
        default_wl = _default_fuzz_wordlist_path()
        if default_wl:
            try:
                with open(default_wl, encoding="utf-8", errors="ignore") as fh:
                    words.extend([x.strip() for x in fh if x.strip() and not x.startswith("#")][:600])
            except Exception:
                pass
    for u in _discover_frontier_urls(base, limit=40)[:40]:
        up = urllib.parse.urlparse(u)
        parts = [p for p in up.path.split("/") if p]
        words.extend(parts[-2:])
        for k in urllib.parse.parse_qs(up.query).keys():
            if re.search(r"(admin|debug|token|key|file|path|redirect|api|user)", k, re.I):
                words.append(k)
    expanded: List[str] = []
    for word in words:
        expanded.append(word)
        stem = word.strip("/")
        for ext in _FUZZ_EXTENSIONS:
            expanded.append(stem + "." + ext)
    words = list(dict.fromkeys(expanded or words))
    out: ScanFindings = []
    calibration = []
    for _ in range(3):
        c404, _, b404x, _ = _req(_join_url(base, "/sc-not-found-" + secrets.token_hex(4)), timeout=5)
        calibration.append((c404, len(b404x)))
    base404 = calibration[0][0] if calibration else 404
    base404_sizes = [x[1] for x in calibration]
    _EVIDENCE_TABLE["fuzzer_calibration"] = {
        "base_status": base404,
        "base_sizes": base404_sizes,
        "word_count": len(words),
        "probe_count": min(len(words), 300),
        "match_status": sorted(_FUZZ_MATCH_STATUS or {200, 204, 206, 301, 302, 307, 308, 401, 403}),
        "filter_size": _FUZZ_FILTER_SIZE,
        "extensions": list(_FUZZ_EXTENSIONS),
        "recursion": bool(_FUZZ_RECURSION),
    }
    discovered_dirs: List[str] = []
    interesting_status = _FUZZ_MATCH_STATUS or {200, 204, 206, 301, 302, 307, 308, 401, 403}

    def _probe_path(path: str) -> Optional[Tuple[int, str, int, str, str]]:
        c, h, b, _ = _req(_join_url(base, path), timeout=5)
        if _FUZZ_FILTER_SIZE >= 0 and abs(len(b) - _FUZZ_FILTER_SIZE) < 8:
            return None
        looks_404 = c == base404 and any(abs(len(b) - sz) < 32 for sz in base404_sizes)
        if c not in interesting_status or looks_404:
            return None
        title_m = re.search(rb"<title[^>]*>(.*-)</title>", b[:4096], re.I | re.S)
        title = re.sub(r"\s+", " ", title_m.group(1).decode("utf-8", "ignore")).strip()[:80] if title_m else ""
        location = h.get("location", "")[:160]
        return c, path, len(b), title, location

    probe_paths: List[str] = []
    for word in words[:300]:
        path = word if word.startswith("/") else "/" + word
        probe_paths.append(path)
    workers = min(max(4, _GLOBAL_SCAN_WORKERS or 12), 32, max(1, len(probe_paths)))
    with ThreadPoolExecutor(max_workers=workers) as ex:
        futures = [ex.submit(_probe_path, path) for path in probe_paths]
        for fut in as_completed(futures):
            item = fut.result()
            if not item:
                continue
            c, path, size, title, location = item
            detail = "path=%s bytes=%d" % (path, size)
            if title:
                detail += " title=" + title
            if location:
                detail += " location=" + location
            out.append(("fuzzer discovered interesting path HTTP %d" % c, detail))
            if _FUZZ_RECURSION and (path.endswith("/") or "." not in os.path.basename(path)):
                discovered_dirs.append(path.rstrip("/") + "/")
    if _FUZZ_RECURSION:
        recursive_paths: List[str] = []
        for prefix in list(dict.fromkeys(discovered_dirs))[:12]:
            for word in words[:80]:
                leaf = word.strip("/")
                if leaf:
                    recursive_paths.append(prefix + leaf)
        workers = min(max(4, _GLOBAL_SCAN_WORKERS or 12), 32, max(1, len(recursive_paths)))
        with ThreadPoolExecutor(max_workers=workers) as ex:
            futures = [ex.submit(_probe_path, "/" + path.lstrip("/")) for path in recursive_paths[:960]]
            for fut in as_completed(futures):
                item = fut.result()
                if not item:
                    continue
                c, path, size, title, location = item
                detail = "path=%s bytes=%d" % (path, size)
                if title:
                    detail += " title=" + title
                if location:
                    detail += " location=" + location
                out.append(("recursive fuzzer discovered path HTTP %d" % c, detail))
    if out:
        _EVIDENCE_TABLE["fuzzer_calibration"]["matches"] = len(out)
    else:
        out.append(("fuzzer calibration completed without matches", "status=%s sizes=%s probes=%d filtered_by_size=%s" % (base404, base404_sizes, min(len(words), 300), _FUZZ_FILTER_SIZE)))
    return out[:80]

def scan_source_code_mode(base: str) -> ScanFindings:
    root = _SOURCE_DIR or os.getcwd()
    return _local_scan_source_tree(root)

def scan_local_dependency_mode(base: str) -> ScanFindings:
    root = _SOURCE_DIR or os.getcwd()
    return _local_scan_dependency_manifests(root)

def scan_service_discovery(base: str) -> ScanFindings:
    out: ScanFindings = []
    p = urllib.parse.urlparse(base)
    host = p.hostname or ""
    if not host:
        return out
    ports = [80, 443, 8080, 8443, 8000, 3000, 5000, 9000]
    for port in ports:
        try:
            with socket.create_connection((host, port), timeout=1.2):
                scheme = "https" if port in (443, 8443) else "http"
                c, h, b, _ = _req("%s://%s:%d/" % (scheme, host, port), timeout=4)
                banner = h.get("server", "") if c else "tcp-open"
                out.append(("service discovery found open port %d" % port, "http_status=%s server=%s" % (c or "?", banner)))
        except Exception:
            pass
    return out

def scan_tls_deep(base: str) -> ScanFindings:
    out: ScanFindings = []
    p = urllib.parse.urlparse(base)
    host = p.hostname or ""
    port = p.port or 443
    if p.scheme != "https" or not host:
        return out
    try:
        ctx = ssl.create_default_context()
        with socket.create_connection((host, port), timeout=4) as sock:
            with ctx.wrap_socket(sock, server_hostname=host) as ssock:
                cert = ssock.getpeercert()
                cipher = ssock.cipher()
                version = ssock.version()
        not_after = cert.get("notAfter", "")
        san = cert.get("subjectAltName", [])
        subject = dict(x[0] for x in cert.get("subject", []) if x)
        issuer = dict(x[0] for x in cert.get("issuer", []) if x)
        subject_cn = subject.get("commonName", "")
        issuer_cn = issuer.get("commonName", "")
        out.append(("TLS deep scan negotiated %s" % version, "cipher=%s cert_expires=%s san_count=%d subject=%s issuer=%s" % (cipher[0] if cipher else "?", not_after, len(san), subject_cn or "?", issuer_cn or "?")))
        if subject and issuer and subject == issuer:
            out.append(("TLS certificate appears self-signed", "subject=%s issuer=%s" % (subject_cn or subject, issuer_cn or issuer)))
        try:
            exp = datetime.datetime.strptime(not_after, "%b %d %H:%M:%S %Y %Z").replace(tzinfo=datetime.timezone.utc)
            days = int((exp - datetime.datetime.now(datetime.timezone.utc)).total_seconds() // 86400)
            if days < 0:
                out.append(("[CONFIRMED] TLS certificate is expired", "expired_days=%d not_after=%s" % (abs(days), not_after)))
            elif days <= 21:
                out.append(("TLS certificate expires soon", "days_remaining=%d not_after=%s" % (days, not_after)))
        except Exception:
            pass
        names = [v for t, v in san if str(t).lower() == "dns"]
        host_match = any(n == host or (n.startswith("*.") and host.endswith(n[1:])) for n in names)
        if names and not host_match:
            out.append(("TLS certificate SAN does not appear to match host", "host=%s sans=%s" % (host, ",".join(names[:10]))))
        elif not names and subject_cn and subject_cn != host and not (subject_cn.startswith("*.") and host.endswith(subject_cn[1:])):
            out.append(("TLS certificate commonName does not appear to match host", "host=%s commonName=%s" % (host, subject_cn)))
        if version in ("TLSv1", "TLSv1.1"):
            out.append(("TLS deep scan negotiated deprecated protocol", version))
        alpn = []
        for proto in ("h2", "http/1.1"):
            try:
                ctxa = ssl.create_default_context()
                ctxa.set_alpn_protocols([proto])
                with socket.create_connection((host, port), timeout=3) as sock:
                    with ctxa.wrap_socket(sock, server_hostname=host) as ssock:
                        picked = ssock.selected_alpn_protocol()
                        if picked:
                            alpn.append(picked)
            except Exception:
                pass
        if alpn:
            out.append(("TLS ALPN protocols accepted", ",".join(sorted(set(alpn)))))
    except Exception as exc:
        out.append(("TLS deep scan failed", str(exc)))
    for label, minimum, maximum in (
        ("TLSv1.0", getattr(ssl.TLSVersion, "TLSv1", None), getattr(ssl.TLSVersion, "TLSv1", None)),
        ("TLSv1.1", getattr(ssl.TLSVersion, "TLSv1_1", None), getattr(ssl.TLSVersion, "TLSv1_1", None)),
    ):
        if not minimum or not maximum:
            continue
        try:
            ctx_old = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
            ctx_old.check_hostname = False
            ctx_old.verify_mode = ssl.CERT_NONE
            ctx_old.minimum_version = minimum
            ctx_old.maximum_version = maximum
            with socket.create_connection((host, port), timeout=3) as sock:
                with ctx_old.wrap_socket(sock, server_hostname=host):
                    out.append(("TLS deep scan accepts deprecated protocol", label))
        except Exception:
            pass
    return out

def scan_waf_fingerprint_deep(base: str) -> ScanFindings:
    out: ScanFindings = []
    probes = ["/-q=<script>alert(1)</script>", "/-id=1' or '1'='1", "/../../etc/passwd", "/-x=${jndi:ldap://127.0.0.1/a}"]
    baseline, _, b0, _ = _req(base, timeout=5, use_cache=True)
    for path in probes:
        c, h, b, _ = _req(_join_url(base, path), timeout=5)
        low = (b[:5000] or b"").decode("utf-8", "ignore").lower()
        vendor = ""
        hdr = " ".join("%s:%s" % (k, v) for k, v in h.items()).lower()
        for name in ("cloudflare", "akamai", "sucuri", "imperva", "mod_security", "aws", "fastly", "barracuda"):
            if name.replace("_", "") in hdr.replace("_", "") or name.replace("_", "") in low.replace("_", ""):
                vendor = name
                break
        if c in (403, 406, 429, 503) or vendor:
            out.append(("WAF deep fingerprint blocked probe HTTP %s" % c, "probe=%s vendor_hint=%s baseline=%s" % (path, vendor or "unknown", baseline)))
    return out

def scan_sourcemap_reconstruction(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, h, b, _ = _req(base, timeout=6, use_cache=True)
    html = b.decode("utf-8", "ignore") if b else ""
    scripts = re.findall(r"<script[^>]+src=['\"]([^'\"]+\.js[^'\"]*)['\"]", html, re.I)
    maps = []
    for src in scripts[:20]:
        js_url = urllib.parse.urljoin(base, src)
        c2, _, jb, _ = _req(js_url, timeout=6, use_cache=True)
        text = jb[-2000:].decode("utf-8", "ignore") if jb else ""
        m = re.search(r"sourceMappingURL=([^\s*]+)", text)
        candidates = [m.group(1)] if m else []
        candidates.append(js_url + ".map")
        for cand in candidates:
            map_url = urllib.parse.urljoin(js_url, cand)
            cm, _, mb, _ = _req(map_url, timeout=6)
            if cm == 200 and b'"sources"' in mb[:200000]:
                try:
                    obj = json.loads(mb.decode("utf-8", "ignore"))
                    sources = obj.get("sources", []) if isinstance(obj, dict) else []
                except Exception:
                    sources = []
                maps.append((map_url, sources[:20]))
                break
    for map_url, sources in maps[:20]:
        out.append(("[CONFIRMED] JavaScript source map is exposed", "map=%s sources=%s" % (map_url, ",".join(map(str, sources[:20])))))
    return out

def scan_dependency_inventory(base: str) -> ScanFindings:
    out: ScanFindings = []
    c, h, b, _ = _req(base, timeout=6, use_cache=True)
    text = b.decode("utf-8", "ignore") if b else ""
    found: Dict[str, str] = {}
    for name, pat in {
        "jquery": r"jquery[-.]([0-9][0-9.]+)",
        "bootstrap": r"bootstrap[-.]([0-9][0-9.]+)",
        "react": r"react(?:\.production)?[-.]([0-9][0-9.]+)",
        "vue": r"vue(?:\.min)?[-.]([0-9][0-9.]+)",
        "angular": r"angular(?:\.min)?[-.]([0-9][0-9.]+)",
    }.items():
        m = re.search(pat, text, re.I)
        if m:
            found[name] = m.group(1)
    server = h.get("server", "")
    powered = h.get("x-powered-by", "")
    if server:
        found["server"] = server
    if powered:
        found["x-powered-by"] = powered
    for path in ("/package.json", "/composer.json", "/requirements.txt"):
        c2, _, b2, _ = _req(_join_url(base, path), timeout=5)
        if c2 == 200 and len(b2) > 20:
            found[path.lstrip("/")] = "exposed"
    if found:
        _EVIDENCE_TABLE["dependency_inventory"] = found
        out.append(("dependency inventory built", json.dumps(found, sort_keys=True)[:2000]))
    return out

def scan_inventory_cve_match(base: str) -> ScanFindings:
    if "dependency_inventory" not in _EVIDENCE_TABLE:
        scan_dependency_inventory(base)
    inv = _EVIDENCE_TABLE.get("dependency_inventory", {})
    out: ScanFindings = []
    jquery = str(inv.get("jquery", ""))
    if jquery and re.match(r"^[12]\.|^3\.[0-4]\.", jquery):
        out.append(("inventory CVE match: old jQuery version may have known XSS/security advisories", "jquery=%s" % jquery))
    bootstrap = str(inv.get("bootstrap", ""))
    if bootstrap and re.match(r"^[0-3]\.", bootstrap):
        out.append(("inventory CVE match: old Bootstrap version may have known XSS advisories", "bootstrap=%s" % bootstrap))
    server = (str(inv.get("server", "")) + " " + str(inv.get("x-powered-by", ""))).lower()
    if "php/" in server or "express" in server or "apache/" in server:
        out.append(("inventory CVE matching needs version review", server[:300]))
    return out

def scan_auth_profile_state(base: str) -> ScanFindings:
    out: ScanFindings = []
    if not _AUTH_PROFILE_FILE:
        return [("auth profile scanner is available", "Use --auth-profile FILE with HAR or JSON session headers to compare authenticated routes")]
    try:
        profiles: List[Tuple[str, Dict[str, str], List[str]]] = []
        if _AUTH_PROFILE_FILE.lower().endswith(".har"):
            urls, hdrs = _parse_har(_AUTH_PROFILE_FILE)
            profiles.append(("auth", hdrs, urls))
        else:
            with open(_AUTH_PROFILE_FILE, encoding="utf-8-sig") as fh:
                data = json.load(fh)
            if isinstance(data, dict) and isinstance(data.get("profiles"), list):
                for idx, prof in enumerate(data.get("profiles", [])):
                    if isinstance(prof, dict):
                        hdrs = dict(prof.get("headers", {}))
                        if prof.get("cookie") and "Cookie" not in hdrs:
                            hdrs["Cookie"] = str(prof.get("cookie"))
                        if prof.get("bearer") and "Authorization" not in hdrs:
                            hdrs["Authorization"] = "Bearer " + str(prof.get("bearer"))
                        if prof.get("authorization") and "Authorization" not in hdrs:
                            hdrs["Authorization"] = str(prof.get("authorization"))
                        profiles.append((str(prof.get("name", "profile%d" % idx)), hdrs, list(prof.get("urls", []))))
            else:
                hdrs = data.get("headers", data if isinstance(data, dict) else {}) if isinstance(data, dict) else {}
                hdrs = dict(hdrs)
                if isinstance(data, dict) and data.get("cookie") and "Cookie" not in hdrs:
                    hdrs["Cookie"] = str(data.get("cookie"))
                if isinstance(data, dict) and data.get("bearer") and "Authorization" not in hdrs:
                    hdrs["Authorization"] = "Bearer " + str(data.get("bearer"))
                profiles.append(("auth", hdrs, data.get("urls", []) if isinstance(data, dict) else []))
    except Exception as exc:
        return [("auth profile load failed", str(exc))]
    if not profiles:
        return []
    _EVIDENCE_TABLE["auth_profiles"] = [{"name": n, "header_count": len(h), "url_count": len(u)} for n, h, u in profiles]
    union_urls: List[str] = []
    for _, _, urls in profiles:
        union_urls.extend(urls)
    targets = union_urls[:30] or _discover_frontier_urls(base, limit=30)[:30] or [base]
    for url in targets:
        if urllib.parse.urlparse(url).netloc and urllib.parse.urlparse(url).netloc != urllib.parse.urlparse(base).netloc:
            continue
        c0, _, b0, _ = _req(url, timeout=5)
        seen_codes = {"anonymous": c0}
        role_bodies: Dict[str, Tuple[int, int, str]] = {"anonymous": (c0, len(b0), hashlib.sha256(b0[:120000]).hexdigest()[:12])}
        for name, hdrs, _ in profiles:
            c1, _, b1, _ = _req(url, headers=hdrs, timeout=5)
            seen_codes[name] = c1
            role_bodies[name] = (c1, len(b1), hashlib.sha256(b1[:120000]).hexdigest()[:12])
            if c0 in (401, 403) and c1 in (200, 206):
                out.append(("[CONFIRMED] auth profile reaches protected route", "profile=%s url=%s anonymous=%s authenticated=%s" % (name, url, c0, c1)))
            elif c0 == 200 and c1 == 200 and abs(len(b1) - len(b0)) > 1000:
                out.append(("auth profile changes response significantly", "profile=%s url=%s anonymous_len=%d authenticated_len=%d" % (name, url, len(b0), len(b1))))
        if len(set(seen_codes.values())) > 1 and len(profiles) > 1:
            out.append(("auth profiles differ on route", "url=%s codes=%s" % (url, seen_codes)))
        if len(profiles) > 1:
            same_200 = {n: v for n, v in role_bodies.items() if v[0] == 200 and n != "anonymous"}
            if len(same_200) >= 2:
                lengths = [v[1] for v in same_200.values()]
                hashes = {v[2] for v in same_200.values()}
                if max(lengths) - min(lengths) > 800 or len(hashes) > 1:
                    out.append(("role matrix: authenticated profiles receive different content", "url=%s profiles=%s" % (url, role_bodies)))
                else:
                    out.append(("role matrix: authenticated profiles appear equivalent on route", "url=%s profiles=%s" % (url, role_bodies)))
    return out[:40]

def _load_template_docs(path: str) -> List[Dict[str, Any]]:
    global _TEMPLATE_LOAD_WARNINGS
    docs: List[Dict[str, Any]] = []
    _TEMPLATE_LOAD_WARNINGS = []
    files: List[str] = []
    if path and os.path.isdir(path):
        for root, _, names in os.walk(path):
            for name in names:
                if name.lower().endswith((".yaml", ".yml", ".json")):
                    files.append(os.path.join(root, name))
            if len(files) > 300:
                break
    elif path and os.path.exists(path):
        files = [path]
    for fn in files[:300]:
        try:
            raw = open(fn, encoding="utf-8-sig", errors="ignore").read()
            if fn.lower().endswith(".json"):
                obj = json.loads(raw)
                if isinstance(obj, dict):
                    obj["_file"] = fn
                    docs.append(obj)
                continue
            tid = (re.search(r"(?m)^id:\s*['\"]?([^'\"\n]+)", raw) or [None, os.path.basename(fn)])[1].strip()
            name = (re.search(r"(?m)^\s*name:\s*['\"]?([^'\"\n]+)", raw) or [None, tid])[1].strip()
            severity = (re.search(r"(?m)^\s*severity:\s*['\"]?([^'\"\n]+)", raw) or [None, "INFO"])[1].strip().upper()
            paths = re.findall(r"(?m)^\s*-\s*['\"]?(\{\{BaseURL\}\}[^'\"\n]+|/[^'\"\n]+)", raw)
            req_paths = re.findall(r"(?m)^\s*path:\s*['\"]?([^'\"\n]+)", raw)
            paths.extend(req_paths)
            words = re.findall(r"(?m)^\s*-\s*['\"]([^'\"]{3,120})['\"]", raw)
            regexes = re.findall(r"(?m)^\s*-\s*regex:\s*['\"]([^'\"]{3,160})['\"]", raw)
            statuses = [int(x) for x in re.findall(r"(?m)^\s*-\s*(\d{3})\s*$", raw)]
            docs.append({"id": tid, "info": {"name": name, "severity": severity}, "paths": paths[:20], "words": words[:20], "regex": regexes[:10], "status": statuses[:10], "stop_at_first_match": "stop-at-first-match: true" in raw.lower(), "_file": fn})
        except Exception as exc:
            _TEMPLATE_LOAD_WARNINGS.append("%s: %s" % (fn, exc))
    return docs

def scan_nuclei_lite_templates(base: str) -> ScanFindings:
    template_path = _TEMPLATE_PATH or _default_template_path()
    if not template_path:
        return [("nuclei-lite template runner is available", "Use --templates DIR_OR_FILE with simple Nuclei-style YAML/JSON templates")]
    out: ScanFindings = []
    template_docs = _load_template_docs(template_path)
    if not template_docs:
        detail = "path=%s docs=0" % template_path
        if _TEMPLATE_LOAD_WARNINGS:
            detail += " errors=%s" % " | ".join(_TEMPLATE_LOAD_WARNINGS[:3])
        return [("nuclei-lite templates not loaded", detail)]
    if _TEMPLATE_LOAD_WARNINGS:
        out.append(("nuclei-lite template load warnings", "errors=%s" % " | ".join(_TEMPLATE_LOAD_WARNINGS[:3])))
    for tpl in template_docs:
        tid = str(tpl.get("id", os.path.basename(str(tpl.get("_file", "template")))))
        info = tpl.get("info", {}) if isinstance(tpl.get("info"), dict) else {}
        name = str(info.get("name", tid))
        severity = str(info.get("severity", tpl.get("severity", "INFO"))).upper()
        requests = tpl.get("requests") if isinstance(tpl.get("requests"), list) else []
        paths = tpl.get("paths") or tpl.get("path") or [req.get("path") for req in requests if isinstance(req, dict) and req.get("path")] or ["/"]
        if isinstance(paths, str):
            paths = [paths]
        words = tpl.get("words") or tpl.get("match_words") or []
        regexes = tpl.get("regex") or tpl.get("regexes") or []
        raw_statuses = tpl.get("status") or tpl.get("statuses") or []
        raw_statuses = raw_statuses if isinstance(raw_statuses, list) else [raw_statuses]
        status: Set[int] = set()
        for raw_status in raw_statuses:
            try:
                status.add(int(raw_status))
            except (TypeError, ValueError):
                out.append(("nuclei-lite template ignored invalid status matcher", "id=%s status=%r template=%s" % (tid, raw_status, tpl.get("_file", ""))))
        matchers = tpl.get("matchers") if isinstance(tpl.get("matchers"), list) else []
        extractors = tpl.get("extractors") if isinstance(tpl.get("extractors"), list) else []
        bad_regexes: Set[str] = set()
        def _template_re_search(pattern: Any, haystack: str) -> bool:
            try:
                return re.search(str(pattern), haystack, re.I) is not None
            except re.error:
                bad_regexes.add(str(pattern))
                return False

        def _template_re_findall(pattern: Any, haystack: str) -> List[str]:
            try:
                return re.findall(str(pattern), haystack, re.I)
            except re.error:
                bad_regexes.add(str(pattern))
                return []

        for path in list(paths)[:20]:
            url = str(path).replace("{{BaseURL}}", base.rstrip("/"))
            url = url.replace("{{Hostname}}", urllib.parse.urlparse(base).hostname or "")
            url = urllib.parse.urljoin(base, url) if not url.startswith("http") else url
            c, h, b, _ = _req(url, timeout=6)
            text = b[:200000].decode("utf-8", "ignore")
            header_text = "\n".join("%s: %s" % (k, v) for k, v in h.items())
            all_text = header_text + "\n\n" + text
            status_ok = not status or c in status
            word_ok = not words or any(str(w) in text for w in words)
            regex_ok = not regexes or any(_template_re_search(r, text) for r in regexes)
            matcher_ok = True
            if matchers:
                hits = []
                for matcher in matchers[:12]:
                    if not isinstance(matcher, dict):
                        continue
                    part = str(matcher.get("part", "body")).lower()
                    hay = header_text if part in ("header", "headers") else all_text if part == "all" else text
                    if matcher.get("status"):
                        vals = matcher.get("status")
                        vals = vals if isinstance(vals, list) else [vals]
                        hits.append(c in set(int(x) for x in vals))
                    elif matcher.get("words"):
                        vals = matcher.get("words")
                        vals = vals if isinstance(vals, list) else [vals]
                        hits.append(any(str(v) in hay for v in vals))
                    elif matcher.get("regex"):
                        vals = matcher.get("regex")
                        vals = vals if isinstance(vals, list) else [vals]
                        hits.append(any(_template_re_search(v, hay) for v in vals))
                condition = str(tpl.get("matchers-condition", tpl.get("condition", "or"))).lower()
                matcher_ok = all(hits) if condition == "and" else any(hits)
            if c and status_ok and word_ok and regex_ok and matcher_ok:
                extracted = []
                for r in list(regexes)[:3]:
                    extracted.extend(_template_re_findall(r, text)[:5])
                for ex in extractors[:5]:
                    if isinstance(ex, dict):
                        vals = ex.get("regex") or []
                        vals = vals if isinstance(vals, list) else [vals]
                        for r in vals[:3]:
                            extracted.extend(_template_re_findall(r, all_text)[:5])
                extra = " extracts=%s" % ",".join(map(str, extracted[:10])) if extracted else ""
                title = "nuclei-lite template matched: %s" % name
                if severity in _REPORT_SEV_ORDER and _REPORT_SEV_ORDER[severity] >= _REPORT_SEV_ORDER["HIGH"]:
                    title = "[CONFIRMED] " + title
                out.append((title, "severity=%s id=%s url=%s template=%s status=%s%s" % (severity, tid, url, tpl.get("_file", ""), c, extra)))
                if tpl.get("stop_at_first_match", True):
                    break
        if bad_regexes:
            out.append(("nuclei-lite template ignored invalid regex matcher", "id=%s regex=%s template=%s" % (tid, ",".join(sorted(bad_regexes)[:3]), tpl.get("_file", ""))))
    return out[:100]

def scan_adaptive_recommendations(base: str) -> ScanFindings:
    recs = _adaptive_recommendations()
    if not recs:
        return [("adaptive recommendation engine found no extra follow-up modules", "target=%s" % base)]
    return [("adaptive next probe: " + r["option"], r["reason"] + " hint=" + r.get("command_hint", "")) for r in recs]

def scan_self_debug_gaps(base: str) -> ScanFindings:
    gaps = _self_debug_gaps()
    if not gaps:
        return [("scanner self-debug: no major coverage gaps detected", "target=%s" % base)]
    return [("scanner self-debug gap: " + g["kind"], g["detail"] + " fix=" + g["fix"]) for g in gaps]

def scan_target_playbooks(base: str) -> ScanFindings:
    plays = _target_playbook_recommendations()
    if not plays:
        return [("target playbook engine ready", "run after technology/finding modules for stack-specific fixes")]
    return [("target playbook: " + str(p.get("module", "stack")), "stack=%s root=%s" % (p.get("stack", ""), p.get("root_cause", ""))) for p in plays]

def _audit_cves_in_source(path: Optional[str] = None) -> int:
    src_path = path or os.path.abspath(__file__)
    code, rows = _maintenance_audit_cves_in_source(src_path)
    _emit_maintenance_rows(rows)
    return code

def _emit_maintenance_rows(rows: List[Tuple[str, str]]) -> None:
    colors = {
        "error": A.R,
        "info": A.C,
        "info_bold": A.BD + A.C,
        "ok": A.G,
        "ok_bold": A.G + A.BD,
        "warn": A.Y,
        "warn_bold": A.Y + A.BD,
        "dim": A.D,
    }
    for kind, text in rows:
        _out(_paint(text, colors.get(kind, "")))

def _run_dead_code_audit(path: Optional[str] = None) -> int:
    src_path = path or os.path.abspath(__file__)
    try:
        result = _audit_dead_code_impl(src_path, SCAN_REGISTRY_SPECS)
    except Exception as exc:
        _out(_paint("  [audit-dead-code] failed: " + str(exc), A.R))
        return 2
    _emit_maintenance_rows(_maintenance_format_dead_code_audit(result, src_path))
    return 0

def _audit_scanner_source(path: Optional[str] = None, audit_category: str = "all") -> int:
    src_path = path or os.path.abspath(__file__)
    code, rows = _maintenance_audit_scanner_source(
        src_path,
        audit_category,
        globals().get("_SCAN_REGISTRY", []),
        SCAN_CATEGORIES,
        category_for_option,
    )
    _emit_maintenance_rows(rows)
    return code

