    def _clamp_arg(name: str, value: Any, minimum: float, default: float, *, integer: bool = False) -> Any:
        try:
            parsed = int(value) if integer else float(value)
        except (TypeError, ValueError):
            _out(_paint("  [config] invalid --%s value %r; using %s" % (name.replace("_", "-"), value, default), A.Y))
            parsed = default
        if parsed < minimum:
            _out(_paint("  [config] --%s must be >= %s; using %s" % (name.replace("_", "-"), minimum, minimum), A.Y))
            parsed = minimum
        return int(parsed) if integer else float(parsed)

