    def _module_filter_tokens(value: str) -> Set[str]:
        raw_tokens = _split_csv(value)
        out: Set[str] = set()
        for token in raw_tokens:
            clean = str(token).strip().lower()
            if not clean:
                continue
            out.add(clean)
            out.add(clean.replace("-", "_"))
        return out

